CREATE OR REPLACE FUNCTION catalogue_private.apply_v2_admin_model_capabilities (
  p_actor_user_id uuid,
  p_model_slug    text,
  p_capabilities  jsonb
)
  RETURNS void
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_capability jsonb;
  v_route_id text;
  v_provider_model_id text;
  v_provider_model_slug text;
  v_capability_id text;
  v_previous_capability_id text;
  v_existing_capability_id text;
  v_existing_effective_to timestamptz;
  v_has_previous boolean;
  v_has_target boolean;
begin
  if not exists (
    select 1
    from public.users
    where user_id = p_actor_user_id
      and lower(coalesce(role::text, '')) = 'admin'
  ) then
    raise exception 'actor must have the admin role';
  end if;

  if jsonb_typeof(coalesce(p_capabilities, '[]'::jsonb)) <> 'array' then
    raise exception 'provider capabilities must be an array';
  end if;

  if not exists (
    select 1 from public.v2_models where model_slug = p_model_slug
  ) then
    raise exception 'model not found';
  end if;

  -- The graph mutation locks the model before calling this helper. Reject
  -- duplicate target keys here so the error is deterministic before the
  -- per-row upserts run.
  if exists (
    select 1
    from jsonb_array_elements(coalesce(p_capabilities, '[]'::jsonb)) as payload(value)
    join public.v2_model_provider_routes route
      on route.model_slug = p_model_slug
      and route.provider_slug = nullif(trim(payload.value->>'provider_id'), '')
      and route.provider_model_slug = coalesce(
        nullif(trim(payload.value->>'provider_model_slug'), ''),
        nullif(trim(payload.value->>'api_model_id'), '')
      )
      and (
        nullif(trim(payload.value->>'provider_model_id'), '') is null
        or route.provider_model_id = trim(payload.value->>'provider_model_id')
      )
    group by route.provider_model_id, lower(trim(payload.value->>'capability_id'))
    having count(*) > 1
  ) then
    raise exception 'a provider model cannot have duplicate capabilities';
  end if;

  for v_capability in
    select value
    from jsonb_array_elements(coalesce(p_capabilities, '[]'::jsonb))
  loop
    v_provider_model_id := nullif(trim(v_capability->>'provider_model_id'), '');
    v_provider_model_slug := coalesce(
      nullif(trim(v_capability->>'provider_model_slug'), ''),
      nullif(trim(v_capability->>'api_model_id'), '')
    );
    v_capability_id := nullif(lower(trim(v_capability->>'capability_id')), '');
    v_previous_capability_id := nullif(lower(trim(v_capability->>'previous_capability_id')), '');

    if v_capability_id is null then
      raise exception 'provider capability id is required';
    end if;

    select route.provider_model_id
    into v_route_id
    from public.v2_model_provider_routes route
    where route.model_slug = p_model_slug
      and route.provider_slug = nullif(trim(v_capability->>'provider_id'), '')
      and route.provider_model_slug = v_provider_model_slug
      and (v_provider_model_id is null or route.provider_model_id = v_provider_model_id)
    order by route.provider_model_id
    limit 1;

    if v_route_id is null then
      raise exception 'provider capability does not match a model route';
    end if;

    select exists (
      select 1
      from public.v2_route_capabilities capability
      where capability.provider_model_id = v_route_id
        and lower(capability.capability_id) = v_capability_id
    )
    into v_has_target;

    v_existing_capability_id := null;
    v_existing_effective_to := null;
    v_has_previous := false;
    select capability.capability_id, capability.effective_to
    into v_existing_capability_id, v_existing_effective_to
    from public.v2_route_capabilities capability
    where capability.provider_model_id = v_route_id
      and lower(capability.capability_id) = coalesce(v_previous_capability_id, v_capability_id)
    for update;

    v_has_previous := v_existing_capability_id is not null;
    -- Historical rows are immutable even when the editor keeps the same
    -- capability identity. Lock and validate the source before any upsert.
    if v_has_previous and v_existing_effective_to is not null
       and v_existing_effective_to <= now() then
      raise exception 'historical capabilities cannot be changed';
    end if;

    if v_previous_capability_id is not null
       and v_previous_capability_id <> v_capability_id then
      if v_has_previous and v_has_target then
        raise exception 'provider model already has capability %', v_capability_id;
      end if;

      -- A historical row is immutable. An active or future row can be
      -- reassigned in place, which is the operation the editor needs.
      if v_has_previous and exists (
        select 1
        from public.v2_route_parameter_support support
        where support.provider_model_id = v_route_id
          and lower(support.capability_id) = lower(v_existing_capability_id)
      ) then
        raise exception 'capability has parameter support records and cannot be reassigned';
      end if;

      if v_has_previous and exists (
        select 1
        from public.v2_execution_plans plan
        where plan.provider_model_id = v_route_id
          and lower(plan.capability_id) = lower(v_existing_capability_id)
      ) then
        raise exception 'capability has execution plans and cannot be reassigned';
      end if;

      if v_has_previous then
        update public.v2_route_capabilities
        set capability_id = v_capability_id,
            updated_at = now()
        where provider_model_id = v_route_id
          and capability_id = v_existing_capability_id;
      end if;
    end if;

    insert into public.v2_route_capabilities(
      provider_model_id,
      capability_id,
      status,
      params,
      effective_from,
      effective_to,
      metadata,
      updated_at
    )
    values (
      v_route_id,
      v_capability_id,
      case
        when coalesce(v_capability->>'status', '') like 'deranked_%' then 'degraded'
        else coalesce(nullif(trim(v_capability->>'status'), ''), 'active')
      end,
      coalesce(v_capability->'params', '{}'::jsonb),
      nullif(v_capability->>'effective_from', '')::timestamptz,
      nullif(v_capability->>'effective_to', '')::timestamptz,
      jsonb_build_object('editor_status', v_capability->>'status', 'source', 'admin'),
      now()
    )
    on conflict (provider_model_id, capability_id) do update set
      status = excluded.status,
      params = excluded.params,
      effective_from = excluded.effective_from,
      effective_to = excluded.effective_to,
      metadata = public.v2_route_capabilities.metadata || excluded.metadata,
      updated_at = now();
  end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION catalogue_private.apply_v2_admin_model_provider_routes (
  p_actor_user_id   uuid,
  p_model_slug      text,
  p_provider_models jsonb
)
  RETURNS void
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_route jsonb;
  v_existing public.v2_model_provider_routes%rowtype;
  v_requested_route_id text;
  v_route_id text;
  v_provider_slug text;
  v_provider_model_slug text;
  v_status text;
  v_routing_enabled boolean;
  v_provider_availability_status text;
  v_phaseo_status text;
  v_access_scope text;
  v_input_modalities text[];
  v_output_modalities text[];
  v_regions text[];
  v_context_length integer;
  v_max_output_tokens integer;
  v_effective_from timestamptz;
  v_effective_to timestamptz;
  v_metadata jsonb;
begin
  if not exists (
    select 1
    from public.users
    where user_id = p_actor_user_id
      and lower(coalesce(role::text, '')) = 'admin'
  ) then
    raise exception 'actor must have the admin role';
  end if;

  if jsonb_typeof(coalesce(p_provider_models, '[]'::jsonb)) <> 'array' then
    raise exception 'provider models must be an array';
  end if;

  if not exists (
    select 1 from public.v2_models where model_slug = p_model_slug
  ) then
    raise exception 'model not found';
  end if;

  for v_route in
    select value
    from jsonb_array_elements(coalesce(p_provider_models, '[]'::jsonb))
  loop
    v_existing := null;
    v_provider_slug := nullif(trim(coalesce(v_route->>'provider_id', v_route->>'provider_slug')), '');
    v_provider_model_slug := nullif(trim(coalesce(v_route->>'provider_model_slug', v_route->>'api_model_id')), '');
    v_requested_route_id := nullif(trim(coalesce(v_route->>'provider_model_id', v_route->>'id')), '');

    if v_provider_slug is null then
      raise exception 'provider id is required';
    end if;
    if v_provider_model_slug is null then
      raise exception 'provider model slug is required';
    end if;
    if not exists (
      select 1 from public.v2_providers where provider_slug = v_provider_slug
    ) then
      raise exception 'provider not found';
    end if;

    -- Resolve by the database key first, then by the natural route identity.
    -- This keeps an editor save from inserting a duplicate route when an
    -- older source adapter supplied a stale provider-model id.
    if v_requested_route_id is not null and v_requested_route_id not like 'new-%' then
      if exists (
        select 1
        from public.v2_model_provider_routes route
        where route.provider_model_id = v_requested_route_id
          and route.model_slug <> p_model_slug
      ) then
        raise exception 'provider model id belongs to another model';
      end if;

      select route.*
      into v_existing
      from public.v2_model_provider_routes route
      where route.provider_model_id = v_requested_route_id
        and route.model_slug = p_model_slug
      for update;
    end if;

    if v_existing.provider_model_id is null then
      select route.*
      into v_existing
      from public.v2_model_provider_routes route
      where route.model_slug = p_model_slug
        and route.provider_slug = v_provider_slug
        and route.provider_model_slug = v_provider_model_slug
      order by route.created_at, route.provider_model_id
      limit 1
      for update;
    end if;

    v_route_id := coalesce(
      v_existing.provider_model_id,
      case
        when v_requested_route_id is null or v_requested_route_id like 'new-%' then null
        else v_requested_route_id
      end,
      v_provider_slug || ':' || p_model_slug || ':' || v_provider_model_slug
    );

    v_status := lower(coalesce(
      nullif(trim(coalesce(v_route->>'status', v_route->>'routing_status')), ''),
      nullif(trim(v_existing.status), ''),
      'active'
    ));
    if v_status not in ('active', 'degraded', 'disabled', 'retired') then
      v_status := 'active';
    end if;

    v_routing_enabled := coalesce(
      nullif(v_route->>'is_active_gateway', '')::boolean,
      nullif(v_route->>'routing_enabled', '')::boolean,
      coalesce(v_existing.routing_enabled, false)
    );

    v_phaseo_status := lower(coalesce(
      nullif(trim(v_route->>'phaseo_status'), ''),
      nullif(trim(v_existing.phaseo_status), ''),
      case when v_routing_enabled then 'enabled' else 'disabled' end
    ));
    if v_routing_enabled and v_phaseo_status <> 'enabled' then
      if not (v_route ? 'phaseo_status') then
        v_phaseo_status := 'enabled';
      else
        raise exception 'routable provider routes require phaseo_status=enabled';
      end if;
    end if;

    -- The editor does not currently send provider availability. Preserve an
    -- existing deprecated route during its future-dated retirement window.
    v_provider_availability_status := lower(case
      when v_route ? 'provider_availability_status' then
        coalesce(nullif(trim(v_route->>'provider_availability_status'), ''), 'unknown')
      when v_existing.provider_model_id is not null then
        coalesce(nullif(trim(v_existing.provider_availability_status), ''), 'unknown')
      when v_routing_enabled then 'available'
      else 'unknown'
    end);
    if v_routing_enabled
       and v_provider_availability_status not in ('available', 'preview', 'limited_access', 'deprecated') then
      if not (v_route ? 'provider_availability_status') then
        v_provider_availability_status := 'available';
      else
        raise exception 'routable provider routes require an available provider';
      end if;
    end if;

    v_access_scope := lower(coalesce(
      nullif(trim(v_route->>'access_scope'), ''),
      nullif(trim(v_existing.access_scope), ''),
      'public'
    ));
    if v_routing_enabled and v_access_scope <> 'public' then
      raise exception 'routable provider routes must have public access scope';
    end if;

    v_input_modalities := case
      when v_route ? 'input_modalities' then case
        when jsonb_typeof(v_route->'input_modalities') = 'array' then
          array(select jsonb_array_elements_text(v_route->'input_modalities'))
        when nullif(trim(v_route->>'input_modalities'), '') is not null then
          string_to_array(v_route->>'input_modalities', ',')
        else '{}'::text[]
      end
      when v_existing.provider_model_id is not null then
        coalesce(v_existing.input_modalities, '{}'::text[])
      else '{}'::text[]
    end;
    v_output_modalities := case
      when v_route ? 'output_modalities' then case
        when jsonb_typeof(v_route->'output_modalities') = 'array' then
          array(select jsonb_array_elements_text(v_route->'output_modalities'))
        when nullif(trim(v_route->>'output_modalities'), '') is not null then
          string_to_array(v_route->>'output_modalities', ',')
        else '{}'::text[]
      end
      when v_existing.provider_model_id is not null then
        coalesce(v_existing.output_modalities, '{}'::text[])
      else '{}'::text[]
    end;
    v_regions := case
      when jsonb_typeof(v_route->'regions') = 'array' then
        array(select jsonb_array_elements_text(v_route->'regions'))
      when v_existing.provider_model_id is not null then
        coalesce(v_existing.regions, '{}'::text[])
      else '{}'::text[]
    end;
    v_context_length := case
      when v_route ? 'context_length' then nullif(v_route->>'context_length', '')::integer
      else v_existing.context_length
    end;
    v_max_output_tokens := case
      when v_route ? 'max_output_tokens' then nullif(v_route->>'max_output_tokens', '')::integer
      else v_existing.max_output_tokens
    end;
    v_effective_from := case
      when v_route ? 'effective_from' then nullif(v_route->>'effective_from', '')::timestamptz
      else v_existing.effective_from
    end;
    v_effective_to := case
      when v_route ? 'effective_to' then nullif(v_route->>'effective_to', '')::timestamptz
      else v_existing.effective_to
    end;
    v_metadata := jsonb_strip_nulls(jsonb_build_object(
      'prompt_training_policy_override', v_route->>'prompt_training_policy_override',
      'prompt_training_override_notes', v_route->>'prompt_training_override_notes',
      'prompt_training_override_source_url', v_route->>'prompt_training_override_source_url',
      'quantization_scheme', v_route->>'quantization_scheme',
      'source', 'admin'
    ));

    insert into public.v2_model_provider_routes(
      provider_model_id,
      model_slug,
      provider_slug,
      provider_model_slug,
      status,
      routing_enabled,
      input_modalities,
      output_modalities,
      regions,
      context_length,
      max_output_tokens,
      effective_from,
      effective_to,
      metadata,
      provider_availability_status,
      phaseo_status,
      access_scope,
      updated_at
    )
    values (
      v_route_id,
      p_model_slug,
      v_provider_slug,
      v_provider_model_slug,
      v_status,
      v_routing_enabled,
      v_input_modalities,
      v_output_modalities,
      v_regions,
      v_context_length,
      v_max_output_tokens,
      v_effective_from,
      v_effective_to,
      v_metadata,
      v_provider_availability_status,
      v_phaseo_status,
      v_access_scope,
      now()
    )
    on conflict (provider_model_id) do update set
      model_slug = excluded.model_slug,
      provider_slug = excluded.provider_slug,
      provider_model_slug = excluded.provider_model_slug,
      status = excluded.status,
      routing_enabled = excluded.routing_enabled,
      input_modalities = excluded.input_modalities,
      output_modalities = excluded.output_modalities,
      regions = excluded.regions,
      context_length = excluded.context_length,
      max_output_tokens = excluded.max_output_tokens,
      effective_from = excluded.effective_from,
      effective_to = excluded.effective_to,
      metadata = (
        coalesce(public.v2_model_provider_routes.metadata, '{}'::jsonb)
          - 'prompt_training_policy_override'
          - 'prompt_training_override_notes'
          - 'prompt_training_override_source_url'
          - 'quantization_scheme'
      ) || excluded.metadata,
      provider_availability_status = excluded.provider_availability_status,
      phaseo_status = excluded.phaseo_status,
      access_scope = excluded.access_scope,
      updated_at = now();
  end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION catalogue_private.history_model (
  p_row jsonb
)
  RETURNS text
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  select coalesce(p_row->>'model_slug',
    (select model_slug from public.v2_model_provider_routes where provider_model_id=p_row->>'provider_model_id'),
    (select r.model_slug from public.v2_pricing_skus s join public.v2_model_provider_routes r using(provider_model_id) where s.sku_id=(p_row->>'sku_id')::uuid));
$function$;

CREATE OR REPLACE FUNCTION catalogue_private.record_row_history()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public', 'pg_temp'
  AS $function$
begin
  if TG_OP='UPDATE' and to_jsonb(OLD)=to_jsonb(NEW) then return NEW; end if;
  insert into public.v2_catalogue_row_history(table_name,model_slug,operation,actor_user_id,before_state,after_state)
  values(TG_TABLE_NAME,catalogue_private.history_model(coalesce(to_jsonb(NEW),to_jsonb(OLD))),TG_OP,nullif(current_setting('phaseo.catalogue_actor',true),'')::uuid,
    case when TG_OP<>'INSERT' then to_jsonb(OLD) end,case when TG_OP<>'DELETE' then to_jsonb(NEW) end);
  return coalesce(NEW,OLD);
end $function$;

CREATE OR REPLACE FUNCTION private.capture_gateway_workspace_publication()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  old_row jsonb;
  new_row jsonb;
  target uuid;
begin
  if tg_op <> 'INSERT' then old_row := to_jsonb(old); end if;
  if tg_op <> 'DELETE' then new_row := to_jsonb(new); end if;
  -- Advisory BYOK usage updates must never create publication traffic.
  if tg_op = 'UPDATE' and
    (old_row - array['updated_at','last_used_at']) is not distinct from
    (new_row - array['updated_at','last_used_at']) then return null; end if;
  for target in
    select distinct id from (
      select case
        when tg_table_name = 'workspaces' then (r->>'id')::uuid
        when tg_table_name = 'key_guardrails' then
          (select g.workspace_id from public.workspace_guardrails g where g.id = (r->>'guardrail_id')::uuid)
        when tg_table_name = 'gateway_dynamic_route_keys' then
          (select d.workspace_id from public.gateway_dynamic_routes d where d.id = (r->>'route_id')::uuid)
        else (r->>'workspace_id')::uuid end as id
      from (values(old_row),(new_row)) rows(r) where r is not null
    ) targets where id is not null order by id
  loop
    perform private.enqueue_gateway_workspace_publication(target);
  end loop;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION private.drain_provider_health_refresh (
  p_limit integer DEFAULT 25
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  item record;
  provider_value text;
  completed integer := 0;
  completed_keys jsonb := '[]'::jsonb;
  failed_keys jsonb := '[]'::jsonb;
  started_at timestamptz := clock_timestamp();
begin
  -- Only workers take this lock. Ingestion never waits for a reporting scan.
  if not pg_try_advisory_xact_lock(hashtextextended('provider_health_refresh_worker', 0)) then return 0; end if;
  for item in select * from private.provider_health_refresh_queue
    where retry_after <= clock_timestamp()
    order by retry_after, usage_date, model_slug, provider_model_id
    limit greatest(1, least(coalesce(p_limit, 25), 25))
  loop
    exit when clock_timestamp() - started_at > interval '5 seconds';
    begin
      select provider_slug into provider_value from public.v2_model_provider_routes
        where provider_model_id = item.provider_model_id;
      -- Remove old provider-slug rows as well when route metadata was corrected.
      delete from public.v2_public_provider_health_daily
        where usage_date = item.usage_date and model_slug = item.model_slug
          and provider_model_id = item.provider_model_id;
      if provider_value is not null then
        insert into public.v2_public_provider_health_daily (
          usage_date, model_slug, provider_model_id, provider_slug, request_count,
          successful_request_count, attempt_count, successful_attempts, failed_attempts,
          fallback_attempts, latency_sum_ms, latency_count, updated_at
        )
        select item.usage_date, item.model_slug, item.provider_model_id, provider_value,
          count(distinct fact.request_event_id), count(distinct fact.request_event_id) filter (where attempt.success),
          count(*), count(*) filter (where attempt.success), count(*) filter (where not attempt.success),
          count(*) filter (where attempt.attempt_number > 1),
          coalesce(sum(attempt.latency_ms), 0), count(attempt.latency_ms), clock_timestamp()
        from public.v2_request_facts fact
        join public.v2_request_attempts attempt on attempt.request_event_id = fact.request_event_id
        where fact.occurred_at >= item.usage_date::timestamptz
          and fact.occurred_at < (item.usage_date + 1)::timestamptz
          and (fact.routed_model_slug = item.model_slug
            or (fact.routed_model_slug is null and fact.requested_model_slug = item.model_slug))
          and attempt.provider_model_id = item.provider_model_id
        having count(*) > 0;
      end if;
      completed_keys := completed_keys || jsonb_build_array(jsonb_build_object(
        'usage_date', item.usage_date, 'model_slug', item.model_slug,
        'provider_model_id', item.provider_model_id, 'generation', item.generation));
      completed := completed + 1;
    exception when query_canceled or lock_not_available or others then
      failed_keys := failed_keys || jsonb_build_array(jsonb_build_object(
        'usage_date', item.usage_date, 'model_slug', item.model_slug,
        'provider_model_id', item.provider_model_id, 'error_code', sqlstate));
    end;
  end loop;
  -- Acknowledge only after ALL scans. Earlier deletions would hold queue row
  -- locks across later scans and make new ingestion wait for reporting again.
  delete from private.provider_health_refresh_queue queue
  using jsonb_to_recordset(completed_keys) as done(
    usage_date date, model_slug text, provider_model_id text, generation bigint)
  where queue.usage_date = done.usage_date and queue.model_slug = done.model_slug
    and queue.provider_model_id = done.provider_model_id and queue.generation = done.generation;
  update private.provider_health_refresh_queue queue
    set retry_after = clock_timestamp() + interval '5 minutes', last_error_code = failed.error_code
  from jsonb_to_recordset(failed_keys) as failed(
    usage_date date, model_slug text, provider_model_id text, error_code text)
  where queue.usage_date = failed.usage_date and queue.model_slug = failed.model_slug
    and queue.provider_model_id = failed.provider_model_id;
  return completed;
end;
$function$;

CREATE OR REPLACE FUNCTION private.drain_public_reporting_refresh()
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare item record;
begin
  if not pg_try_advisory_xact_lock(hashtextextended('public-reporting-refresh-worker',0)) then return 0; end if;
  select q.report,q.bucket_start,array_agg(q.generation) as generations into item
  from private.public_reporting_refresh_queue q
  where not exists(select 1 from private.public_reporting_refresh_backoff b
    where b.report=q.report and b.bucket_start=q.bucket_start and b.retry_after>clock_timestamp())
  group by q.report,q.bucket_start order by min(q.requested_at),q.report,q.bucket_start limit 1;
  if not found then return 0; end if;
  begin
    if item.report='users_daily' then
      perform public.refresh_public_model_user_usage_daily(
        item.bucket_start::timestamp at time zone 'utc',(item.bucket_start+1)::timestamp at time zone 'utc');
    else
      perform public.refresh_public_model_workspace_usage_weekly(
        item.bucket_start::timestamp at time zone 'utc',(item.bucket_start+7)::timestamp at time zone 'utc');
    end if;
  exception when query_canceled or lock_not_available or others then
    insert into private.public_reporting_refresh_backoff values
      (item.report,item.bucket_start,clock_timestamp()+interval '2 hours',sqlstate)
    on conflict(report,bucket_start) do update set retry_after=excluded.retry_after,last_error_code=excluded.last_error_code;
    update private.public_reporting_refresh_queue
    set retry_after=clock_timestamp()+interval '2 hours',last_error_code=sqlstate
    where generation=any(item.generations);
    return 0;
  end;
  -- Capture exact visible IDs, not a sequence cutoff: an older sequence value
  -- can belong to a transaction that commits AFTER the source scan.
  delete from private.public_reporting_refresh_queue where generation=any(item.generations);
  delete from private.public_reporting_refresh_backoff where report=item.report and bucket_start=item.bucket_start;
  return 1;
end;
$function$;

CREATE OR REPLACE FUNCTION private.enforce_workspace_enterprise_member_capacity()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_member_limit integer;
  v_member_count bigint;
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('enterprise-member-limit:' || new.workspace_id::text, 0)
  );

  if exists (
    select 1 from public.workspace_members member
    where member.workspace_id = new.workspace_id and member.user_id = new.user_id
  ) then return new; end if;

  select subscription.included_members into v_member_limit
  from public.workspace_addon_subscriptions subscription
  where subscription.workspace_id = new.workspace_id
    and subscription.addon_key = 'identity'
    and subscription.included_members < 100000
    and (
      subscription.status in ('active', 'trialing')
      or (subscription.status = 'past_due' and subscription.grace_until > pg_catalog.now())
    );

  if v_member_limit is null then return new; end if;

  select pg_catalog.count(*) into v_member_count
  from public.workspace_members member where member.workspace_id = new.workspace_id;

  if v_member_count >= v_member_limit then
    raise exception using errcode = '23514', message = 'workspace_enterprise_member_limit_reached';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.enqueue_gateway_workspace_publication (
  p_workspace_id uuid
)
  RETURNS void
  LANGUAGE sql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  insert into public.gateway_workspace_publications as pending (workspace_id)
    select w.id from public.workspaces w where w.id = p_workspace_id
  on conflict (workspace_id) do update set
    revision = gen_random_uuid(), available_at = clock_timestamp(), attempts = 0;
  -- Preserve an active lease. Its acknowledgement must compare the revision.
$function$;

CREATE OR REPLACE FUNCTION private.enqueue_provider_health_for_fact()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare provider_value text;
begin
  if tg_op = 'UPDATE' and old.occurred_at::date is not distinct from new.occurred_at::date
    and coalesce(old.routed_model_slug, old.requested_model_slug) is not distinct from
        coalesce(new.routed_model_slug, new.requested_model_slug) then
    return new;
  end if;
  for provider_value in select distinct provider_model_id from public.v2_request_attempts
    where request_event_id = old.request_event_id and provider_model_id is not null
    order by provider_model_id
  loop
    perform private.enqueue_provider_health_refresh(old.occurred_at::date,
      coalesce(old.routed_model_slug, old.requested_model_slug), provider_value);
    if tg_op = 'UPDATE' then
      perform private.enqueue_provider_health_refresh(new.occurred_at::date,
        coalesce(new.routed_model_slug, new.requested_model_slug), provider_value);
    end if;
  end loop;
  if tg_op = 'UPDATE' then return new; end if;
  return old;
end;
$function$;

CREATE OR REPLACE FUNCTION private.enqueue_provider_health_refresh (
  p_date     date,
  p_model    text,
  p_provider text
)
  RETURNS void
  LANGUAGE sql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  insert into private.provider_health_refresh_queue (usage_date, model_slug, provider_model_id)
  select p_date, p_model, p_provider
  where p_date is not null and p_model is not null and p_provider is not null
  on conflict (usage_date, model_slug, provider_model_id) do update
    set generation = excluded.generation, requested_at = excluded.requested_at;
$function$;

CREATE OR REPLACE FUNCTION private.enqueue_public_reporting_for_fact()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if tg_op = 'UPDATE' and old is not distinct from new then return new; end if;
  if tg_op <> 'INSERT' then
    perform private.enqueue_public_reporting_refresh(old.occurred_at);
  end if;
  if tg_op <> 'DELETE' then
    if tg_op = 'INSERT' or new.occurred_at is distinct from old.occurred_at then
      perform private.enqueue_public_reporting_refresh(new.occurred_at);
    end if;
    return new;
  end if;
  return old;
end;
$function$;

CREATE OR REPLACE FUNCTION private.enqueue_public_reporting_for_request()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if row(old.api_model_id, old.pricing_plan, old.is_free_variant)
    is distinct from row(new.api_model_id, new.pricing_plan, new.is_free_variant) then
    perform private.enqueue_public_reporting_refresh(f.occurred_at)
    from public.v2_request_facts f
    where f.gateway_request_id = new.id and f.gateway_request_created_at = new.created_at;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.enqueue_public_reporting_for_usage()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if tg_op <> 'INSERT' then
    perform private.enqueue_public_reporting_refresh(f.occurred_at)
    from public.v2_request_facts f where f.request_event_id = old.request_event_id;
  end if;
  if tg_op <> 'DELETE' then
    if tg_op = 'INSERT' or new.request_event_id is distinct from old.request_event_id then
      perform private.enqueue_public_reporting_refresh(f.occurred_at)
      from public.v2_request_facts f where f.request_event_id = new.request_event_id;
    end if;
    return new;
  end if;
  return old;
end;
$function$;

CREATE OR REPLACE FUNCTION private.enqueue_public_reporting_refresh (
  p_occurred_at timestamp with time zone
)
  RETURNS void
  LANGUAGE sql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  insert into private.public_reporting_refresh_queue as queue(report,bucket_start)
  select 'users_daily',(p_occurred_at at time zone 'utc')::date where p_occurred_at is not null and coalesce(current_setting('phaseo.pruning_byok_metadata', true), '') <> 'on'
  union all
  select 'workspaces_weekly',date_trunc('week',p_occurred_at at time zone 'utc')::date where p_occurred_at is not null and coalesce(current_setting('phaseo.pruning_byok_metadata', true), '') <> 'on'
  on conflict(report,bucket_start,signal_shard) do update
  set generation=excluded.generation,transaction_id=excluded.transaction_id,requested_at=excluded.requested_at
  -- At most one update per period per ingestion transaction. 64 lanes spread
  -- concurrent transactions instead of serializing all writes on two tuples.
  where queue.transaction_id<>excluded.transaction_id;
$function$;

CREATE OR REPLACE FUNCTION private.enqueue_v2_analytics_correction (
  p_request_event_id uuid
)
  RETURNS void
  LANGUAGE sql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  insert into public.v2_analytics_outbox as outbox
    (request_event_id,workspace_id,occurred_at,status,attempt_count,available_at,last_error,updated_at)
  select request_event_id,workspace_id,occurred_at,'pending',0,now(),null,now()
  from public.v2_request_facts where request_event_id=p_request_event_id and coalesce(current_setting('phaseo.pruning_byok_metadata', true), '') <> 'on'
  on conflict(request_event_id) do update set workspace_id=excluded.workspace_id,
    occurred_at=excluded.occurred_at,status='pending',attempt_count=0,
    available_at=now(),last_error=null,updated_at=now()
  where outbox.status<>'pending' or outbox.workspace_id is distinct from excluded.workspace_id
    or outbox.occurred_at is distinct from excluded.occurred_at;
$function$;

CREATE OR REPLACE FUNCTION private.enqueue_v2_analytics_fact_correction()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if coalesce(current_setting('phaseo.pruning_byok_metadata',true),'')='on' then
    if tg_op='DELETE' then return old; end if;
    return new;
  end if;
  if coalesce(old.routed_model_slug,old.requested_model_slug) is not null and (tg_op='DELETE' or row(old.workspace_id,date_trunc('hour',old.occurred_at at time zone 'utc'),old.app_id,
    coalesce(old.routed_model_slug,old.requested_model_slug),old.provider_model_id,old.cloudflare_colo)
    is distinct from row(new.workspace_id,date_trunc('hour',new.occurred_at at time zone 'utc'),new.app_id,
    coalesce(new.routed_model_slug,new.requested_model_slug),new.provider_model_id,new.cloudflare_colo)) then
    insert into private.v2_analytics_previous_grains as queued(workspace_id,occurred_at,app_id,model_slug,provider_model_id,cloudflare_colo)
    values(old.workspace_id,date_trunc('hour',old.occurred_at at time zone 'utc') at time zone 'utc',old.app_id,
      coalesce(old.routed_model_slug,old.requested_model_slug),old.provider_model_id,old.cloudflare_colo)
    on conflict(workspace_id,occurred_at,app_id,model_slug,provider_model_id,cloudflare_colo) do update
    set grain_id=excluded.grain_id,transaction_id=excluded.transaction_id
    where queued.transaction_id<>excluded.transaction_id;
  end if;
  if tg_op='DELETE' then return old; end if;
  if old is distinct from new then perform private.enqueue_v2_analytics_correction(new.request_event_id); end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.enqueue_v2_analytics_meter_correction()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if tg_op<>'INSERT' then perform private.enqueue_v2_analytics_correction(old.request_event_id); end if;
  if tg_op<>'DELETE' then
    if tg_op='INSERT' or new.request_event_id is distinct from old.request_event_id then
      perform private.enqueue_v2_analytics_correction(new.request_event_id);
    end if;
    return new;
  end if;
  return old;
end;
$function$;

CREATE OR REPLACE FUNCTION private.gateway_compiled_context_access (
  workspace_id uuid,
  model        text,
  endpoint     text,
  api_key_id   uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  credit_status       jsonb;
  key_status          jsonb;
  key_limit_status    jsonb;
  min_balance_nanos bigint := case when endpoint like 'video.%' or endpoint like 'batch%' then 1000000000 else 100000000 end; -- 1.00 USD

  providers           jsonb;
  pricing             jsonb;
  preset_data         jsonb := null;

  -- key row fields
  v_key_active        boolean;
  v_key_team_ok       boolean;
  v_soft_blocked      boolean;

  v_day_req_limit     bigint;
  v_wk_req_limit      bigint;
  v_mo_req_limit      bigint;
  v_day_cost_limit    bigint;
  v_wk_cost_limit     bigint;
  v_mo_cost_limit     bigint;

  now_utc             timestamptz := (now() at time zone 'utc');
  day_start           timestamptz := date_trunc('day',  now_utc);
  week_start          timestamptz := date_trunc('week', now_utc);   -- Monday 00:00 UTC
  month_start         timestamptz := date_trunc('month', now_utc);

  used_day_reqs       bigint;
  used_wk_reqs        bigint;
  used_mo_reqs        bigint;
  used_day_cost       bigint;
  used_wk_cost        bigint;
  used_mo_cost        bigint;

  within_limits       boolean := true;
  limit_reason        text := null;
  limit_window        text := null;
  limit_metric        text := null;
  current_value       bigint := null;
  limit_value         bigint := null;
  limit_reset_at      timestamptz := null;

  -- Preset handling
  is_preset           boolean := false;
  preset_name         text := null;
  preset_publisher    text := null;

  -- Resolve model from alias if exists
  resolved_model      text := gateway_compiled_context_access.model;
  base_model          text;

  team_enrichment     jsonb;
  key_enrichment      jsonb;

  -- Team aggregates
  team_total_requests bigint;
  team_total_spend_nanos bigint;
  team_spend_24h_nanos bigint;
  team_spend_7d_nanos bigint;
  team_spend_30d_nanos bigint;
  team_requests_1h bigint;
  team_requests_24h bigint;
  team_created_at timestamptz;
  team_tier text;
  team_balance_nanos bigint;
  team_reserved_nanos bigint;

  -- Key aggregates
  key_name text;
  key_created_at timestamptz;
  key_total_requests bigint;
  key_total_spend_nanos bigint;
begin
  base_model := gateway_compiled_context_access.model;
  -- hard requirement: key must be provided
  if gateway_compiled_context_access.api_key_id is null then
    raise exception using errcode = '22023', message = 'missing_api_key', detail = 'api_key_id is required';
  end if;

  -- Check if model is a preset (starts with @)
  if base_model like '@%' then
    is_preset := true;
    preset_name := substring(base_model from 2); -- Remove @ prefix

    -- Fetch preset configuration. Qualified references resolve a
    -- public publisher globally; unqualified references remain workspace-local.
    if position('/' in preset_name) > 0 then
      preset_publisher := split_part(preset_name, '/', 1);
      preset_name := substring(preset_name from position('/' in preset_name) + 1);
      select jsonb_build_object(
        'id', p.id, 'name', p.name, 'slug', p.slug, 'description', p.description,
        'config', p.config, 'visibility', p.visibility, 'publisher', w.publisher_handle
      ) into preset_data
      from public.presets p
      join public.workspaces w on w.id = p.workspace_id
      where p.archived_at is null and lower(p.slug) = lower(preset_name)
        and p.visibility = 'public'
        and true
        and (lower(w.publisher_handle) = lower(preset_publisher) or exists (select 1 from public.workspace_publisher_handle_aliases alias where alias.workspace_id = w.id and alias.handle = lower(preset_publisher)))
      limit 1;
    else
      select jsonb_build_object(
        'id', p.id, 'name', p.name,
        'slug', coalesce(nullif(p.slug, ''), regexp_replace(p.name, '^@', '')),
        'description', p.description, 'config', p.config, 'visibility', p.visibility
      ) into preset_data
      from public.presets p
      where p.archived_at is null and lower(coalesce(nullif(p.slug, ''), regexp_replace(p.name, '^@', ''))) = lower(preset_name)
        and p.workspace_id = gateway_compiled_context_access.workspace_id
        and (
          p.visibility in ('public', 'team')
          or p.created_by = (
            select ak.created_by from public.keys ak
            where ak.id = gateway_compiled_context_access.api_key_id
              and ak.workspace_id = gateway_compiled_context_access.workspace_id
              and ak.status = 'active'
          )
        )
      limit 1;
    end if;

    if preset_data is null then
      raise exception using
        errcode = '22023',
        message = 'preset_not_found',
        detail = format('Preset "%s" not found or not accessible', preset_name);
    end if;

    -- Extract model from preset config (fallback to default/default_model/model/first models entry)
    base_model := coalesce(
      preset_data->'config'->>'defaultModel',
      preset_data->'config'->>'default_model',
      preset_data->'config'->>'model',
      preset_data->'config'->'models'->>0,
      preset_data->'config'->'allowedModels'->>0,
      preset_data->'config'->'allowed_models'->>0
    );

    if base_model is null then
      raise exception using
        errcode = '22023',
        message = 'preset_no_model',
        detail = format('Preset "%s" has no model configured', preset_name);
    end if;
  end if;

  resolved_model := base_model;

  -- validate key row, status, and team
  select
    (k.status = 'active'),
    (k.workspace_id = gateway_compiled_context_access.workspace_id),
    k.soft_blocked,
    k.daily_limit_requests,   k.weekly_limit_requests,   k.monthly_limit_requests,
    k.daily_limit_cost_nanos, k.weekly_limit_cost_nanos, k.monthly_limit_cost_nanos
  into
    v_key_active,
    v_key_team_ok,
    v_soft_blocked,
    v_day_req_limit, v_wk_req_limit, v_mo_req_limit,
    v_day_cost_limit, v_wk_cost_limit, v_mo_cost_limit
  from public.keys k
  where k.id = gateway_compiled_context_access.api_key_id
  limit 1;

  if v_key_active is null then
    raise exception using errcode = '22023', message = 'api_key_not_found', detail = 'key id does not exist';
  end if;
  if not v_key_team_ok then
    raise exception using errcode = '22023', message = 'api_key_wrong_team', detail = 'key does not belong to provided workspace_id';
  end if;
  if not v_key_active then
    raise exception using errcode = '22023', message = 'api_key_inactive', detail = 'key status is not active';
  end if;

  key_status := jsonb_build_object('ok', true, 'mode', 'first_party');

  -- credit check
  credit_status :=
    coalesce((
      select case
        when greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0) >= min_balance_nanos then
          jsonb_build_object(
            'ok', true,
            'balance_nanos', greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0),
            'raw_balance_nanos', coalesce(w.balance_nanos, 0)::bigint,
            'reserved_nanos', coalesce(w.reserved_nanos, 0)::bigint,
            'available_nanos', greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0)
          )
        else
          jsonb_build_object(
            'ok', false,
            'reason', 'insufficient_funds',
            'balance_nanos', greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0),
            'raw_balance_nanos', coalesce(w.balance_nanos, 0)::bigint,
            'reserved_nanos', coalesce(w.reserved_nanos, 0)::bigint,
            'available_nanos', greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0)
          )
      end
      from public.wallets w
      where w.workspace_id = gateway_compiled_context_access.workspace_id
      limit 1
    ), jsonb_build_object('ok', false, 'reason', 'wallet_missing'));

  -- per-key limits (requests + cost)
  select
    count(*) filter (where gr.created_at >= day_start)                                  as used_day_reqs,
    count(*) filter (where gr.created_at >= week_start)                                 as used_wk_reqs,
    count(*) filter (where gr.created_at >= month_start)                                as used_mo_reqs,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= day_start), 0)::bigint   as used_day_cost,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= week_start), 0)::bigint  as used_wk_cost,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= month_start), 0)::bigint as used_mo_cost
  into
    used_day_reqs, used_wk_reqs, used_mo_reqs,
    used_day_cost, used_wk_cost, used_mo_cost
  from public.gateway_requests gr
  where gr.key_id  = gateway_compiled_context_access.api_key_id
    and gr.workspace_id = gateway_compiled_context_access.workspace_id
    and gr.success is true
    and gr.created_at >= month_start;

  if v_soft_blocked then
    within_limits := false;
    limit_reason := 'key_limit_soft_blocked';
    limit_metric := 'soft_blocked';
  end if;
  if within_limits and v_day_req_limit > 0 and used_day_reqs >= v_day_req_limit then
    within_limits := false;
    limit_reason := 'daily_request_limit_reached';
    limit_window := 'daily';
    limit_metric := 'requests';
    current_value := used_day_reqs;
    limit_value := v_day_req_limit;
    limit_reset_at := day_start + interval '1 day';
  end if;
  if within_limits and v_wk_req_limit > 0 and used_wk_reqs >= v_wk_req_limit then
    within_limits := false;
    limit_reason := 'weekly_request_limit_reached';
    limit_window := 'weekly';
    limit_metric := 'requests';
    current_value := used_wk_reqs;
    limit_value := v_wk_req_limit;
    limit_reset_at := week_start + interval '1 week';
  end if;
  if within_limits and v_mo_req_limit > 0 and used_mo_reqs >= v_mo_req_limit then
    within_limits := false;
    limit_reason := 'monthly_request_limit_reached';
    limit_window := 'monthly';
    limit_metric := 'requests';
    current_value := used_mo_reqs;
    limit_value := v_mo_req_limit;
    limit_reset_at := month_start + interval '1 month';
  end if;
  if within_limits and v_day_cost_limit > 0 and used_day_cost >= v_day_cost_limit then
    within_limits := false;
    limit_reason := 'daily_cost_limit_reached';
    limit_window := 'daily';
    limit_metric := 'cost';
    current_value := used_day_cost;
    limit_value := v_day_cost_limit;
    limit_reset_at := day_start + interval '1 day';
  end if;
  if within_limits and v_wk_cost_limit > 0 and used_wk_cost >= v_wk_cost_limit then
    within_limits := false;
    limit_reason := 'weekly_cost_limit_reached';
    limit_window := 'weekly';
    limit_metric := 'cost';
    current_value := used_wk_cost;
    limit_value := v_wk_cost_limit;
    limit_reset_at := week_start + interval '1 week';
  end if;
  if within_limits and v_mo_cost_limit > 0 and used_mo_cost >= v_mo_cost_limit then
    within_limits := false;
    limit_reason := 'monthly_cost_limit_reached';
    limit_window := 'monthly';
    limit_metric := 'cost';
    current_value := used_mo_cost;
    limit_value := v_mo_cost_limit;
    limit_reset_at := month_start + interval '1 month';
  end if;

  key_limit_status :=
    jsonb_build_object(
      'ok', within_limits,
      'reason', limit_reason,
      'limit_window', limit_window,
      'limit_metric', limit_metric,
      'current_value', current_value,
      'limit_value', limit_value,
      'reset_at', to_jsonb(limit_reset_at),
      'now', to_jsonb(now_utc),
      'buckets', jsonb_build_object(
        'daily', jsonb_build_object(
          'window_start', to_jsonb(day_start),
          'requests_used', used_day_reqs,
          'requests_limit', v_day_req_limit,
          'cost_used_nanos', used_day_cost,
          'cost_limit_nanos', v_day_cost_limit
        ),
        'weekly', jsonb_build_object(
          'window_start', to_jsonb(week_start),
          'requests_used', used_wk_reqs,
          'requests_limit', v_wk_req_limit,
          'cost_used_nanos', used_wk_cost,
          'cost_limit_nanos', v_wk_cost_limit
        ),
        'monthly', jsonb_build_object(
          'window_start', to_jsonb(month_start),
          'requests_used', used_mo_reqs,
          'requests_limit', v_mo_req_limit,
          'cost_used_nanos', used_mo_cost,
          'cost_limit_nanos', v_mo_cost_limit
        )
      )
    );

  -- ============================================================================
  -- TEAM & KEY ENRICHMENT (Wide Event Context for Observability)
  -- Purpose: Gather user/team context for comprehensive logging (loggingsucks.com pattern)
  -- ============================================================================
  -- Team metadata & wallet
  select
    t.created_at,
    coalesce(t.tier, 'basic'),
    greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0),
    coalesce(w.reserved_nanos, 0)::bigint
  into
    team_created_at,
    team_tier,
    team_balance_nanos,
    team_reserved_nanos
  from public.workspaces t
  left join public.wallets w on w.workspace_id = t.id
  where t.id = gateway_compiled_context_access.workspace_id
  limit 1;

  -- Team spend & request aggregates
  select
    count(*),
    coalesce(sum(gr.cost_nanos), 0)::bigint,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= now_utc - interval '24 hours'), 0)::bigint,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= now_utc - interval '7 days'), 0)::bigint,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= now_utc - interval '30 days'), 0)::bigint,
    count(*) filter (where gr.created_at >= now_utc - interval '1 hour'),
    count(*) filter (where gr.created_at >= now_utc - interval '24 hours')
  into
    team_total_requests,
    team_total_spend_nanos,
    team_spend_24h_nanos,
    team_spend_7d_nanos,
    team_spend_30d_nanos,
    team_requests_1h,
    team_requests_24h
  from public.gateway_requests gr
  where gr.workspace_id = gateway_compiled_context_access.workspace_id
    and gr.success is true;

  -- Calculate tier using calendar-month qualification + lock-window grace.
  -- Function maintains team tier/counters in database when state changes.
  team_tier := public.calculate_tier_with_grace(gateway_compiled_context_access.workspace_id, team_spend_30d_nanos);

  team_enrichment := jsonb_build_object(
    'tier', team_tier,
    'created_at', to_jsonb(team_created_at),
    'account_age_days', extract(epoch from (now_utc - team_created_at)) / 86400,
    'balance_nanos', team_balance_nanos,
    'available_nanos', team_balance_nanos,
    'reserved_nanos', team_reserved_nanos,
    'balance_usd', round((team_balance_nanos::numeric / 1000000000.0)::numeric, 2),
    'balance_is_low', team_balance_nanos < min_balance_nanos,
    'total_requests', team_total_requests,
    'total_spend_nanos', team_total_spend_nanos,
    'total_spend_usd', round((team_total_spend_nanos::numeric / 1000000000.0)::numeric, 2),
    'spend_24h_nanos', team_spend_24h_nanos,
    'spend_24h_usd', round((team_spend_24h_nanos::numeric / 1000000000.0)::numeric, 4),
    'spend_7d_nanos', team_spend_7d_nanos,
    'spend_7d_usd', round((team_spend_7d_nanos::numeric / 1000000000.0)::numeric, 2),
    'spend_30d_nanos', team_spend_30d_nanos,
    'spend_30d_usd', round((team_spend_30d_nanos::numeric / 1000000000.0)::numeric, 2),
    'requests_1h', team_requests_1h,
    'requests_24h', team_requests_24h
  );

  -- Key metadata & aggregates
  select
    k.name,
    k.created_at
  into
    key_name,
    key_created_at
  from public.keys k
  where k.id = gateway_compiled_context_access.api_key_id
  limit 1;

  select
    count(*),
    coalesce(sum(gr.cost_nanos), 0)::bigint
  into
    key_total_requests,
    key_total_spend_nanos
  from public.gateway_requests gr
  where gr.key_id = gateway_compiled_context_access.api_key_id
    and gr.success is true;

  key_enrichment := jsonb_build_object(
    'name', key_name,
    'created_at', to_jsonb(key_created_at),
    'key_age_days', extract(epoch from (now_utc - key_created_at)) / 86400,
    'total_requests', key_total_requests,
    'total_spend_nanos', key_total_spend_nanos,
    'total_spend_usd', round((key_total_spend_nanos::numeric / 1000000000.0)::numeric, 2),
    'requests_today', used_day_reqs,
    'spend_today_nanos', used_day_cost,
    'spend_today_usd', round((used_day_cost::numeric / 1000000000.0)::numeric, 4),
    'daily_limit_pct', case
      when v_day_req_limit > 0 then round((used_day_reqs::numeric / v_day_req_limit::numeric * 100)::numeric, 1)
      else null
    end
  );

  providers := '[]'::jsonb;
  pricing := '{}'::jsonb;

  return jsonb_build_object(
    'workspace_id', gateway_compiled_context_access.workspace_id,
    'resolved_model', resolved_model,
    'preset', preset_data,
    'key_ok', key_status,
    'key_limit_ok', key_limit_status,
    'credit_ok', credit_status,
    'providers', providers,
    'pricing', pricing,
    'team_enrichment', team_enrichment,
    'key_enrichment', key_enrichment
  );
end;

$function$;

CREATE OR REPLACE FUNCTION private.gateway_context_access (
  workspace_id uuid,
  model        text,
  endpoint     text,
  api_key_id   uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  credit_status       jsonb;
  key_status          jsonb;
  key_limit_status    jsonb;
  min_balance_nanos bigint := case when endpoint like 'video.%' or endpoint like 'batch%' then 1000000000 else 100000000 end; -- 1.00 USD

  providers           jsonb;
  pricing             jsonb;
  preset_data         jsonb := null;

  -- key row fields
  v_key_active        boolean;
  v_key_team_ok       boolean;
  v_soft_blocked      boolean;

  v_day_req_limit     bigint;
  v_wk_req_limit      bigint;
  v_mo_req_limit      bigint;
  v_day_cost_limit    bigint;
  v_wk_cost_limit     bigint;
  v_mo_cost_limit     bigint;

  now_utc             timestamptz := (now() at time zone 'utc');
  day_start           timestamptz := date_trunc('day',  now_utc);
  week_start          timestamptz := date_trunc('week', now_utc);   -- Monday 00:00 UTC
  month_start         timestamptz := date_trunc('month', now_utc);

  used_day_reqs       bigint;
  used_wk_reqs        bigint;
  used_mo_reqs        bigint;
  used_day_cost       bigint;
  used_wk_cost        bigint;
  used_mo_cost        bigint;

  within_limits       boolean := true;
  limit_reason        text := null;
  limit_window        text := null;
  limit_metric        text := null;
  current_value       bigint := null;
  limit_value         bigint := null;
  limit_reset_at      timestamptz := null;

  -- Preset handling
  is_preset           boolean := false;
  preset_name         text := null;
  preset_publisher    text := null;

  -- Resolve model from alias if exists
  resolved_model      text := gateway_context_access.model;
  base_model          text;

  team_enrichment     jsonb;
  key_enrichment      jsonb;

  -- Team aggregates
  team_total_requests bigint;
  team_total_spend_nanos bigint;
  team_spend_24h_nanos bigint;
  team_spend_7d_nanos bigint;
  team_spend_30d_nanos bigint;
  team_requests_1h bigint;
  team_requests_24h bigint;
  team_created_at timestamptz;
  team_tier text;
  team_balance_nanos bigint;
  team_reserved_nanos bigint;

  -- Key aggregates
  key_name text;
  key_created_at timestamptz;
  key_total_requests bigint;
  key_total_spend_nanos bigint;
begin
  base_model := gateway_context_access.model;
  -- hard requirement: key must be provided
  if gateway_context_access.api_key_id is null then
    raise exception using errcode = '22023', message = 'missing_api_key', detail = 'api_key_id is required';
  end if;

  -- Check if model is a preset (starts with @)
  if base_model like '@%' then
    is_preset := true;
    preset_name := substring(base_model from 2); -- Remove @ prefix

    -- Fetch preset configuration. Qualified references resolve a
    -- public publisher globally; unqualified references remain workspace-local.
    if position('/' in preset_name) > 0 then
      preset_publisher := split_part(preset_name, '/', 1);
      preset_name := substring(preset_name from position('/' in preset_name) + 1);
      select jsonb_build_object(
        'id', p.id, 'name', p.name, 'slug', p.slug, 'description', p.description,
        'config', p.config, 'visibility', p.visibility, 'publisher', w.publisher_handle
      ) into preset_data
      from public.presets p
      join public.workspaces w on w.id = p.workspace_id
      where p.archived_at is null and lower(p.slug) = lower(preset_name)
        and p.visibility = 'public'
        and true
        and (lower(w.publisher_handle) = lower(preset_publisher) or exists (select 1 from public.workspace_publisher_handle_aliases alias where alias.workspace_id = w.id and alias.handle = lower(preset_publisher)))
      limit 1;
    else
      select jsonb_build_object(
        'id', p.id, 'name', p.name,
        'slug', coalesce(nullif(p.slug, ''), regexp_replace(p.name, '^@', '')),
        'description', p.description, 'config', p.config, 'visibility', p.visibility
      ) into preset_data
      from public.presets p
      where p.archived_at is null and lower(coalesce(nullif(p.slug, ''), regexp_replace(p.name, '^@', ''))) = lower(preset_name)
        and p.workspace_id = gateway_context_access.workspace_id
        and (
          p.visibility in ('public', 'team')
          or p.created_by = (
            select ak.created_by from public.keys ak
            where ak.id = gateway_context_access.api_key_id
              and ak.workspace_id = gateway_context_access.workspace_id
              and ak.status = 'active'
          )
        )
      limit 1;
    end if;

    if preset_data is null then
      raise exception using
        errcode = '22023',
        message = 'preset_not_found',
        detail = format('Preset "%s" not found or not accessible', preset_name);
    end if;

    -- Extract model from preset config (fallback to default/default_model/model/first models entry)
    base_model := coalesce(
      preset_data->'config'->>'defaultModel',
      preset_data->'config'->>'default_model',
      preset_data->'config'->>'model',
      preset_data->'config'->'models'->>0,
      preset_data->'config'->'allowedModels'->>0,
      preset_data->'config'->'allowed_models'->>0
    );

    if base_model is null then
      raise exception using
        errcode = '22023',
        message = 'preset_no_model',
        detail = format('Preset "%s" has no model configured', preset_name);
    end if;
  end if;

  -- Resolve alias/model indirection:
  -- 1) explicit alias table (`v2_model_aliases`)
  -- 2) provider-scoped slug form (`provider/provider_model_slug`)
  resolved_model := coalesce(
    (
      select a.api_model_id
      from (select alias_slug, model_slug as api_model_id, enabled as is_enabled from public.v2_model_aliases) a
      where a.alias_slug = base_model
        and a.is_enabled = true
        and a.api_model_id is not null
      limit 1
    ),
    (
      select m.api_model_id
      from (select provider_model_id as provider_api_model_id, provider_slug as provider_id, model_slug as api_model_id, model_slug as model_id, provider_model_slug, routing_enabled as is_active_gateway, status as routing_status, input_modalities, output_modalities, context_length, max_output_tokens, effective_from, effective_to, created_at, updated_at from public.v2_model_provider_routes) m
      where position('/' in base_model) > 0
        and m.provider_id = split_part(base_model, '/', 1)
        and m.provider_model_slug = regexp_replace(base_model, '^[^/]+/', '')
        and m.is_active_gateway
        and (m.effective_from is null or m.effective_from <= now() at time zone 'utc')
        and (m.effective_to   is null or (now() at time zone 'utc') < m.effective_to)
      order by coalesce(m.effective_from, to_timestamp(0)) desc, m.provider_api_model_id
      limit 1
    ),
    base_model
  );

  -- validate key row, status, and team
  select
    (k.status = 'active'),
    (k.workspace_id = gateway_context_access.workspace_id),
    k.soft_blocked,
    k.daily_limit_requests,   k.weekly_limit_requests,   k.monthly_limit_requests,
    k.daily_limit_cost_nanos, k.weekly_limit_cost_nanos, k.monthly_limit_cost_nanos
  into
    v_key_active,
    v_key_team_ok,
    v_soft_blocked,
    v_day_req_limit, v_wk_req_limit, v_mo_req_limit,
    v_day_cost_limit, v_wk_cost_limit, v_mo_cost_limit
  from public.keys k
  where k.id = gateway_context_access.api_key_id
  limit 1;

  if v_key_active is null then
    raise exception using errcode = '22023', message = 'api_key_not_found', detail = 'key id does not exist';
  end if;
  if not v_key_team_ok then
    raise exception using errcode = '22023', message = 'api_key_wrong_team', detail = 'key does not belong to provided workspace_id';
  end if;
  if not v_key_active then
    raise exception using errcode = '22023', message = 'api_key_inactive', detail = 'key status is not active';
  end if;

  key_status := jsonb_build_object('ok', true, 'mode', 'first_party');

  -- credit check
  credit_status :=
    coalesce((
      select case
        when greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0) >= min_balance_nanos then
          jsonb_build_object(
            'ok', true,
            'balance_nanos', greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0),
            'raw_balance_nanos', coalesce(w.balance_nanos, 0)::bigint,
            'reserved_nanos', coalesce(w.reserved_nanos, 0)::bigint,
            'available_nanos', greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0)
          )
        else
          jsonb_build_object(
            'ok', false,
            'reason', 'insufficient_funds',
            'balance_nanos', greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0),
            'raw_balance_nanos', coalesce(w.balance_nanos, 0)::bigint,
            'reserved_nanos', coalesce(w.reserved_nanos, 0)::bigint,
            'available_nanos', greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0)
          )
      end
      from public.wallets w
      where w.workspace_id = gateway_context_access.workspace_id
      limit 1
    ), jsonb_build_object('ok', false, 'reason', 'wallet_missing'));

  -- per-key limits (requests + cost)
  select
    count(*) filter (where gr.created_at >= day_start)                                  as used_day_reqs,
    count(*) filter (where gr.created_at >= week_start)                                 as used_wk_reqs,
    count(*) filter (where gr.created_at >= month_start)                                as used_mo_reqs,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= day_start), 0)::bigint   as used_day_cost,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= week_start), 0)::bigint  as used_wk_cost,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= month_start), 0)::bigint as used_mo_cost
  into
    used_day_reqs, used_wk_reqs, used_mo_reqs,
    used_day_cost, used_wk_cost, used_mo_cost
  from public.gateway_requests gr
  where gr.key_id  = gateway_context_access.api_key_id
    and gr.workspace_id = gateway_context_access.workspace_id
    and gr.success is true
    and gr.created_at >= month_start;

  if v_soft_blocked then
    within_limits := false;
    limit_reason := 'key_limit_soft_blocked';
    limit_metric := 'soft_blocked';
  end if;
  if within_limits and v_day_req_limit > 0 and used_day_reqs >= v_day_req_limit then
    within_limits := false;
    limit_reason := 'daily_request_limit_reached';
    limit_window := 'daily';
    limit_metric := 'requests';
    current_value := used_day_reqs;
    limit_value := v_day_req_limit;
    limit_reset_at := day_start + interval '1 day';
  end if;
  if within_limits and v_wk_req_limit > 0 and used_wk_reqs >= v_wk_req_limit then
    within_limits := false;
    limit_reason := 'weekly_request_limit_reached';
    limit_window := 'weekly';
    limit_metric := 'requests';
    current_value := used_wk_reqs;
    limit_value := v_wk_req_limit;
    limit_reset_at := week_start + interval '1 week';
  end if;
  if within_limits and v_mo_req_limit > 0 and used_mo_reqs >= v_mo_req_limit then
    within_limits := false;
    limit_reason := 'monthly_request_limit_reached';
    limit_window := 'monthly';
    limit_metric := 'requests';
    current_value := used_mo_reqs;
    limit_value := v_mo_req_limit;
    limit_reset_at := month_start + interval '1 month';
  end if;
  if within_limits and v_day_cost_limit > 0 and used_day_cost >= v_day_cost_limit then
    within_limits := false;
    limit_reason := 'daily_cost_limit_reached';
    limit_window := 'daily';
    limit_metric := 'cost';
    current_value := used_day_cost;
    limit_value := v_day_cost_limit;
    limit_reset_at := day_start + interval '1 day';
  end if;
  if within_limits and v_wk_cost_limit > 0 and used_wk_cost >= v_wk_cost_limit then
    within_limits := false;
    limit_reason := 'weekly_cost_limit_reached';
    limit_window := 'weekly';
    limit_metric := 'cost';
    current_value := used_wk_cost;
    limit_value := v_wk_cost_limit;
    limit_reset_at := week_start + interval '1 week';
  end if;
  if within_limits and v_mo_cost_limit > 0 and used_mo_cost >= v_mo_cost_limit then
    within_limits := false;
    limit_reason := 'monthly_cost_limit_reached';
    limit_window := 'monthly';
    limit_metric := 'cost';
    current_value := used_mo_cost;
    limit_value := v_mo_cost_limit;
    limit_reset_at := month_start + interval '1 month';
  end if;

  key_limit_status :=
    jsonb_build_object(
      'ok', within_limits,
      'reason', limit_reason,
      'limit_window', limit_window,
      'limit_metric', limit_metric,
      'current_value', current_value,
      'limit_value', limit_value,
      'reset_at', to_jsonb(limit_reset_at),
      'now', to_jsonb(now_utc),
      'buckets', jsonb_build_object(
        'daily', jsonb_build_object(
          'window_start', to_jsonb(day_start),
          'requests_used', used_day_reqs,
          'requests_limit', v_day_req_limit,
          'cost_used_nanos', used_day_cost,
          'cost_limit_nanos', v_day_cost_limit
        ),
        'weekly', jsonb_build_object(
          'window_start', to_jsonb(week_start),
          'requests_used', used_wk_reqs,
          'requests_limit', v_wk_req_limit,
          'cost_used_nanos', used_wk_cost,
          'cost_limit_nanos', v_wk_cost_limit
        ),
        'monthly', jsonb_build_object(
          'window_start', to_jsonb(month_start),
          'requests_used', used_mo_reqs,
          'requests_limit', v_mo_req_limit,
          'cost_used_nanos', used_mo_cost,
          'cost_limit_nanos', v_mo_cost_limit
        )
      )
    );

  -- ============================================================================
  -- TEAM & KEY ENRICHMENT (Wide Event Context for Observability)
  -- Purpose: Gather user/team context for comprehensive logging (loggingsucks.com pattern)
  -- ============================================================================
  -- Team metadata & wallet
  select
    t.created_at,
    coalesce(t.tier, 'basic'),
    greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0),
    coalesce(w.reserved_nanos, 0)::bigint
  into
    team_created_at,
    team_tier,
    team_balance_nanos,
    team_reserved_nanos
  from public.workspaces t
  left join public.wallets w on w.workspace_id = t.id
  where t.id = gateway_context_access.workspace_id
  limit 1;

  -- Team spend & request aggregates
  select
    count(*),
    coalesce(sum(gr.cost_nanos), 0)::bigint,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= now_utc - interval '24 hours'), 0)::bigint,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= now_utc - interval '7 days'), 0)::bigint,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= now_utc - interval '30 days'), 0)::bigint,
    count(*) filter (where gr.created_at >= now_utc - interval '1 hour'),
    count(*) filter (where gr.created_at >= now_utc - interval '24 hours')
  into
    team_total_requests,
    team_total_spend_nanos,
    team_spend_24h_nanos,
    team_spend_7d_nanos,
    team_spend_30d_nanos,
    team_requests_1h,
    team_requests_24h
  from public.gateway_requests gr
  where gr.workspace_id = gateway_context_access.workspace_id
    and gr.success is true;

  -- Calculate tier using calendar-month qualification + lock-window grace.
  -- Function maintains team tier/counters in database when state changes.
  team_tier := public.calculate_tier_with_grace(gateway_context_access.workspace_id, team_spend_30d_nanos);

  team_enrichment := jsonb_build_object(
    'tier', team_tier,
    'created_at', to_jsonb(team_created_at),
    'account_age_days', extract(epoch from (now_utc - team_created_at)) / 86400,
    'balance_nanos', team_balance_nanos,
    'available_nanos', team_balance_nanos,
    'reserved_nanos', team_reserved_nanos,
    'balance_usd', round((team_balance_nanos::numeric / 1000000000.0)::numeric, 2),
    'balance_is_low', team_balance_nanos < min_balance_nanos,
    'total_requests', team_total_requests,
    'total_spend_nanos', team_total_spend_nanos,
    'total_spend_usd', round((team_total_spend_nanos::numeric / 1000000000.0)::numeric, 2),
    'spend_24h_nanos', team_spend_24h_nanos,
    'spend_24h_usd', round((team_spend_24h_nanos::numeric / 1000000000.0)::numeric, 4),
    'spend_7d_nanos', team_spend_7d_nanos,
    'spend_7d_usd', round((team_spend_7d_nanos::numeric / 1000000000.0)::numeric, 2),
    'spend_30d_nanos', team_spend_30d_nanos,
    'spend_30d_usd', round((team_spend_30d_nanos::numeric / 1000000000.0)::numeric, 2),
    'requests_1h', team_requests_1h,
    'requests_24h', team_requests_24h
  );

  -- Key metadata & aggregates
  select
    k.name,
    k.created_at
  into
    key_name,
    key_created_at
  from public.keys k
  where k.id = gateway_context_access.api_key_id
  limit 1;

  select
    count(*),
    coalesce(sum(gr.cost_nanos), 0)::bigint
  into
    key_total_requests,
    key_total_spend_nanos
  from public.gateway_requests gr
  where gr.key_id = gateway_context_access.api_key_id
    and gr.success is true;

  key_enrichment := jsonb_build_object(
    'name', key_name,
    'created_at', to_jsonb(key_created_at),
    'key_age_days', extract(epoch from (now_utc - key_created_at)) / 86400,
    'total_requests', key_total_requests,
    'total_spend_nanos', key_total_spend_nanos,
    'total_spend_usd', round((key_total_spend_nanos::numeric / 1000000000.0)::numeric, 2),
    'requests_today', used_day_reqs,
    'spend_today_nanos', used_day_cost,
    'spend_today_usd', round((used_day_cost::numeric / 1000000000.0)::numeric, 4),
    'daily_limit_pct', case
      when v_day_req_limit > 0 then round((used_day_reqs::numeric / v_day_req_limit::numeric * 100)::numeric, 1)
      else null
    end
  );

  providers := '[]'::jsonb;
  pricing := '{}'::jsonb;

  return jsonb_build_object(
    'workspace_id', gateway_context_access.workspace_id,
    'resolved_model', resolved_model,
    'preset', preset_data,
    'key_ok', key_status,
    'key_limit_ok', key_limit_status,
    'credit_ok', credit_status,
    'providers', providers,
    'pricing', pricing,
    'team_enrichment', team_enrichment,
    'key_enrichment', key_enrichment
  );
end;

$function$;

CREATE OR REPLACE FUNCTION private.invalidate_routing_catalogue()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  update private.routing_catalogue_revision set revision=revision+1 where singleton;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION private.materialize_free_admission_usage()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
    admission jsonb := new.detail_metadata #> '{routing_diagnostics,freeQuota}';
    owner uuid;
    day date;
    used integer;
begin
    if admission is null or admission ->> 'admitted' is distinct from 'true' then return new; end if;
    -- Audit metadata is advisory. Invalid reporting must not break request audit.
    begin
        owner := (admission ->> 'ownerId')::uuid;
        day := (admission ->> 'utcDay')::date;
        used := (admission ->> 'used')::integer;
    exception when invalid_text_representation or datetime_field_overflow or invalid_datetime_format or numeric_value_out_of_range then
        return new;
    end;
    if owner is null or day is null or used is null or used not between 1 and 1500 then return new; end if;
    -- Cumulative admission sequence makes duplicate and out-of-order audit delivery
    -- idempotent and recovers earlier missing audit events on the next delivery.
    insert into public.free_model_usage_daily(owner_id, usage_date, included_requests)
    values (owner, day, used)
    on conflict (owner_id, usage_date) do update
      set included_requests = excluded.included_requests, updated_at = now()
      where public.free_model_usage_daily.included_requests < excluded.included_requests;
    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.project_routing_catalogue_row (
  input jsonb
)
  RETURNS jsonb
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) || jsonb_build_object('metadata',
  (select coalesce(jsonb_object_agg(key,value),'{}'::jsonb)
   from jsonb_each(case when jsonb_typeof(input->'metadata')='object' then input->'metadata' else '{}'::jsonb end)
   where key in ('availability','self_serve','quantization_scheme','match','priority',
     'included_quantity','billing_timestamp_basis','time_windows')))
from jsonb_each(input) where key in (
 'model_slug','provider_slug','provider_model_id','variant_id','sku_id','sku_meter_id',
 'provider_region_id','service_tier_slug','capability_id','alias_slug','enabled',
 'status','hidden','access_scope','is_stealth','availability','provider_availability_status',
 'phaseo_status','available_from','effective_from','effective_to','released_at','retired_at',
 'routable','routing_enabled','route_variant_id','region','execution_region','data_region',
 'region_code','execution_supported','data_residency_supported','currency','operation',
 'billable','meter_key','unit','unit_quantity','price_nanos','meter_order','params',
 'regions','default_execution_regions','default_data_regions','provider_family_slug',
 'provider_model_slug','context_length','max_input_tokens','max_output_tokens',
 'input_modalities','output_modalities','zero_data_retention','credential_mode',
 'residency_mode','prompt_training_policy','data_policy_tier','data_policy_confidence',
 'data_policy_contract_mode','data_policy_variant','stream_cancellation_support',
 'stream_cancellation_stops_provider_billing','stream_cancellation_usage_recovery',
 'stream_cancellation_evidence_kind','benchmark_id','score_numeric','is_self_reported'
);
$function$;

CREATE OR REPLACE FUNCTION private.record_workspace_enterprise_member_overage()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_period_start date;
  v_included_members integer;
  v_monthly_unique_members bigint;
  v_overage_count bigint;
begin
  select subscription.included_members,
         coalesce(subscription.current_period_start::date, pg_catalog.date_trunc('month', pg_catalog.now() at time zone 'UTC')::date)
  into v_included_members, v_period_start
  from public.workspace_addon_subscriptions subscription
  where subscription.workspace_id = new.workspace_id
    and subscription.addon_key = 'identity'
    and subscription.included_members >= 100000
    and (
      subscription.status in ('active', 'trialing')
      or (subscription.status = 'past_due' and subscription.grace_until > pg_catalog.now())
    );

  if v_included_members is null then return new; end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('enterprise-member-overage:' || new.workspace_id::text || ':' || v_period_start::text, 0)
  );

  if not exists (
    select 1 from public.workspace_enterprise_member_overages usage
    where usage.workspace_id = new.workspace_id and usage.period_start = v_period_start
  ) then
    insert into public.workspace_enterprise_member_overages (workspace_id, period_start, user_id)
    select member.workspace_id, v_period_start, member.user_id
    from public.workspace_members member
    where member.workspace_id = new.workspace_id
    on conflict do nothing;
  end if;

  insert into public.workspace_enterprise_member_overages (workspace_id, period_start, user_id)
  values (new.workspace_id, v_period_start, new.user_id)
  on conflict do nothing;

  select pg_catalog.count(*) into v_monthly_unique_members
  from public.workspace_enterprise_member_overages usage
  where usage.workspace_id = new.workspace_id and usage.period_start = v_period_start;

  v_overage_count := greatest(v_monthly_unique_members - v_included_members, 0);

  insert into public.workspace_addon_usage_monthly as usage_monthly (
    workspace_id, addon_key, metric_key, period_start, quantity, updated_at
  ) values (
    new.workspace_id, 'identity', 'member_overage', v_period_start, v_overage_count, pg_catalog.now()
  )
  on conflict (workspace_id, addon_key, metric_key, period_start) do update set
    quantity = greatest(usage_monthly.quantity, excluded.quantity),
    updated_at = excluded.updated_at;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.seed_workspace_enterprise_member_overages()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_period_start date := coalesce(new.current_period_start::date, pg_catalog.date_trunc('month', pg_catalog.now() at time zone 'UTC')::date);
  v_monthly_unique_members bigint;
  v_overage_count bigint;
begin
  if new.addon_key <> 'identity'
     or new.included_members < 100000
     or not (
       new.status in ('active', 'trialing')
       or (new.status = 'past_due' and new.grace_until > pg_catalog.now())
     ) then
    return new;
  end if;

  insert into public.workspace_enterprise_member_overages (workspace_id, period_start, user_id)
  select member.workspace_id, v_period_start, member.user_id
  from public.workspace_members member
  where member.workspace_id = new.workspace_id
  on conflict do nothing;

  select pg_catalog.count(*) into v_monthly_unique_members
  from public.workspace_enterprise_member_overages usage
  where usage.workspace_id = new.workspace_id and usage.period_start = v_period_start;

  v_overage_count := greatest(v_monthly_unique_members - new.included_members, 0);

  insert into public.workspace_addon_usage_monthly as usage_monthly (
    workspace_id, addon_key, metric_key, period_start, quantity, updated_at
  ) values (
    new.workspace_id, 'identity', 'member_overage', v_period_start, v_overage_count, pg_catalog.now()
  )
  on conflict (workspace_id, addon_key, metric_key, period_start) do update set
    quantity = greatest(usage_monthly.quantity, excluded.quantity),
    updated_at = excluded.updated_at;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.acknowledge_model_discovery_issue_signals (
  p_entries jsonb
)
  RETURNS integer
  LANGUAGE sql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  with acknowledged as (
    update public.model_discovery_issue_signals signal
    set emitted_at = now()
    where signal.action = 'delete'
      and signal.emitted_at is null
      and exists (
        select 1
        from jsonb_array_elements(coalesce(p_entries, '[]'::jsonb)) entry(value)
        where entry.value ->> 'source' = signal.source
          and entry.value ->> 'providerId' = signal.provider_id
          and entry.value ->> 'action' = signal.action
          and entry.value ->> 'modelId' = signal.model_id
      )
    returning 1
  )
  select count(*)::integer from acknowledged;
$function$;

REVOKE ALL ON FUNCTION "public"."acknowledge_model_discovery_issue_signals"(jsonb) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.activate_due_provider_catalog_releases()
  RETURNS integer
  LANGUAGE plpgsql
  SET search_path TO 'public'
  AS $function$
declare
  activated_count integer := 0;
  activated_route_ids text[] := '{}';
begin
  with due as (
    select route.provider_model_id,
      case when candidate.availability = 'ready' then 'active' else 'degraded' end as next_status
    from public.v2_model_provider_routes route
    join public.provider_catalog_route_candidates candidate
      on candidate.provider_slug = route.provider_slug
     and candidate.canonical_model_slug = route.model_slug
     and candidate.provider_model_slug = route.provider_model_slug
     and route.metadata ->> 'source_run_id' = candidate.run_id::text
    where candidate.status = 'promoted'
      and candidate.availability in ('ready', 'degraded')
      and route.metadata ->> 'managed_by' = 'provider_catalog'
      and route.metadata ->> 'release_scheduled' = 'true'
      and route.access_scope = 'internal'
      and route.effective_from is not null
      and route.effective_from <= now()
      and (route.effective_to is null or route.effective_to > now())
      and not route.is_stealth
      and not exists (
        select 1 from public.v2_model_provider_routes stealth_route
        where stealth_route.model_slug = route.model_slug and stealth_route.is_stealth
      )
      and exists (
        select 1 from public.v2_providers provider
        where provider.provider_slug = route.provider_slug
          and (provider.status = 'not_ready' or (provider.status <> 'disabled' and provider.routable and provider.routing_enabled))
          and (not (coalesce(provider.metadata, '{}'::jsonb) ? 'self_serve')
            or provider.metadata -> 'self_serve' ->> 'provider_review_status' = 'approved')
          and coalesce((provider.metadata ->> 'adapter_ready')::boolean, false)
          and coalesce((provider.metadata ->> 'credentials_ready')::boolean, false)
          and nullif(trim(provider.base_url), '') is not null
      )
    for update of route skip locked
  ), activated as (
    update public.v2_model_provider_routes route
    set status = due.next_status,
        routing_enabled = true,
        provider_availability_status = case when due.next_status = 'active' then 'available' else 'preview' end,
        phaseo_status = 'enabled', access_scope = 'public',
        metadata = route.metadata || jsonb_build_object('release_scheduled', false, 'release_activated_at', now()),
        updated_at = now()
    from due where route.provider_model_id = due.provider_model_id
    returning route.provider_model_id
  ) select coalesce(array_agg(provider_model_id), '{}'::text[]) into activated_route_ids from activated;
  activated_count := cardinality(activated_route_ids);

  update public.v2_route_variants variant
  set status = route.status, routing_enabled = true, updated_at = now()
  from public.v2_model_provider_routes route
  where route.provider_model_id = variant.provider_model_id
    and route.provider_model_id = any(activated_route_ids)
    and route.metadata ->> 'managed_by' = 'provider_catalog'
    and route.metadata ->> 'release_scheduled' = 'false'
    and route.metadata ->> 'release_activated_at' is not null
    and variant.metadata ->> 'managed_by' = 'provider_catalog'
    and variant.metadata ->> 'source_run_id' = route.metadata ->> 'source_run_id';

  update public.v2_route_capabilities capability
  set status = case when route.status = 'active' then 'active' else 'degraded' end, updated_at = now()
  from public.v2_model_provider_routes route
  where route.provider_model_id = capability.provider_model_id
    and route.provider_model_id = any(activated_route_ids)
    and route.metadata ->> 'managed_by' = 'provider_catalog'
    and route.metadata ->> 'release_scheduled' = 'false'
    and route.metadata ->> 'release_activated_at' is not null
    and capability.metadata ->> 'managed_by' = 'provider_catalog'
    and capability.metadata ->> 'source_run_id' = route.metadata ->> 'source_run_id';

  update public.v2_providers provider
  set status = case
        when provider.status = 'not_ready'
          or (provider.status = 'disabled' and provider.metadata -> 'self_serve' ->> 'status' = 'submitted')
          then 'beta'
        else provider.status
      end,
      routable = true, routing_enabled = true, updated_at = now()
  where (not (coalesce(provider.metadata, '{}'::jsonb) ? 'self_serve')
      or provider.metadata -> 'self_serve' ->> 'provider_review_status' = 'approved')
    and provider.provider_slug in (
      select distinct route.provider_slug
      from public.v2_model_provider_routes route
      where route.metadata ->> 'managed_by' = 'provider_catalog'
        and route.provider_model_id = any(activated_route_ids)
        and route.metadata ->> 'release_scheduled' = 'false'
        and route.metadata ->> 'release_activated_at' is not null
    );

  update public.v2_models model
  set hidden = false, released_at = coalesce(model.released_at, route.effective_from, now()), updated_at = now()
  from public.v2_model_provider_routes route
  where route.model_slug = model.model_slug
    and route.provider_model_id = any(activated_route_ids)
    and model.metadata ->> 'created_from_provider_proposal' = 'true'
    and route.metadata ->> 'managed_by' = 'provider_catalog'
    and route.metadata ->> 'release_scheduled' = 'false'
    and route.metadata ->> 'release_activated_at' is not null;

  update public.v2_labs lab
  set status = case when lab.status = 'disabled' then 'active' else lab.status end, updated_at = now()
  where lab.lab_slug in (
    select distinct model.lab_slug
    from public.v2_models model
    join public.v2_model_provider_routes route on route.model_slug = model.model_slug
    where model.metadata ->> 'created_from_provider_proposal' = 'true'
      and route.provider_model_id = any(activated_route_ids)
      and route.metadata ->> 'managed_by' = 'provider_catalog'
      and route.metadata ->> 'release_scheduled' = 'false'
      and route.metadata ->> 'release_activated_at' is not null
  );

  return activated_count;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."activate_due_provider_catalog_releases"() FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.api_app_public_slug (
  p_title  text,
  p_url    text,
  p_app_id text
)
  RETURNS text
  LANGUAGE sql
  IMMUTABLE
  PARALLEL SAFE
  SET search_path TO ''
  AS $function$
  select public.api_app_slug_base(p_title) || '--' || left(md5(coalesce(p_app_id, '')), 12);
$function$;

REVOKE ALL ON FUNCTION "public"."api_app_public_slug"(text, text, text) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.api_app_slug_base (
  p_title text
)
  RETURNS text
  LANGUAGE sql
  IMMUTABLE
  PARALLEL SAFE
  SET search_path TO ''
  AS $function$
  select coalesce(
    nullif(
      trim(both '-' from regexp_replace(lower(coalesce(p_title, '')), '[^a-z0-9]+', '-', 'g')),
      ''
    ),
    'app'
  );
$function$;

REVOKE ALL ON FUNCTION "public"."api_app_slug_base"(text) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.api_app_url_group_key (
  p_url    text,
  p_app_id text
)
  RETURNS text
  LANGUAGE sql
  IMMUTABLE
  PARALLEL SAFE
  SET search_path TO ''
  AS $function$
  select coalesce(
    nullif(lower(regexp_replace(btrim(coalesce(p_url, '')), '/+$', '')), ''),
    'app-id:' || p_app_id
  );
$function$;

CREATE OR REPLACE FUNCTION public.apply_preset_upstream_version (
  target_preset_id  uuid,
  target_version_id uuid,
  actor_user_id     uuid
)
  RETURNS public.presets
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  p public.presets%rowtype;
  source public.presets%rowtype;
  upstream public.preset_versions%rowtype;
  updated public.presets%rowtype;
begin
  select * into p from public.presets where id = target_preset_id and archived_at is null for update;
  if not found or p.created_by <> actor_user_id then raise exception 'preset_update_forbidden'; end if;
  if p.source_preset_id is null then raise exception 'preset_has_no_upstream'; end if;
  if p.draft_name is distinct from p.name
    or p.draft_slug is distinct from p.slug
    or p.draft_description is distinct from p.description
    or p.draft_config is distinct from p.config
    or p.draft_visibility is distinct from p.visibility
  then raise exception 'preset_has_local_draft_changes'; end if;

  select * into source from public.presets
  where id = p.source_preset_id and visibility = 'public' and archived_at is null;
  if not found then raise exception 'upstream_preset_not_public'; end if;

  select * into upstream from public.preset_versions
  where id = target_version_id and preset_id = source.id and visibility = 'public';
  if not found then raise exception 'upstream_version_not_public'; end if;

  update public.presets set draft_name = upstream.name, draft_slug = upstream.slug,
    draft_description = upstream.description, draft_config = upstream.config,
    upstream_version_id = upstream.id, updated_at = now()
  where id = p.id returning * into updated;
  return updated;
end $function$;

REVOKE ALL ON FUNCTION "public"."apply_preset_upstream_version"(uuid, uuid, uuid) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.apply_provider_catalog_snapshot (
  p_provider_slug text,
  p_run_id        uuid,
  p_models        jsonb
)
  RETURNS integer
  LANGUAGE plpgsql
  SET search_path TO 'public'
  AS $function$
declare
  model jsonb;
  capability jsonb;
  applied_count integer := 0;
  model_slug_value text;
  capability_id_value text;
begin
  update public.provider_catalog_models
  set status = 'removed', updated_at = now(), source_run_id = p_run_id
  where provider_slug = p_provider_slug
    and status = 'active'
    and not exists (
      select 1
      from jsonb_array_elements(p_models) as incoming(value)
      where incoming.value ->> 'id' = provider_catalog_models.model_slug
    );

  update public.provider_catalog_model_capabilities
  set status = 'removed', source_run_id = p_run_id, observed_at = now()
  where provider_slug = p_provider_slug;

  for model in select value from jsonb_array_elements(p_models)
  loop
    model_slug_value := model ->> 'id';

    insert into public.provider_catalog_sync_models (
      run_id, provider_slug, model_slug, provider_model_slug, name, description,
      input_modalities, output_modalities, context_length, max_output_tokens,
      availability, available_from, deprecated_at, shutdown_at, metadata
    ) values (
      p_run_id,
      p_provider_slug,
      model_slug_value,
      coalesce(nullif(model ->> 'providerModelSlug', ''), model_slug_value),
      coalesce(nullif(model ->> 'name', ''), model_slug_value),
      nullif(model ->> 'description', ''),
      coalesce(array(select jsonb_array_elements_text(model -> 'inputModalities')), '{}'::text[]),
      coalesce(array(select jsonb_array_elements_text(model -> 'outputModalities')), '{}'::text[]),
      nullif(model ->> 'contextLength', '')::integer,
      nullif(model ->> 'maxOutputTokens', '')::integer,
      coalesce(nullif(model ->> 'availability', ''), 'ready'),
      nullif(model ->> 'availableFrom', '')::timestamptz,
      nullif(model ->> 'deprecatedAt', '')::timestamptz,
      nullif(model ->> 'shutdownAt', '')::timestamptz,
      jsonb_build_object('pricing', coalesce(model -> 'pricing', '[]'::jsonb))
    )
    on conflict (run_id, model_slug) do update set
      provider_model_slug = excluded.provider_model_slug,
      name = excluded.name,
      description = excluded.description,
      input_modalities = excluded.input_modalities,
      output_modalities = excluded.output_modalities,
      context_length = excluded.context_length,
      max_output_tokens = excluded.max_output_tokens,
      availability = excluded.availability,
      available_from = excluded.available_from,
      deprecated_at = excluded.deprecated_at,
      shutdown_at = excluded.shutdown_at,
      metadata = excluded.metadata;

    insert into public.provider_catalog_models (
      provider_slug, model_slug, provider_model_slug, name, description,
      input_modalities, output_modalities, context_length, max_output_tokens,
      availability, available_from, deprecated_at, shutdown_at,
      status, last_seen_at, source_run_id, metadata, updated_at
    ) values (
      p_provider_slug,
      model_slug_value,
      coalesce(nullif(model ->> 'providerModelSlug', ''), model_slug_value),
      coalesce(nullif(model ->> 'name', ''), model_slug_value),
      nullif(model ->> 'description', ''),
      coalesce(array(select jsonb_array_elements_text(model -> 'inputModalities')), '{}'::text[]),
      coalesce(array(select jsonb_array_elements_text(model -> 'outputModalities')), '{}'::text[]),
      nullif(model ->> 'contextLength', '')::integer,
      nullif(model ->> 'maxOutputTokens', '')::integer,
      coalesce(nullif(model ->> 'availability', ''), 'ready'),
      nullif(model ->> 'availableFrom', '')::timestamptz,
      nullif(model ->> 'deprecatedAt', '')::timestamptz,
      nullif(model ->> 'shutdownAt', '')::timestamptz,
      'active', now(), p_run_id,
      jsonb_build_object('pricing', coalesce(model -> 'pricing', '[]'::jsonb)),
      now()
    )
    on conflict (provider_slug, model_slug) do update set
      provider_model_slug = excluded.provider_model_slug,
      name = excluded.name,
      description = excluded.description,
      input_modalities = excluded.input_modalities,
      output_modalities = excluded.output_modalities,
      context_length = excluded.context_length,
      max_output_tokens = excluded.max_output_tokens,
      availability = excluded.availability,
      available_from = excluded.available_from,
      deprecated_at = excluded.deprecated_at,
      shutdown_at = excluded.shutdown_at,
      status = 'active',
      last_seen_at = now(),
      source_run_id = excluded.source_run_id,
      metadata = excluded.metadata,
      updated_at = now();

    for capability in select value from jsonb_array_elements(coalesce(model -> 'capabilities', '[]'::jsonb))
    loop
      capability_id_value := capability ->> 'id';

      insert into public.provider_catalog_sync_model_capabilities (
        run_id, model_slug, capability_id, parameters
      ) values (
        p_run_id,
        model_slug_value,
        capability_id_value,
        coalesce(array(select jsonb_array_elements_text(capability -> 'parameters')), '{}'::text[])
      )
      on conflict (run_id, model_slug, capability_id) do update set
        parameters = excluded.parameters;

      insert into public.provider_catalog_model_capabilities (
        provider_slug, model_slug, capability_id, parameters, status, source_run_id, observed_at
      ) values (
        p_provider_slug,
        model_slug_value,
        capability_id_value,
        coalesce(array(select jsonb_array_elements_text(capability -> 'parameters')), '{}'::text[]),
        'active', p_run_id, now()
      )
      on conflict (provider_slug, model_slug, capability_id) do update set
        parameters = excluded.parameters,
        status = 'active',
        source_run_id = excluded.source_run_id,
        observed_at = now();
    end loop;

    applied_count := applied_count + 1;
  end loop;

  return applied_count;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."apply_provider_catalog_snapshot"(text, uuid, jsonb) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.apply_workspace_member_override (
  p_workspace_id                uuid,
  p_user_id                     uuid,
  p_access_role                 text,
  p_department_override_enabled boolean,
  p_department_id               uuid,
  p_department_position         text,
  p_actor_user_id               uuid,
  p_request_id                  text    DEFAULT NULL::text
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare before_row jsonb; after_row jsonb; owner_id uuid;
begin
  select owner_user_id into owner_id from public.workspaces where id=p_workspace_id;
  if owner_id is null then raise exception 'Workspace not found'; end if;
  if not exists(select 1 from public.workspace_members where workspace_id=p_workspace_id and user_id=p_user_id) then
    raise exception 'Workspace member not found';
  end if;
  if p_user_id=owner_id and (p_access_role is not null or p_department_override_enabled) then
    raise exception 'Workspace owner cannot be overridden';
  end if;
  if p_access_role is not null and p_access_role not in ('member','admin') then raise exception 'Invalid access role'; end if;
  if p_department_override_enabled and p_department_id is not null
     and not exists(select 1 from public.workspace_departments where id=p_department_id and workspace_id=p_workspace_id) then
    raise exception 'Department not found';
  end if;
  select to_jsonb(o) into before_row from public.workspace_member_overrides o where workspace_id=p_workspace_id and user_id=p_user_id;

  if p_access_role is null and not p_department_override_enabled then
    delete from public.workspace_member_overrides where workspace_id=p_workspace_id and user_id=p_user_id;
  else
    insert into public.workspace_member_overrides(workspace_id,user_id,access_role,department_override_enabled,department_id,department_position,updated_by)
    values(p_workspace_id,p_user_id,p_access_role,coalesce(p_department_override_enabled,false),
      case when p_department_override_enabled then p_department_id else null end,
      case when p_department_override_enabled then coalesce(p_department_position,'member') else null end,p_actor_user_id)
    on conflict(workspace_id,user_id) do update set access_role=excluded.access_role,
      department_override_enabled=excluded.department_override_enabled,department_id=excluded.department_id,
      department_position=excluded.department_position,updated_by=excluded.updated_by,updated_at=now();
  end if;

  perform public.reconcile_scim_entitlements(p_workspace_id);
	perform set_config('phaseo.entitlement_reconcile','on',true);
	update public.workspace_members wm set role=o.access_role::public.workspace_role
	from public.workspace_member_overrides o
	where wm.workspace_id=p_workspace_id and wm.workspace_id=o.workspace_id and wm.user_id=o.user_id and o.access_role is not null
	  and lower(wm.role::text) is distinct from o.access_role;
  perform public.refresh_workspace_effective_entitlements(p_workspace_id,p_actor_user_id,'manual_override');
  select to_jsonb(o) into after_row from public.workspace_member_overrides o where workspace_id=p_workspace_id and user_id=p_user_id;
  insert into public.workspace_directory_audit_events(workspace_id,actor_user_id,action,target_type,target_id,before_state,after_state,request_id)
  values(p_workspace_id,p_actor_user_id,'workspace.member.override','workspace_member',p_user_id::text,before_row,after_row,p_request_id);
end;
$function$;

