CREATE OR REPLACE FUNCTION public.calculate_workspace_previous_month_spend (
  p_team_id uuid
)
  RETURNS numeric
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public', 'pg_temp'
  AS $function$
DECLARE
    v_spend_nanos bigint;
    v_spend_usd numeric(12, 2);
    v_prev_month_start timestamptz;
    v_prev_month_end timestamptz;
BEGIN
    -- Calculate previous calendar month boundaries
    v_prev_month_start := date_trunc('month', now() - interval '1 month');
    v_prev_month_end := date_trunc('month', now());

    -- Sum all successful request costs from previous month
    SELECT COALESCE(SUM(cost_nanos), 0)
    INTO v_spend_nanos
    FROM private.v2_rpc_gateway_requests_compat
    WHERE team_id = p_team_id
      AND success = true
      AND created_at >= v_prev_month_start
      AND created_at < v_prev_month_end;

    -- Convert nanos to USD
    v_spend_usd := ROUND((v_spend_nanos::numeric / 1000000000.0)::numeric, 2);

    RETURN v_spend_usd;
END;
$function$;

REVOKE ALL ON FUNCTION "public"."calculate_workspace_previous_month_spend"(uuid) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.capture_gateway_billing_alert()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare alert_uuid uuid;
begin
  if new.billed_at is not null then
    update public.gateway_billing_alerts set status = 'resolved', resolved_at = now()
    where operation_id = new.id and status = 'open';
    return new;
  end if;
  if new.kind not in ('video', 'batch') or new.meta->>'billingReason' is distinct from 'unexpected_zero_cost' then
    return new;
  end if;
  insert into public.gateway_billing_alerts(operation_id, workspace_id, resource_id, kind, provider, reason)
  values(new.id, new.workspace_id, new.internal_id, new.kind, new.provider, 'unexpected_zero_cost')
  on conflict(operation_id, reason) do nothing;
  select id into alert_uuid from public.gateway_billing_alerts
    where operation_id = new.id and reason = 'unexpected_zero_cost';
  perform public.queue_gateway_billing_alert(alert_uuid);
  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."capture_gateway_billing_alert"() FROM PUBLIC, "anon", "authenticated", "service_role";

CREATE OR REPLACE FUNCTION public.capture_manual_workspace_grant()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if current_setting('phaseo.entitlement_reconcile', true) = 'on' then
    return coalesce(new, old);
  end if;

  if tg_op = 'DELETE' then
    delete from public.workspace_access_grants
    where workspace_id = old.workspace_id
      and user_id = old.user_id
      and source_type = 'manual';

    perform public.reconcile_scim_entitlements(old.workspace_id);
    return old;
  end if;

  insert into public.workspace_access_grants(
    workspace_id,
    user_id,
    source_type,
    source_id,
    access_role
  )
  values (
    new.workspace_id,
    new.user_id,
    'manual',
    new.user_id,
    lower(new.role::text)
  )
  on conflict (workspace_id, user_id, source_type, source_id)
  do update set
    access_role = excluded.access_role,
    updated_at = now();

  perform public.reconcile_scim_entitlements(new.workspace_id);
  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."capture_manual_workspace_grant"() FROM PUBLIC, "anon", "authenticated";

