CREATE OR REPLACE FUNCTION public.claim_account_deletion_jobs (
  p_limit         integer DEFAULT 5,
  p_lease_seconds integer DEFAULT 300
)
  RETURNS SETOF public.account_deletion_jobs
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  return query
  with candidates as (
    select job.id
    from public.account_deletion_jobs as job
    where job.status in ('pending', 'purging', 'failed')
      and job.next_attempt_at <= now()
      and (job.lease_expires_at is null or job.lease_expires_at <= now())
      and job.completed_at is null
    order by job.deadline_at asc, job.next_attempt_at asc, job.requested_at asc
    for update skip locked
    limit greatest(1, least(coalesce(p_limit, 5), 25))
  )
  update public.account_deletion_jobs as job
  set status = 'purging',
      lease_expires_at = now() + make_interval(secs => greatest(30, least(coalesce(p_lease_seconds, 300), 900))),
      last_attempt_at = now(),
      attempts = job.attempts + 1,
      last_error = null,
      updated_at = now()
  from candidates
  where job.id = candidates.id
  returning job.*;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."claim_account_deletion_jobs"(integer, integer) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.claim_data_contributions (
  p_limit         integer DEFAULT 25,
  p_lease_seconds integer DEFAULT 300
)
  RETURNS SETOF public.data_contributions
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  return query
  with candidates as (
    select contribution.id
    from public.data_contributions contribution
    where contribution.status in ('pending', 'failed', 'processing')
      and case
        when contribution.status = 'processing' then contribution.lease_expires_at
        else contribution.available_at
      end <= now()
      and contribution.retention_until > now()
    order by
      case
        when contribution.status = 'processing' then contribution.lease_expires_at
        else contribution.available_at
      end,
      contribution.occurred_at,
      contribution.id
    for update skip locked
    limit greatest(1, least(coalesce(p_limit, 25), 250))
  )
  update public.data_contributions contribution
  set status = 'processing',
      attempt_count = contribution.attempt_count + 1,
      lease_expires_at = now() + make_interval(secs => greatest(30, least(coalesce(p_lease_seconds, 300), 3600))),
      updated_at = now()
  from candidates
  where contribution.id = candidates.id
  returning contribution.*;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."claim_data_contributions"(integer, integer) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.claim_gateway_async_operations_for_reconciliation (
  p_kind          text,
  p_limit         integer DEFAULT 100,
  p_statuses      text[]  DEFAULT NULL::text[],
  p_worker_id     text    DEFAULT 'gateway-reconciler'::text,
  p_lease_seconds integer DEFAULT 120,
  p_shard_count   integer DEFAULT 1,
  p_shard_index   integer DEFAULT 0
)
  RETURNS TABLE (
    workspace_id         uuid,
    kind                 text,
    internal_id          text,
    request_id           text,
    session_id           text,
    app_id               uuid,
    provider             text,
    native_id            text,
    model                text,
    status               text,
    meta                 jsonb,
    billed_at            timestamp with time zone,
    next_reconcile_at    timestamp with time zone,
    reconcile_attempts   integer,
    reconcile_locked_at  timestamp with time zone,
    reconcile_locked_by  text,
    last_reconcile_error text,
    created_at           timestamp with time zone,
    updated_at           timestamp with time zone
  )
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_limit integer := greatest(1, least(coalesce(p_limit, 100), 2000));
  v_lease_seconds integer := greatest(30, least(coalesce(p_lease_seconds, 120), 3600));
  v_shard_count integer := greatest(1, least(coalesce(p_shard_count, 1), 256));
  v_shard_index integer := greatest(0, least(coalesce(p_shard_index, 0), greatest(1, least(coalesce(p_shard_count, 1), 256)) - 1));
  v_worker_id text := left(coalesce(nullif(trim(p_worker_id), ''), 'gateway-reconciler'), 200);
begin
  return query
  with candidates as (
    select op.id
    from public.gateway_async_operations op
    where op.kind = p_kind
      and op.billed_at is null
      and (op.next_reconcile_at is null or op.next_reconcile_at <= now())
      and (
        op.reconcile_locked_at is null
        or op.reconcile_locked_at < now() - make_interval(secs => v_lease_seconds)
      )
      and (
        p_statuses is null
        or coalesce(op.status, '') = any(p_statuses)
      )
      and not (op.kind = 'batch' and op.meta->>'resource' = 'file')
      and (
        v_shard_count = 1
        or mod(
          mod(hashtextextended(op.workspace_id::text || ':' || op.internal_id, 0), v_shard_count::bigint)
            + v_shard_count::bigint,
          v_shard_count::bigint
        ) = v_shard_index::bigint
      )
    order by op.next_reconcile_at asc nulls first, op.updated_at asc
    limit v_limit
    for update skip locked
  ),
  claimed as (
    update public.gateway_async_operations op
    set
      reconcile_locked_at = now(),
      reconcile_locked_by = v_worker_id,
      reconcile_attempts = op.reconcile_attempts + 1,
      updated_at = now()
    from candidates
    where op.id = candidates.id
    returning op.*
  )
  select
    claimed.workspace_id,
    claimed.kind,
    claimed.internal_id,
    claimed.request_id,
    claimed.session_id,
    claimed.app_id,
    claimed.provider,
    claimed.native_id,
    claimed.model,
    claimed.status,
    claimed.meta,
    claimed.billed_at,
    claimed.next_reconcile_at,
    claimed.reconcile_attempts,
    claimed.reconcile_locked_at,
    claimed.reconcile_locked_by,
    claimed.last_reconcile_error,
    claimed.created_at,
    claimed.updated_at
  from claimed
  order by claimed.next_reconcile_at asc nulls first, claimed.updated_at asc;
end;
$function$;

CREATE OR REPLACE FUNCTION public.claim_gateway_async_webhook_delivery (
  p_workspace_id        uuid,
  p_kind                text,
  p_internal_id         text,
  p_delivery_key        text,
  p_claim_token         text,
  p_stale_after_seconds integer          DEFAULT 300,
  p_event_type          text             DEFAULT NULL::text,
  p_phase               text             DEFAULT NULL::text,
  p_progress            double precision DEFAULT NULL::double precision,
  p_previous_status     text             DEFAULT NULL::text,
  p_current_status      text             DEFAULT NULL::text
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_row public.gateway_async_webhook_deliveries%rowtype;
begin
  if p_workspace_id is null or coalesce(trim(p_kind), '') = ''
     or coalesce(trim(p_internal_id), '') = '' or coalesce(trim(p_delivery_key), '') = ''
     or coalesce(trim(p_claim_token), '') = '' then
    raise exception 'invalid_webhook_delivery_claim';
  end if;

  insert into public.gateway_async_webhook_deliveries (
    workspace_id, kind, internal_id, delivery_key, status, claim_token, claimed_at, updated_at
  ) values (
    p_workspace_id, p_kind, p_internal_id, p_delivery_key, 'claimed', p_claim_token, now(), now()
  ) on conflict do nothing;

  select * into v_row
  from public.gateway_async_webhook_deliveries
  where workspace_id = p_workspace_id and kind = p_kind
    and internal_id = p_internal_id and delivery_key = p_delivery_key
  for update;

  if v_row.status in ('delivered', 'failed') then return false; end if;
  if v_row.status = 'pending' and v_row.next_attempt_at > now() then return false; end if;
  if v_row.status = 'claimed' and v_row.claim_token <> p_claim_token
     and v_row.claimed_at > now() - make_interval(secs => greatest(30, p_stale_after_seconds)) then
    return false;
  end if;

  update public.gateway_async_webhook_deliveries
  set status = 'claimed', claim_token = p_claim_token, claimed_at = now(), updated_at = now(),
      event_type = coalesce(event_type, p_event_type, split_part(p_delivery_key, ':', 1)),
      phase = coalesce(phase, p_phase, split_part(split_part(p_delivery_key, ':', 1), '.', 2)),
      progress = coalesce(progress, p_progress),
      previous_status = coalesce(previous_status, p_previous_status),
      current_status = coalesce(current_status, p_current_status)
  where workspace_id = p_workspace_id and kind = p_kind
    and internal_id = p_internal_id and delivery_key = p_delivery_key;
  return true;
end;
$function$;

REVOKE ALL
  ON FUNCTION "public"."claim_gateway_async_webhook_delivery"(uuid, text, text, text, text, integer, text, text, double precision, text, text)
  FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.claim_model_discovery_public_announcements (
  p_run_id        uuid,
  p_model_slugs   text[],
  p_now           timestamp with time zone,
  p_lease_seconds integer                  DEFAULT 300
)
  RETURNS TABLE (
