      or claim_run_id = p_run_id
    )
  returning model_slug, attempt_count;
$function$;

REVOKE ALL ON FUNCTION "public"."claim_model_discovery_public_announcements"(uuid, text[], timestamp WITH time zone, integer) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.claim_notification_delivery_attempts (
  p_limit integer DEFAULT 25
)
  RETURNS TABLE (
    id             uuid,
    event_id       uuid,
    destination_id uuid,
    attempts       integer,
    claim_token    uuid
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
begin
  if p_limit is null or p_limit < 1 or p_limit > 100 then
    raise exception 'invalid_notification_delivery_claim_limit';
  end if;

  return query
  with candidates as (
    select attempt.id
    from public.notification_delivery_attempts attempt
    where (
      attempt.status in ('pending', 'retry')
      and attempt.next_attempt_at <= now()
    ) or (
      attempt.status = 'processing'
      and attempt.claimed_at < now() - interval '5 minutes'
    )
    order by attempt.created_at, attempt.id
    for update skip locked
    limit p_limit
  )
  update public.notification_delivery_attempts attempt
  set status = 'processing',
      claim_token = gen_random_uuid(),
      claimed_at = now(),
      updated_at = now()
  from candidates
  where attempt.id = candidates.id
  returning attempt.id, attempt.event_id, attempt.destination_id, attempt.attempts, attempt.claim_token;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."claim_notification_delivery_attempts"(integer) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.claim_otel_export_outbox (
  p_limit integer DEFAULT 100
)
  RETURNS SETOF public.otel_export_outbox
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
begin
  return query
  with candidates as (
    select id
    from public.otel_export_outbox
    where (
      status = 'pending'
      or (status = 'processing' and lease_expires_at < now())
    )
      and next_attempt_at <= now()
    order by next_attempt_at, created_at
    for update skip locked
    limit greatest(1, least(coalesce(p_limit, 100), 500))
  ),
  claimed as (
    update public.otel_export_outbox outbox
    set status = 'processing',
        attempts = attempts + 1,
        lease_expires_at = now() + interval '15 minutes',
        updated_at = now()
    from candidates
    where outbox.id = candidates.id
    returning outbox.*
  )
  select * from claimed;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."claim_otel_export_outbox"(integer) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.claim_payment_method_mutation (
  p_workspace_id uuid,
  p_claim_token  uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  claimed uuid;
begin
  insert into public.payment_method_mutation_leases (workspace_id, claim_token, expires_at, updated_at)
  values (p_workspace_id, p_claim_token, now() + interval '10 minutes', now())
  on conflict (workspace_id) do update
    set claim_token = excluded.claim_token,
        expires_at = excluded.expires_at,
        updated_at = now()
    where public.payment_method_mutation_leases.expires_at <= now()
  returning claim_token into claimed;
  return claimed = p_claim_token;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."claim_payment_method_mutation"(uuid, uuid) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.claim_provider_catalog_sync (
  p_provider_slug text,
  p_lease_token   uuid,
  p_lease_seconds integer DEFAULT 120
)
  RETURNS boolean
  LANGUAGE plpgsql
  SET search_path TO 'public'
  AS $function$
declare
  affected integer;
begin
  update public.provider_catalog_sources
  set sync_lease_token = p_lease_token,
      sync_lease_expires_at = now() + make_interval(secs => greatest(30, least(p_lease_seconds, 300))),
      updated_at = now()
  where provider_slug = p_provider_slug
    and status = 'active'
    and (sync_lease_expires_at is null or sync_lease_expires_at <= now());
  get diagnostics affected = row_count;
  return affected > 0;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."claim_provider_catalog_sync"(text, uuid, integer) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.claim_workspace_top_up_fee_policy (
  p_workspace_id             uuid,
  p_stripe_payment_intent_id text,
  p_gross_nanos              bigint,
  p_payment_rail             text,
  p_seen_at                  timestamp with time zone DEFAULT now()
)
  RETURNS TABLE (
    fee_waived             boolean,
    reason                 text,
    allowance_before_nanos bigint,
    allowance_after_nanos  bigint
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_period_start date := date_trunc('month', p_seen_at at time zone 'UTC')::date;
  v_subscription public.workspace_addon_subscriptions%rowtype;
  v_used bigint := 0;
  v_waived boolean := false;
  v_reason text := 'standard_fee';
  v_before bigint := 0;
  v_after bigint := 0;
begin
  if p_gross_nanos < 0 or p_stripe_payment_intent_id is null or trim(p_stripe_payment_intent_id) = '' then
    raise exception 'invalid top-up fee claim';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_workspace_id::text || ':' || v_period_start::text || ':top_up_fee', 0)
  );

  return query
  select d.fee_waived, d.reason, d.allowance_before_nanos, d.allowance_after_nanos
  from public.workspace_top_up_fee_decisions d
  where d.stripe_payment_intent_id = p_stripe_payment_intent_id;
  if found then return; end if;

  select * into v_subscription
  from public.workspace_addon_subscriptions s
  where s.workspace_id = p_workspace_id
    and s.addon_key = 'identity'
    and (
      s.status in ('active', 'trialing')
      or (s.status = 'past_due' and s.grace_until > p_seen_at)
    )
  limit 1;

  if v_subscription.id is not null and v_subscription.fee_policy = 'included_allowance' then
    select coalesce(sum(d.gross_nanos), 0) into v_used
    from public.workspace_top_up_fee_decisions d
    where d.workspace_id = p_workspace_id
      and d.period_start = v_period_start
      and d.fee_waived
      and d.payment_rail <> 'bank_transfer';
    v_before := greatest(v_subscription.included_card_top_up_nanos - v_used, 0);

    if p_payment_rail = 'bank_transfer' then
      v_waived := true;
      v_reason := 'included_bank_transfer';
      v_after := v_before;
    elsif p_gross_nanos <= v_before then
      v_waived := true;
      v_reason := 'included_card_allowance';
      v_after := v_before - p_gross_nanos;
    else
      v_reason := 'allowance_exceeded';
      v_after := v_before;
    end if;
  elsif v_subscription.id is null then
    v_reason := 'no_active_subscription';
  end if;

  insert into public.workspace_top_up_fee_decisions (
    stripe_payment_intent_id, workspace_id, period_start, payment_rail,
    gross_nanos, fee_waived, allowance_before_nanos, allowance_after_nanos, reason
  ) values (
    p_stripe_payment_intent_id, p_workspace_id, v_period_start,
    case when p_payment_rail in ('card', 'ach', 'bank_transfer') then p_payment_rail else 'unknown' end,
    p_gross_nanos, v_waived, v_before, v_after, v_reason
  );

  return query select v_waived, v_reason, v_before, v_after;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."claim_workspace_top_up_fee_policy"(uuid, text, bigint, text, timestamp WITH time zone) FROM PUBLIC, "anon", "authenticated";

