CREATE OR REPLACE FUNCTION public.complete_gateway_async_webhook_delivery (
  p_workspace_id uuid,
  p_kind         text,
  p_internal_id  text,
  p_delivery_key text,
  p_claim_token  text
)
  RETURNS boolean
