CREATE OR REPLACE FUNCTION public.deduct_and_check_top_up (
  p_workspace_id uuid,
  p_cost_nanos   bigint
)
  RETURNS json
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_new_balance bigint;
  v_low_threshold bigint;
  v_auto_top_up_amount bigint;
  v_auto_top_up_enabled boolean;
  v_auto_top_up_account_id text;
  v_stripe_customer_id text;
begin
  if p_cost_nanos is null or p_cost_nanos <= 0 then
    raise exception 'invalid_cost_nanos';
  end if;
  update public.wallets
  set balance_nanos = balance_nanos - p_cost_nanos
  where workspace_id = p_workspace_id
    and balance_nanos - p_cost_nanos >= coalesce(reserved_nanos, 0)
  returning balance_nanos, low_balance_threshold, auto_top_up_amount,
    auto_top_up_enabled, auto_top_up_account_id, stripe_customer_id
  into v_new_balance, v_low_threshold, v_auto_top_up_amount,
    v_auto_top_up_enabled, v_auto_top_up_account_id, v_stripe_customer_id;

  if v_new_balance is null then
    if exists (select 1 from public.wallets where workspace_id = p_workspace_id) then
      raise exception 'insufficient_unreserved_balance';
    end if;
    return json_build_object('status', 'wallet_not_found');
  end if;
  if v_auto_top_up_enabled and v_new_balance < v_low_threshold then
    return json_build_object(
      'status', 'top_up_required',
      'auto_top_up_amount_nanos', v_auto_top_up_amount,
      'auto_top_up_account_id', v_auto_top_up_account_id,
      'stripe_customer_id', v_stripe_customer_id,
      'new_balance_nanos', v_new_balance
    );
  end if;
  return json_build_object('status', 'top_up_not_required', 'new_balance_nanos', v_new_balance);
end;
$function$;

REVOKE ALL ON FUNCTION "public"."deduct_and_check_top_up"(uuid, bigint) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.default_workspace_publisher_handle()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO 'public'
  AS $function$
begin
  if nullif(new.publisher_handle, '') is null then
    new.publisher_handle := lower(regexp_replace(regexp_replace(coalesce(nullif(new.slug, ''), new.name), '[^a-zA-Z0-9_-]+', '-', 'g'), '^-+|-+$', '', 'g'));

    if length(new.publisher_handle) < 3 then
      new.publisher_handle := 'workspace-' || left(new.id::text, 8);
    end if;

    new.publisher_handle := left(new.publisher_handle, 40);
  end if;

  return new;
end
$function$;

REVOKE ALL ON FUNCTION "public"."default_workspace_publisher_handle"() FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.enforce_byok_key_provider_limit()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  existing_provider_count integer;
  existing_mode_count integer;
  excluded_key_id uuid;
begin
  if tg_op = 'UPDATE'
    and new.workspace_id is not distinct from old.workspace_id
    and new.provider_id is not distinct from old.provider_id
    and new.routing_mode is not distinct from old.routing_mode then
    return new;
  end if;

  if tg_op = 'UPDATE' then
    excluded_key_id := old.id;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(new.workspace_id::text || ':' || new.provider_id, 0)
  );

  select
    count(*),
    count(*) filter (where routing_mode = new.routing_mode)
  into existing_provider_count, existing_mode_count
  from public.byok_keys
  where workspace_id = new.workspace_id
    and provider_id = new.provider_id
    and (excluded_key_id is null or id <> excluded_key_id);

  if existing_provider_count >= 32 then
    raise exception 'BYOK key limit reached for workspace provider'
      using errcode = '23514';
  end if;
  if existing_mode_count >= 16 then
    raise exception 'BYOK key routing-mode limit reached for workspace provider'
      using errcode = '23514';
  end if;

  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."enforce_byok_key_provider_limit"() FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.enforce_oauth_device_poll_interval (
  p_device_id uuid
)
  RETURNS text
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  device public.oauth_device_codes%rowtype;
begin
  select * into device
  from public.oauth_device_codes
  where id = p_device_id
  for update;

  if not found then return 'invalid'; end if;

  if device.last_polled_at is not null
     and device.last_polled_at + make_interval(secs => device.interval_seconds) > now() then
    update public.oauth_device_codes
    set last_polled_at = now(), interval_seconds = interval_seconds + 5
    where id = p_device_id;
    return 'slow_down';
  end if;

  update public.oauth_device_codes set last_polled_at = now() where id = p_device_id;
  return 'ok';
end;
$function$;

REVOKE ALL ON FUNCTION "public"."enforce_oauth_device_poll_interval"(uuid) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.enforce_provider_catalog_source_owner_limit()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if new.created_by is null then
    return new;
  end if;

  perform pg_advisory_xact_lock(hashtextextended(new.created_by::text, 918273));
  if (
    select count(*)
    from public.provider_catalog_sources source
    where source.created_by = new.created_by
  ) >= 5 then
    raise exception using
      errcode = '23514',
      message = 'provider_catalog_source_owner_limit';
  end if;
  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."enforce_provider_catalog_source_owner_limit"() FROM PUBLIC, "anon", "authenticated", "service_role";

CREATE OR REPLACE FUNCTION public.enforce_self_serve_provider_approval()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO 'public'
  AS $function$
declare
  is_self_serve boolean := false;
  review_status text;
begin
  select coalesce(provider.metadata, '{}'::jsonb) ? 'self_serve',
    provider.metadata -> 'self_serve' ->> 'provider_review_status'
    into is_self_serve, review_status
  from public.v2_providers provider
  where provider.provider_slug = new.provider_slug;

  if is_self_serve and review_status is distinct from 'approved' then
    new.routing_enabled := false;
    new.access_scope := 'internal';
    new.phaseo_status := 'testing';
    if new.status in ('active', 'degraded') then new.status := 'disabled'; end if;
    if new.provider_availability_status in ('available', 'preview') then
      new.provider_availability_status := 'coming_soon';
    end if;
  end if;
  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."enforce_self_serve_provider_approval"() FROM PUBLIC, "anon", "authenticated", "service_role";

CREATE OR REPLACE FUNCTION public.enforce_self_serve_provider_review_routing()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO 'public'
  AS $function$
declare
  review_status text;
begin
  if coalesce(new.metadata, '{}'::jsonb) ? 'self_serve' then
    review_status := new.metadata -> 'self_serve' ->> 'provider_review_status';
    if review_status is distinct from 'approved' then
      new.routable := false;
      new.routing_enabled := false;
      if new.status in ('active', 'degraded', 'beta') then
        new.status := 'not_ready';
      end if;
    end if;
  end if;
  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."enforce_self_serve_provider_review_routing"() FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.enforce_workspace_invite_role_policy()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
begin
  if lower(coalesce(new.role::text, '')) not in ('admin', 'member') then
    raise exception using
      errcode = '23514',
      message = 'invalid_workspace_invite_role',
      detail = 'Invite roles are restricted to admin and member.';
  end if;

  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."enforce_workspace_invite_role_policy"() FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.enforce_workspace_join_request_write_rules()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
begin
  if new.invite_id is not null then
    if not exists (
      select 1
      from public.team_invites ti
      where ti.id = new.invite_id
        and ti.team_id = new.team_id
    ) then
      raise exception using
        errcode = '23514',
        message = 'invite_team_mismatch',
        detail = 'Join request invite must belong to the same team.';
    end if;
  end if;

  if tg_op = 'INSERT' then
    if new.status <> 'pending'::join_request_status
       or new.decided_by is not null
       or new.decided_at is not null then
      raise exception using
        errcode = '23514',
        message = 'invalid_join_request_insert_state',
        detail = 'New join requests must be pending and undecided.';
    end if;
    return new;
  end if;

  -- UPDATE path
  if old.status <> 'pending'::join_request_status then
    raise exception using
      errcode = '23514',
      message = 'join_request_already_decided',
      detail = 'Only pending join requests can be updated.';
  end if;

  if new.status not in ('approved'::join_request_status, 'denied'::join_request_status) then
    raise exception using
      errcode = '23514',
      message = 'invalid_join_request_status_transition',
      detail = 'Join request updates must transition to approved or denied.';
  end if;

  if new.decided_by is null or new.decided_at is null then
    raise exception using
      errcode = '23514',
      message = 'join_request_decision_metadata_required',
      detail = 'Decided join requests must include decided_by and decided_at.';
  end if;

  if new.team_id <> old.team_id or new.requester_user_id <> old.requester_user_id then
    raise exception using
      errcode = '23514',
      message = 'join_request_immutable_fields_modified',
      detail = 'team_id and requester_user_id are immutable.';
  end if;

  if new.invite_id is distinct from old.invite_id then
    raise exception using
      errcode = '23514',
      message = 'join_request_invite_immutable',
      detail = 'invite_id is immutable after request creation.';
  end if;

  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."enforce_workspace_join_request_write_rules"() FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.enforce_workspace_member_role_policy()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  v_owner_user_id uuid;
begin
  select w.owner_user_id
    into v_owner_user_id
  from public.workspaces w
  where w.id = new.workspace_id;

  if v_owner_user_id is null then
    raise exception using
      errcode = '23514',
      message = 'workspace_not_found_for_membership';
  end if;

  if new.user_id = v_owner_user_id then
    new.role := 'owner'::public.workspace_role;
    return new;
  end if;

  if lower(coalesce(new.role::text, '')) = 'owner' then
    raise exception using
      errcode = '23514',
      message = 'owner_role_reserved_for_workspace_owner',
      detail = 'Only workspaces.owner_user_id may have role=owner.';
  end if;

  if lower(coalesce(new.role::text, '')) not in ('admin', 'member') then
    raise exception using
      errcode = '23514',
      message = 'invalid_workspace_member_role',
      detail = 'Assignable roles are admin and member.';
  end if;

  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."enforce_workspace_member_role_policy"() FROM PUBLIC, "anon", "authenticated";

