CREATE OR REPLACE FUNCTION public.gateway_catalogue_source()
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
with selected_routes as materialized (
 select * from public.v2_model_provider_routes
 where is_stealth is true or (access_scope='public' and routing_enabled is true
   and status in ('active','degraded') and (effective_to is null or effective_to>statement_timestamp()))
), selected_skus as materialized (
 select s.* from public.v2_pricing_skus s join selected_routes r using(provider_model_id)
 where s.status in ('active','degraded') and (s.effective_to is null or s.effective_to>statement_timestamp())
), projected as materialized (
 select 'models' as kind,private.project_routing_catalogue_row(to_jsonb(t)) as row from public.v2_models t
 union all select 'providers',private.project_routing_catalogue_row(to_jsonb(t)) from public.v2_providers t
 union all select 'routes',private.project_routing_catalogue_row(to_jsonb(t)) from selected_routes t
 union all select 'capabilities',private.project_routing_catalogue_row(to_jsonb(t)) from public.v2_route_capabilities t where exists(select 1 from selected_routes r where r.provider_model_id=t.provider_model_id)
 union all select 'variants',private.project_routing_catalogue_row(to_jsonb(t)) from public.v2_route_variants t where exists(select 1 from selected_routes r where r.provider_model_id=t.provider_model_id)
 union all select 'regions',private.project_routing_catalogue_row(to_jsonb(t)) from public.v2_provider_regions t
 union all select 'serviceTiers',private.project_routing_catalogue_row(to_jsonb(t)) from public.v2_service_tiers t
 union all select 'skus',private.project_routing_catalogue_row(to_jsonb(t)) from selected_skus t
 union all select 'meters',private.project_routing_catalogue_row(to_jsonb(t)||jsonb_build_object('price_nanos',t.price_nanos::text)) from public.v2_pricing_sku_meters t where exists(select 1 from selected_skus s where s.sku_id=t.sku_id)
 union all select 'aliases',private.project_routing_catalogue_row(to_jsonb(t)) from public.v2_model_aliases t
 union all select 'benchmarks',jsonb_build_object('model_slug',t.model_slug,'benchmark_id',t.benchmark_id,
   'score_numeric',t.score_numeric,'is_self_reported',t.is_self_reported,'effective_to',t.effective_to)
   from public.v2_benchmark_results t join public.v2_benchmarks b using(benchmark_id)
   where t.is_self_reported=false and (t.effective_to is null or t.effective_to>statement_timestamp())
     and concat_ws(' ',t.benchmark_id,t.result_key,t.other_info,b.name) !~* '\minternal\M'
), budget as (
 select count(*) as rows,coalesce(sum(octet_length(row::text)),0) as bytes,
   coalesce(max(octet_length(row::text)),0) as largest from projected
)
select case when rows > 100000 or bytes > 16777216 or largest > 262144
 then jsonb_build_object('error','catalogue_source_too_large')
 else jsonb_build_object(
  'revision',(select revision::text from private.routing_catalogue_revision where singleton),
  'generatedAt',floor(extract(epoch from statement_timestamp())*1000),
  'source',(select jsonb_object_agg(k.kind,coalesce(p.items,'[]'::jsonb))
    from unnest(array['models','providers','routes','capabilities','variants','regions','serviceTiers','skus','meters','aliases','benchmarks']) k(kind)
    left join (select kind,jsonb_agg(row) as items from projected group by kind) p using(kind))
 ) end from budget;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_catalogue_source"() FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_charge_with_credit_cache (
  p_workspace_id                  uuid,
  p_request_id                    text,
  p_cost_nanos                    bigint,
  p_credit_snapshot_balance_nanos bigint DEFAULT NULL::bigint
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  v_result jsonb;
  v_legacy jsonb;
  v_available numeric;
  v_invalidate boolean := true;
begin
  -- Keep the existing idempotency key, debit, wallet lock and top-up behavior.
  -- A successful debit holds its wallet row lock until this transaction ends.
  select to_jsonb(charged) into v_result
  from public.gateway_deduct_and_check_top_up_once(
    p_workspace_id, p_request_id, p_cost_nanos
  ) as charged;

  if v_result is null then raise exception 'gateway_charge_result_missing'; end if;

  -- Some deployed debit functions return JSON through a scalar result column.
  -- The older idempotency wrapper stores that JSON as the status string.
  -- Normalize the known fields here without replacing either existing function.
  begin
    v_legacy := (v_result ->> 'status')::jsonb;
    if jsonb_typeof(v_legacy) = 'object' and jsonb_typeof(v_legacy -> 'status') = 'string' then
      v_result := v_result || jsonb_build_object(
        'status', v_legacy -> 'status',
        'auto_top_up_amount_nanos', coalesce(v_legacy -> 'auto_top_up_amount_nanos', v_result -> 'auto_top_up_amount_nanos'),
        'auto_top_up_account_id', coalesce(v_legacy -> 'auto_top_up_account_id', v_result -> 'auto_top_up_account_id'),
        'stripe_customer_id', coalesce(v_legacy -> 'stripe_customer_id', v_result -> 'stripe_customer_id')
      );
    end if;
  exception when invalid_text_representation then
    null; -- Ordinary textual status; no legacy conversion is needed.
  end;

  if (v_result ->> 'applied')::boolean is true
     and v_result ->> 'status' = 'top_up_not_required'
     and p_credit_snapshot_balance_nanos >= 10000000000 then
    select w.balance_nanos::numeric - coalesce(w.reserved_nanos, 0)::numeric
    into v_available from public.wallets w where w.workspace_id = p_workspace_id;

    -- Compare to the request's original snapshot, NOT just this request's cost.
    -- This catches cumulative spending by other requests and includes holds.
    -- Numeric arithmetic avoids bigint multiplication overflow at large balances.
    if v_available >= 10000000000
       and v_available * 10 > p_credit_snapshot_balance_nanos::numeric * 9 then
      v_invalidate := false;
    end if;
  end if;

  -- Replays invalidate conservatively: an earlier response/invalidation may
  -- have been lost after the debit committed. Never debit a replay twice.
  return v_result || jsonb_build_object('invalidate_credit_cache', v_invalidate);
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_charge_with_credit_cache"(uuid, text, bigint, bigint) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_claim_batch_file_upload (
  p_workspace_id uuid,
  p_upload_id    text,
  p_bytes        bigint
)
  RETURNS TABLE (
    ok     boolean,
    reason text
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_hour_count bigint;
  v_day_bytes bigint;
begin
  if p_workspace_id is null or coalesce(trim(p_upload_id), '') = '' or p_bytes is null or p_bytes <= 0 then
    raise exception 'invalid_batch_file_upload_claim';
  end if;
  if p_bytes > 20971520 then
    return query select false, 'batch_file_too_large'::text;
    return;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('batch-file:' || p_workspace_id::text, 0));
  if not exists (
    select 1 from public.wallets
    where workspace_id = p_workspace_id
      and coalesce(balance_nanos, 0) - coalesce(reserved_nanos, 0) > 0
  ) then
    return query select false, 'insufficient_funds'::text;
    return;
  end if;
  select count(*) into v_hour_count
  from public.gateway_batch_file_uploads
  where workspace_id = p_workspace_id and created_at >= now() - interval '1 hour';
  if v_hour_count >= 20 then
    return query select false, 'batch_file_hourly_quota_exceeded'::text;
    return;
  end if;
  select coalesce(sum(bytes), 0) into v_day_bytes
  from public.gateway_batch_file_uploads
  where workspace_id = p_workspace_id and created_at >= now() - interval '24 hours';
  if v_day_bytes + p_bytes > 104857600 then
    return query select false, 'batch_file_daily_bytes_exceeded'::text;
    return;
  end if;
  insert into public.gateway_batch_file_uploads (workspace_id, upload_id, bytes, status)
  values (p_workspace_id, p_upload_id, p_bytes, 'claimed')
  on conflict (workspace_id, upload_id) do nothing;
  if not found then
    return query select false, 'batch_file_upload_already_claimed'::text;
    return;
  end if;
  return query select true, null::text;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_claim_batch_file_upload"(uuid, text, bigint) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_claim_provider_event (
  p_provider          text,
  p_provider_event_id text,
  p_worker_id         text    DEFAULT 'batch-provider-webhook'::text,
  p_lease_seconds     integer DEFAULT 120
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_claimed integer;
begin
  update public.gateway_provider_events event
  set replay_locked_at = now(),
      replay_locked_by = left(coalesce(nullif(trim(p_worker_id), ''), 'batch-provider-webhook'), 200),
      updated_at = now()
  where event.provider = nullif(trim(p_provider), '')
    and event.provider_event_id = nullif(trim(p_provider_event_id), '')
    and event.processed_at is null
    and event.dead_lettered_at is null
    and (event.next_attempt_at is null or event.next_attempt_at <= now())
    and (
      event.replay_locked_at is null
      or event.replay_locked_at < now() - make_interval(
        secs => greatest(30, least(coalesce(p_lease_seconds, 120), 3600))
      )
    );

  get diagnostics v_claimed = row_count;
  return v_claimed = 1;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_claim_provider_event"(text, text, text, integer) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_claim_provider_events (
  p_providers     text[],
  p_limit         integer DEFAULT 100,
  p_worker_id     text    DEFAULT 'batch-provider-event-replay'::text,
  p_lease_seconds integer DEFAULT 120
)
  RETURNS SETOF public.gateway_provider_events
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  return query
  with candidates as (
    select event.id
    from public.gateway_provider_events event
    where event.provider = any(p_providers)
      and event.processed_at is null
      and event.dead_lettered_at is null
      and (event.next_attempt_at is null or event.next_attempt_at <= now())
      and (
        event.replay_locked_at is null
        or event.replay_locked_at < now() - make_interval(secs => greatest(30, least(coalesce(p_lease_seconds, 120), 3600)))
      )
    order by event.created_at asc
    for update skip locked
    limit greatest(1, least(coalesce(p_limit, 100), 500))
  )
  update public.gateway_provider_events event
  set replay_locked_at = now(),
      replay_locked_by = left(coalesce(nullif(trim(p_worker_id), ''), 'batch-provider-event-replay'), 200),
      updated_at = now()
  from candidates
  where event.id = candidates.id
  returning event.*;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_claim_provider_events"(text[], integer, text, integer) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_claim_workspace_publications (
  p_limit        integer DEFAULT 25,
  p_workspace_id uuid    DEFAULT NULL::uuid
)
  RETURNS TABLE (
    workspace_id uuid,
    revision     uuid,
    lease_id     uuid
  )
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  if p_limit is null or p_limit < 1 or p_limit > 100 then
    raise exception 'invalid_publication_limit' using errcode='22023';
  end if;
  -- The existing authenticated explicit-invalidation route can also request
  -- publication when there was no preceding mutation. A busy lease is not stolen.
  if p_workspace_id is not null then
    insert into public.gateway_workspace_publications (workspace_id)
      select w.id from public.workspaces w where w.id = p_workspace_id
      on conflict on constraint gateway_workspace_publications_pkey do nothing;
  end if;
  return query
  with due as (
    select p.workspace_id from public.gateway_workspace_publications p
    where p.attempts < 10 and p.available_at <= clock_timestamp()
      and (p.lease_until is null or p.lease_until <= clock_timestamp())
      and (p_workspace_id is null or p.workspace_id = p_workspace_id)
    order by p.available_at, p.workspace_id limit p_limit for update skip locked
  )
  update public.gateway_workspace_publications p set
    lease_id = gen_random_uuid(), lease_until = clock_timestamp() + interval '3 minutes',
    attempts = p.attempts + 1
  from due where p.workspace_id = due.workspace_id
  returning p.workspace_id, p.revision, p.lease_id;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_claim_workspace_publications"(integer, uuid) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_cleanup_batch_hold_key_usage()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if new.status = 'released' and old.status is distinct from new.status and new.key_id is not null then
    delete from public.gateway_requests
    where workspace_id = new.workspace_id
      and key_id = new.key_id
      and request_id like 'batch_hold_usage:' || new.reservation_id || ':%';
  end if;
  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_cleanup_batch_hold_key_usage"() FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_deduct_and_check_top_up_once (
  p_workspace_id uuid,
  p_request_id   text,
  p_cost_nanos   bigint
)
  RETURNS TABLE (
    applied                  boolean,
    already_applied          boolean,
    status                   text,
    auto_top_up_amount_nanos bigint,
    auto_top_up_account_id   text,
    stripe_customer_id       text
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  v_charge public.gateway_request_charges%rowtype;
  v_result record;
  v_result_json jsonb;
  v_status text;
  v_auto_top_up_amount_nanos bigint;
  v_auto_top_up_account_id text;
  v_stripe_customer_id text;
begin
  if p_workspace_id is null then
    raise exception 'missing_workspace_id';
  end if;

  if coalesce(trim(p_request_id), '') = '' then
    raise exception 'missing_request_id';
  end if;

  if p_cost_nanos is null or p_cost_nanos <= 0 then
    raise exception 'invalid_cost_nanos';
  end if;

  insert into public.gateway_request_charges (
    workspace_id,
    request_id,
    cost_nanos,
    status,
    created_at,
    updated_at
  ) values (
    p_workspace_id,
    p_request_id,
    p_cost_nanos,
    'applying',
    now(),
    now()
  )
  on conflict (workspace_id, request_id) do nothing;

  select *
  into v_charge
  from public.gateway_request_charges
  where workspace_id = p_workspace_id
    and request_id = p_request_id
  for update;

  if not found then
    raise exception 'gateway_request_charge_row_missing';
  end if;

  if v_charge.cost_nanos <> p_cost_nanos then
    raise exception 'request_charge_amount_mismatch';
  end if;

  if v_charge.status = 'applied' then
    return query
    select
      false,
      true,
      coalesce(v_charge.deducted_status, 'already_applied')::text,
      0::bigint,
      null::text,
      null::text;
    return;
  end if;

  update public.gateway_request_charges
  set status = 'applying',
      error_message = null,
      updated_at = now()
  where workspace_id = p_workspace_id
    and request_id = p_request_id;

  begin
    select *
    into v_result
    from public.deduct_and_check_top_up(
      p_workspace_id := p_workspace_id,
      p_cost_nanos := p_cost_nanos
    );

    v_result_json := to_jsonb(v_result);
  exception when others then
    update public.gateway_request_charges
    set status = 'failed',
        error_message = sqlerrm,
        updated_at = now()
    where workspace_id = p_workspace_id
      and request_id = p_request_id;
    raise;
  end;

  v_status := coalesce(
    nullif(trim(v_result_json ->> 'status'), ''),
    nullif(trim(v_result_json ->> 'result'), ''),
    nullif(trim(v_result_json ->> 'deduct_and_check_top_up'), ''),
    'unknown'
  );

  v_auto_top_up_amount_nanos := case
    when coalesce(v_result_json ->> 'auto_top_up_amount_nanos', '') ~ '^-?[0-9]+$'
      then (v_result_json ->> 'auto_top_up_amount_nanos')::bigint
    when coalesce(v_result_json ->> 'auto_top_up_amount', '') ~ '^-?[0-9]+$'
      then (v_result_json ->> 'auto_top_up_amount')::bigint
    else 0::bigint
  end;

  v_auto_top_up_account_id := nullif(
    coalesce(
      v_result_json ->> 'auto_top_up_account_id',
      v_result_json ->> 'auto_top_up_payment_method_id',
      ''
    ),
    ''
  );

  v_stripe_customer_id := nullif(v_result_json ->> 'stripe_customer_id', '');

  update public.gateway_request_charges
  set status = 'applied',
      deducted_status = v_status,
      auto_top_up_required = v_status = 'top_up_required',
      updated_at = now()
  where workspace_id = p_workspace_id
    and request_id = p_request_id;

  return query
  select
    true,
    false,
    v_status,
    v_auto_top_up_amount_nanos,
    v_auto_top_up_account_id,
    v_stripe_customer_id;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_deduct_and_check_top_up_once"(uuid, text, bigint) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_defer_provider_event (
  p_provider          text,
  p_provider_event_id text,
  p_reason            text
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_next_attempt integer;
begin
  select attempt_count + 1 into v_next_attempt
  from public.gateway_provider_events
  where provider = p_provider and provider_event_id = p_provider_event_id
  for update;
  if not found then return; end if;

  update public.gateway_provider_events
  set attempt_count = v_next_attempt,
      last_error = left(coalesce(p_reason, 'provider_event_deferred'), 500),
      next_attempt_at = case
        when v_next_attempt >= 20 then null
        else now() + make_interval(secs => least(1800, 5 * (2 ^ least(v_next_attempt, 8))::integer))
      end,
      dead_lettered_at = case when v_next_attempt >= 20 then now() else dead_lettered_at end,
      processed_at = case when v_next_attempt >= 20 then now() else processed_at end,
      replay_locked_at = null,
      replay_locked_by = null,
      updated_at = now()
  where provider = p_provider and provider_event_id = p_provider_event_id;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_defer_provider_event"(text, text, text) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_feedback_summary (
  p_workspace_id       uuid,
  p_visible_preset_ids uuid[],
  p_group_by           text                     DEFAULT 'preset_id'::text,
  p_metadata_key       text                     DEFAULT NULL::text,
  p_request_id         text                     DEFAULT NULL::text,
  p_session_id         text                     DEFAULT NULL::text,
  p_preset_id          uuid                     DEFAULT NULL::uuid,
  p_test_run_id        uuid                     DEFAULT NULL::uuid,
  p_created_since      timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  p_created_until      timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  p_metadata_filters   jsonb                    DEFAULT '{}'::jsonb,
  p_limit              integer                  DEFAULT 5000
)
  RETURNS TABLE (
    group_value      text,
    count            bigint,
    positive         bigint,
    negative         bigint,
    partial          bigint,
    average_score    numeric,
    ratings          jsonb,
    last_feedback_at timestamp with time zone
  )
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if p_group_by not in ('preset_id', 'test_run_id', 'metadata') then
    raise exception 'invalid feedback summary grouping' using errcode = '22023';
  end if;
  if p_group_by = 'metadata'
     and (p_metadata_key is null or p_metadata_key !~ '^[a-zA-Z0-9_.:-]{1,64}$') then
    raise exception 'valid metadata key required for metadata grouping' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_metadata_filters, '{}'::jsonb)) <> 'object' then
    raise exception 'metadata filters must be a JSON object' using errcode = '22023';
  end if;

  return query
  with filtered as (
    select
      case p_group_by
        when 'preset_id' then feedback.preset_id::text
        when 'test_run_id' then feedback.test_run_id::text
        when 'metadata' then feedback.metadata_dimensions ->> p_metadata_key
      end as summary_group,
      feedback.rating,
      feedback.score,
      feedback.created_at
    from public.gateway_feedback as feedback
    where feedback.workspace_id = p_workspace_id
      and (feedback.preset_id is null or feedback.preset_id = any(coalesce(p_visible_preset_ids, '{}'::uuid[])))
      and (p_request_id is null or feedback.request_id = p_request_id)
      and (p_session_id is null or feedback.session_id = p_session_id)
      and (p_preset_id is null or feedback.preset_id = p_preset_id)
      and (p_test_run_id is null or feedback.test_run_id = p_test_run_id)
      and (p_created_since is null or feedback.created_at >= p_created_since)
      and (p_created_until is null or feedback.created_at <= p_created_until)
      and feedback.metadata_dimensions @> coalesce(p_metadata_filters, '{}'::jsonb)
  ),
  grouped as (
    select summary_group,
      count(*) as feedback_count,
      count(*) filter (where rating in ('thumbs_up', 'correct')) as positive_count,
      count(*) filter (where rating in ('thumbs_down', 'incorrect', 'unsafe')) as negative_count,
      count(*) filter (where rating = 'partly_correct') as partial_count,
      avg(score) filter (where score is not null) as mean_score,
      max(created_at) as latest_feedback_at
    from filtered
    where summary_group is not null and summary_group <> ''
    group by summary_group
  ),
  rating_counts as (
    select summary_group, coalesce(rating, 'unrated') as rating_key, count(*) as rating_count
    from filtered
    where summary_group is not null and summary_group <> ''
    group by summary_group, coalesce(rating, 'unrated')
  ),
  rating_totals as (
    select summary_group, jsonb_object_agg(rating_key, rating_count) as rating_map
    from rating_counts group by summary_group
  )
  select grouped.summary_group, grouped.feedback_count, grouped.positive_count,
    grouped.negative_count, grouped.partial_count, grouped.mean_score,
    coalesce(rating_totals.rating_map, '{}'::jsonb), grouped.latest_feedback_at
  from grouped left join rating_totals using (summary_group)
  order by grouped.latest_feedback_at desc, grouped.summary_group asc
  limit greatest(1, least(coalesce(p_limit, 5000), 10000));
end;
$function$;

REVOKE ALL
  ON FUNCTION "public"."gateway_feedback_summary"(uuid, uuid[], text, text, text, text, uuid, uuid, timestamp WITH time zone, timestamp WITH time zone, jsonb, integer)
  FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_fetch_compiled_context_authority (
  workspace_id uuid,
  model        text,
  endpoint     text,
  api_key_id   uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  v_context jsonb;
  v_budget jsonb;
  v_runtime jsonb;
  v_owner uuid;
begin
  if model is null or length(model) not between 1 and 512
      or endpoint is null or length(endpoint) not between 1 and 128 then
    raise exception 'invalid_context_request' using errcode = '22023';
  end if;
  v_context := private.gateway_compiled_context_access(workspace_id, model, endpoint, api_key_id);
  v_budget := public.gateway_workspace_budget_status(workspace_id, 0);
  if coalesce((v_context->'key_limit_ok'->>'ok')::boolean,true)
      and not coalesce((v_budget->>'ok')::boolean,true) then
    v_context := jsonb_set(v_context,'{key_limit_ok}',v_budget,true);
  end if;
  if jsonb_array_length(coalesce(v_budget->'budgets','[]'::jsonb)) > 0 then
    v_context := jsonb_set(v_context,'{key_limit_ok,budgets}',v_budget->'budgets',true);
  end if;
  v_runtime := public.gateway_fetch_workspace_runtime(workspace_id);
  select w.owner_user_id into v_owner from public.workspaces w where w.id = workspace_id;
  if v_owner is null then raise exception 'workspace_owner_missing'; end if;
  return jsonb_build_object('context',v_context,
    'workspaceRuntime',v_runtime || jsonb_build_object('ownerId',v_owner));
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_fetch_compiled_context_authority"(uuid, text, text, uuid) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_fetch_public_catalog (
  p_model     text,
  p_endpoints text[]
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  v_endpoint text;
  v_model text;
  v_providers jsonb;
  v_pricing jsonb;
  v_variants jsonb := '[]'::jsonb;
  v_provider_rows jsonb;
  v_route_modes jsonb;
  v_until timestamptz := now() + interval '5 minutes';
  v_boundary timestamptz;
begin
  if p_model is null or length(p_model) > 512 or p_model like '@%'
    or cardinality(p_endpoints) not between 1 and 2
    or not (p_endpoints <@ array['text.generate','responses','chat.completions','messages']::text[]) then
    raise exception 'invalid_public_catalog_request' using errcode = '22023';
  end if;
  v_model := coalesce(
    (select a.model_slug from public.v2_model_aliases a where a.alias_slug=p_model and a.enabled limit 1),
    (select r.model_slug from public.v2_model_provider_routes r
      where position('/' in p_model)>0 and r.provider_slug=split_part(p_model,'/',1)
        and r.provider_model_slug=regexp_replace(p_model,'^[^/]+/','') and r.routing_enabled
        and (r.effective_from is null or r.effective_from<=now()) and (r.effective_to is null or now()<r.effective_to)
      order by coalesce(r.effective_from,to_timestamp(0)) desc,r.provider_model_id limit 1), p_model);

  foreach v_endpoint in array p_endpoints loop
    with provider_rows as (
      select distinct on (r.provider_model_id)
        r.*, c.status as capability_status,c.params,c.max_input_tokens as cap_input,c.max_output_tokens as cap_output,
        coalesce(case when jsonb_typeof(r.metadata->'availability') = 'object' and (r.metadata->'availability'->>'mode') in ('allowlist','blocklist') and jsonb_typeof(r.metadata->'availability'->'countries') = 'array' then r.metadata->'availability' end,p.metadata->'availability') as availability,
        p.prompt_training_policy,p.data_policy_tier,p.data_policy_confidence,p.data_policy_contract_mode,p.data_policy_variant
      from public.v2_model_provider_routes r
      join public.v2_models m on m.model_slug=r.model_slug
      join public.v2_providers p on p.provider_slug=r.provider_slug
      join public.v2_route_capabilities c on c.provider_model_id=r.provider_model_id
      where r.model_slug=v_model and not coalesce(m.hidden,false)
        and (m.status is null or lower(m.status) in ('active','available','deprecated'))
        and (m.retired_at is null or m.retired_at>now())
        and c.capability_id=v_endpoint and c.status in ('active','deranked','deranked_lvl1','deranked_lvl2','deranked_lvl3')
        and r.routing_enabled
        and (p.status <> 'external' or coalesce(r.metadata->>'external_routing_override', 'false') = 'true')
        and (r.effective_from is null or r.effective_from<=now())
        and (r.effective_to is null or now()<r.effective_to)
        and (c.effective_from is null or c.effective_from<=now())
        and (c.effective_to is null or now()<c.effective_to)
      order by r.provider_model_id,coalesce(c.updated_at,c.created_at) desc
    )
    select coalesce(jsonb_agg(jsonb_build_object(
      'provider_id',r.provider_slug,'api_model_id',r.model_slug,'pricing_key',r.provider_slug,
      'provider_model_slug',r.provider_model_slug,'availability',r.availability,'model_status',r.status,
      'external_routing_override',coalesce((r.metadata->>'external_routing_override')::boolean,false),
      'input_modalities',r.input_modalities,'output_modalities',r.output_modalities,
      'prompt_training_policy',coalesce(r.prompt_training_policy,'unknown'),
      'data_policy_tier',coalesce(r.data_policy_tier,'unknown'),'data_policy_confidence',coalesce(r.data_policy_confidence,'unknown'),
      'data_policy_contract_mode',coalesce(r.data_policy_contract_mode,'none'),'data_policy_variant',coalesce(r.data_policy_variant,'standard'),
      'capability_status',r.capability_status,'capability_params',coalesce(r.params,'{}'::jsonb),
      'max_input_tokens',r.cap_input,'max_output_tokens',r.cap_output,'supports_endpoint',true,'base_weight',1,'byok_meta','[]'::jsonb
    ) order by r.provider_model_id),'[]'::jsonb),
    coalesce(jsonb_object_agg(r.provider_slug,(
      select jsonb_build_object('provider',r.provider_slug,'model',v_model,'endpoint',v_endpoint,
        'effective_from',min(pr.effective_from),'effective_to',min(pr.effective_to),'currency','USD','version',max(pr.updated_at),
        'rules',coalesce(jsonb_agg(jsonb_build_object(
          'id',pr.rule_id,'pricing_plan',pr.pricing_plan,'meter',pr.meter,'unit',pr.unit,'unit_size',pr.unit_size,
          'price_per_unit',pr.price_per_unit,'included_quantity',pr.included_quantity,'currency',pr.currency,
          'match',pr.match,'priority',pr.priority,'billing_timestamp_basis',coalesce(pr.billing_timestamp_basis,'request_start'),
          'time_windows',coalesce(pr.time_windows,'[]'::jsonb)
        ) order by pr.priority desc,coalesce(pr.effective_from,now()) desc),'[]'::jsonb))
      from (
        select meter.sku_meter_id::text as rule_id,route.provider_slug||':'||route.model_slug||':'||sku.operation as model_key,
          sku.operation as capability_id,coalesce(sku.service_tier_slug,'standard') as pricing_plan,meter.meter_key as meter,
          meter.unit,meter.unit_quantity as unit_size,meter.price_nanos/1000000000.0 as price_per_unit,
          coalesce(nullif(meter.metadata->>'included_quantity','')::numeric,nullif(sku.metadata->>'included_quantity','')::numeric,0) as included_quantity,
          sku.currency,coalesce(nullif(meter.metadata->>'priority','')::integer,meter.meter_order,100) as priority,
          sku.effective_from,sku.effective_to,coalesce(sku.metadata->'match',meter.metadata->'match','[]'::jsonb) as match,
          coalesce(sku.metadata->>'billing_timestamp_basis','request_start') as billing_timestamp_basis,
          coalesce(sku.metadata->'time_windows','[]'::jsonb) as time_windows,greatest(sku.updated_at,meter.updated_at) as updated_at
        from public.v2_pricing_skus sku join public.v2_model_provider_routes route using(provider_model_id)
          join public.v2_pricing_sku_meters meter using(sku_id) where sku.status='active' and meter.billable
      ) pr
      where pr.model_key=r.provider_slug||':'||v_model||':'||v_endpoint and pr.capability_id=v_endpoint
        and (pr.effective_from is null or pr.effective_from<=now()) and (pr.effective_to is null or now()<pr.effective_to)
    )),'{}'::jsonb) into v_providers,v_pricing from provider_rows r;
    v_variants := v_variants || jsonb_build_array(jsonb_build_object('endpoint',v_endpoint,'providers',v_providers,'pricing',v_pricing));
  end loop;

  select coalesce(jsonb_agg(to_jsonb(p)),'[]'::jsonb) into v_provider_rows from (
    select provider_slug,status,routing_enabled,routable,credential_mode,provider_family_slug,offer_scope,offer_label,
      residency_mode,default_execution_regions,default_data_regions,zero_data_retention,prompt_training_policy,
      data_policy_tier,data_policy_confidence,data_policy_contract_mode,data_policy_variant,stream_cancellation_support,
      stream_cancellation_stops_provider_billing,stream_cancellation_usage_recovery,stream_cancellation_evidence_kind,
      stream_cancellation_source_url,jsonb_build_object('availability',metadata->'availability') as metadata
    from public.v2_providers where provider_slug in (
      select item->>'provider_id' from jsonb_array_elements(v_variants) variant,
        lateral jsonb_array_elements(variant->'providers') item)
  ) p;
  select coalesce(jsonb_agg(jsonb_build_object('provider_slug',provider_slug,'credential_mode',credential_mode)),'[]'::jsonb)
    into v_route_modes from public.v2_model_provider_routes where model_slug=v_model and routing_enabled and status in ('active','degraded');

  -- Absolute deadlines also cover future route/capability/price activation, not
  -- only currently selected price cards. KV's physical TTL is not freshness.
  select min(boundary) into v_boundary from (
    select effective_from as boundary from public.v2_model_provider_routes where model_slug=v_model
    union all select effective_to from public.v2_model_provider_routes where model_slug=v_model
    union all select c.effective_from from public.v2_route_capabilities c join public.v2_model_provider_routes r using(provider_model_id) where r.model_slug=v_model
    union all select c.effective_to from public.v2_route_capabilities c join public.v2_model_provider_routes r using(provider_model_id) where r.model_slug=v_model
    union all select s.effective_from from public.v2_pricing_skus s join public.v2_model_provider_routes r using(provider_model_id) where r.model_slug=v_model and s.status='active'
    union all select s.effective_to from public.v2_pricing_skus s join public.v2_model_provider_routes r using(provider_model_id) where r.model_slug=v_model and s.status='active'
    union all select retired_at from public.v2_models where model_slug=v_model
  ) boundaries where boundary>now();
  v_until := least(v_until,coalesce(v_boundary,v_until));
  return jsonb_build_object('version',1,'model',p_model,'resolvedModel',v_model,'endpoints',p_endpoints,
    'checkedAt',floor(extract(epoch from now())*1000),'expiresAt',floor(extract(epoch from v_until)*1000),
    'variants',v_variants,'providerRows',v_provider_rows,'routeModes',v_route_modes);
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_fetch_public_catalog"(text, text[]) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_fetch_request_context (
  workspace_id uuid,
  model        text,
  endpoint     text,
  api_key_id   uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_context jsonb;
  v_budget_status jsonb;
begin
  v_context := public.gateway_fetch_request_context_without_workspace_budget(workspace_id, model, endpoint, api_key_id);
  v_budget_status := public.gateway_workspace_budget_status(workspace_id, 0);
  if coalesce((v_context->'key_limit_ok'->>'ok')::boolean, true)
    and not coalesce((v_budget_status->>'ok')::boolean, true) then
    v_context := jsonb_set(v_context, '{key_limit_ok}', v_budget_status, true);
  end if;
  return v_context;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_fetch_request_context"(uuid, text, text, uuid) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_fetch_request_context_bundle (
  workspace_id    uuid,
  model           text,
  endpoint        text,
  api_key_id      uuid,
  include_catalog boolean DEFAULT true
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  v_context jsonb;
  v_budget jsonb;
  v_byok jsonb;
  v_settings jsonb;
  v_billing text;
  v_catalog jsonb;
  v_endpoints text[];
begin
  if model like '@%' or endpoint not in ('responses','chat.completions','messages','text.generate') then
    raise exception 'unsupported_context_bundle' using errcode='22023';
  end if;
  v_context := private.gateway_context_access(workspace_id,model,endpoint,api_key_id);
  v_budget := public.gateway_workspace_budget_status(workspace_id,0);
  if coalesce((v_context->'key_limit_ok'->>'ok')::boolean,true) and not coalesce((v_budget->>'ok')::boolean,true) then
    v_context := jsonb_set(v_context,'{key_limit_ok}',v_budget,true);
  end if;
  -- Return configured workspace budgets even when below their limit, so Workers
  -- never reuse an admission snapshot for a workspace with a spending cap.
  if jsonb_array_length(coalesce(v_budget->'budgets','[]'::jsonb))>0 then
    v_context := jsonb_set(v_context,'{key_limit_ok,budgets}',v_budget->'budgets',true);
  end if;
  select coalesce(jsonb_object_agg(provider_id,items),'{}'::jsonb) into v_byok from (
    select bk.provider_id,jsonb_agg(jsonb_build_object('provider_id',bk.provider_id,'id',bk.id,
      'fingerprint_sha256',bk.fingerprint_sha256,'key_version',bk.key_version,'always_use',bk.always_use)) as items
    from public.byok_keys bk where bk.workspace_id=gateway_fetch_request_context_bundle.workspace_id and bk.enabled
    group by bk.provider_id
  ) byok;
  select jsonb_build_object(
    'routing_mode',s.routing_mode,'byok_fallback_enabled',s.byok_fallback_enabled,'beta_channel_enabled',s.beta_channel_enabled,
    'alpha_channel_enabled',s.alpha_channel_enabled,'cache_aware_routing_enabled',s.cache_aware_routing_enabled,
    'privacy_zdr_only',s.privacy_zdr_only,'privacy_enable_paid_may_train',s.privacy_enable_paid_may_train,
    'privacy_enable_free_may_train',s.privacy_enable_free_may_train,'privacy_enable_input_output_logging',s.privacy_enable_input_output_logging,
    'io_logging_enabled',s.io_logging_enabled,'io_logging_include_provider_payloads',s.io_logging_include_provider_payloads,
    'data_contribution_enabled',s.data_contribution_enabled,'data_contribution_policy_version',s.data_contribution_policy_version,
    'data_contribution_sample_rate_bps',s.data_contribution_sample_rate_bps,'data_contribution_classifier_sample_rate_bps',s.data_contribution_classifier_sample_rate_bps,
    'data_contribution_discount_bps',s.data_contribution_discount_bps,'response_healing_enabled',s.response_healing_enabled,
    'response_healing_locked',s.response_healing_locked,'response_healing_mode',s.response_healing_mode
  ) into v_settings from public.workspace_settings s where s.workspace_id=gateway_fetch_request_context_bundle.workspace_id;
  select billing_mode into v_billing from public.workspaces where id=workspace_id;
  if v_settings is null or v_billing is null or v_billing not in ('wallet','invoice') then
    raise exception 'workspace_context_enrichment_missing';
  end if;
  v_endpoints := case when endpoint='text.generate' then array['text.generate'] else array['text.generate',endpoint] end;
  if include_catalog then v_catalog := public.gateway_fetch_public_catalog(model,v_endpoints); end if;
  return jsonb_build_object('context',v_context,'byok',v_byok,'settings',v_settings,'billingMode',v_billing,'catalog',v_catalog);
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_fetch_request_context_bundle"(uuid, text, text, uuid, boolean) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_fetch_request_context_bundle_v2 (
  workspace_id      uuid,
  model             text,
  endpoint          text,
  api_key_id        uuid,
  include_catalog   boolean DEFAULT true,
  include_workspace boolean DEFAULT true
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  v_context jsonb;
  v_budget jsonb;
  v_catalog jsonb;
  v_workspace jsonb;
  v_endpoints text[];
begin
  if model is null or length(model) not between 1 and 512 or model like '@%'
    or endpoint is null or endpoint not in ('responses','chat.completions','messages','text.generate')
    or include_catalog is null or include_workspace is null then
    raise exception 'unsupported_context_bundle' using errcode='22023';
  end if;
  v_context := private.gateway_context_access(workspace_id,model,endpoint,api_key_id);
  v_budget := public.gateway_workspace_budget_status(workspace_id,0);
  if coalesce((v_context->'key_limit_ok'->>'ok')::boolean,true) and not coalesce((v_budget->>'ok')::boolean,true) then
    v_context := jsonb_set(v_context,'{key_limit_ok}',v_budget,true);
  end if;
  if jsonb_array_length(coalesce(v_budget->'budgets','[]'::jsonb))>0 then
    v_context := jsonb_set(v_context,'{key_limit_ok,budgets}',v_budget->'budgets',true);
  end if;
  if include_workspace then v_workspace := public.gateway_fetch_workspace_runtime(workspace_id); end if;
  v_endpoints := case when endpoint='text.generate' then array['text.generate'] else array['text.generate',endpoint] end;
  if include_catalog then v_catalog := public.gateway_fetch_public_catalog(model,v_endpoints); end if;
  return jsonb_build_object('context',v_context,'workspaceRuntime',v_workspace,'catalog',v_catalog);
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_fetch_request_context_bundle_v2"(uuid, text, text, uuid, boolean, boolean) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_fetch_request_context_with_reservations (
  workspace_id uuid,
  model        text,
  endpoint     text,
  api_key_id   uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  payload jsonb;
  min_balance_nanos bigint := case when endpoint like 'video.%' or endpoint like 'batch%' then 1000000000 else 100000000 end; -- 1.00 USD
  wallet_balance_nanos bigint := 0;
  wallet_reserved_nanos bigint := 0;
  wallet_available_nanos bigint := 0;
  credit_status jsonb;
  enriched_pricing jsonb;
begin
  payload := public.gateway_fetch_request_context(workspace_id, model, endpoint, api_key_id);
  if payload is null then
    return null;
  end if;

  with provider_cards as (
    select provider_key, card
    from jsonb_each(coalesce(payload->'pricing', '{}'::jsonb)) as p(provider_key, card)
  ),
  enriched_cards as (
    select
      provider_key,
      jsonb_set(
        card,
        '{rules}',
        coalesce(rules.enriched_rules, '[]'::jsonb),
        true
      ) as card
    from provider_cards
    cross join lateral (
      select jsonb_agg(
        rule_item.value ||
        jsonb_build_object(
          'billing_timestamp_basis', coalesce(rule_row.billing_timestamp_basis, 'request_start'),
          'time_windows', coalesce(rule_row.time_windows, '[]'::jsonb)
        )
        order by rule_item.ordinality
      ) as enriched_rules
      from jsonb_array_elements(coalesce(card->'rules', '[]'::jsonb)) with ordinality as rule_item(value, ordinality)
      left join private.v2_rpc_pricing_compat rule_row
        on rule_row.rule_id::text = rule_item.value->>'id'
    ) rules
  )
  select coalesce(jsonb_object_agg(provider_key, card), '{}'::jsonb)
  into enriched_pricing
  from enriched_cards;

  payload := jsonb_set(payload, '{pricing}', coalesce(enriched_pricing, '{}'::jsonb), true);

  select
    coalesce(w.balance_nanos, 0)::bigint,
    coalesce(w.reserved_nanos, 0)::bigint
  into
    wallet_balance_nanos,
    wallet_reserved_nanos
  from public.wallets w
  where w.workspace_id = gateway_fetch_request_context_with_reservations.workspace_id
  limit 1;

  if not found then
    credit_status := jsonb_build_object('ok', false, 'reason', 'wallet_missing');
    return jsonb_set(payload, '{credit_ok}', credit_status, true);
  end if;

  wallet_available_nanos := greatest(wallet_balance_nanos - wallet_reserved_nanos, 0);

  if wallet_available_nanos >= min_balance_nanos then
    credit_status := jsonb_build_object(
      'ok', true,
      'balance_nanos', wallet_available_nanos,
      'raw_balance_nanos', wallet_balance_nanos,
      'reserved_nanos', wallet_reserved_nanos,
      'available_nanos', wallet_available_nanos
    );
  else
    credit_status := jsonb_build_object(
      'ok', false,
      'reason', 'insufficient_funds',
      'balance_nanos', wallet_available_nanos,
      'raw_balance_nanos', wallet_balance_nanos,
      'reserved_nanos', wallet_reserved_nanos,
      'available_nanos', wallet_available_nanos
    );
  end if;

  payload := jsonb_set(payload, '{credit_ok}', credit_status, true);

  if jsonb_typeof(payload->'team_enrichment') = 'object' then
    payload := jsonb_set(payload, '{team_enrichment,balance_nanos}', to_jsonb(wallet_available_nanos), true);
    payload := jsonb_set(payload, '{team_enrichment,available_nanos}', to_jsonb(wallet_available_nanos), true);
    payload := jsonb_set(payload, '{team_enrichment,reserved_nanos}', to_jsonb(wallet_reserved_nanos), true);
    payload := jsonb_set(
      payload,
      '{team_enrichment,balance_usd}',
      to_jsonb(round((wallet_available_nanos::numeric / 1000000000.0)::numeric, 2)),
      true
    );
    payload := jsonb_set(payload, '{team_enrichment,balance_is_low}', to_jsonb(wallet_available_nanos < min_balance_nanos), true);
  end if;

  return payload;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_fetch_request_context_with_reservations"(uuid, text, text, uuid) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_fetch_request_context_without_workspace_budget (
  workspace_id uuid,
  model        text,
  endpoint     text,
  api_key_id   uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  credit_status       jsonb;
  key_status          jsonb;
  key_limit_status    jsonb;
  min_balance_nanos bigint := case when endpoint like 'video.%' or endpoint like 'batch%' then 1000000000 else 100000000 end; -- 1.00 USD

  providers           jsonb;
  pricing             jsonb;
  preset_data         jsonb := null;

  -- key row fields
  v_key_active        boolean;
  v_key_team_ok       boolean;
  v_soft_blocked      boolean;

  v_day_req_limit     bigint;
  v_wk_req_limit      bigint;
  v_mo_req_limit      bigint;
  v_day_cost_limit    bigint;
  v_wk_cost_limit     bigint;
  v_mo_cost_limit     bigint;

  now_utc             timestamptz := (now() at time zone 'utc');
  day_start           timestamptz := date_trunc('day',  now_utc);
  week_start          timestamptz := date_trunc('week', now_utc);   -- Monday 00:00 UTC
  month_start         timestamptz := date_trunc('month', now_utc);

  used_day_reqs       bigint;
  used_wk_reqs        bigint;
  used_mo_reqs        bigint;
  used_day_cost       bigint;
  used_wk_cost        bigint;
  used_mo_cost        bigint;

  within_limits       boolean := true;
  limit_reason        text := null;
  limit_window        text := null;
  limit_metric        text := null;
  current_value       bigint := null;
  limit_value         bigint := null;
  limit_reset_at      timestamptz := null;

  -- Preset handling
  is_preset           boolean := false;
  preset_name         text := null;
  preset_publisher    text := null;

  -- Resolve model from alias if exists
  resolved_model      text := gateway_fetch_request_context_without_workspace_budget.model;
  base_model          text;

  team_enrichment     jsonb;
  key_enrichment      jsonb;

  -- Team aggregates
  team_total_requests bigint;
  team_total_spend_nanos bigint;
  team_spend_24h_nanos bigint;
  team_spend_7d_nanos bigint;
  team_spend_30d_nanos bigint;
  team_requests_1h bigint;
  team_requests_24h bigint;
  team_created_at timestamptz;
  team_tier text;
  team_balance_nanos bigint;
  team_reserved_nanos bigint;

  -- Key aggregates
  key_name text;
  key_created_at timestamptz;
  key_total_requests bigint;
  key_total_spend_nanos bigint;
begin
  base_model := gateway_fetch_request_context_without_workspace_budget.model;
  -- hard requirement: key must be provided
  if gateway_fetch_request_context_without_workspace_budget.api_key_id is null then
    raise exception using errcode = '22023', message = 'missing_api_key', detail = 'api_key_id is required';
  end if;

  -- Check if model is a preset (starts with @)
  if base_model like '@%' then
    is_preset := true;
    preset_name := substring(base_model from 2); -- Remove @ prefix

    -- Fetch preset configuration. Qualified references resolve a
    -- public publisher globally; unqualified references remain workspace-local.
    if position('/' in preset_name) > 0 then
      preset_publisher := split_part(preset_name, '/', 1);
      preset_name := substring(preset_name from position('/' in preset_name) + 1);
      select jsonb_build_object(
        'id', p.id, 'name', p.name, 'slug', p.slug, 'description', p.description,
        'config', p.config, 'visibility', p.visibility, 'publisher', w.publisher_handle
      ) into preset_data
      from public.presets p
      join public.workspaces w on w.id = p.workspace_id
      where p.archived_at is null and lower(p.slug) = lower(preset_name)
        and p.visibility = 'public'
        and true
        and (lower(w.publisher_handle) = lower(preset_publisher) or exists (select 1 from public.workspace_publisher_handle_aliases alias where alias.workspace_id = w.id and alias.handle = lower(preset_publisher)))
      limit 1;
    else
      select jsonb_build_object(
        'id', p.id, 'name', p.name,
        'slug', coalesce(nullif(p.slug, ''), regexp_replace(p.name, '^@', '')),
        'description', p.description, 'config', p.config, 'visibility', p.visibility
      ) into preset_data
      from public.presets p
      where p.archived_at is null and lower(coalesce(nullif(p.slug, ''), regexp_replace(p.name, '^@', ''))) = lower(preset_name)
        and p.workspace_id = gateway_fetch_request_context_without_workspace_budget.workspace_id
        and (
          p.visibility in ('public', 'team')
          or p.created_by = (
            select ak.created_by from public.keys ak
            where ak.id = gateway_fetch_request_context_without_workspace_budget.api_key_id
              and ak.workspace_id = gateway_fetch_request_context_without_workspace_budget.workspace_id
              and ak.status = 'active'
          )
        )
      limit 1;
    end if;

    if preset_data is null then
      raise exception using
        errcode = '22023',
        message = 'preset_not_found',
        detail = format('Preset "%s" not found or not accessible', preset_name);
    end if;

    -- Extract model from preset config (fallback to default/default_model/model/first models entry)
    base_model := coalesce(
      preset_data->'config'->>'defaultModel',
      preset_data->'config'->>'default_model',
      preset_data->'config'->>'model',
      preset_data->'config'->'models'->>0,
      preset_data->'config'->'allowedModels'->>0,
      preset_data->'config'->'allowed_models'->>0
    );

    if base_model is null then
      raise exception using
        errcode = '22023',
        message = 'preset_no_model',
        detail = format('Preset "%s" has no model configured', preset_name);
    end if;
  end if;

  -- Resolve alias/model indirection:
  -- 1) explicit alias table (`v2_model_aliases`)
  -- 2) provider-scoped slug form (`provider/provider_model_slug`)
  resolved_model := coalesce(
    (
      select a.api_model_id
      from (select alias_slug, model_slug as api_model_id, enabled as is_enabled from public.v2_model_aliases) a
      where a.alias_slug = base_model
        and a.is_enabled = true
        and a.api_model_id is not null
      limit 1
    ),
    (
      select m.api_model_id
      from (select provider_model_id as provider_api_model_id, provider_slug as provider_id, model_slug as api_model_id, model_slug as model_id, provider_model_slug, routing_enabled as is_active_gateway, status as routing_status, input_modalities, output_modalities, context_length, max_output_tokens, effective_from, effective_to, created_at, updated_at, metadata from public.v2_model_provider_routes) m
      where position('/' in base_model) > 0
        and m.provider_id = split_part(base_model, '/', 1)
        and m.provider_model_slug = regexp_replace(base_model, '^[^/]+/', '')
        and m.is_active_gateway
        and (m.effective_from is null or m.effective_from <= now() at time zone 'utc')
        and (m.effective_to   is null or (now() at time zone 'utc') < m.effective_to)
      order by coalesce(m.effective_from, to_timestamp(0)) desc, m.provider_api_model_id
      limit 1
    ),
    base_model
  );

  -- validate key row, status, and team
  select
    (k.status = 'active'),
    (k.workspace_id = gateway_fetch_request_context_without_workspace_budget.workspace_id),
    k.soft_blocked,
    k.daily_limit_requests,   k.weekly_limit_requests,   k.monthly_limit_requests,
    k.daily_limit_cost_nanos, k.weekly_limit_cost_nanos, k.monthly_limit_cost_nanos
  into
    v_key_active,
    v_key_team_ok,
    v_soft_blocked,
    v_day_req_limit, v_wk_req_limit, v_mo_req_limit,
    v_day_cost_limit, v_wk_cost_limit, v_mo_cost_limit
  from public.keys k
  where k.id = gateway_fetch_request_context_without_workspace_budget.api_key_id
  limit 1;

  if v_key_active is null then
    raise exception using errcode = '22023', message = 'api_key_not_found', detail = 'key id does not exist';
  end if;
  if not v_key_team_ok then
    raise exception using errcode = '22023', message = 'api_key_wrong_team', detail = 'key does not belong to provided workspace_id';
  end if;
  if not v_key_active then
    raise exception using errcode = '22023', message = 'api_key_inactive', detail = 'key status is not active';
  end if;

  key_status := jsonb_build_object('ok', true, 'mode', 'first_party');

  -- credit check
  credit_status :=
    coalesce((
      select case
        when greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0) >= min_balance_nanos then
          jsonb_build_object(
            'ok', true,
            'balance_nanos', greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0),
            'raw_balance_nanos', coalesce(w.balance_nanos, 0)::bigint,
            'reserved_nanos', coalesce(w.reserved_nanos, 0)::bigint,
            'available_nanos', greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0)
          )
        else
          jsonb_build_object(
            'ok', false,
            'reason', 'insufficient_funds',
            'balance_nanos', greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0),
            'raw_balance_nanos', coalesce(w.balance_nanos, 0)::bigint,
            'reserved_nanos', coalesce(w.reserved_nanos, 0)::bigint,
            'available_nanos', greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0)
          )
      end
      from public.wallets w
      where w.workspace_id = gateway_fetch_request_context_without_workspace_budget.workspace_id
      limit 1
    ), jsonb_build_object('ok', false, 'reason', 'wallet_missing'));

  -- per-key limits (requests + cost)
  select
    count(*) filter (where gr.created_at >= day_start)                                  as used_day_reqs,
    count(*) filter (where gr.created_at >= week_start)                                 as used_wk_reqs,
    count(*) filter (where gr.created_at >= month_start)                                as used_mo_reqs,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= day_start), 0)::bigint   as used_day_cost,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= week_start), 0)::bigint  as used_wk_cost,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= month_start), 0)::bigint as used_mo_cost
  into
    used_day_reqs, used_wk_reqs, used_mo_reqs,
    used_day_cost, used_wk_cost, used_mo_cost
  from public.gateway_requests gr
  where gr.key_id  = gateway_fetch_request_context_without_workspace_budget.api_key_id
    and gr.workspace_id = gateway_fetch_request_context_without_workspace_budget.workspace_id
    and gr.success is true
    and gr.created_at >= month_start;

  if v_soft_blocked then
    within_limits := false;
    limit_reason := 'key_limit_soft_blocked';
    limit_metric := 'soft_blocked';
  end if;
  if within_limits and v_day_req_limit > 0 and used_day_reqs >= v_day_req_limit then
    within_limits := false;
    limit_reason := 'daily_request_limit_reached';
    limit_window := 'daily';
    limit_metric := 'requests';
    current_value := used_day_reqs;
    limit_value := v_day_req_limit;
    limit_reset_at := day_start + interval '1 day';
  end if;
  if within_limits and v_wk_req_limit > 0 and used_wk_reqs >= v_wk_req_limit then
    within_limits := false;
    limit_reason := 'weekly_request_limit_reached';
    limit_window := 'weekly';
    limit_metric := 'requests';
    current_value := used_wk_reqs;
    limit_value := v_wk_req_limit;
    limit_reset_at := week_start + interval '1 week';
  end if;
  if within_limits and v_mo_req_limit > 0 and used_mo_reqs >= v_mo_req_limit then
    within_limits := false;
    limit_reason := 'monthly_request_limit_reached';
    limit_window := 'monthly';
    limit_metric := 'requests';
    current_value := used_mo_reqs;
    limit_value := v_mo_req_limit;
    limit_reset_at := month_start + interval '1 month';
  end if;
  if within_limits and v_day_cost_limit > 0 and used_day_cost >= v_day_cost_limit then
    within_limits := false;
    limit_reason := 'daily_cost_limit_reached';
    limit_window := 'daily';
    limit_metric := 'cost';
    current_value := used_day_cost;
    limit_value := v_day_cost_limit;
    limit_reset_at := day_start + interval '1 day';
  end if;
  if within_limits and v_wk_cost_limit > 0 and used_wk_cost >= v_wk_cost_limit then
    within_limits := false;
    limit_reason := 'weekly_cost_limit_reached';
    limit_window := 'weekly';
    limit_metric := 'cost';
    current_value := used_wk_cost;
    limit_value := v_wk_cost_limit;
    limit_reset_at := week_start + interval '1 week';
  end if;
  if within_limits and v_mo_cost_limit > 0 and used_mo_cost >= v_mo_cost_limit then
    within_limits := false;
    limit_reason := 'monthly_cost_limit_reached';
    limit_window := 'monthly';
    limit_metric := 'cost';
    current_value := used_mo_cost;
    limit_value := v_mo_cost_limit;
    limit_reset_at := month_start + interval '1 month';
  end if;

  key_limit_status :=
    jsonb_build_object(
      'ok', within_limits,
      'reason', limit_reason,
      'limit_window', limit_window,
      'limit_metric', limit_metric,
      'current_value', current_value,
      'limit_value', limit_value,
      'reset_at', to_jsonb(limit_reset_at),
      'now', to_jsonb(now_utc),
      'buckets', jsonb_build_object(
        'daily', jsonb_build_object(
          'window_start', to_jsonb(day_start),
          'requests_used', used_day_reqs,
          'requests_limit', v_day_req_limit,
          'cost_used_nanos', used_day_cost,
          'cost_limit_nanos', v_day_cost_limit
        ),
        'weekly', jsonb_build_object(
          'window_start', to_jsonb(week_start),
          'requests_used', used_wk_reqs,
          'requests_limit', v_wk_req_limit,
          'cost_used_nanos', used_wk_cost,
          'cost_limit_nanos', v_wk_cost_limit
        ),
        'monthly', jsonb_build_object(
          'window_start', to_jsonb(month_start),
          'requests_used', used_mo_reqs,
          'requests_limit', v_mo_req_limit,
          'cost_used_nanos', used_mo_cost,
          'cost_limit_nanos', v_mo_cost_limit
        )
      )
    );

  -- ============================================================================
  -- TEAM & KEY ENRICHMENT (Wide Event Context for Observability)
  -- Purpose: Gather user/team context for comprehensive logging (loggingsucks.com pattern)
  -- ============================================================================
  -- Team metadata & wallet
  select
    t.created_at,
    coalesce(t.tier, 'basic'),
    greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0),
    coalesce(w.reserved_nanos, 0)::bigint
  into
    team_created_at,
    team_tier,
    team_balance_nanos,
    team_reserved_nanos
  from public.workspaces t
  left join public.wallets w on w.workspace_id = t.id
  where t.id = gateway_fetch_request_context_without_workspace_budget.workspace_id
  limit 1;

  -- Team spend & request aggregates
  select
    count(*),
    coalesce(sum(gr.cost_nanos), 0)::bigint,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= now_utc - interval '24 hours'), 0)::bigint,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= now_utc - interval '7 days'), 0)::bigint,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= now_utc - interval '30 days'), 0)::bigint,
    count(*) filter (where gr.created_at >= now_utc - interval '1 hour'),
    count(*) filter (where gr.created_at >= now_utc - interval '24 hours')
  into
    team_total_requests,
    team_total_spend_nanos,
    team_spend_24h_nanos,
    team_spend_7d_nanos,
    team_spend_30d_nanos,
    team_requests_1h,
    team_requests_24h
  from public.gateway_requests gr
  where gr.workspace_id = gateway_fetch_request_context_without_workspace_budget.workspace_id
    and gr.success is true;

  -- Calculate tier using calendar-month qualification + lock-window grace.
  -- Function maintains team tier/counters in database when state changes.
  team_tier := calculate_tier_with_grace(gateway_fetch_request_context_without_workspace_budget.workspace_id, team_spend_30d_nanos);

  team_enrichment := jsonb_build_object(
    'tier', team_tier,
    'created_at', to_jsonb(team_created_at),
    'account_age_days', extract(epoch from (now_utc - team_created_at)) / 86400,
    'balance_nanos', team_balance_nanos,
    'available_nanos', team_balance_nanos,
    'reserved_nanos', team_reserved_nanos,
    'balance_usd', round((team_balance_nanos::numeric / 1000000000.0)::numeric, 2),
    'balance_is_low', team_balance_nanos < min_balance_nanos,
    'total_requests', team_total_requests,
    'total_spend_nanos', team_total_spend_nanos,
    'total_spend_usd', round((team_total_spend_nanos::numeric / 1000000000.0)::numeric, 2),
    'spend_24h_nanos', team_spend_24h_nanos,
    'spend_24h_usd', round((team_spend_24h_nanos::numeric / 1000000000.0)::numeric, 4),
    'spend_7d_nanos', team_spend_7d_nanos,
    'spend_7d_usd', round((team_spend_7d_nanos::numeric / 1000000000.0)::numeric, 2),
    'spend_30d_nanos', team_spend_30d_nanos,
    'spend_30d_usd', round((team_spend_30d_nanos::numeric / 1000000000.0)::numeric, 2),
    'requests_1h', team_requests_1h,
    'requests_24h', team_requests_24h
  );

  -- Key metadata & aggregates
  select
    k.name,
    k.created_at
  into
    key_name,
    key_created_at
  from public.keys k
  where k.id = gateway_fetch_request_context_without_workspace_budget.api_key_id
  limit 1;

  select
    count(*),
    coalesce(sum(gr.cost_nanos), 0)::bigint
  into
    key_total_requests,
    key_total_spend_nanos
  from public.gateway_requests gr
  where gr.key_id = gateway_fetch_request_context_without_workspace_budget.api_key_id
    and gr.success is true;

  key_enrichment := jsonb_build_object(
    'name', key_name,
    'created_at', to_jsonb(key_created_at),
    'key_age_days', extract(epoch from (now_utc - key_created_at)) / 86400,
    'total_requests', key_total_requests,
    'total_spend_nanos', key_total_spend_nanos,
    'total_spend_usd', round((key_total_spend_nanos::numeric / 1000000000.0)::numeric, 2),
    'requests_today', used_day_reqs,
    'spend_today_nanos', used_day_cost,
    'spend_today_usd', round((used_day_cost::numeric / 1000000000.0)::numeric, 4),
    'daily_limit_pct', case
      when v_day_req_limit > 0 then round((used_day_reqs::numeric / v_day_req_limit::numeric * 100)::numeric, 1)
      else null
    end
  );

  -- provider candidates (BYOK) + pricing, fully qualifying params
  with provider_rows as (
    select distinct on (m.provider_api_model_id)
      m.provider_api_model_id,
      m.provider_id,
      m.api_model_id,
      m.provider_model_slug, coalesce((select route.metadata -> 'availability' from public.v2_model_provider_routes route where route.provider_model_id = m.provider_api_model_id and jsonb_typeof(route.metadata -> 'availability') = 'object' and (route.metadata -> 'availability' ->> 'mode') in ('allowlist', 'blocklist') and jsonb_typeof(route.metadata -> 'availability' -> 'countries') = 'array'), p.metadata -> 'availability') as availability,
      m.routing_status as model_status,
      coalesce((m.metadata->>'external_routing_override')::boolean, false) as external_routing_override,
      m.input_modalities,
      m.output_modalities,
      p.prompt_training_policy,
      p.data_policy_tier,
      p.data_policy_confidence,
      p.data_policy_contract_mode,
	  p.data_policy_variant,
      c.status as capability_status,
      c.params as capability_params,
      c.max_input_tokens,
      c.max_output_tokens
    from (select provider_model_id as provider_api_model_id, provider_slug as provider_id, model_slug as api_model_id, model_slug as model_id, provider_model_slug, routing_enabled as is_active_gateway, status as routing_status, input_modalities, output_modalities, context_length, max_output_tokens, effective_from, effective_to, created_at, updated_at, metadata from public.v2_model_provider_routes) m
    join (select model_slug as model_id, lab_slug as organisation_id, name, description, status, hidden, announced_at as announcement_date, released_at as release_date, deprecated_at as deprecation_date, retired_at as retirement_date, previous_model_slug as previous_model_id, input_modalities as input_types, output_modalities as output_types, metadata, created_at, updated_at from public.v2_models) dm
      on dm.model_id = coalesce(m.model_id, m.api_model_id)
    join public.v2_providers p
      on p.provider_slug = m.provider_id
    join (select provider_model_id as provider_api_model_id, capability_id, status, params, max_input_tokens, max_output_tokens, effective_from, effective_to, created_at, updated_at from public.v2_route_capabilities) c
      on c.provider_api_model_id = m.provider_api_model_id
    where m.api_model_id = resolved_model
      and coalesce(dm.hidden, false) = false
      and (dm.status is null or lower(dm.status) in ('active', 'available', 'deprecated'))
      and (dm.retirement_date is null or dm.retirement_date > now() at time zone 'utc')
      and c.capability_id = gateway_fetch_request_context_without_workspace_budget.endpoint
      and c.status in ('active', 'deranked', 'deranked_lvl1', 'deranked_lvl2', 'deranked_lvl3')
      and m.is_active_gateway
      and (
        p.status <> 'external'
        or coalesce((m.metadata->>'external_routing_override')::boolean, false)
      )
      and (m.effective_from is null or m.effective_from <= now() at time zone 'utc')
      and (m.effective_to   is null or (now() at time zone 'utc') < m.effective_to)
    order by m.provider_api_model_id, coalesce(c.updated_at, c.created_at) desc
  )
  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'provider_id', pr.provider_id,
          'api_model_id', pr.api_model_id,
          'pricing_key', pr.provider_id,
          'provider_model_slug', pr.provider_model_slug, 'availability', pr.availability,
          'model_status', pr.model_status,
          'external_routing_override', pr.external_routing_override,
          'input_modalities', pr.input_modalities,
          'output_modalities', pr.output_modalities,
          'prompt_training_policy', coalesce(pr.prompt_training_policy, 'unknown'),
          'data_policy_tier', coalesce(pr.data_policy_tier, 'unknown'),
          'data_policy_confidence', coalesce(pr.data_policy_confidence, 'unknown'),
          'data_policy_contract_mode', coalesce(pr.data_policy_contract_mode, 'none'),
		  'data_policy_variant', coalesce(pr.data_policy_variant, 'standard'),
          'capability_status', pr.capability_status,
          'capability_params', coalesce(pr.capability_params, '{}'::jsonb),
          'max_input_tokens', pr.max_input_tokens,
          'max_output_tokens', pr.max_output_tokens,
          'supports_endpoint', true,
          'base_weight', 1,
          'byok_meta', coalesce((
            select jsonb_agg(
              jsonb_build_object(
                'provider_id', bk.provider_id,
                'id', bk.id,
                'name', bk.name,
                'fingerprint_sha256', bk.fingerprint_sha256,
                'key_version', bk.key_version,
                'always_use', bk.always_use
              )
            )
            from public.byok_keys bk
            where bk.workspace_id    = gateway_fetch_request_context_without_workspace_budget.workspace_id
              and bk.provider_id = pr.provider_id
              and bk.enabled     = true
          ), '[]'::jsonb)
        )
      ), '[]'::jsonb
    ) as provider_payload,
    coalesce(
      jsonb_object_agg(
        pr.provider_id,
        (
          with rules as (
            select r.*
            from (select meter.sku_meter_id::text as rule_id, route.provider_slug as provider_id, route.model_slug as api_model_id, route.provider_slug || ':' || route.model_slug || ':' || sku.operation as model_key, sku.operation as capability_id, coalesce(sku.service_tier_slug, 'standard') as pricing_plan, meter.meter_key as meter, meter.unit, meter.unit_quantity as unit_size, meter.price_nanos / 1000000000.0 as price_per_unit, coalesce(nullif(meter.metadata->>'included_quantity', '')::numeric, nullif(sku.metadata->>'included_quantity', '')::numeric, 0) as included_quantity, sku.currency, coalesce(nullif(meter.metadata->>'priority', '')::integer, meter.meter_order, 100) as priority, sku.effective_from, sku.effective_to, coalesce(sku.metadata->'match', meter.metadata->'match', '[]'::jsonb) as match, coalesce(sku.metadata->>'billing_timestamp_basis', 'request_start') as billing_timestamp_basis, coalesce(sku.metadata->'time_windows', '[]'::jsonb) as time_windows, greatest(sku.updated_at, meter.updated_at) as updated_at from public.v2_pricing_skus sku join public.v2_model_provider_routes route on route.provider_model_id = sku.provider_model_id join public.v2_pricing_sku_meters meter on meter.sku_id = sku.sku_id where sku.status = 'active' and meter.billable) r
            -- TODO: Redesign pricing selection to key on provider_api_model_id or
            -- explicit variant metadata so provider-only SKUs (for example CrofAI
            -- precision tiers) can share a parent internal model without forcing
            -- distinct api_model_id values just to preserve pricing separation.
            where r.model_key =
              pr.provider_id || ':' || resolved_model || ':' || gateway_fetch_request_context_without_workspace_budget.endpoint
              and r.capability_id = gateway_fetch_request_context_without_workspace_budget.endpoint
              and (r.effective_from is null or r.effective_from <= now() at time zone 'utc')
              and (r.effective_to   is null or (now() at time zone 'utc') < r.effective_to)
          ),
          ordered_rules as (
            select
              jsonb_agg(
                jsonb_build_object(
                  'id', r.rule_id,
                  'pricing_plan', r.pricing_plan,
                  'meter', r.meter,
                  'unit', r.unit,
                  'unit_size', r.unit_size,
                  'price_per_unit', r.price_per_unit,
                  'included_quantity', r.included_quantity,
                  'currency', r.currency,
                  'match', r.match,
                  'priority', r.priority,
                  'billing_timestamp_basis', coalesce(r.billing_timestamp_basis, 'request_start'),
                  'time_windows', coalesce(r.time_windows, '[]'::jsonb)
                )
                order by r.priority desc, coalesce(r.effective_from, now() at time zone 'utc') desc
              ) as items,
              max(r.updated_at) as version_ts,
              min(r.effective_from) as effective_from,
              min(r.effective_to) as effective_to
            from rules r
          )
          select jsonb_build_object(
            'provider', pr.provider_id,
            'model', resolved_model,
            'endpoint', gateway_fetch_request_context_without_workspace_budget.endpoint,
            'effective_from', to_jsonb(o.effective_from),
            'effective_to',   to_jsonb(o.effective_to),
            'currency', 'USD',
            'version', to_jsonb(o.version_ts),
            'rules', coalesce(o.items, '[]'::jsonb)
          )
          from ordered_rules o
        )
      ),
      '{}'::jsonb
    ) as pricing_payload
  into providers, pricing
  from provider_rows pr;

  return jsonb_build_object(
    'workspace_id', gateway_fetch_request_context_without_workspace_budget.workspace_id,
    'resolved_model', resolved_model,
    'preset', preset_data,
    'key_ok', key_status,
    'key_limit_ok', key_limit_status,
    'credit_ok', credit_status,
    'providers', providers,
    'pricing', pricing,
    'team_enrichment', team_enrichment,
    'key_enrichment', key_enrichment
  );
end;

$function$;

REVOKE ALL ON FUNCTION "public"."gateway_fetch_request_context_without_workspace_budget"(uuid, text, text, uuid) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_fetch_workspace_runtime (
  p_workspace_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  v_settings jsonb;
  v_byok jsonb;
  v_billing text;
  v_tier text;
  v_owner uuid;
  v_checked bigint := floor(extract(epoch from statement_timestamp()) * 1000);
begin
  if p_workspace_id is null then raise exception 'missing_workspace_id' using errcode='22023'; end if;
  select w.billing_mode,w.tier,w.owner_user_id into v_billing,v_tier,v_owner from public.workspaces w where w.id=p_workspace_id;
  -- Explicit allowlist: a future private settings column cannot leak into KV.
  select jsonb_build_object(
    'routing_mode',s.routing_mode,'byok_fallback_enabled',s.byok_fallback_enabled,
    'beta_channel_enabled',s.beta_channel_enabled,'alpha_channel_enabled',s.alpha_channel_enabled,
    'cache_aware_routing_enabled',s.cache_aware_routing_enabled,
    'privacy_zdr_only',s.privacy_zdr_only,'privacy_enable_paid_may_train',s.privacy_enable_paid_may_train,
    'privacy_enable_free_may_train',s.privacy_enable_free_may_train,
    'privacy_enable_input_output_logging',s.privacy_enable_input_output_logging,
    'privacy_enable_free_may_publish_prompts',s.privacy_enable_free_may_publish_prompts,
    'provider_restriction_mode',s.provider_restriction_mode,'provider_restriction_provider_ids',s.provider_restriction_provider_ids,
    'provider_restriction_enforce_allowed',s.provider_restriction_enforce_allowed,
    'model_restriction_mode',s.model_restriction_mode,'model_restriction_model_ids',s.model_restriction_model_ids,
    'io_logging_enabled',s.io_logging_enabled,'io_logging_retention_days',s.io_logging_retention_days,
    'io_logging_include_provider_payloads',s.io_logging_include_provider_payloads,
    'data_contribution_enabled',s.data_contribution_enabled,'data_contribution_policy_version',s.data_contribution_policy_version,
    'data_contribution_sample_rate_bps',s.data_contribution_sample_rate_bps,
    'data_contribution_classifier_sample_rate_bps',s.data_contribution_classifier_sample_rate_bps,
    'data_contribution_discount_bps',s.data_contribution_discount_bps,
    'response_healing_enabled',s.response_healing_enabled,'response_healing_locked',s.response_healing_locked,
    'response_healing_mode',s.response_healing_mode,
    'auto_routing_allowed_patterns',s.auto_routing_allowed_patterns,'auto_routing_spend_profile',s.auto_routing_spend_profile,
    'auto_routing_max_input_price_per_million',s.auto_routing_max_input_price_per_million,
    'auto_routing_max_output_price_per_million',s.auto_routing_max_output_price_per_million,
    'auto_routing_objective',s.auto_routing_objective,'auto_routing_fallbacks_enabled',s.auto_routing_fallbacks_enabled,
    'auto_routing_revision',s.auto_routing_revision
  ) into v_settings from public.workspace_settings s where s.workspace_id=p_workspace_id;
  if v_settings is null or v_billing is null or v_billing not in ('wallet','invoice') then
    raise exception 'workspace_context_enrichment_missing';
  end if;
  select coalesce(jsonb_object_agg(provider_id,items),'{}'::jsonb) into v_byok from (
    select bk.provider_id,jsonb_agg(jsonb_build_object(
      'provider_id',bk.provider_id,'id',bk.id,'fingerprint_sha256',bk.fingerprint_sha256,
      'key_version',bk.key_version,'always_use',bk.always_use) order by bk.id) as items
    from public.byok_keys bk where bk.workspace_id=p_workspace_id and bk.enabled group by bk.provider_id
  ) refs;
  return jsonb_build_object('version',1,'workspaceId',p_workspace_id,'checkedAtMs',v_checked,
    'ownerUserId',v_owner,'expiresAtMs',v_checked+60000,'configuredTier',v_tier,'billingMode',v_billing,'settings',v_settings,'byok',v_byok);
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_fetch_workspace_runtime"(uuid) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_finish_batch_file_upload (
  p_workspace_id     uuid,
  p_upload_id        text,
  p_status           text,
  p_provider_file_id text DEFAULT NULL::text
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if p_status is null or p_status not in ('completed', 'failed') then
    raise exception 'invalid_batch_file_upload_status';
  end if;
  update public.gateway_batch_file_uploads
  set status = p_status,
      provider_file_id = nullif(trim(coalesce(p_provider_file_id, '')), ''),
      updated_at = now()
  where workspace_id = p_workspace_id and upload_id = p_upload_id;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_finish_batch_file_upload"(uuid, text, text, text) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_finish_workspace_publication (
  p_workspace_id uuid,
  p_revision     uuid,
  p_lease_id     uuid,
  p_success      boolean
)
  RETURNS text
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare pending public.gateway_workspace_publications%rowtype;
begin
  if p_success is null then raise exception 'invalid_publication_result' using errcode='22023'; end if;
  select * into pending from public.gateway_workspace_publications p
    where p.workspace_id = p_workspace_id and p.lease_id = p_lease_id for update;
  if not found then return 'lost'; end if;
  if pending.revision = p_revision and p_success then
    delete from public.gateway_workspace_publications where workspace_id = p_workspace_id;
    return 'completed';
  end if;
  update public.gateway_workspace_publications set lease_id = null, lease_until = null,
    available_at = case when pending.revision <> p_revision then clock_timestamp()
      else clock_timestamp() + make_interval(secs => least(3600, 30 * (2 ^ least(pending.attempts, 7)))::integer) end
    where workspace_id = p_workspace_id;
  if pending.revision <> p_revision then return 'superseded'; end if;
  return case when pending.attempts >= 10 then 'exhausted' else 'retry' end;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_finish_workspace_publication"(uuid, uuid, uuid, boolean) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_marketing_uptime_tokens (
  hours_window integer DEFAULT 24
)
  RETURNS TABLE (
    window_start    timestamp with time zone,
    window_end      timestamp with time zone,
    timeframe_hours integer,
    total_requests  bigint,
    uptime_pct      double precision,
    uptime_events   bigint,
    total_tokens    double precision
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public'
  AS $function$
	with params as (
		select greatest(1, hours_window) as hours_window
	),
	bounds as (
		select
			now() at time zone 'utc' as window_end,
			(now() at time zone 'utc') - (p.hours_window || ' hours')::interval as window_start,
			p.hours_window
		from params p
	),
	scoped_requests as (
		select
			gr.success,
			gr.error_code,
			gr.usage,
			gr.created_at
		from gateway_requests gr
		cross join bounds b
		where gr.created_at >= b.window_start
			and gr.created_at < b.window_end
	)
	select
		b.window_start,
		b.window_end,
		b.hours_window as timeframe_hours,
		count(sr.*) as total_requests,
		case
			when count(sr.*) = 0 then null
			else round(
				(
					100.0 * count(*) filter (
						where coalesce(sr.success, false) or (sr.error_code ilike 'user:%')
					)::double precision
					/ greatest(count(sr.*), 1)::double precision
				)::numeric,
				4
			)::double precision
		end as uptime_pct,
		count(*) filter (
			where coalesce(sr.success, false) or (sr.error_code ilike 'user:%')
		) as uptime_events,
		coalesce(
			sum(
				case
					when jsonb_typeof(sr.usage -> 'total_tokens') = 'number' then
						(sr.usage ->> 'total_tokens')::double precision
					else 0::double precision
				end
			),
			0::double precision
		) as total_tokens
	from bounds b
	left join scoped_requests sr on true
	group by b.window_start, b.window_end, b.hours_window;
$function$;

CREATE OR REPLACE FUNCTION public.gateway_realtime_claim_connection (
  p_session_id         text,
  p_client_secret_hash text
)
  RETURNS SETOF public.gateway_realtime_sessions
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  v_session public.gateway_realtime_sessions%rowtype;
begin
  select * into v_session
  from public.gateway_realtime_sessions
  where session_id = p_session_id
  for update;

  if not found then raise exception 'realtime_session_not_found'; end if;
  if coalesce(v_session.provider_client_secret_hash, '') <> coalesce(p_client_secret_hash, '') then
    raise exception 'realtime_relay_forbidden';
  end if;
  if v_session.status <> 'created' then
    raise exception 'realtime_relay_already_connected';
  end if;
  if v_session.expires_at is not null and v_session.expires_at <= now() then
    raise exception 'realtime_session_expired';
  end if;

  update public.gateway_realtime_sessions
  set status = 'connecting', last_event_at = now(), updated_at = now()
  where id = v_session.id and status = 'created'
  returning * into v_session;

  if not found then raise exception 'realtime_relay_already_connected'; end if;
  return next v_session;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_realtime_claim_connection"(text, text) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_realtime_create_with_hold (
  p_workspace_id             uuid,
  p_session_id               text,
  p_key_id                   uuid,
  p_user_id                  text,
  p_source                   text,
  p_provider                 text,
  p_model_id                 text,
  p_provider_model_id        text,
  p_voice                    text,
  p_expires_at               timestamp with time zone,
  p_reservation_prefix       text,
  p_reservation_id           text,
  p_hold_nanos               bigint,
  p_client_secret_hash       text,
  p_metadata                 jsonb                    DEFAULT '{}'::jsonb,
  p_max_workspace_sessions   integer                  DEFAULT 8,
  p_max_key_sessions         integer                  DEFAULT 4,
  p_max_user_sessions        integer                  DEFAULT 1,
  p_max_creations_per_minute integer                  DEFAULT 8
)
  RETURNS SETOF public.gateway_realtime_sessions
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_budget_status jsonb;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text, 0));
  v_budget_status := public.gateway_workspace_budget_status(p_workspace_id, p_hold_nanos);
  if not coalesce((v_budget_status->>'ok')::boolean, true) then
    raise exception '%', v_budget_status->>'reason';
  end if;

  return query select * from public.gateway_realtime_create_with_hold_without_workspace_budget(
    p_workspace_id, p_session_id, p_key_id, p_user_id, p_source, p_provider,
    p_model_id, p_provider_model_id, p_voice, p_expires_at, p_reservation_prefix,
    p_reservation_id, p_hold_nanos, p_client_secret_hash, p_metadata,
    p_max_workspace_sessions, p_max_key_sessions, p_max_user_sessions,
    p_max_creations_per_minute
  );
end;
$function$;

REVOKE ALL
  ON FUNCTION "public"."gateway_realtime_create_with_hold"(uuid, text, uuid, text, text, text, text, text, text, timestamp
    WITH time zone, text, text, bigint, text, jsonb, integer, integer, integer, integer)
  FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_realtime_create_with_hold_without_workspace_budget (
  p_workspace_id             uuid,
  p_session_id               text,
  p_key_id                   uuid,
  p_user_id                  text,
  p_source                   text,
  p_provider                 text,
  p_model_id                 text,
  p_provider_model_id        text,
  p_voice                    text,
  p_expires_at               timestamp with time zone,
  p_reservation_prefix       text,
  p_reservation_id           text,
  p_hold_nanos               bigint,
  p_client_secret_hash       text,
  p_metadata                 jsonb                    DEFAULT '{}'::jsonb,
  p_max_workspace_sessions   integer                  DEFAULT 8,
  p_max_key_sessions         integer                  DEFAULT 4,
  p_max_user_sessions        integer                  DEFAULT 1,
  p_max_creations_per_minute integer                  DEFAULT 8
)
  RETURNS SETOF public.gateway_realtime_sessions
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  v_wallet public.wallets%rowtype;
  v_session public.gateway_realtime_sessions%rowtype;
  v_count integer;
begin
  if p_workspace_id is null or coalesce(trim(p_session_id), '') = '' then
    raise exception 'invalid_realtime_session_identity';
  end if;
  if p_key_id is null then
    raise exception 'invalid_realtime_key';
  end if;
  if p_hold_nanos is null or p_hold_nanos <= 0 then
    raise exception 'invalid_realtime_hold';
  end if;
  if p_source not in ('api', 'chat') then
    raise exception 'invalid_realtime_source';
  end if;
  if p_expires_at is null or p_expires_at <= now() then
    raise exception 'invalid_realtime_expiry';
  end if;

  -- The wallet row serializes create/limit checks for the workspace.
  select * into v_wallet
  from public.wallets
  where workspace_id = p_workspace_id
  for update;

  if not found then
    raise exception 'wallet_not_found';
  end if;

  select count(*)::integer into v_count
  from public.gateway_realtime_sessions
  where workspace_id = p_workspace_id
    and status in ('created', 'connecting', 'connected', 'ending', 'billing_unresolved');
  if v_count >= greatest(1, p_max_workspace_sessions) then
    raise exception 'realtime_workspace_concurrency_limit';
  end if;

  select count(*)::integer into v_count
  from public.gateway_realtime_sessions
  where workspace_id = p_workspace_id
    and key_id = p_key_id
    and status in ('created', 'connecting', 'connected', 'ending', 'billing_unresolved');
  if v_count >= greatest(1, p_max_key_sessions) then
    raise exception 'realtime_key_concurrency_limit';
  end if;

  if nullif(trim(coalesce(p_user_id, '')), '') is not null then
    select count(*)::integer into v_count
    from public.gateway_realtime_sessions
    where workspace_id = p_workspace_id
      and user_id = p_user_id
      and status in ('created', 'connecting', 'connected', 'ending', 'billing_unresolved');
    if v_count >= greatest(1, p_max_user_sessions) then
      raise exception 'realtime_user_concurrency_limit';
    end if;
  end if;

  select count(*)::integer into v_count
  from public.gateway_realtime_sessions
  where workspace_id = p_workspace_id
    and created_at >= now() - interval '1 minute';
  if v_count >= greatest(1, p_max_creations_per_minute) then
    raise exception 'realtime_creation_rate_limit';
  end if;

  if coalesce(v_wallet.balance_nanos, 0) - coalesce(v_wallet.reserved_nanos, 0) < p_hold_nanos then
    raise exception 'insufficient_funds';
  end if;

  insert into public.gateway_realtime_sessions (
    session_id, workspace_id, key_id, user_id, source, provider, model_id,
    provider_model_id, voice, status, expires_at, reservation_prefix,
    reservation_count, reserved_nanos, provider_client_secret_hash, metadata
  ) values (
    p_session_id, p_workspace_id, p_key_id, nullif(trim(coalesce(p_user_id, '')), ''),
    p_source, p_provider, p_model_id, p_provider_model_id, p_voice, 'created',
    p_expires_at, p_reservation_prefix, 1, p_hold_nanos,
    p_client_secret_hash, coalesce(p_metadata, '{}'::jsonb)
  ) returning * into v_session;

  insert into public.gateway_wallet_reservations (
    reservation_id, workspace_id, amount_nanos, status, hold_ref_id,
    captured_nanos, released_nanos, created_at, updated_at
  ) values (
    p_reservation_id, p_workspace_id, p_hold_nanos, 'reserved', p_session_id,
    0, 0, now(), now()
  );

  insert into public.gateway_requests (
    workspace_id, request_id, realtime_session_id, endpoint, model_id, provider,
    stream, byok, status_code, success, usage, cost_nanos, currency,
    pricing_lines, key_id, created_at
  ) values (
    p_workspace_id, 'realtime:' || p_session_id, p_session_id, 'audio.realtime',
    p_model_id, p_provider, true, false, 102, false, '{}'::jsonb, 0, 'USD',
    '[]'::jsonb, p_key_id, v_session.started_at
  );

  update public.wallets
  set reserved_nanos = coalesce(reserved_nanos, 0) + p_hold_nanos,
      updated_at = now()
  where workspace_id = p_workspace_id;

  return next v_session;
end;
$function$;

REVOKE ALL
  ON FUNCTION "public"."gateway_realtime_create_with_hold_without_workspace_budget"(uuid, text, uuid, text, text, text, text, text, text, timestamp
    WITH time zone, text, text, bigint, text, jsonb, integer, integer, integer, integer)
  FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_realtime_enforce_provider_concurrency()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO 'public'
  AS $function$
declare
  v_provider text := lower(trim(coalesce(new.provider, '')));
  v_active_count integer;
begin
  if v_provider = '' then
    raise exception 'realtime_provider_required';
  end if;

  -- Serialize creates for one shared provider account across all workspaces.
  perform pg_advisory_xact_lock(
    hashtextextended('gateway_realtime_provider:' || v_provider, 0)
  );

  select count(*)::integer into v_active_count
  from public.gateway_realtime_sessions
  where lower(provider) = v_provider
    and status in ('created', 'connecting', 'connected', 'ending');

  if v_active_count >= 20 then
    raise exception 'realtime_provider_concurrency_limit';
  end if;

  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_realtime_enforce_provider_concurrency"() FROM PUBLIC, "anon", "authenticated", "service_role";

CREATE OR REPLACE FUNCTION public.gateway_realtime_extend_hold_once (
  p_workspace_id          uuid,
  p_session_id            text,
  p_reservation_id        text,
  p_target_reserved_nanos bigint,
  p_estimated_cost_nanos  bigint DEFAULT 0
)
  RETURNS SETOF public.gateway_realtime_sessions
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_current_reserved_nanos bigint;
  v_additional_nanos bigint;
  v_budget_status jsonb;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text, 0));
  select reserved_nanos into v_current_reserved_nanos
  from public.gateway_realtime_sessions
  where workspace_id = p_workspace_id and session_id = p_session_id;
  if not found then raise exception 'realtime_session_not_found'; end if;

  v_additional_nanos := greatest(0, coalesce(p_target_reserved_nanos, 0) - coalesce(v_current_reserved_nanos, 0));
  if v_additional_nanos > 0 then
    v_budget_status := public.gateway_workspace_budget_status(p_workspace_id, v_additional_nanos);
    if not coalesce((v_budget_status->>'ok')::boolean, true) then
      raise exception '%', v_budget_status->>'reason';
    end if;
  end if;

  return query select * from public.gateway_realtime_extend_hold_once_without_workspace_budget(
    p_workspace_id, p_session_id, p_reservation_id, p_target_reserved_nanos,
    p_estimated_cost_nanos
  );
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_realtime_extend_hold_once"(uuid, text, text, bigint, bigint) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_realtime_extend_hold_once_without_workspace_budget (
  p_workspace_id          uuid,
  p_session_id            text,
  p_reservation_id        text,
  p_target_reserved_nanos bigint,
  p_estimated_cost_nanos  bigint DEFAULT 0
)
  RETURNS SETOF public.gateway_realtime_sessions
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  v_wallet public.wallets%rowtype;
  v_session public.gateway_realtime_sessions%rowtype;
  v_additional bigint;
begin
  select * into v_wallet
  from public.wallets
  where workspace_id = p_workspace_id
  for update;
  if not found then raise exception 'wallet_not_found'; end if;

  select * into v_session
  from public.gateway_realtime_sessions
  where workspace_id = p_workspace_id and session_id = p_session_id
  for update;
  if not found then raise exception 'realtime_session_not_found'; end if;
  if v_session.status not in ('created', 'connected', 'ending') then
    raise exception 'realtime_session_terminal';
  end if;

  v_additional := greatest(0, coalesce(p_target_reserved_nanos, 0) - coalesce(v_session.reserved_nanos, 0));
  if v_additional > 0 then
    if coalesce(v_wallet.balance_nanos, 0) - coalesce(v_wallet.reserved_nanos, 0) < v_additional then
      update public.gateway_realtime_sessions
      set status = 'ending', disconnect_reason = 'credit_hold_extension_failed',
          error_code = 'insufficient_funds', updated_at = now()
      where id = v_session.id;
      raise exception 'insufficient_funds';
    end if;

    insert into public.gateway_wallet_reservations (
      reservation_id, workspace_id, amount_nanos, status, hold_ref_id,
      captured_nanos, released_nanos, created_at, updated_at
    ) values (
      p_reservation_id, p_workspace_id, v_additional, 'reserved', p_session_id,
      0, 0, now(), now()
    );
    update public.wallets
    set reserved_nanos = coalesce(reserved_nanos, 0) + v_additional,
        updated_at = now()
    where workspace_id = p_workspace_id;
  end if;

  update public.gateway_realtime_sessions
  set reservation_count = reservation_count + case when v_additional > 0 then 1 else 0 end,
      reserved_nanos = reserved_nanos + v_additional,
      estimated_cost_nanos = greatest(estimated_cost_nanos, coalesce(p_estimated_cost_nanos, 0)),
      last_event_at = now(), updated_at = now()
  where id = v_session.id
  returning * into v_session;

  return next v_session;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_realtime_extend_hold_once_without_workspace_budget"(uuid, text, text, bigint, bigint) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_realtime_mark_billing_unresolved (
  p_workspace_id uuid,
  p_session_id   text,
  p_usage        jsonb,
  p_reason       text
)
  RETURNS SETOF public.gateway_realtime_sessions
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_session public.gateway_realtime_sessions%rowtype;
begin
  update public.gateway_realtime_sessions
  set status = 'billing_unresolved',
      usage = coalesce(p_usage, '{}'::jsonb),
      disconnect_reason = left(coalesce(nullif(trim(p_reason), ''), 'authoritative_usage_missing'), 240),
      error_code = 'realtime_authoritative_usage_missing',
      last_event_at = now(),
      updated_at = now()
  where workspace_id = p_workspace_id
    and session_id = p_session_id
    and status in ('created', 'connecting', 'connected', 'ending', 'billing_unresolved')
  returning * into v_session;

  if not found then
    select * into v_session
    from public.gateway_realtime_sessions
    where workspace_id = p_workspace_id and session_id = p_session_id;
  end if;
  if not found then raise exception 'realtime_session_not_found'; end if;
  if v_session.status in ('completed', 'failed', 'cancelled', 'expired') then
    return next v_session;
    return;
  end if;

  update public.gateway_requests
  set status_code = 202,
      success = false,
      error_code = 'realtime_authoritative_usage_missing',
      error_message = 'Realtime billing requires reconciliation.',
      usage = coalesce(p_usage, '{}'::jsonb)
  where realtime_session_id = p_session_id
    and created_at = v_session.started_at;

  return next v_session;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_realtime_mark_billing_unresolved"(uuid, text, jsonb, text) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_realtime_review_admission()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  perform 1 from public.wallets where workspace_id = new.workspace_id for update;
  if exists (select 1 from public.gateway_realtime_billing_reviews
    where workspace_id = new.workspace_id and access_blocked) then
    raise exception 'realtime_billing_review_required';
  end if;
  return new;
end $function$;

REVOKE ALL ON FUNCTION "public"."gateway_realtime_review_admission"() FROM PUBLIC, "anon", "authenticated", "service_role";

CREATE OR REPLACE FUNCTION public.gateway_realtime_review_decide (
  p_session_id       text,
  p_actor_user_id    text,
  p_operation_id     uuid,
  p_expected_version bigint,
  p_action           text,
  p_reason           text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_session public.gateway_realtime_sessions%rowtype;
  v_review public.gateway_realtime_billing_reviews%rowtype;
  v_previous public.gateway_realtime_billing_decisions%rowtype;
  v_settlement record;
  v_held bigint;
  v_cost bigint;
begin
  if not exists (select 1 from public.users where user_id::text = p_actor_user_id and lower(role::text) = 'admin') then
    raise exception 'realtime_review_forbidden';
  end if;
  if p_action is null or p_action not in ('retry', 'retain', 'capture_confirmed', 'write_off', 'restore_access')
    or p_operation_id is null or p_expected_version is null
    or p_reason is null or length(trim(p_reason)) < 10 or length(p_reason) > 1000 then
    raise exception 'realtime_review_invalid_decision';
  end if;
  select * into v_session from public.gateway_realtime_sessions where session_id = p_session_id;
  if not found then raise exception 'realtime_review_not_found'; end if;
  -- Match the existing settlement lock order: reservations, wallet, session, review.
  perform 1 from public.gateway_wallet_reservations r where r.workspace_id = v_session.workspace_id
    and r.status in ('held', 'reserved') and (r.hold_ref_id = p_session_id or r.reservation_id like v_session.reservation_prefix || '%')
    order by r.created_at, r.reservation_id for update;
  perform 1 from public.wallets where workspace_id = v_session.workspace_id for update;
  select * into v_session from public.gateway_realtime_sessions where session_id = p_session_id for update;
  select * into v_review from public.gateway_realtime_billing_reviews where session_id = p_session_id for update;
  if not found then raise exception 'realtime_review_not_found'; end if;
  select * into v_previous from public.gateway_realtime_billing_decisions where operation_id = p_operation_id;
  if found then
    if v_previous.session_id <> p_session_id or v_previous.actor_user_id is distinct from p_actor_user_id
      or v_previous.action <> p_action or v_previous.reason <> trim(p_reason) then
      raise exception 'realtime_review_idempotency_conflict';
    end if;
    return jsonb_build_object('applied', false, 'already_applied', true);
  end if;
  if v_review.version <> p_expected_version then raise exception 'realtime_review_stale'; end if;
  if p_action = 'restore_access' then
    if v_review.status <> 'resolved' then raise exception 'realtime_review_still_open'; end if;
    update public.gateway_realtime_billing_reviews set access_blocked = false, version = version + 1 where session_id = p_session_id;
  else
    if v_review.status <> 'open' or v_session.status <> 'billing_unresolved' then raise exception 'realtime_review_closed'; end if;
    if p_action in ('retry', 'retain') then
      if p_action = 'retain' and now() >= v_review.opened_at + interval '7 days' then
        raise exception 'realtime_review_retention_limit';
      end if;
      update public.gateway_realtime_billing_reviews set
        retry_after = case when p_action = 'retry' then now() else retry_after end,
        review_due_at = case when p_action = 'retain' then least(now() + interval '1 day', opened_at + interval '7 days') else review_due_at end,
        version = version + 1 where session_id = p_session_id;
    else
      v_cost := 0;
      if p_action = 'capture_confirmed' then
        if v_review.confirmed_cost_nanos is null or v_review.billable_usage is null
          or v_review.evidence_usage is distinct from v_session.usage
          or v_review.evidence_metadata is distinct from v_session.metadata then raise exception 'realtime_review_evidence_missing'; end if;
        v_cost := v_review.confirmed_cost_nanos;
      end if;
      select coalesce(sum(amount_nanos), 0) into v_held from public.gateway_wallet_reservations r
      where r.workspace_id = v_session.workspace_id and r.status in ('held', 'reserved')
        and (r.hold_ref_id = p_session_id or r.reservation_id like v_session.reservation_prefix || '%');
      if v_cost > v_held then raise exception 'realtime_review_cost_exceeds_hold'; end if;
      if p_action = 'write_off' then
        update public.gateway_realtime_billing_reviews set evidence_usage = v_session.usage, evidence_metadata = v_session.metadata
        where session_id = p_session_id;
      end if;
      select * into v_settlement from public.gateway_realtime_settle_once(v_session.workspace_id, p_session_id,
        v_cost, case when p_action = 'capture_confirmed' then v_review.billable_usage else '{}'::jsonb end,
        case when p_action = 'capture_confirmed' then v_review.pricing_lines else '[]'::jsonb end,
        'failed', 'billing_review_' || p_action, 'billing_review_resolved', null);
      if not coalesce(v_settlement.applied, false) then raise exception 'realtime_review_settlement_failed'; end if;
    end if;
  end if;
  insert into public.gateway_realtime_billing_decisions
    (operation_id, session_id, workspace_id, actor_user_id, action, reason, review_version, cost_nanos)
  values (p_operation_id, p_session_id, v_session.workspace_id, p_actor_user_id, p_action, trim(p_reason), v_review.version, v_cost);
  return jsonb_build_object('applied', true, 'already_applied', false);
end $function$;

REVOKE ALL ON FUNCTION "public"."gateway_realtime_review_decide"(text, text, uuid, bigint, text, text) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_realtime_review_evidence (
  p_session_id        text,
  p_expected_usage    jsonb,
  p_expected_metadata jsonb,
  p_cost_nanos        bigint,
  p_pricing_lines     jsonb,
  p_complete          boolean,
  p_error             text,
  p_billable_usage    jsonb
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare v_session public.gateway_realtime_sessions%rowtype;
begin
  select * into v_session from public.gateway_realtime_sessions where session_id = p_session_id for update;
  if not found or v_session.status <> 'billing_unresolved'
    or v_session.usage is distinct from p_expected_usage
    or v_session.metadata is distinct from p_expected_metadata then return false; end if;
  update public.gateway_realtime_billing_reviews set evidence_usage = p_expected_usage,
    evidence_metadata = p_expected_metadata, confirmed_cost_nanos = p_cost_nanos,
    billable_usage = p_billable_usage,
    pricing_lines = coalesce(p_pricing_lines, '[]'), evidence_complete = coalesce(p_complete, false),
    recovery_error = left(p_error, 200), attempts = attempts + 1, last_attempt_at = now(),
    retry_after = now() + interval '1 day', version = version + 1
  where session_id = p_session_id and status = 'open';
  return found;
end $function$;

REVOKE ALL ON FUNCTION "public"."gateway_realtime_review_evidence"(text, jsonb, jsonb, bigint, jsonb, boolean, text, jsonb) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_realtime_review_lifecycle()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if new.status = 'billing_unresolved' then
    insert into public.gateway_realtime_billing_reviews (session_id, workspace_id, evidence_usage, evidence_metadata)
    values (new.session_id, new.workspace_id, new.usage, new.metadata) on conflict do nothing;
    if old.usage is distinct from new.usage or old.metadata is distinct from new.metadata then
      update public.gateway_realtime_billing_reviews set confirmed_cost_nanos = null,
        evidence_complete = false, version = version + 1, retry_after = now()
      where session_id = new.session_id and status = 'open';
    end if;
  elsif new.status in ('completed', 'failed', 'cancelled', 'expired') then
    insert into public.gateway_realtime_billing_decisions
      (session_id, workspace_id, action, reason, review_version, cost_nanos)
    select session_id, workspace_id, 'settled', coalesce(new.disconnect_reason, 'server_settlement'),
      version, new.final_cost_nanos
    from public.gateway_realtime_billing_reviews where session_id = new.session_id and status = 'open';
    update public.gateway_realtime_billing_reviews set status = 'resolved', resolved_at = now(), version = version + 1
    where session_id = new.session_id and status = 'open';
  end if;
  return new;
end $function$;

REVOKE ALL ON FUNCTION "public"."gateway_realtime_review_lifecycle"() FROM PUBLIC, "anon", "authenticated", "service_role";

CREATE OR REPLACE FUNCTION public.gateway_realtime_review_summary_synced (
  p_session_id text
)
  RETURNS void
  LANGUAGE sql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  update public.gateway_realtime_billing_reviews set summary_synced_at = now()
  where session_id = p_session_id and status = 'resolved';
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_realtime_review_summary_synced"(text) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_realtime_settle_once (
  p_workspace_id      uuid,
  p_session_id        text,
  p_final_cost_nanos  bigint,
  p_usage             jsonb  DEFAULT '{}'::jsonb,
  p_pricing_lines     jsonb  DEFAULT '[]'::jsonb,
  p_status            text   DEFAULT 'completed'::text,
  p_disconnect_reason text   DEFAULT NULL::text,
  p_error_code        text   DEFAULT NULL::text,
  p_error_message     text   DEFAULT NULL::text
)
  RETURNS TABLE (
    applied               boolean,
    already_applied       boolean,
    status                text,
    final_cost_nanos      bigint,
    reserved_nanos        bigint,
    captured_nanos        bigint,
    released_nanos        bigint,
    before_balance_nanos  bigint,
    after_balance_nanos   bigint,
    before_reserved_nanos bigint,
    after_reserved_nanos  bigint
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  v_session public.gateway_realtime_sessions%rowtype;
  v_wallet public.wallets%rowtype;
  v_reservation public.gateway_wallet_reservations%rowtype;
  v_cost bigint := greatest(0, coalesce(p_final_cost_nanos, 0));
  v_held bigint := 0;
  v_capture_remaining bigint;
  v_row_capture bigint;
  v_before_balance bigint;
  v_before_reserved bigint;
  v_request_count integer;
  v_next_status text := lower(coalesce(nullif(trim(p_status), ''), 'completed'));
begin
  if v_next_status not in ('completed', 'failed', 'cancelled', 'expired') then
    raise exception 'invalid_realtime_terminal_status';
  end if;

  select * into v_session from public.gateway_realtime_sessions
  where workspace_id = p_workspace_id and session_id = p_session_id;
  if not found then
    return query select false, false, 'not_found'::text, 0::bigint, 0::bigint,
      0::bigint, 0::bigint, null::bigint, null::bigint, null::bigint, null::bigint;
    return;
  end if;
  if v_session.status in ('completed', 'failed', 'cancelled', 'expired') then
    return query select false, true, v_session.status, coalesce(v_session.final_cost_nanos, 0),
      v_session.reserved_nanos, v_session.captured_nanos, v_session.released_nanos,
      null::bigint, null::bigint, null::bigint, null::bigint;
    return;
  end if;

  perform 1 from public.gateway_wallet_reservations gwr
  where gwr.workspace_id = p_workspace_id and gwr.status in ('held', 'reserved')
    and (gwr.hold_ref_id = p_session_id or gwr.reservation_id like v_session.reservation_prefix || '%')
  order by gwr.created_at, gwr.reservation_id
  for update;

  select * into v_wallet from public.wallets
  where workspace_id = p_workspace_id for update;
  if not found then raise exception 'wallet_not_found'; end if;

  select * into v_session from public.gateway_realtime_sessions
  where workspace_id = p_workspace_id and session_id = p_session_id for update;
  if v_session.status in ('completed', 'failed', 'cancelled', 'expired') then
    return query select false, true, v_session.status, coalesce(v_session.final_cost_nanos, 0),
      v_session.reserved_nanos, v_session.captured_nanos, v_session.released_nanos,
      null::bigint, null::bigint, null::bigint, null::bigint;
    return;
  end if;

  select coalesce(sum(gwr.amount_nanos), 0)::bigint into v_held
  from public.gateway_wallet_reservations gwr
  where gwr.workspace_id = p_workspace_id and gwr.status in ('held', 'reserved')
    and (gwr.hold_ref_id = p_session_id or gwr.reservation_id like v_session.reservation_prefix || '%');

  v_before_balance := coalesce(v_wallet.balance_nanos, 0);
  v_before_reserved := coalesce(v_wallet.reserved_nanos, 0);
  if v_before_reserved < v_held then
    return query select false, false, 'reserved_balance_mismatch'::text, v_cost, v_held,
      0::bigint, v_held, v_before_balance, v_before_balance, v_before_reserved, v_before_reserved;
    return;
  end if;
  if v_cost > v_held + greatest(0, v_before_balance - v_before_reserved) then
    return query select false, false, 'insufficient_unreserved_balance'::text, v_cost, v_held,
      0::bigint, v_held, v_before_balance, v_before_balance, v_before_reserved, v_before_reserved;
    return;
  end if;

  update public.wallets w
  set balance_nanos = w.balance_nanos - v_cost,
      reserved_nanos = w.reserved_nanos - v_held,
      updated_at = now()
  where workspace_id = p_workspace_id;

  v_capture_remaining := least(v_cost, v_held);
  for v_reservation in
    select gwr.* from public.gateway_wallet_reservations gwr
    where gwr.workspace_id = p_workspace_id and gwr.status in ('held', 'reserved')
      and (gwr.hold_ref_id = p_session_id or gwr.reservation_id like v_session.reservation_prefix || '%')
    order by gwr.created_at, gwr.reservation_id
    for update
  loop
    v_row_capture := least(v_reservation.amount_nanos, v_capture_remaining);
    update public.gateway_wallet_reservations
    set status = case when v_row_capture > 0 then 'captured' else 'released' end,
        captured_nanos = v_row_capture,
        released_nanos = v_reservation.amount_nanos - v_row_capture,
        capture_ref_id = case when v_row_capture > 0 then p_session_id else null end,
        release_ref_id = case when v_row_capture < v_reservation.amount_nanos then p_session_id else null end,
        captured_at = case when v_row_capture > 0 then now() else null end,
        released_at = case when v_row_capture < v_reservation.amount_nanos then now() else null end,
        updated_at = now()
    where workspace_id = p_workspace_id and reservation_id = v_reservation.reservation_id;
    v_capture_remaining := greatest(0, v_capture_remaining - v_row_capture);
  end loop;

  if v_cost > 0 then
    insert into public.credit_ledger (
      workspace_id, event_time, kind, amount_nanos, before_balance_nanos,
      after_balance_nanos, before_reserved_nanos, after_reserved_nanos,
      ref_type, ref_id, created_at, status
    ) values (
      p_workspace_id, now(), 'charge', -v_cost, v_before_balance,
      v_before_balance - v_cost, v_before_reserved, v_before_reserved - v_held,
      'realtime_session', p_session_id, now(), 'captured'
    ) on conflict (ref_type, ref_id) do nothing;
  end if;

  update public.gateway_realtime_sessions
  set status = v_next_status,
      ended_at = coalesce(ended_at, now()),
      final_cost_nanos = v_cost,
      captured_nanos = v_cost,
      released_nanos = greatest(0, v_held - least(v_cost, v_held)),
      reserved_nanos = v_held,
      usage = coalesce(p_usage, '{}'::jsonb),
      pricing_lines = case when jsonb_typeof(coalesce(p_pricing_lines, '[]'::jsonb)) = 'array'
        then p_pricing_lines else '[]'::jsonb end,
      disconnect_reason = nullif(trim(coalesce(p_disconnect_reason, '')), ''),
      error_code = nullif(trim(coalesce(p_error_code, '')), ''),
      error_message = nullif(trim(coalesce(p_error_message, '')), ''),
      updated_at = now()
  where id = v_session.id
  returning * into v_session;

  update public.gateway_requests
  set native_response_id = coalesce(v_session.provider_session_id, v_session.provider_native_id),
      status_code = case when v_next_status = 'completed' then 200 else 499 end,
      success = v_next_status = 'completed',
      error_code = nullif(trim(coalesce(p_error_code, '')), ''),
      error_message = nullif(trim(coalesce(p_error_message, '')), ''),
      generation_ms = greatest(0, floor(extract(epoch from (v_session.ended_at - v_session.started_at)) * 1000))::integer,
      usage = coalesce(p_usage, '{}'::jsonb),
      cost_nanos = v_cost,
      currency = 'USD',
      pricing_lines = case when jsonb_typeof(coalesce(p_pricing_lines, '[]'::jsonb)) = 'array'
        then p_pricing_lines else '[]'::jsonb end
  where realtime_session_id = p_session_id
    and created_at = v_session.started_at;
  get diagnostics v_request_count = row_count;
  if v_request_count <> 1 then
    raise exception 'realtime_request_summary_missing';
  end if;

  return query select true, false, v_session.status, v_cost, v_held, v_cost,
    greatest(0, v_held - least(v_cost, v_held)), v_before_balance,
    v_before_balance - v_cost, v_before_reserved, v_before_reserved - v_held;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_realtime_settle_once"(uuid, text, bigint, jsonb, jsonb, text, text, text, text) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_record_batch_key_usage (
  p_workspace_id uuid,
  p_key_id       uuid,
  p_batch_id     text,
  p_provider     text,
  p_rows         jsonb
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_inserted integer := 0;
begin
  if p_workspace_id is null or p_key_id is null or coalesce(trim(p_batch_id), '') = '' then
    raise exception 'invalid_batch_key_usage_identity';
  end if;
  if not exists (
    select 1 from public.keys
    where id = p_key_id and workspace_id = p_workspace_id
  ) then
    raise exception 'batch_key_not_owned_by_workspace';
  end if;
  if jsonb_typeof(p_rows) <> 'array' then
    raise exception 'invalid_batch_key_usage_rows';
  end if;

  delete from public.gateway_requests gr
  where gr.workspace_id = p_workspace_id
    and gr.key_id = p_key_id
    and gr.request_id like 'batch_hold_usage:%'
    and exists (
      select 1
      from public.gateway_wallet_reservations reservation
      where reservation.workspace_id = p_workspace_id
        and reservation.key_id = p_key_id
        and reservation.capture_ref_id = p_batch_id
        and reservation.status = 'captured'
        and gr.request_id like 'batch_hold_usage:' || reservation.reservation_id || ':%'
    );

  with source_rows as (
    select
      coalesce(nullif(trim(row ->> 'custom_id'), ''), ordinality::text) as custom_id,
      coalesce(nullif(trim(row ->> 'endpoint'), ''), 'batch') as endpoint,
      coalesce(nullif(trim(row ->> 'model'), ''), 'batch/unknown') as model,
      greatest(0, coalesce((row ->> 'cost_nanos')::bigint, 0)) as cost_nanos,
      case when jsonb_typeof(row -> 'usage') = 'object' then row -> 'usage' else '{}'::jsonb end as usage
    from jsonb_array_elements(p_rows) with ordinality as entries(row, ordinality)
  ), claimed_rows as (
    insert into public.gateway_batch_key_usage_records (
      workspace_id, batch_id, custom_id, key_id, provider, endpoint, model, cost_nanos, usage
    )
    select
      p_workspace_id, p_batch_id, source.custom_id, p_key_id,
      nullif(trim(coalesce(p_provider, '')), ''), source.endpoint,
      source.model, source.cost_nanos, source.usage
    from source_rows source
    on conflict (workspace_id, batch_id, custom_id) do nothing
    returning custom_id, provider, endpoint, model, cost_nanos, usage
  )
  insert into public.gateway_requests (
    workspace_id, request_id, endpoint, model_id, provider,
    status_code, success, usage, cost_nanos, currency, key_id
  )
  select
    p_workspace_id,
    'batch_usage:' || p_batch_id || ':' || claimed.custom_id,
    claimed.endpoint,
    claimed.model,
    claimed.provider,
    200,
    true,
    claimed.usage,
    claimed.cost_nanos,
    'USD',
    p_key_id
  from claimed_rows claimed;
  get diagnostics v_inserted = row_count;

  update public.gateway_wallet_reservations
  set key_usage_recorded_at = coalesce(key_usage_recorded_at, now()), updated_at = now()
  where workspace_id = p_workspace_id
    and key_id = p_key_id
    and capture_ref_id = p_batch_id
    and status = 'captured';

  return v_inserted;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_record_batch_key_usage"(uuid, uuid, text, text, jsonb) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_request_usage_rollup_rows (
  p_since timestamp with time zone,
  p_until timestamp with time zone DEFAULT now()
)
  RETURNS TABLE (
    day_bucket                  date,
    model_id                    text,
    provider_id                 text,
    endpoint                    text,
    requests                    bigint,
    success_requests            bigint,
    failed_requests             bigint,
    neutral_requests            bigint,
    rate_limited_requests       bigint,
    total_tokens                bigint,
    input_tokens                bigint,
    output_tokens               bigint,
    reasoning_tokens            bigint,
    input_text_tokens           bigint,
    output_text_tokens          bigint,
    input_image_tokens          bigint,
    output_image_tokens         bigint,
    input_audio_tokens          bigint,
    output_audio_tokens         bigint,
    input_video_tokens          bigint,
    output_video_tokens         bigint,
    image_inputs                bigint,
    image_outputs               bigint,
    audio_inputs                bigint,
    audio_outputs               bigint,
    video_inputs                bigint,
    video_outputs               bigint,
    cached_read_tokens          bigint,
    cached_write_tokens         bigint,
    cached_read_text_tokens     bigint,
    cached_write_text_tokens    bigint,
    cached_write_text_tokens_5m bigint,
    cached_write_text_tokens_1h bigint,
    cached_read_image_tokens    bigint,
    cached_write_image_tokens   bigint,
    cached_read_audio_tokens    bigint,
    cached_write_audio_tokens   bigint,
    cached_read_video_tokens    bigint,
    cached_write_video_tokens   bigint,
    input_quad_tokens           bigint,
    output_quad_tokens          bigint,
    total_quad_tokens           bigint,
    text_quad_tokens            bigint,
    rerank_quad_tokens          bigint,
    embedding_quad_tokens       bigint,
    moderation_quad_tokens      bigint,
    ocr_quad_tokens             bigint,
    image_megapixels            numeric,
    audio_seconds               numeric,
    video_pixel_seconds         numeric,
    input_characters            bigint,
    output_characters           bigint,
    total_characters            bigint,
    total_cost_nanos            bigint,
    latency_sum_ms              bigint,
    latency_samples             bigint,
    generation_sum_ms           bigint,
    generation_samples          bigint,
    throughput_sum              numeric,
    throughput_samples          bigint,
    last_request_at             timestamp with time zone
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  with base as (
    select
      date_trunc('day', gr.created_at at time zone 'utc')::date as day_bucket,
      coalesce(
        nullif(gr.canonical_model_id, ''),
        public.resolve_public_model_id(gr.model_id, gr.provider),
        nullif(gr.routed_model_id, ''),
        nullif(gr.requested_model_id, ''),
        nullif(gr.model_id, ''),
        'unknown'
      ) as model_id,
      coalesce(nullif(gr.provider, ''), 'unknown') as provider_id,
      coalesce(nullif(gr.endpoint, ''), 'unknown') as endpoint,
      gr.created_at,
      gr.success,
      gr.status_code,
      lower(coalesce(gr.error_code, '')) as error_code,
      gr.cost_nanos,
      gr.latency_ms,
      gr.generation_ms,
      gr.throughput,
      gr.usage_total_tokens,
      gr.usage_input_tokens,
      gr.usage_output_tokens,
      gr.usage_reasoning_tokens,
      gr.usage_input_text_tokens,
      gr.usage_output_text_tokens,
      gr.usage_input_image_tokens,
      gr.usage_output_image_tokens,
      gr.usage_input_audio_tokens,
      gr.usage_output_audio_tokens,
      gr.usage_input_video_tokens,
      gr.usage_output_video_tokens,
      gr.usage_image_inputs,
      gr.usage_image_outputs,
      gr.usage_audio_inputs,
      gr.usage_audio_outputs,
      gr.usage_video_inputs,
      gr.usage_video_outputs,
      gr.usage_cached_read_tokens,
      gr.usage_cached_write_tokens,
      gr.usage_cached_read_text_tokens,
      gr.usage_cached_write_text_tokens,
      gr.usage_cached_write_text_tokens_5m,
      gr.usage_cached_write_text_tokens_1h,
      gr.usage_cached_read_image_tokens,
      gr.usage_cached_write_image_tokens,
      gr.usage_cached_read_audio_tokens,
      gr.usage_cached_write_audio_tokens,
      gr.usage_cached_read_video_tokens,
      gr.usage_cached_write_video_tokens,
      gr.usage_input_quad_tokens,
      gr.usage_output_quad_tokens,
      gr.usage_total_quad_tokens,
      gr.usage_text_quad_tokens,
      gr.usage_rerank_quad_tokens,
      gr.usage_embedding_quad_tokens,
      gr.usage_moderation_quad_tokens,
      gr.usage_ocr_quad_tokens,
      gr.usage_image_megapixels,
      gr.usage_audio_seconds,
      gr.usage_video_pixel_seconds,
      gr.usage_input_characters,
      gr.usage_output_characters,
      gr.usage_total_characters
    from private.v2_rpc_gateway_requests_compat gr
    where gr.created_at >= p_since
      and gr.created_at < p_until
  ),
  classified as (
    select
      b.*,
      case
        when b.success is true then 'success'
        when b.status_code = 429
          or b.error_code like '%rate limit%'
          or b.error_code like '%rate_limit%'
          or b.error_code like '%ratelimit%'
          or b.error_code like '%too many requests%'
          or b.error_code like '%quota exceeded%'
          or b.error_code like '%abort%'
          or b.error_code like '%cancel%'
          or b.error_code like '%client_closed%'
        then 'neutral'
        else 'failure'
      end as health_outcome,
      case
        when b.status_code = 429
          or b.error_code like '%rate limit%'
          or b.error_code like '%rate_limit%'
          or b.error_code like '%ratelimit%'
          or b.error_code like '%too many requests%'
          or b.error_code like '%quota exceeded%'
        then true
        else false
      end as is_rate_limited
    from base b
  )
  select
    c.day_bucket,
    c.model_id,
    c.provider_id,
    c.endpoint,
    count(*)::bigint as requests,
    count(*) filter (where c.success is true)::bigint as success_requests,
    count(*) filter (where c.health_outcome = 'failure')::bigint as failed_requests,
    count(*) filter (where c.health_outcome = 'neutral')::bigint as neutral_requests,
    count(*) filter (where c.is_rate_limited)::bigint as rate_limited_requests,
    sum(c.usage_total_tokens)::bigint as total_tokens,
    sum(c.usage_input_tokens)::bigint as input_tokens,
    sum(c.usage_output_tokens)::bigint as output_tokens,
    sum(c.usage_reasoning_tokens)::bigint as reasoning_tokens,
    sum(c.usage_input_text_tokens)::bigint as input_text_tokens,
    sum(c.usage_output_text_tokens)::bigint as output_text_tokens,
    sum(c.usage_input_image_tokens)::bigint as input_image_tokens,
    sum(c.usage_output_image_tokens)::bigint as output_image_tokens,
    sum(c.usage_input_audio_tokens)::bigint as input_audio_tokens,
    sum(c.usage_output_audio_tokens)::bigint as output_audio_tokens,
    sum(c.usage_input_video_tokens)::bigint as input_video_tokens,
    sum(c.usage_output_video_tokens)::bigint as output_video_tokens,
    sum(c.usage_image_inputs)::bigint as image_inputs,
    sum(c.usage_image_outputs)::bigint as image_outputs,
    sum(c.usage_audio_inputs)::bigint as audio_inputs,
    sum(c.usage_audio_outputs)::bigint as audio_outputs,
    sum(c.usage_video_inputs)::bigint as video_inputs,
    sum(c.usage_video_outputs)::bigint as video_outputs,
    sum(c.usage_cached_read_tokens)::bigint as cached_read_tokens,
    sum(c.usage_cached_write_tokens)::bigint as cached_write_tokens,
    sum(c.usage_cached_read_text_tokens)::bigint as cached_read_text_tokens,
    sum(c.usage_cached_write_text_tokens)::bigint as cached_write_text_tokens,
    sum(c.usage_cached_write_text_tokens_5m)::bigint as cached_write_text_tokens_5m,
    sum(c.usage_cached_write_text_tokens_1h)::bigint as cached_write_text_tokens_1h,
    sum(c.usage_cached_read_image_tokens)::bigint as cached_read_image_tokens,
    sum(c.usage_cached_write_image_tokens)::bigint as cached_write_image_tokens,
    sum(c.usage_cached_read_audio_tokens)::bigint as cached_read_audio_tokens,
    sum(c.usage_cached_write_audio_tokens)::bigint as cached_write_audio_tokens,
    sum(c.usage_cached_read_video_tokens)::bigint as cached_read_video_tokens,
    sum(c.usage_cached_write_video_tokens)::bigint as cached_write_video_tokens,
    sum(c.usage_input_quad_tokens)::bigint as input_quad_tokens,
    sum(c.usage_output_quad_tokens)::bigint as output_quad_tokens,
    sum(c.usage_total_quad_tokens)::bigint as total_quad_tokens,
    sum(c.usage_text_quad_tokens)::bigint as text_quad_tokens,
    sum(c.usage_rerank_quad_tokens)::bigint as rerank_quad_tokens,
    sum(c.usage_embedding_quad_tokens)::bigint as embedding_quad_tokens,
    sum(c.usage_moderation_quad_tokens)::bigint as moderation_quad_tokens,
    sum(c.usage_ocr_quad_tokens)::bigint as ocr_quad_tokens,
    sum(c.usage_image_megapixels)::numeric as image_megapixels,
    sum(c.usage_audio_seconds)::numeric as audio_seconds,
    sum(c.usage_video_pixel_seconds)::numeric as video_pixel_seconds,
    sum(c.usage_input_characters)::bigint as input_characters,
    sum(c.usage_output_characters)::bigint as output_characters,
    sum(c.usage_total_characters)::bigint as total_characters,
    sum(coalesce(c.cost_nanos, 0))::bigint as total_cost_nanos,
    sum(coalesce(c.latency_ms, 0)) filter (where c.latency_ms is not null)::bigint as latency_sum_ms,
    count(c.latency_ms)::bigint as latency_samples,
    sum(coalesce(c.generation_ms, 0)) filter (where c.generation_ms is not null)::bigint as generation_sum_ms,
    count(c.generation_ms)::bigint as generation_samples,
    sum(coalesce(c.throughput, 0)) filter (where c.throughput is not null)::numeric as throughput_sum,
    count(c.throughput)::bigint as throughput_samples,
    max(c.created_at) as last_request_at
  from classified c
  where c.model_id is not null
    and c.model_id <> ''
  group by c.day_bucket, c.model_id, c.provider_id, c.endpoint;
$function$;

CREATE OR REPLACE FUNCTION public.gateway_requests_attach_chat_app_id()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  v_key_name text;
  v_chat_app_key constant text := 'https://ai-stats.phaseo.app/chat';
  v_app_id uuid;
begin
  if new.app_id is not null then
    return new;
  end if;

  if new.workspace_id is null or new.key_id is null then
    return new;
  end if;

  select k.name into v_key_name
  from public.keys k
  where k.id = new.key_id
  limit 1;

  if coalesce(v_key_name, '') <> '__chat_route_managed_key__' then
    return new;
  end if;

  insert into public.api_apps (
    workspace_id,
    app_key,
    title,
    url,
    is_active,
    last_seen,
    updated_at,
    meta
  )
  values (
    new.workspace_id,
    v_chat_app_key,
    'AI Stats Chat',
    v_chat_app_key,
    true,
    coalesce(new.created_at, now()),
    now(),
    jsonb_build_object(
      'identityUrl', v_chat_app_key,
      'managed', true
    )
  )
  on conflict (workspace_id, app_key) do update
    set title = excluded.title,
        url = excluded.url,
        is_active = true,
        last_seen = greatest(public.api_apps.last_seen, excluded.last_seen),
        updated_at = now(),
        meta = coalesce(public.api_apps.meta, '{}'::jsonb) || excluded.meta
  returning id into v_app_id;

  new.app_id := v_app_id;
  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_requests_attach_chat_app_id"() FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_set_async_operation_status (
  p_workspace_id          uuid,
  p_kind                  text,
  p_internal_id           text,
  p_status                text                     DEFAULT NULL::text,
  p_meta_patch            jsonb                    DEFAULT '{}'::jsonb,
  p_update_next_reconcile boolean                  DEFAULT false,
  p_next_reconcile_at     timestamp with time zone DEFAULT NULL::timestamp WITH time zone
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if p_kind not in ('video', 'batch') then
    raise exception 'invalid async operation kind';
  end if;

  update public.gateway_async_operations
  set
    status = case
      when p_status is null then status
      when lower(coalesce(status, '')) in ('completed', 'failed', 'cancelled', 'canceled', 'expired') then status
      when (
        case lower(p_status)
          when 'queued' then 1 when 'pending' then 1
          when 'in_progress' then 2 when 'processing' then 2 when 'running' then 2
          when 'completed' then 3 when 'failed' then 3 when 'cancelled' then 3 when 'canceled' then 3 when 'expired' then 3
          else 0
        end
      ) < (
        case lower(coalesce(status, ''))
          when 'queued' then 1 when 'pending' then 1
          when 'in_progress' then 2 when 'processing' then 2 when 'running' then 2
          when 'completed' then 3 when 'failed' then 3 when 'cancelled' then 3 when 'canceled' then 3 when 'expired' then 3
          else 0
        end
      ) then status
      else p_status
    end,
    meta = coalesce(meta, '{}'::jsonb) || coalesce(p_meta_patch, '{}'::jsonb),
    next_reconcile_at = case
      when p_update_next_reconcile then p_next_reconcile_at
      else next_reconcile_at
    end,
    updated_at = now()
  where workspace_id = p_workspace_id
    and kind = p_kind
    and internal_id = p_internal_id;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_set_async_operation_status"(uuid, text, text, text, jsonb, boolean, timestamp WITH time zone) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_usage_nonnegative_bigint (
  p_value numeric
)
  RETURNS bigint
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  select greatest(coalesce(floor(p_value), 0), 0)::bigint;
$function$;

CREATE OR REPLACE FUNCTION public.gateway_usage_numeric_field (
  p_usage  jsonb,
  VARIADIC p_keys text[]
)
  RETURNS numeric
  LANGUAGE plpgsql
  IMMUTABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_key text;
  v_part text;
  v_cursor jsonb;
  v_value text;
begin
  if p_usage is null then
    return null;
  end if;

  foreach v_key in array p_keys loop
    v_cursor := p_usage;

    foreach v_part in array string_to_array(v_key, '.') loop
      if v_cursor is null or jsonb_typeof(v_cursor) <> 'object' or not (v_cursor ? v_part) then
        v_cursor := null;
        exit;
      end if;
      v_cursor := v_cursor -> v_part;
    end loop;

    if v_cursor is null then
      continue;
    end if;

    v_value := trim(both '"' from v_cursor::text);
    if v_value ~ '^-?[0-9]+(\.[0-9]+)?$' then
      return v_value::numeric;
    end if;
  end loop;

  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.gateway_usage_total_tokens (
  p_usage jsonb
)
  RETURNS bigint
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  select coalesce(
    case
      when coalesce(p_usage->>'total_tokens', '') ~ '^\d+$'
        then (p_usage->>'total_tokens')::bigint
      else null
    end,
    greatest(
      coalesce(case when coalesce(p_usage->>'input_text_tokens', '') ~ '^\d+$' then (p_usage->>'input_text_tokens')::bigint end, 0),
      coalesce(case when coalesce(p_usage->>'input_tokens', '') ~ '^\d+$' then (p_usage->>'input_tokens')::bigint end, 0),
      coalesce(case when coalesce(p_usage->>'prompt_tokens', '') ~ '^\d+$' then (p_usage->>'prompt_tokens')::bigint end, 0)
    )
    + greatest(
      coalesce(case when coalesce(p_usage->>'output_text_tokens', '') ~ '^\d+$' then (p_usage->>'output_text_tokens')::bigint end, 0),
      coalesce(case when coalesce(p_usage->>'output_tokens', '') ~ '^\d+$' then (p_usage->>'output_tokens')::bigint end, 0),
      coalesce(case when coalesce(p_usage->>'completion_tokens', '') ~ '^\d+$' then (p_usage->>'completion_tokens')::bigint end, 0)
    )
    + coalesce(case when coalesce(p_usage->>'reasoning_tokens', '') ~ '^\d+$' then (p_usage->>'reasoning_tokens')::bigint end, 0)
    + coalesce(case when coalesce(p_usage->>'cached_read_text_tokens', '') ~ '^\d+$' then (p_usage->>'cached_read_text_tokens')::bigint end, 0),
    0
  );
$function$;

CREATE OR REPLACE FUNCTION public.gateway_validate_pricing_time_windows (
  value jsonb
)
  RETURNS boolean
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  select
    jsonb_typeof(value) = 'array'
    and not exists (
      select 1
      from jsonb_array_elements(value) as item(window_value)
      where
        jsonb_typeof(item.window_value) is distinct from 'object'
        or jsonb_typeof(item.window_value->'label') is distinct from 'string'
        or btrim(item.window_value->>'label') = ''
        or item.window_value->>'timezone' is distinct from 'UTC'
        or coalesce(item.window_value->>'start_time', '') !~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9]$'
        or coalesce(item.window_value->>'end_time', '') !~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9]$'
        or item.window_value->>'start_time' = item.window_value->>'end_time'
        or (
          item.window_value ? 'price_per_unit'
          and case jsonb_typeof(item.window_value->'price_per_unit')
            when 'null' then false
            when 'number' then (item.window_value->>'price_per_unit')::numeric < 0
            when 'string' then
              case
                when btrim(item.window_value->>'price_per_unit') !~ '^[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?$' then true
                else (btrim(item.window_value->>'price_per_unit'))::numeric < 0
              end
            else true
          end
        )
        or (
          item.window_value ? 'priority'
          and case jsonb_typeof(item.window_value->'priority')
            when 'null' then false
            when 'number' then ((item.window_value->>'priority')::numeric % 1) <> 0
            else true
          end
        )
    );
$function$;

CREATE OR REPLACE FUNCTION public.gateway_wallet_capture_once (
  p_workspace_id   uuid,
  p_reservation_id text,
  p_capture_ref_id text DEFAULT NULL::text
)
  RETURNS TABLE (
    ok                    boolean,
    applied               boolean,
    reason                text,
    amount_nanos          bigint,
    before_balance_nanos  bigint,
    after_balance_nanos   bigint,
    before_reserved_nanos bigint,
    after_reserved_nanos  bigint
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  v_wallet public.wallets%rowtype;
  v_existing public.gateway_wallet_reservations%rowtype;
  v_amount bigint;
begin
  if p_workspace_id is null then
    raise exception 'workspace_id_required' using errcode = 'P0001';
  end if;
  if coalesce(trim(p_reservation_id), '') = '' then
    raise exception 'reservation_id_required' using errcode = 'P0001';
  end if;

  select * into v_existing
  from public.gateway_wallet_reservations
  where reservation_id = p_reservation_id
    and workspace_id = p_workspace_id
  for update;

  if not found then
    return query select false, false, 'reservation_not_found'::text, null::bigint,
      null::bigint, null::bigint, null::bigint, null::bigint;
    return;
  end if;

  select * into v_wallet
  from public.wallets
  where workspace_id = p_workspace_id
  for update;

  if not found then
    return query select false, false, 'wallet_not_found'::text, v_existing.amount_nanos,
      null::bigint, null::bigint, null::bigint, null::bigint;
    return;
  end if;

  if v_existing.status = 'captured' then
    return query select true, false, 'already_captured'::text, coalesce(v_existing.settled_amount_nanos, v_existing.amount_nanos),
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint;
    return;
  end if;

  if v_existing.status not in ('held', 'reserved') then
    return query select false, false, 'reservation_not_active'::text, v_existing.amount_nanos,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint;
    return;
  end if;

  v_amount := v_existing.amount_nanos;

  if coalesce(v_wallet.reserved_nanos, 0) < v_amount then
    return query select false, false, 'reserved_balance_mismatch'::text, v_amount,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint;
    return;
  end if;

  update public.wallets
  set balance_nanos = coalesce(balance_nanos, 0) - v_amount,
      reserved_nanos = coalesce(reserved_nanos, 0) - v_amount,
      updated_at = now()
  where workspace_id = p_workspace_id
  returning *
  into v_wallet;

  update public.gateway_wallet_reservations
  set status = 'captured',
      settled_amount_nanos = v_amount,
      captured_nanos = v_amount,
      released_nanos = 0,
      capture_ref_id = nullif(trim(coalesce(p_capture_ref_id, '')), ''),
      captured_at = now(),
      updated_at = now()
  where reservation_id = p_reservation_id
    and workspace_id = p_workspace_id;

  insert into public.credit_ledger (
    workspace_id, kind, amount_nanos, before_balance_nanos, after_balance_nanos,
    before_reserved_nanos, after_reserved_nanos, ref_type, ref_id, source_ref_type, source_ref_id, status
  ) values (
    p_workspace_id, 'charge', -v_amount, v_wallet.balance_nanos + v_amount, v_wallet.balance_nanos,
    v_wallet.reserved_nanos + v_amount, v_wallet.reserved_nanos,
    'async_job_charge', p_workspace_id::text || ':' || p_reservation_id,
    'async_job', coalesce(nullif(trim(p_capture_ref_id), ''), p_reservation_id), 'captured'
  );

  return query select true, true, null::text, v_amount,
    coalesce(v_wallet.balance_nanos, 0) + v_amount,
    coalesce(v_wallet.balance_nanos, 0),
    coalesce(v_wallet.reserved_nanos, 0) + v_amount,
    coalesce(v_wallet.reserved_nanos, 0);
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_wallet_capture_once"(uuid, text, text) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_wallet_release_once (
  p_workspace_id   uuid,
  p_reservation_id text,
  p_release_ref_id text DEFAULT NULL::text
)
  RETURNS TABLE (
    ok                    boolean,
    applied               boolean,
    reason                text,
    amount_nanos          bigint,
    before_balance_nanos  bigint,
    after_balance_nanos   bigint,
    before_reserved_nanos bigint,
    after_reserved_nanos  bigint
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  v_wallet public.wallets%rowtype;
  v_existing public.gateway_wallet_reservations%rowtype;
  v_amount bigint;
begin
  if p_workspace_id is null then
    raise exception 'workspace_id_required' using errcode = 'P0001';
  end if;
  if coalesce(trim(p_reservation_id), '') = '' then
    raise exception 'reservation_id_required' using errcode = 'P0001';
  end if;

  select * into v_existing
  from public.gateway_wallet_reservations
  where reservation_id = p_reservation_id
    and workspace_id = p_workspace_id
  for update;

  if not found then
    return query select false, false, 'reservation_not_found'::text, null::bigint,
      null::bigint, null::bigint, null::bigint, null::bigint;
    return;
  end if;

  select * into v_wallet
  from public.wallets
  where workspace_id = p_workspace_id
  for update;

  if not found then
    return query select false, false, 'wallet_not_found'::text, v_existing.amount_nanos,
      null::bigint, null::bigint, null::bigint, null::bigint;
    return;
  end if;

  if v_existing.status = 'released' then
    return query select true, false, 'already_released'::text, v_existing.amount_nanos,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint;
    return;
  end if;

  if v_existing.status not in ('held', 'reserved') then
    return query select false, false, 'reservation_not_active'::text, v_existing.amount_nanos,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint;
    return;
  end if;

  v_amount := v_existing.amount_nanos;

  if coalesce(v_wallet.reserved_nanos, 0) < v_amount then
    return query select false, false, 'reserved_balance_mismatch'::text, v_amount,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint;
    return;
  end if;

  update public.wallets
  set reserved_nanos = coalesce(reserved_nanos, 0) - v_amount,
      updated_at = now()
  where workspace_id = p_workspace_id
  returning *
  into v_wallet;

  update public.gateway_wallet_reservations
  set status = 'released',
      captured_nanos = 0,
      released_nanos = v_amount,
      release_ref_id = nullif(trim(coalesce(p_release_ref_id, '')), ''),
      released_at = now(),
      updated_at = now()
  where reservation_id = p_reservation_id
    and workspace_id = p_workspace_id;

  return query select true, true, null::text, v_amount,
    coalesce(v_wallet.balance_nanos, 0),
    coalesce(v_wallet.balance_nanos, 0),
    coalesce(v_wallet.reserved_nanos, 0) + v_amount,
    coalesce(v_wallet.reserved_nanos, 0);
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_wallet_release_once"(uuid, text, text) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_wallet_release_stale_orphan_batch_reservations (
  p_older_than_seconds integer DEFAULT 1800,
  p_limit              integer DEFAULT 100
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_reservation public.gateway_wallet_reservations%rowtype;
  v_released integer := 0;
begin
  for v_reservation in
    select reservation.*
    from public.gateway_wallet_reservations reservation
    where reservation.reservation_id like 'batch_hold:%'
      and reservation.status in ('held', 'reserved')
      and reservation.created_at < now() - make_interval(secs => greatest(300, p_older_than_seconds))
      and not exists (
        select 1
        from public.gateway_async_operations operation
        where operation.workspace_id = reservation.workspace_id
          and operation.kind = 'batch'
          and (
            operation.request_id = reservation.hold_ref_id
            or operation.meta ->> 'reservationId' = reservation.reservation_id
            or operation.meta ->> 'reservation_id' = reservation.reservation_id
          )
      )
    order by reservation.created_at asc
    for update skip locked
    limit greatest(1, least(coalesce(p_limit, 100), 1000))
  loop
    update public.wallets
    set reserved_nanos = greatest(0, coalesce(reserved_nanos, 0) - v_reservation.amount_nanos),
        updated_at = now()
    where workspace_id = v_reservation.workspace_id
      and coalesce(reserved_nanos, 0) >= v_reservation.amount_nanos;

    if found then
      update public.gateway_wallet_reservations
      set status = 'released',
          release_ref_id = 'stale_orphan_batch_reaper',
          released_at = now(),
          updated_at = now()
      where workspace_id = v_reservation.workspace_id
        and reservation_id = v_reservation.reservation_id;
      v_released := v_released + 1;
    end if;
  end loop;
  return v_released;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_wallet_release_stale_orphan_batch_reservations"(integer, integer) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_wallet_reserve_once (
  p_workspace_id   uuid,
  p_reservation_id text,
  p_amount_nanos   bigint,
  p_hold_ref_id    text    DEFAULT NULL::text,
  p_key_id         uuid    DEFAULT NULL::uuid,
  p_request_count  integer DEFAULT NULL::integer
)
  RETURNS TABLE (
    ok                    boolean,
    applied               boolean,
    reason                text,
    amount_nanos          bigint,
    before_balance_nanos  bigint,
    after_balance_nanos   bigint,
    before_reserved_nanos bigint,
    after_reserved_nanos  bigint
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_budget_status jsonb;
  v_balance_nanos bigint;
  v_reserved_nanos bigint;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text, 0));
  perform 1 from public.workspace_budgets
    where workspace_id = p_workspace_id
    order by interval
    for update;

  if not exists (
    select 1 from public.gateway_wallet_reservations
    where workspace_id = p_workspace_id and reservation_id = p_reservation_id
  ) then
    v_budget_status := public.gateway_workspace_budget_status(p_workspace_id, p_amount_nanos);
    if not coalesce((v_budget_status->>'ok')::boolean, true) then
      return query select false, false, (v_budget_status->>'reason')::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;

    if p_reservation_id like 'video_hold:%' or p_reservation_id like 'batch_hold:%' then
      select coalesce(wallet.balance_nanos, 0), coalesce(wallet.reserved_nanos, 0)
      into v_balance_nanos, v_reserved_nanos
      from public.wallets wallet
      where wallet.workspace_id = p_workspace_id
      for update;
      if found and v_balance_nanos - v_reserved_nanos < 1000000000 then
        return query select false, false, 'insufficient_funds'::text, p_amount_nanos,
          v_balance_nanos, v_balance_nanos, v_reserved_nanos, v_reserved_nanos;
        return;
      end if;
    end if;
  end if;

  return query
  select * from public.gateway_wallet_reserve_once_without_workspace_budget(
    p_workspace_id, p_reservation_id, p_amount_nanos, p_hold_ref_id, p_key_id, p_request_count
  );
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_wallet_reserve_once"(uuid, text, bigint, text, uuid, integer) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_wallet_reserve_once_without_workspace_budget (
  p_workspace_id   uuid,
  p_reservation_id text,
  p_amount_nanos   bigint,
  p_hold_ref_id    text    DEFAULT NULL::text,
  p_key_id         uuid    DEFAULT NULL::uuid,
  p_request_count  integer DEFAULT NULL::integer
)
  RETURNS TABLE (
    ok                    boolean,
    applied               boolean,
    reason                text,
    amount_nanos          bigint,
    before_balance_nanos  bigint,
    after_balance_nanos   bigint,
    before_reserved_nanos bigint,
    after_reserved_nanos  bigint
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_wallet public.wallets%rowtype;
  v_existing public.gateway_wallet_reservations%rowtype;
  v_key public.keys%rowtype;
  v_available bigint;
  v_before_balance bigint;
  v_before_reserved bigint;
  v_day_start timestamptz := (date_trunc('day', now() at time zone 'utc') at time zone 'utc');
  v_week_start timestamptz := (date_trunc('week', now() at time zone 'utc') at time zone 'utc');
  v_month_start timestamptz := (date_trunc('month', now() at time zone 'utc') at time zone 'utc');
  v_day_requests bigint := 0;
  v_week_requests bigint := 0;
  v_month_requests bigint := 0;
  v_day_cost bigint := 0;
  v_week_cost bigint := 0;
  v_month_cost bigint := 0;
  v_requested_count integer := greatest(0, coalesce(p_request_count, 0));
  v_video_exposure record;
begin
  if p_workspace_id is null or coalesce(trim(p_reservation_id), '') = '' then
    raise exception 'invalid_reservation_identity';
  end if;
  if p_amount_nanos is null or p_amount_nanos <= 0 then
    raise exception 'invalid_reservation_amount';
  end if;
  if p_key_id is not null and v_requested_count <= 0 then
    raise exception 'batch_request_count_required';
  end if;
  if v_requested_count > 10000 then
    raise exception 'batch_request_limit_exceeded';
  end if;

  select * into v_existing
  from public.gateway_wallet_reservations
  where workspace_id = p_workspace_id and reservation_id = p_reservation_id
  for update;
  if found then
    select * into v_wallet from public.wallets
    where workspace_id = p_workspace_id for update;
    if not found then
      return query select false, false, 'wallet_not_found'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;
    if v_existing.amount_nanos <> p_amount_nanos
      or v_existing.key_id is distinct from p_key_id
      or coalesce(v_existing.request_count, 0) <> v_requested_count then
      raise exception 'reservation_identity_mismatch';
    end if;
    if v_existing.status in ('held', 'reserved') then
      return query select true, false, 'already_reserved'::text, v_existing.amount_nanos,
        coalesce(v_wallet.balance_nanos, 0), coalesce(v_wallet.balance_nanos, 0),
        coalesce(v_wallet.reserved_nanos, 0), coalesce(v_wallet.reserved_nanos, 0);
      return;
    end if;
    return query select false, false, 'reservation_not_active'::text, v_existing.amount_nanos,
      coalesce(v_wallet.balance_nanos, 0), coalesce(v_wallet.balance_nanos, 0),
      coalesce(v_wallet.reserved_nanos, 0), coalesce(v_wallet.reserved_nanos, 0);
    return;
  end if;

  if p_key_id is not null then
    select * into v_key from public.keys where id = p_key_id for update;
    if not found then
      return query select false, false, 'key_not_found'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;
    if v_key.workspace_id <> p_workspace_id then
      return query select false, false, 'key_wrong_workspace'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;
    if v_key.status <> 'active' or (v_key.expires_at is not null and v_key.expires_at <= now()) then
      return query select false, false, 'key_not_active'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;
    if coalesce(v_key.soft_blocked, false) then
      return query select false, false, 'key_limit_soft_blocked'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;

    select
      count(*) filter (where created_at >= v_day_start),
      count(*) filter (where created_at >= v_week_start),
      count(*) filter (where created_at >= v_month_start),
      coalesce(sum(cost_nanos) filter (where created_at >= v_day_start), 0),
      coalesce(sum(cost_nanos) filter (where created_at >= v_week_start), 0),
      coalesce(sum(cost_nanos) filter (where created_at >= v_month_start), 0)
    into v_day_requests, v_week_requests, v_month_requests,
      v_day_cost, v_week_cost, v_month_cost
    from public.gateway_requests
    where workspace_id = p_workspace_id and key_id = p_key_id and success is true;

    -- Video create audit rows have zero cost until completion. Count the unpaid
    -- portion of each reservation under the same key lock as admission. Captured
    -- reservations bridge the gap until the final request audit is persisted.
    -- Active holds remain exposure across budget-window boundaries.
    with exposure as (
      select r.created_at, r.status in ('held', 'reserved') as active,
        greatest(0, (case when r.status = 'captured'
          then coalesce(r.settled_amount_nanos, r.amount_nanos)
          else r.amount_nanos end) - coalesce(a.cost, 0)) as cost,
        case when coalesce(a.requests, 0) = 0 then 1 else 0 end as requests
      from public.gateway_wallet_reservations r
      left join lateral (
        select sum(gr.cost_nanos) as cost, count(*) as requests
        from public.gateway_requests gr
        where gr.workspace_id = r.workspace_id and gr.key_id = r.key_id
          and gr.request_id = r.hold_ref_id
          and (r.reservation_id not like 'free_model_hold:%' or
            gr.detail_metadata->>'free_model_fee_request_id' = substr(r.reservation_id, 17)) and gr.success is true
      ) a on true
      where r.workspace_id = p_workspace_id and r.key_id = p_key_id
        and (r.reservation_id like 'video_hold:%' or r.reservation_id like 'free_model_hold:%')
        and r.status in ('held', 'reserved', 'captured')
        and (r.status in ('held', 'reserved') or r.created_at >= least(v_day_start, v_week_start, v_month_start))
    )
    select
      coalesce(sum(cost) filter (where active or created_at >= v_day_start), 0) as day_cost,
      coalesce(sum(cost) filter (where active or created_at >= v_week_start), 0) as week_cost,
      coalesce(sum(cost) filter (where active or created_at >= v_month_start), 0) as month_cost,
      coalesce(sum(requests) filter (where active or created_at >= v_day_start), 0) as day_requests,
      coalesce(sum(requests) filter (where active or created_at >= v_week_start), 0) as week_requests,
      coalesce(sum(requests) filter (where active or created_at >= v_month_start), 0) as month_requests
    into v_video_exposure from exposure;
    v_day_cost := v_day_cost + v_video_exposure.day_cost;
    v_week_cost := v_week_cost + v_video_exposure.week_cost;
    v_month_cost := v_month_cost + v_video_exposure.month_cost;
    v_day_requests := v_day_requests + v_video_exposure.day_requests;
    v_week_requests := v_week_requests + v_video_exposure.week_requests;
    v_month_requests := v_month_requests + v_video_exposure.month_requests;

    if coalesce(v_key.daily_limit_requests, 0) > 0
      and v_day_requests + v_requested_count > v_key.daily_limit_requests then
      return query select false, false, 'daily_request_limit_reached'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;
    if coalesce(v_key.weekly_limit_requests, 0) > 0
      and v_week_requests + v_requested_count > v_key.weekly_limit_requests then
      return query select false, false, 'weekly_request_limit_reached'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;
    if coalesce(v_key.monthly_limit_requests, 0) > 0
      and v_month_requests + v_requested_count > v_key.monthly_limit_requests then
      return query select false, false, 'monthly_request_limit_reached'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;
    if coalesce(v_key.daily_limit_cost_nanos, 0) > 0
      and v_day_cost + p_amount_nanos > v_key.daily_limit_cost_nanos then
      return query select false, false, 'daily_cost_limit_reached'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;
    if coalesce(v_key.weekly_limit_cost_nanos, 0) > 0
      and v_week_cost + p_amount_nanos > v_key.weekly_limit_cost_nanos then
      return query select false, false, 'weekly_cost_limit_reached'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;
    if coalesce(v_key.monthly_limit_cost_nanos, 0) > 0
      and v_month_cost + p_amount_nanos > v_key.monthly_limit_cost_nanos then
      return query select false, false, 'monthly_cost_limit_reached'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;
  end if;

  select * into v_wallet from public.wallets
  where workspace_id = p_workspace_id for update;
  if not found then
    return query select false, false, 'wallet_not_found'::text, p_amount_nanos,
      null::bigint, null::bigint, null::bigint, null::bigint;
    return;
  end if;
  v_available := coalesce(v_wallet.balance_nanos, 0) - coalesce(v_wallet.reserved_nanos, 0);
  if v_available < p_amount_nanos then
    return query select false, false, 'insufficient_balance'::text, p_amount_nanos,
      coalesce(v_wallet.balance_nanos, 0), coalesce(v_wallet.balance_nanos, 0),
      coalesce(v_wallet.reserved_nanos, 0), coalesce(v_wallet.reserved_nanos, 0);
    return;
  end if;

  insert into public.gateway_wallet_reservations (
    reservation_id, workspace_id, amount_nanos, status, hold_ref_id,
    key_id, request_count, created_at, updated_at
  ) values (
    p_reservation_id, p_workspace_id, p_amount_nanos, 'reserved',
    nullif(trim(coalesce(p_hold_ref_id, '')), ''), p_key_id,
    nullif(v_requested_count, 0), now(), now()
  );

  v_before_balance := coalesce(v_wallet.balance_nanos, 0);
  v_before_reserved := coalesce(v_wallet.reserved_nanos, 0);
  update public.wallets
  set reserved_nanos = v_before_reserved + p_amount_nanos, updated_at = now()
  where workspace_id = p_workspace_id
  returning * into v_wallet;

  if p_key_id is not null and p_reservation_id not like 'video_hold:%' and p_reservation_id not like 'free_model_hold:%' then
    insert into public.gateway_requests (
      workspace_id, request_id, endpoint, model_id, provider,
      status_code, success, usage, cost_nanos, currency, key_id
    )
    select
      p_workspace_id,
      'batch_hold_usage:' || p_reservation_id || ':' || item::text,
      'batch',
      'batch/reserved',
      null,
      202,
      true,
      jsonb_build_object('batch_reserved', true),
      (p_amount_nanos / v_requested_count)
        + case when item <= (p_amount_nanos % v_requested_count) then 1 else 0 end,
      'USD',
      p_key_id
    from generate_series(1, v_requested_count) as item
    ;
  end if;

  return query select true, true, null::text, p_amount_nanos,
    v_before_balance, coalesce(v_wallet.balance_nanos, 0),
    v_before_reserved, coalesce(v_wallet.reserved_nanos, 0);
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_wallet_reserve_once_without_workspace_budget"(uuid, text, bigint, text, uuid, integer) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_wallet_settle_once (
  p_workspace_id   uuid,
  p_reservation_id text,
  p_actual_nanos   bigint,
  p_settle_ref_id  text   DEFAULT NULL::text
)
  RETURNS TABLE (
    ok                    boolean,
    applied               boolean,
    reason                text,
    amount_nanos          bigint,
    before_balance_nanos  bigint,
    after_balance_nanos   bigint,
    before_reserved_nanos bigint,
    after_reserved_nanos  bigint
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_wallet public.wallets%rowtype;
  v_reservation public.gateway_wallet_reservations%rowtype;
  v_before_balance bigint;
  v_before_reserved bigint;
  v_available_for_settlement bigint;
begin
  if p_workspace_id is null or coalesce(trim(p_reservation_id), '') = '' then
    raise exception 'invalid_batch_reservation_identity';
  end if;
  if p_actual_nanos is null or p_actual_nanos < 0 then
    raise exception 'invalid_actual_nanos';
  end if;

  select * into v_reservation
  from public.gateway_wallet_reservations
  where workspace_id = p_workspace_id and reservation_id = p_reservation_id
  for update;
  if not found then
    return query select false, false, 'reservation_not_found'::text, p_actual_nanos,
      null::bigint, null::bigint, null::bigint, null::bigint;
    return;
  end if;

  select * into v_wallet from public.wallets
  where workspace_id = p_workspace_id for update;
  if not found then
    return query select false, false, 'wallet_not_found'::text, p_actual_nanos,
      null::bigint, null::bigint, null::bigint, null::bigint;
    return;
  end if;

  if v_reservation.status = 'captured' then
    if p_reservation_id not like 'video_hold:%' and coalesce(v_reservation.settled_amount_nanos, v_reservation.amount_nanos) <> p_actual_nanos then
      raise exception 'reservation_settlement_amount_mismatch';
    end if;
    return query select true, false, 'already_captured'::text, coalesce(v_reservation.settled_amount_nanos, v_reservation.amount_nanos),
      coalesce(v_wallet.balance_nanos, 0), coalesce(v_wallet.balance_nanos, 0),
      coalesce(v_wallet.reserved_nanos, 0), coalesce(v_wallet.reserved_nanos, 0);
    return;
  end if;

  if v_reservation.status not in ('held', 'reserved') then
    return query select false, false, 'reservation_not_active'::text, p_actual_nanos,
      coalesce(v_wallet.balance_nanos, 0), coalesce(v_wallet.balance_nanos, 0),
      coalesce(v_wallet.reserved_nanos, 0), coalesce(v_wallet.reserved_nanos, 0);
    return;
  end if;
  if coalesce(v_wallet.reserved_nanos, 0) < v_reservation.amount_nanos then
    return query select false, false, 'reserved_balance_mismatch'::text, p_actual_nanos,
      coalesce(v_wallet.balance_nanos, 0), coalesce(v_wallet.balance_nanos, 0),
      coalesce(v_wallet.reserved_nanos, 0), coalesce(v_wallet.reserved_nanos, 0);
    return;
  end if;

  -- The reservation itself is available to this settlement; all other holds
  -- remain excluded from spendable balance.
  v_available_for_settlement := coalesce(v_wallet.balance_nanos, 0)
    - coalesce(v_wallet.reserved_nanos, 0)
    + v_reservation.amount_nanos;
  if p_actual_nanos > v_available_for_settlement then
    return query select false, false, 'insufficient_balance'::text, p_actual_nanos,
      coalesce(v_wallet.balance_nanos, 0), coalesce(v_wallet.balance_nanos, 0),
      coalesce(v_wallet.reserved_nanos, 0), coalesce(v_wallet.reserved_nanos, 0);
    return;
  end if;

  v_before_balance := coalesce(v_wallet.balance_nanos, 0);
  v_before_reserved := coalesce(v_wallet.reserved_nanos, 0);
  update public.wallets
  set balance_nanos = v_before_balance - p_actual_nanos,
      reserved_nanos = v_before_reserved - v_reservation.amount_nanos,
      updated_at = now()
  where workspace_id = p_workspace_id
  returning * into v_wallet;

  update public.gateway_wallet_reservations
  set status = 'captured',
      settled_amount_nanos = p_actual_nanos,
      captured_nanos = least(p_actual_nanos, v_reservation.amount_nanos),
      released_nanos = greatest(0, v_reservation.amount_nanos - p_actual_nanos),
      capture_ref_id = nullif(trim(coalesce(p_settle_ref_id, '')), ''),
      captured_at = now(),
      updated_at = now()
  where workspace_id = p_workspace_id and reservation_id = p_reservation_id;

  if p_actual_nanos > 0 then
    insert into public.credit_ledger (
      workspace_id, kind, amount_nanos, before_balance_nanos, after_balance_nanos,
      before_reserved_nanos, after_reserved_nanos, ref_type, ref_id, source_ref_type, source_ref_id, status
    ) values (
      p_workspace_id, 'charge', -p_actual_nanos, v_before_balance, v_wallet.balance_nanos,
      v_before_reserved, v_wallet.reserved_nanos,
      'async_job_charge', p_workspace_id::text || ':' || p_reservation_id,
      'async_job', coalesce(nullif(trim(p_settle_ref_id), ''), p_reservation_id), 'captured'
    );
  end if;

  return query select true, true, null::text, p_actual_nanos,
    v_before_balance, coalesce(v_wallet.balance_nanos, 0),
    v_before_reserved, coalesce(v_wallet.reserved_nanos, 0);
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_wallet_settle_once"(uuid, text, bigint, text) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_workspace_budget_status (
  p_workspace_id           uuid,
  p_requested_amount_nanos bigint DEFAULT 0
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_now timestamptz := now();
  v_result jsonb;
  v_exceeded jsonb;
begin
  if p_workspace_id is null then
    raise exception 'workspace_id_required';
  end if;
  if coalesce(p_requested_amount_nanos, 0) < 0 then
    raise exception 'requested_amount_must_be_non_negative';
  end if;

  with configured as (
    select
      budget.id,
      budget.workspace_id,
      budget.interval,
      budget.limit_nanos,
      budget.created_by,
      budget.created_at,
      budget.updated_at,
      case budget.interval
        when 'daily' then date_trunc('day', v_now at time zone 'utc') at time zone 'utc'
        when 'weekly' then date_trunc('week', v_now at time zone 'utc') at time zone 'utc'
        when 'monthly' then date_trunc('month', v_now at time zone 'utc') at time zone 'utc'
        else null
      end as window_start,
      case budget.interval
        when 'daily' then (date_trunc('day', v_now at time zone 'utc') + interval '1 day') at time zone 'utc'
        when 'weekly' then (date_trunc('week', v_now at time zone 'utc') + interval '1 week') at time zone 'utc'
        when 'monthly' then (date_trunc('month', v_now at time zone 'utc') + interval '1 month') at time zone 'utc'
        else null
      end as reset_at
    from public.workspace_budgets budget
    where budget.workspace_id = p_workspace_id
  ), request_usage as (
    select
      configured.id,
      coalesce(sum(request.cost_nanos) filter (
        where request.success is true
          and (configured.window_start is null or request.created_at >= configured.window_start)
      ), 0)::bigint as completed_nanos
    from configured
    left join public.gateway_requests request
      on request.workspace_id = configured.workspace_id
    group by configured.id
  ), reservation_usage as (
    select
      configured.id,
      coalesce(sum(case
        when reservation.reservation_id like 'free_model_hold:%' then
          case when reservation.status in ('held', 'reserved') or
            (reservation.status = 'captured' and (configured.window_start is null or reservation.created_at >= configured.window_start))
          then greatest(0, (case when reservation.status = 'captured'
            then coalesce(reservation.settled_amount_nanos, reservation.amount_nanos)
            else reservation.amount_nanos end) - coalesce(free_audit.cost, 0))
          else 0 end
        when reservation.status = 'reserved' and
          (configured.window_start is null or reservation.created_at >= configured.window_start)
        then greatest(0, reservation.amount_nanos - coalesce(reservation.captured_nanos, 0) - coalesce(reservation.released_nanos, 0))
        else 0 end), 0)::bigint as held_nanos
    from configured
    left join public.gateway_wallet_reservations reservation
      on reservation.workspace_id = configured.workspace_id
    left join lateral (
      select sum(request.cost_nanos) as cost from public.gateway_requests request
      where reservation.reservation_id like 'free_model_hold:%'
        and request.workspace_id = reservation.workspace_id
        and request.key_id = reservation.key_id
        and request.request_id = reservation.hold_ref_id
        and request.detail_metadata->>'free_model_fee_request_id' = substr(reservation.reservation_id, 17) and request.success is true
    ) free_audit on true
    group by configured.id
  ), usage_rows as (
    select
      configured.*,
      request_usage.completed_nanos + reservation_usage.held_nanos as usage_nanos
    from configured
    join request_usage using (id)
    join reservation_usage using (id)
  ), normalized as (
    select *,
      usage_nanos + coalesce(p_requested_amount_nanos, 0) as projected_usage_nanos,
      greatest(limit_nanos - usage_nanos, 0) as remaining_nanos,
      case
        when coalesce(p_requested_amount_nanos, 0) > 0
          then usage_nanos + p_requested_amount_nanos > limit_nanos
        else usage_nanos >= limit_nanos
      end as exceeded
    from usage_rows
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', id,
    'workspace_id', workspace_id,
    'interval', interval,
    'limit_nanos', limit_nanos,
    'usage_nanos', usage_nanos,
    'remaining_nanos', remaining_nanos,
    'projected_usage_nanos', projected_usage_nanos,
    'exceeded', exceeded,
    'window_start', window_start,
    'reset_at', reset_at,
    'created_by', created_by,
    'created_at', created_at,
    'updated_at', updated_at
  ) order by case interval when 'daily' then 1 when 'weekly' then 2 when 'monthly' then 3 else 4 end), '[]'::jsonb)
  into v_result
  from normalized;

  select budget
  into v_exceeded
  from jsonb_array_elements(v_result) budget
  where (budget->>'exceeded')::boolean
  order by case budget->>'interval' when 'daily' then 1 when 'weekly' then 2 when 'monthly' then 3 else 4 end
  limit 1;

  if v_exceeded is not null then
    return jsonb_build_object(
      'ok', false,
      'reason', 'workspace_' || (v_exceeded->>'interval') || '_cost_budget_reached',
      'limit_window', v_exceeded->>'interval',
      'limit_metric', 'cost',
      'current_value', (v_exceeded->>'usage_nanos')::bigint,
      'limit_value', (v_exceeded->>'limit_nanos')::bigint,
      'reset_at', v_exceeded->'reset_at',
      'now', to_jsonb(v_now),
      'budgets', v_result
    );
  end if;

  return jsonb_build_object('ok', true, 'reason', null, 'now', to_jsonb(v_now), 'budgets', v_result);
end;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_workspace_budget_status"(uuid, bigint) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.gateway_workspace_key_usage (
  p_workspace_id uuid,
  p_key_ids      uuid[] DEFAULT NULL::uuid[]
)
  RETURNS TABLE (
    key_id                uuid,
    total_request_count   bigint,
    daily_request_count   bigint,
    weekly_request_count  bigint,
    monthly_request_count bigint,
    total_cost_nanos      bigint,
    daily_cost_nanos      bigint,
    weekly_cost_nanos     bigint,
    monthly_cost_nanos    bigint,
    last_used_at          timestamp with time zone
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  with bounds as (
    select
      date_trunc('day', now() at time zone 'utc') at time zone 'utc' as day_start,
      date_trunc('week', now() at time zone 'utc') at time zone 'utc' as week_start,
      date_trunc('month', now() at time zone 'utc') at time zone 'utc' as month_start
  )
  select
    request.key_id,
    count(*)::bigint,
    count(*) filter (where request.created_at >= bounds.day_start)::bigint,
    count(*) filter (where request.created_at >= bounds.week_start)::bigint,
    count(*) filter (where request.created_at >= bounds.month_start)::bigint,
    coalesce(sum(request.cost_nanos), 0)::bigint,
    coalesce(sum(request.cost_nanos) filter (where request.created_at >= bounds.day_start), 0)::bigint,
    coalesce(sum(request.cost_nanos) filter (where request.created_at >= bounds.week_start), 0)::bigint,
    coalesce(sum(request.cost_nanos) filter (where request.created_at >= bounds.month_start), 0)::bigint,
    max(request.created_at)
  from public.gateway_requests request
  cross join bounds
  where request.workspace_id = p_workspace_id
    and request.key_id is not null
    and request.success is true
    and (p_key_ids is null or request.key_id = any(p_key_ids))
  group by request.key_id;
$function$;

REVOKE ALL ON FUNCTION "public"."gateway_workspace_key_usage"(uuid, uuid[]) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.get_app_rising_model (
  p_app_id        uuid,
  p_recent_days   integer DEFAULT 7,
  p_previous_days integer DEFAULT 7
)
  RETURNS TABLE (
    model_id        text,
    provider        text,
    recent_tokens   bigint,
    previous_tokens bigint,
    delta_tokens    bigint
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  with recent as (
    select
      coalesce(gr.model_id, 'Unknown model') as model_id,
      gr.provider as provider,
      sum(coalesce((gr.usage->>'total_tokens')::bigint, 0))::bigint as tokens
    from private.v2_rpc_gateway_requests_compat gr
    where gr.app_id = p_app_id
      and gr.success = true
      and gr.created_at >= now() - (p_recent_days::text || ' days')::interval
    group by 1, 2
  ),
  previous as (
    select
      coalesce(gr.model_id, 'Unknown model') as model_id,
      gr.provider as provider,
      sum(coalesce((gr.usage->>'total_tokens')::bigint, 0))::bigint as tokens
    from private.v2_rpc_gateway_requests_compat gr
    where gr.app_id = p_app_id
      and gr.success = true
      and gr.created_at >= now() - ((p_recent_days + p_previous_days)::text || ' days')::interval
      and gr.created_at < now() - (p_recent_days::text || ' days')::interval
    group by 1, 2
  ),
  combined as (
    select
      r.model_id,
      r.provider,
      r.tokens as recent_tokens,
      coalesce(p.tokens, 0)::bigint as previous_tokens,
      (r.tokens - coalesce(p.tokens, 0))::bigint as delta_tokens
    from recent r
    left join previous p
      on p.model_id = r.model_id
      and (
        (p.provider is null and r.provider is null)
        or p.provider = r.provider
      )
  )
  select
    model_id,
    provider,
    recent_tokens,
    previous_tokens,
    delta_tokens
  from combined
  order by delta_tokens desc
  limit 1;
$function$;

CREATE OR REPLACE FUNCTION public.get_app_top_model_all_time (
  p_app_id uuid
)
  RETURNS TABLE (
