CREATE OR REPLACE FUNCTION public.get_benchmark_result_rankings (
  p_benchmark_ids       text[]  DEFAULT NULL::text[],
  p_model_id            text    DEFAULT NULL::text,
  p_include_hidden      boolean DEFAULT false,
  p_limit_per_benchmark integer DEFAULT NULL::integer
)
  RETURNS TABLE (
    result_id           uuid,
    model_id            text,
    benchmark_id        text,
    score               text,
    score_numeric       numeric,
    is_self_reported    boolean,
    other_info          text,
    source_link         text,
    created_at          timestamp with time zone,
    updated_at          timestamp with time zone,
    occur_idx           integer,
    variant             text,
    result_key          text,
    benchmark_rank      bigint,
    total_ranked_models bigint,
    is_primary_result   boolean,
    model_name          text,
    release_date        timestamp with time zone,
    announcement_date   timestamp with time zone,
    organisation_id     text,
    organisation_name   text,
    organisation_colour text
  )
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  with target_benchmarks as (
    select
      b.id,
      b.ascending_order,
      b.type
    from private.v2_rpc_benchmarks_compat b
    where
      (p_benchmark_ids is null or b.id = any (p_benchmark_ids))
      and (
        p_model_id is null
        or exists (
          select 1
          from private.v2_rpc_benchmark_results_compat requested_result
          where requested_result.benchmark_id = b.id
            and requested_result.model_id = p_model_id
        )
      )
  ),
  scoped_results as (
    select
      result.*,
      model.name as model_name,
      model.release_date,
      model.announcement_date,
      model.organisation_id,
      organisation.name as organisation_name,
      organisation.colour as organisation_colour,
      target.ascending_order,
      case
        when target.type = 'percentage'
          and abs(result.score_numeric) > 0
          and abs(result.score_numeric) <= 1
          then result.score_numeric * 100
        else result.score_numeric
      end as comparable_score
    from target_benchmarks target
    join private.v2_rpc_benchmark_results_compat result
      on result.benchmark_id = target.id
    join private.v2_rpc_models_compat model
      on model.model_id = result.model_id
    left join private.v2_rpc_labs_compat organisation
      on organisation.organisation_id = model.organisation_id
    where p_include_hidden or not coalesce(model.hidden, false)
  ),
  model_scores as (
    select
      scoped.benchmark_id,
      scoped.model_id,
      bool_or(scoped.ascending_order is false) as lower_is_better,
      case
        when bool_or(scoped.ascending_order is false)
          then min(scoped.comparable_score)
        else max(scoped.comparable_score)
      end as primary_score
    from scoped_results scoped
    where scoped.comparable_score is not null
    group by scoped.benchmark_id, scoped.model_id
  ),
  ranked_models as (
    select
      scores.benchmark_id,
      scores.model_id,
      scores.primary_score,
      rank() over (
        partition by scores.benchmark_id
        order by
          case when scores.lower_is_better then scores.primary_score end asc nulls last,
          case when not scores.lower_is_better then scores.primary_score end desc nulls last
      ) as benchmark_rank,
      count(*) over (
        partition by scores.benchmark_id
      ) as total_ranked_models
    from model_scores scores
  ),
  selected_models as (
    select
      roster.benchmark_id,
      roster.model_id,
      ranked.primary_score,
      ranked.benchmark_rank,
      ranked.total_ranked_models
    from (
      select distinct scoped.benchmark_id, scoped.model_id
      from scoped_results scoped
    ) roster
    left join ranked_models ranked
      on ranked.benchmark_id = roster.benchmark_id
     and ranked.model_id = roster.model_id
    where
      (p_model_id is null or roster.model_id = p_model_id)
      and (
        p_limit_per_benchmark is null
        or ranked.benchmark_rank <= greatest(p_limit_per_benchmark, 1)
      )
  )
  select
    scoped.id as result_id,
    scoped.model_id,
    scoped.benchmark_id,
    scoped.score,
    scoped.score_numeric,
    scoped.is_self_reported,
    scoped.other_info,
    scoped.source_link,
    scoped.created_at,
    scoped.updated_at,
    scoped.occur_idx,
    scoped.variant,
    scoped.result_key,
    ranked.benchmark_rank,
    ranked.total_ranked_models,
    ranked.primary_score is not null
      and scoped.comparable_score is not distinct from ranked.primary_score
      as is_primary_result,
    scoped.model_name,
    scoped.release_date,
    scoped.announcement_date,
    scoped.organisation_id,
    scoped.organisation_name,
    scoped.organisation_colour
  from scoped_results scoped
  join selected_models ranked
    on ranked.benchmark_id = scoped.benchmark_id
   and ranked.model_id = scoped.model_id
  order by
    scoped.benchmark_id,
    ranked.benchmark_rank,
    scoped.model_id,
    scoped.occur_idx,
    scoped.id;
$function$;

REVOKE ALL ON FUNCTION "public"."get_benchmark_result_rankings"(text[], text, boolean, integer) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.get_data_contribution_totals (
  p_workspace_id uuid,
  p_since        timestamp with time zone
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'contributions', count(*),
    'discount_nanos', coalesce(sum(contribution.discount_nanos), 0)
  )
  from public.data_contributions contribution
  where contribution.workspace_id = p_workspace_id
    and contribution.created_at >= p_since;
$function$;

REVOKE ALL ON FUNCTION "public"."get_data_contribution_totals"(uuid, timestamp WITH time zone) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.get_free_router_usage_summary (
  p_model_slugs text[],
  p_since       timestamp with time zone
)
  RETURNS TABLE (
    model_slug       text,
    requests_30d     bigint,
    total_cost_nanos numeric,
    last_routed_at   timestamp with time zone
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public'
  AS $function$
  with matching_usage as materialized (
    select fact.request_event_id, fact.routed_model_slug, fact.occurred_at
    from public.v2_request_facts as fact
    where fact.requested_model_input = 'phaseo/free'
      and fact.routed_model_slug = any (p_model_slugs)
      and fact.occurred_at >= p_since
  ), pricing_by_request as (
    select pricing_line.request_event_id,
      sum(pricing_line.charged_nanos) as total_cost_nanos
    from public.v2_request_pricing_lines as pricing_line
    join matching_usage as usage_row using (request_event_id)
    group by pricing_line.request_event_id
  )
  select usage_row.routed_model_slug as model_slug,
    count(*)::bigint as requests_30d,
    coalesce(sum(pricing.total_cost_nanos), 0)::numeric as total_cost_nanos,
    max(usage_row.occurred_at) as last_routed_at
  from matching_usage as usage_row
  left join pricing_by_request as pricing using (request_event_id)
  group by usage_row.routed_model_slug;
$function$;

REVOKE ALL ON FUNCTION "public"."get_free_router_usage_summary"(text[], timestamp WITH time zone) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.get_gateway_jobs_rollup (
  p_team       uuid,
  p_limit      integer DEFAULT 100,
  p_offset     integer DEFAULT 0,
  p_kind       text    DEFAULT NULL::text,
  p_status     text    DEFAULT NULL::text,
  p_session_id text    DEFAULT NULL::text,
  p_provider   text    DEFAULT NULL::text
)
  RETURNS TABLE (
    job_id             uuid,
    kind               text,
    internal_id        text,
    request_id         text,
    session_id         text,
    app_id             uuid,
    provider           text,
    model              text,
    status             text,
    billed_at          timestamp with time zone,
    created_at         timestamp with time zone,
    updated_at         timestamp with time zone,
    request_created_at timestamp with time zone,
    request_endpoint   text,
    request_model_id   text,
    request_cost_nanos bigint,
    request_cost_usd   numeric
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  with filtered_ops as (
    select op.*
    from public.gateway_async_operations op
    where op.workspace_id = p_team
      and (p_kind is null or op.kind = p_kind)
      and (p_status is null or op.status = p_status)
      and (p_session_id is null or op.session_id = p_session_id)
      and (p_provider is null or op.provider = p_provider)
  ),
  request_lookup as (
    select
      gr.workspace_id,
      gr.request_id,
      gr.created_at,
      gr.endpoint,
      gr.model_id,
      gr.cost_nanos,
      row_number() over (
        partition by gr.workspace_id, gr.request_id
        order by gr.created_at desc
      ) as rn
    from private.v2_rpc_gateway_requests_compat gr
    where gr.workspace_id = p_team
  )
  select
    op.id as job_id,
    op.kind,
    op.internal_id,
    op.request_id,
    op.session_id,
    op.app_id,
    op.provider,
    op.model,
    op.status,
    op.billed_at,
    op.created_at,
    op.updated_at,
    req.created_at as request_created_at,
    req.endpoint as request_endpoint,
    req.model_id as request_model_id,
    req.cost_nanos as request_cost_nanos,
    coalesce(req.cost_nanos, 0)::numeric / 1e9 as request_cost_usd
  from filtered_ops op
  left join request_lookup req
    on req.workspace_id = op.workspace_id
   and req.request_id = op.request_id
   and req.rn = 1
  order by op.updated_at desc
  limit greatest(1, least(coalesce(p_limit, 100), 500))
  offset greatest(0, coalesce(p_offset, 0));
$function$;

CREATE OR REPLACE FUNCTION public.get_gateway_marketing_rollup (
  p_hours integer DEFAULT 24
)
  RETURNS TABLE (
    bucket_hour      timestamp with time zone,
    requests         bigint,
    success_requests bigint,
    total_tokens     bigint,
    latency_sum_ms   numeric,
    latency_samples  bigint
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  select
    date_trunc('hour', r.bucket_15m) as bucket_hour,
    sum(r.requests)::bigint as requests,
    sum(r.success_requests)::bigint as success_requests,
    sum(r.total_tokens)::bigint as total_tokens,
    sum(r.latency_sum_ms)::numeric as latency_sum_ms,
    sum(r.latency_samples)::bigint as latency_samples
  from public.v2_web_public_usage_hourly r
  where r.bucket_15m >= now() - make_interval(hours => greatest(1, p_hours))
  group by date_trunc('hour', r.bucket_15m)
  order by date_trunc('hour', r.bucket_15m);
$function$;

CREATE OR REPLACE FUNCTION public.get_gateway_request_facets (
  p_workspace_id uuid,
  p_from         timestamp with time zone,
  p_to           timestamp with time zone
)
  RETURNS TABLE (
    facet         text,
    value         text,
    value_label   text,
    request_count bigint
  )
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  with scoped as materialized (
    select
      gr.model_id,
      gr.provider,
      gr.app_id::text as app_id,
	  gr.key_id::text as key_id,
      gr.endpoint,
	  case when gr.stream then 'streaming' else 'non_streaming' end as stream_mode,
      gr.finish_reason,
      gr.error_code,
      gr.status_code::text as status_code,
      case when gr.success then 'success' else 'error' end as request_status,
      gr.client_source_id,
      gr.client_source_name
    from public.gateway_requests gr
    where gr.workspace_id = p_workspace_id
      and gr.created_at >= p_from
      and gr.created_at <= p_to
      and gr.endpoint not in ('video.generation', 'batch', 'music.generate')
  )
  select 'model', model_id, null::text, count(*) from scoped where model_id is not null group by model_id
  union all
  select 'provider', provider, null::text, count(*) from scoped where provider is not null group by provider
  union all
  select 'app', app_id, null::text, count(*) from scoped where app_id is not null group by app_id
  union all
	select 'key', key_id, null::text, count(*) from scoped where key_id is not null group by key_id
	union all
  select 'endpoint', endpoint, null::text, count(*) from scoped where endpoint is not null group by endpoint
  union all
	select 'stream', stream_mode, null::text, count(*) from scoped group by stream_mode
	union all
  select 'finish_reason', finish_reason, null::text, count(*) from scoped where finish_reason is not null group by finish_reason
  union all
  select 'error_code', error_code, null::text, count(*) from scoped where error_code is not null group by error_code
  union all
  select 'http_status', status_code, null::text, count(*) from scoped where status_code is not null group by status_code
  union all
  select 'status', request_status, null::text, count(*) from scoped group by request_status
  union all
  select 'source', client_source_id, max(client_source_name), count(*) from scoped where client_source_id is not null group by client_source_id;
$function$;

CREATE OR REPLACE FUNCTION public.get_gateway_request_facets (
  p_workspace_id uuid,
  p_from         timestamp with time zone,
  p_to           timestamp with time zone,
  p_filters      jsonb
)
  RETURNS TABLE (
    facet         text,
    value         text,
    value_label   text,
    request_count bigint
  )
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  with scoped as materialized (
    select
      gr.model_id,
      gr.provider,
      gr.app_id::text as app_id,
      gr.key_id::text as key_id,
      gr.endpoint,
      case when gr.stream then 'streaming' else 'non_streaming' end as stream_mode,
      gr.finish_reason,
      gr.error_code,
      gr.status_code::text as status_code,
      case when gr.success then 'success' else 'error' end as request_status,
      gr.client_source_id,
      gr.client_source_name
    from public.gateway_requests gr
    where gr.workspace_id = p_workspace_id
      and gr.created_at >= p_from
      and gr.created_at <= p_to
      and gr.endpoint not in ('video.generation', 'batch', 'music.generate')
      and (not (p_filters ? 'model') or case when p_filters->>'model_op' = 'is_not' then gr.model_id is distinct from p_filters->>'model' else gr.model_id = p_filters->>'model' end)
      and (not (p_filters ? 'provider') or case when p_filters->>'provider_op' = 'is_not' then gr.provider is distinct from p_filters->>'provider' else gr.provider = p_filters->>'provider' end)
      and (not (p_filters ? 'app') or case when p_filters->>'app_op' = 'is_not' then gr.app_id::text is distinct from p_filters->>'app' else gr.app_id::text = p_filters->>'app' end)
      and (not (p_filters ? 'key') or case when p_filters->>'key_op' = 'is_not' then gr.key_id::text is distinct from p_filters->>'key' else gr.key_id::text = p_filters->>'key' end)
      and (not (p_filters ? 'endpoint') or case when p_filters->>'endpoint_op' = 'is_not' then gr.endpoint is distinct from p_filters->>'endpoint' else gr.endpoint = p_filters->>'endpoint' end)
      and (not (p_filters ? 'finish_reason') or case when p_filters->>'finish_op' = 'is_not' then gr.finish_reason is distinct from p_filters->>'finish_reason' else gr.finish_reason = p_filters->>'finish_reason' end)
      and (not (p_filters ? 'error_code') or case when p_filters->>'error_op' = 'is_not' then gr.error_code is distinct from p_filters->>'error_code' else gr.error_code = p_filters->>'error_code' end)
      and (not (p_filters ? 'http_status') or case when p_filters->>'http_op' = 'is_not' then gr.status_code is distinct from (p_filters->>'http_status')::integer else gr.status_code = (p_filters->>'http_status')::integer end)
      and (not (p_filters ? 'source') or case when p_filters->>'source_op' = 'is_not' then gr.client_source_id is distinct from p_filters->>'source' else gr.client_source_id = p_filters->>'source' end)
      and (not (p_filters ? 'stream') or case when p_filters->>'stream_op' = 'is_not' then gr.stream is distinct from ((p_filters->>'stream') = 'streaming') else gr.stream = ((p_filters->>'stream') = 'streaming') end)
      and (not (p_filters ? 'status') or case when p_filters->>'status_op' = 'is_not' then gr.success is distinct from ((p_filters->>'status') = 'success') else gr.success = ((p_filters->>'status') = 'success') end)
      and (not (p_filters ? 'input_tokens') or case p_filters->>'input_tokens_op' when 'eq' then gr.usage_input_tokens = (p_filters->>'input_tokens')::bigint when 'lte' then gr.usage_input_tokens <= (p_filters->>'input_tokens')::bigint when 'between' then gr.usage_input_tokens between (p_filters->>'input_tokens')::bigint and (p_filters->>'input_tokens_max')::bigint else gr.usage_input_tokens >= (p_filters->>'input_tokens')::bigint end)
      and (not (p_filters ? 'output_tokens') or case p_filters->>'output_tokens_op' when 'eq' then gr.usage_output_tokens = (p_filters->>'output_tokens')::bigint when 'lte' then gr.usage_output_tokens <= (p_filters->>'output_tokens')::bigint when 'between' then gr.usage_output_tokens between (p_filters->>'output_tokens')::bigint and (p_filters->>'output_tokens_max')::bigint else gr.usage_output_tokens >= (p_filters->>'output_tokens')::bigint end)
      and (not (p_filters ? 'total_tokens') or case p_filters->>'total_tokens_op' when 'eq' then gr.usage_total_tokens = (p_filters->>'total_tokens')::bigint when 'lte' then gr.usage_total_tokens <= (p_filters->>'total_tokens')::bigint when 'between' then gr.usage_total_tokens between (p_filters->>'total_tokens')::bigint and (p_filters->>'total_tokens_max')::bigint else gr.usage_total_tokens >= (p_filters->>'total_tokens')::bigint end)
  )
  select 'model', model_id, null::text, count(*) from scoped where model_id is not null group by model_id
  union all select 'provider', provider, null::text, count(*) from scoped where provider is not null group by provider
  union all select 'app', app_id, null::text, count(*) from scoped where app_id is not null group by app_id
  union all select 'key', key_id, null::text, count(*) from scoped where key_id is not null group by key_id
  union all select 'endpoint', endpoint, null::text, count(*) from scoped where endpoint is not null group by endpoint
  union all select 'stream', stream_mode, null::text, count(*) from scoped group by stream_mode
  union all select 'finish_reason', finish_reason, null::text, count(*) from scoped where finish_reason is not null group by finish_reason
  union all select 'error_code', error_code, null::text, count(*) from scoped where error_code is not null group by error_code
  union all select 'http_status', status_code, null::text, count(*) from scoped where status_code is not null group by status_code
  union all select 'status', request_status, null::text, count(*) from scoped group by request_status
  union all select 'source', client_source_id, max(client_source_name), count(*) from scoped where client_source_id is not null group by client_source_id;
$function$;

CREATE OR REPLACE FUNCTION public.get_gateway_request_observability (
  p_workspace_id uuid,
  p_request_id   text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'request', to_jsonb(gateway_request),
    'fact', case when fact.request_event_id is null then null else to_jsonb(fact) end,
    'routing_trace', case when trace.request_event_id is null then null else to_jsonb(trace) end,
    'attempts', coalesce((select jsonb_agg(to_jsonb(attempt) order by attempt.attempt_number) from public.v2_request_attempts attempt where attempt.request_event_id = fact.request_event_id), '[]'::jsonb),
    'routing_decisions', coalesce((select jsonb_agg(to_jsonb(routing_decision) order by routing_decision.decision_order) from public.v2_request_routing_decisions routing_decision where routing_decision.request_event_id = fact.request_event_id), '[]'::jsonb),
    'usage_meters', coalesce((select jsonb_agg(to_jsonb(usage) order by usage.sequence, usage.meter_key) from public.v2_request_usage usage where usage.request_event_id = fact.request_event_id), '[]'::jsonb),
    'pricing_lines', coalesce((select jsonb_agg(to_jsonb(line) order by line.created_at, line.pricing_line_id) from public.v2_request_pricing_lines line where line.request_event_id = fact.request_event_id), '[]'::jsonb),
    'artifacts', coalesce((select jsonb_agg(to_jsonb(artifact) order by artifact.created_at, artifact.artifact_id) from public.v2_request_artifacts artifact where artifact.request_event_id = fact.request_event_id), '[]'::jsonb),
    'feedback', coalesce((select jsonb_agg(to_jsonb(feedback) order by feedback.created_at, feedback.feedback_id) from public.v2_request_feedback feedback where feedback.request_event_id = fact.request_event_id), '[]'::jsonb)
  )
  from public.gateway_requests gateway_request
  left join public.v2_request_facts fact
    on fact.gateway_request_id = gateway_request.id
   and fact.gateway_request_created_at = gateway_request.created_at
  left join public.v2_request_routing_traces trace
    on trace.request_event_id = fact.request_event_id
  where gateway_request.workspace_id = p_workspace_id
    and gateway_request.request_id = p_request_id
  order by gateway_request.created_at desc
  limit 1;
$function$;

REVOKE ALL ON FUNCTION "public"."get_gateway_request_observability"(uuid, text) FROM PUBLIC, "anon";

CREATE OR REPLACE FUNCTION public.get_gateway_sessions_rollup (
  p_team     uuid,
  p_from     timestamp with time zone,
  p_to       timestamp with time zone,
  p_limit    integer                  DEFAULT 100,
  p_offset   integer                  DEFAULT 0,
  p_app_id   uuid                     DEFAULT NULL::uuid,
  p_model_id text                     DEFAULT NULL::text,
  p_provider text                     DEFAULT NULL::text
)
  RETURNS TABLE (
    session_id       text,
    request_count    bigint,
    total_cost_nanos numeric,
    total_cost_usd   numeric,
    first_request_at timestamp with time zone,
    last_request_at  timestamp with time zone,
    app_ids          uuid[],
    model_ids        text[],
    provider_ids     text[],
    end_user_ids     text[]
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  with filtered as (
    select gr.*
    from private.v2_rpc_gateway_requests_compat gr
    where gr.workspace_id = p_team
      and gr.created_at >= p_from
      and gr.created_at <= p_to
      and gr.session_id is not null
      and length(trim(gr.session_id)) > 0
      and (p_app_id is null or gr.app_id = p_app_id)
      and (p_model_id is null or gr.model_id = p_model_id)
      and (p_provider is null or gr.provider = p_provider)
  ),
  grouped as (
    select
      gr.session_id,
      count(*)::bigint as request_count,
      coalesce(sum(gr.cost_nanos::numeric), 0) as total_cost_nanos,
      min(gr.created_at) as first_request_at,
      max(gr.created_at) as last_request_at,
      array_remove(array_agg(distinct gr.app_id), null) as app_ids,
      array_remove(array_agg(distinct gr.model_id), null) as model_ids,
      array_remove(array_agg(distinct gr.provider), null) as provider_ids,
      array_remove(array_agg(distinct gr.end_user_id), null) as end_user_ids
    from filtered gr
    group by gr.session_id
  )
  select
    g.session_id,
    g.request_count,
    g.total_cost_nanos,
    g.total_cost_nanos / 1e9 as total_cost_usd,
    g.first_request_at,
    g.last_request_at,
    g.app_ids,
    g.model_ids,
    g.provider_ids,
    g.end_user_ids
  from grouped g
  order by g.last_request_at desc
  limit greatest(1, least(coalesce(p_limit, 100), 500))
  offset greatest(0, coalesce(p_offset, 0));
$function$;

CREATE OR REPLACE FUNCTION public.get_latest_provider_onboarding_review_page (
  p_before_created_at timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  p_before_id         uuid                     DEFAULT NULL::uuid,
  p_limit             integer                  DEFAULT 101
)
  RETURNS TABLE (
    id                     uuid,
    provider_slug          text,
    submitted_by           uuid,
    provider_name          text,
    website_url            text,
    catalog_url            text,
    catalog_mode           text,
    application_type       text,
    model_count            integer,
    validation_summary     jsonb,
    submitted_at           timestamp with time zone,
    created_at             timestamp with time zone,
    provider_review_status text,
    provider_review_reason text
  )
  LANGUAGE sql
  SET search_path TO 'pg_catalog', 'public'
  AS $function$
  with latest_submissions as (
    select distinct on (submission.provider_slug)
      submission.id,
      submission.provider_slug,
      submission.submitted_by,
      submission.provider_name,
      submission.website_url,
      submission.catalog_url,
      submission.catalog_mode,
      submission.application_type,
      submission.model_count,
      submission.validation_summary,
      submission.submitted_at,
      submission.created_at,
      submission.provider_review_status,
      submission.provider_review_reason
    from public.provider_onboarding_submissions submission
    order by submission.provider_slug, submission.created_at desc, submission.id desc
  )
  select latest.*
  from latest_submissions latest
  where (
      p_before_created_at is null and p_before_id is null
    ) or (
      p_before_created_at is not null and p_before_id is not null
      and (latest.created_at, latest.id) < (p_before_created_at, p_before_id)
    )
  order by latest.created_at desc, latest.id desc
  limit least(greatest(coalesce(p_limit, 101), 1), 101)
$function$;

REVOKE ALL ON FUNCTION "public"."get_latest_provider_onboarding_review_page"(timestamp WITH time zone, uuid, integer) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.get_model_gateway_overview (
  p_model_id text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
with
-- 1) Build the set of gateway model_id values we consider "this model"
model_ids as (
  select p_model_id as model_id
  union
  select pm.provider_id || '/' || pm.api_model_id
  from private.v2_rpc_routes_compat pm
  where pm.internal_model_id = p_model_id
),

-- 2) Anchor times in UTC as timestamptz (safe to compare with created_at timestamptz)
anchors as (
  select
    (date_trunc('hour', now() at time zone 'utc') at time zone 'utc') as now_hour,
    (select release_date
     from private.v2_rpc_models_compat
     where model_id = p_model_id
     limit 1) as release_date
),
windows as (
  select
    now_hour,
    now_hour - interval '24 hours'  as last24_start,
    now_hour - interval '48 hours'  as prev24_start,
    now_hour - interval '120 hours' as last5d_start
  from anchors
),

-- 3) Requests for the last 5d (used by 5d + 24h calcs)
requests_5d as (
  select
    gr.created_at,
    gr.success as success_bool,
    gr.latency_ms,
    gr.throughput,
    gr.generation_ms,
    gr.provider,
    gr.usage
  from private.v2_rpc_gateway_requests_compat gr
  join model_ids mi on mi.model_id = gr.model_id
  join windows w on gr.created_at >= w.last5d_start
              and gr.created_at <  w.now_hour
),

requests_last24 as (
  select r.*
  from requests_5d r, windows w
  where r.created_at >= w.last24_start
    and r.created_at <  w.now_hour
),
requests_prev24 as (
  select r.*
  from requests_5d r, windows w
  where r.created_at >= w.prev24_start
    and r.created_at <  w.last24_start
),

-- 4) 24h aggregates
last_24h as (
  select jsonb_build_object(
    'avg_throughput',
      case when count(*) filter (where throughput is not null) > 0
        then percentile_cont(0.5) within group (order by throughput) filter (where throughput is not null)
        else null end,
    'avg_latency_ms',
      case when count(*) filter (where latency_ms is not null) > 0
        then percentile_cont(0.5) within group (order by latency_ms) filter (where latency_ms is not null)
        else null end,
    'avg_generation_ms',
      case when count(*) filter (where generation_ms is not null) > 0
        then percentile_cont(0.5) within group (order by generation_ms) filter (where generation_ms is not null)
        else null end,
    'uptime_pct',
      case when count(*) > 0
        then (count(*) filter (where success_bool) * 100.0 / count(*))
        else null end,
    'total_requests', count(*),
    'successful_requests', count(*) filter (where success_bool)
  ) as value
  from requests_last24
),
prev_24h as (
  select jsonb_build_object(
    'avg_throughput',
      case when count(*) filter (where throughput is not null) > 0
        then percentile_cont(0.5) within group (order by throughput) filter (where throughput is not null)
        else null end,
    'avg_latency_ms',
      case when count(*) filter (where latency_ms is not null) > 0
        then percentile_cont(0.5) within group (order by latency_ms) filter (where latency_ms is not null)
        else null end,
    'avg_generation_ms',
      case when count(*) filter (where generation_ms is not null) > 0
        then percentile_cont(0.5) within group (order by generation_ms) filter (where generation_ms is not null)
        else null end,
    'uptime_pct',
      case when count(*) > 0
        then (count(*) filter (where success_bool) * 100.0 / count(*))
        else null end,
    'total_requests', count(*),
    'successful_requests', count(*) filter (where success_bool)
  ) as value
  from requests_prev24
),

hourly_24h as (
  select coalesce(jsonb_agg(bucket_json order by bucket_start), '[]'::jsonb) as value
  from (
    select
      s.bucket_start,
      jsonb_build_object(
        'bucket', s.bucket_start,
        'avg_throughput',
          case when count(r.*) filter (where r.throughput is not null) > 0
            then percentile_cont(0.5) within group (order by r.throughput) filter (where r.throughput is not null)
            else null end,
        'avg_latency_ms',
          case when count(r.*) filter (where r.latency_ms is not null) > 0
            then percentile_cont(0.5) within group (order by r.latency_ms) filter (where r.latency_ms is not null)
            else null end,
        'avg_generation_ms',
          case when count(r.*) filter (where r.generation_ms is not null) > 0
            then percentile_cont(0.5) within group (order by r.generation_ms) filter (where r.generation_ms is not null)
            else null end,
        'requests', count(r.*),
        'success_pct',
          case when count(r.*) > 0
            then (count(*) filter (where r.success_bool) * 100.0 / count(r.*))
            else null end,
        'worst_provider_success_pct',
          (
            select min(pct)
            from (
              select
                case when count(*) > 0
                  then (count(*) filter (where r2.success_bool) * 100.0 / count(*))
                  else null end as pct
              from requests_last24 r2
              where r2.created_at >= s.bucket_start
                and r2.created_at <  s.bucket_start + interval '1 hour'
              group by r2.provider
            ) provider_stats
          )
      ) as bucket_json
    from (
      select generate_series(
        w.last24_start,
        w.now_hour - interval '1 hour',
        interval '1 hour'
      ) as bucket_start
      from windows w
    ) s
    left join requests_last24 r
      on r.created_at >= s.bucket_start
     and r.created_at <  s.bucket_start + interval '1 hour'
    group by s.bucket_start
  ) buckets
),

provider_uptime_24h as (
  select coalesce(jsonb_agg(provider_json order by requests desc), '[]'::jsonb) as value
  from (
    select
      r.provider,
      count(*) as requests,
      jsonb_build_object(
        'provider', r.provider,
        'provider_name', coalesce(p.api_provider_name, r.provider),
        'avg_throughput',
          case when count(*) filter (where r.throughput is not null) > 0
            then percentile_cont(0.5) within group (order by r.throughput) filter (where r.throughput is not null)
            else null end,
        'avg_latency_ms',
          case when count(*) filter (where r.latency_ms is not null) > 0
            then percentile_cont(0.5) within group (order by r.latency_ms) filter (where r.latency_ms is not null)
            else null end,
        'avg_generation_ms',
          case when count(*) filter (where r.generation_ms is not null) > 0
            then percentile_cont(0.5) within group (order by r.generation_ms) filter (where r.generation_ms is not null)
            else null end,
        'requests', count(*),
        'uptime_pct',
          case when count(*) > 0
            then (count(*) filter (where r.success_bool) * 100.0 / count(*))
            else null end,
        'uptime_buckets',
          (
            select coalesce(jsonb_agg(bucket_json order by bucket_end asc), '[]'::jsonb)
            from (
              select
                bucket_end,
                jsonb_build_object(
                  'start', bucket_end - interval '6 hours',
                  'end', bucket_end,
                  'success_pct',
                    case when count(pr.*) > 0
                      then (count(*) filter (where pr.success_bool) * 100.0 / count(pr.*))
                      else null end
                ) as bucket_json
              from (
                select generate_series(
                  w.last24_start + interval '6 hours',
                  w.now_hour,
                  interval '6 hours'
                ) as bucket_end
                from windows w
              ) buckets
              left join requests_last24 pr
                on pr.provider = r.provider
               and pr.created_at >  buckets.bucket_end - interval '6 hours'
               and pr.created_at <= buckets.bucket_end
              group by bucket_end
            ) per_bucket
          )
      ) as provider_json
    from requests_last24 r
    left join private.v2_rpc_providers_compat p on p.api_provider_id = r.provider
    group by r.provider, p.api_provider_name
  ) provider_rows
),

-- 5) 5d aggregates
hourly_5d as (
  select coalesce(jsonb_agg(bucket_json order by bucket_start), '[]'::jsonb) as value
  from (
    select
      s.bucket_start,
      jsonb_build_object(
        'bucket', s.bucket_start,
        'avg_throughput',
          case when count(r.*) filter (where r.throughput is not null) > 0
            then percentile_cont(0.5) within group (order by r.throughput) filter (where r.throughput is not null)
            else null end,
        'avg_latency_ms',
          case when count(r.*) filter (where r.latency_ms is not null) > 0
            then percentile_cont(0.5) within group (order by r.latency_ms) filter (where r.latency_ms is not null)
            else null end,
        'avg_generation_ms',
          case when count(r.*) filter (where r.generation_ms is not null) > 0
            then percentile_cont(0.5) within group (order by r.generation_ms) filter (where r.generation_ms is not null)
            else null end,
        'requests', count(r.*),
        'success_pct',
          case when count(r.*) > 0
            then (count(*) filter (where r.success_bool) * 100.0 / count(r.*))
            else null end
      ) as bucket_json
    from (
      select generate_series(
        w.last5d_start,
        w.now_hour - interval '1 hour',
        interval '1 hour'
      ) as bucket_start
      from windows w
    ) s
    left join requests_5d r
      on r.created_at >= s.bucket_start
     and r.created_at <  s.bucket_start + interval '1 hour'
    group by s.bucket_start
  ) buckets
),
time_of_day_5d as (
  select coalesce(jsonb_agg(hour_json order by hour), '[]'::jsonb) as value
  from (
    select
      hour,
      jsonb_build_object(
        'hour', hour,
        'avg_throughput',
          case when count(*) filter (where throughput is not null) > 0
            then percentile_cont(0.5) within group (order by throughput) filter (where throughput is not null)
            else null end,
        'avg_latency_ms',
          case when count(*) filter (where latency_ms is not null) > 0
            then percentile_cont(0.5) within group (order by latency_ms) filter (where latency_ms is not null)
            else null end,
        'avg_generation_ms',
          case when count(*) filter (where generation_ms is not null) > 0
            then percentile_cont(0.5) within group (order by generation_ms) filter (where generation_ms is not null)
            else null end,
        'sample_count', count(*)
      ) as hour_json
    from (
      select
        extract(hour from (created_at at time zone 'utc'))::int as hour,
        throughput,
        latency_ms,
        generation_ms
      from requests_5d
    ) r
    group by hour
  ) hours
),

-- 6) Cumulative token totals since release date (or from first seen request)
token_totals as (
  select
    coalesce(
      (select (release_date::timestamp at time zone 'utc') from anchors),
      min(gr.created_at)
    ) as release_at,
    coalesce(
      sum(
        coalesce(
          nullif((gr.usage ->> 'total_tokens')::numeric, 0),
          coalesce((gr.usage ->> 'input_tokens')::numeric, 0)
          + coalesce((gr.usage ->> 'output_tokens')::numeric, 0)
        )
      ),
      0
    ) as total_tokens
  from private.v2_rpc_gateway_requests_compat gr
  join model_ids mi on mi.model_id = gr.model_id
  where (select release_date from anchors) is null
     or gr.created_at >= (select (release_date::timestamp at time zone 'utc') from anchors)
)

select jsonb_build_object(
  'last_24h',              (select value from last_24h),
  'prev_24h',              (select value from prev_24h),
  'hourly_24h',            (select value from hourly_24h),
  'provider_uptime_24h',   (select value from provider_uptime_24h),
  'hourly_5d',             (select value from hourly_5d),
  'time_of_day_5d',        (select value from time_of_day_5d),
  'cumulative_tokens',     jsonb_build_object(
                             'release_date', (select release_date from anchors),
                             'total_tokens', (select total_tokens from token_totals)
                           )
);
$function$;

CREATE OR REPLACE FUNCTION public.get_model_gateway_overview (
  p_internal_model_id text,
  p_hours             integer DEFAULT 24
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
with
-- Clamp hours to something sane
args as (
  select greatest(1, least(coalesce(p_hours, 24), 720))::int as hours
),

-- UTC anchor as timestamptz (safe comparisons vs created_at timestamptz)
anchors as (
  select
    (date_trunc('hour', now() at time zone 'utc') at time zone 'utc') as now_hour
),

windows as (
  select
    a.now_hour,
    a.now_hour - make_interval(hours => (select hours from args)) as window_start
  from anchors a
),

-- Build the set of gateway model_id values we should include
model_ids as (
  select p_internal_model_id as model_id

  union

  select pm.provider_id || '/' || pm.api_model_id
  from private.v2_rpc_routes_compat pm
  where pm.internal_model_id = p_internal_model_id

  -- Optional: honour effective windows if you actually use them
  -- and (pm.effective_from is null or pm.effective_from <= (select now_hour from anchors))
  -- and (pm.effective_to   is null or pm.effective_to   >  (select now_hour from anchors))
),

-- Pull only the rows we need (windowed)
requests as (
  select
    gr.created_at,
    gr.success as success_bool,
    gr.latency_ms,
    gr.throughput,
    gr.generation_ms,
    gr.provider,
    gr.usage,
    gr.model_id
  from private.v2_rpc_gateway_requests_compat gr
  join model_ids mi on mi.model_id = gr.model_id
  join windows w on gr.created_at >= w.window_start
              and gr.created_at <  w.now_hour
),

summary as (
  select jsonb_build_object(
    'hours', (select hours from args),
    'window_start', (select window_start from windows),
    'window_end', (select now_hour from windows),

    'median_throughput',
      case when count(*) filter (where throughput is not null) > 0
        then percentile_cont(0.5) within group (order by throughput) filter (where throughput is not null)
        else null end,

    'median_latency_ms',
      case when count(*) filter (where latency_ms is not null) > 0
        then percentile_cont(0.5) within group (order by latency_ms) filter (where latency_ms is not null)
        else null end,

    'median_generation_ms',
      case when count(*) filter (where generation_ms is not null) > 0
        then percentile_cont(0.5) within group (order by generation_ms) filter (where generation_ms is not null)
        else null end,

    'uptime_pct',
      case when count(*) > 0
        then (count(*) filter (where success_bool) * 100.0 / count(*))
        else null end,

    'total_requests', count(*),
    'successful_requests', count(*) filter (where success_bool)
  ) as value
  from requests
),

hourly as (
  select coalesce(jsonb_agg(bucket_json order by bucket_start), '[]'::jsonb) as value
  from (
    select
      s.bucket_start,
      jsonb_build_object(
        'bucket', s.bucket_start,
        'requests', count(r.*),
        'success_pct',
          case when count(r.*) > 0
            then (count(*) filter (where r.success_bool) * 100.0 / count(r.*))
            else null end,

        'median_throughput',
          case when count(r.*) filter (where r.throughput is not null) > 0
            then percentile_cont(0.5) within group (order by r.throughput) filter (where r.throughput is not null)
            else null end,

        'median_latency_ms',
          case when count(r.*) filter (where r.latency_ms is not null) > 0
            then percentile_cont(0.5) within group (order by r.latency_ms) filter (where r.latency_ms is not null)
            else null end,

        'median_generation_ms',
          case when count(r.*) filter (where r.generation_ms is not null) > 0
            then percentile_cont(0.5) within group (order by r.generation_ms) filter (where r.generation_ms is not null)
            else null end
      ) as bucket_json
    from (
      select generate_series(
        (select window_start from windows),
        (select now_hour from windows) - interval '1 hour',
        interval '1 hour'
      ) as bucket_start
    ) s
    left join requests r
      on r.created_at >= s.bucket_start
     and r.created_at <  s.bucket_start + interval '1 hour'
    group by s.bucket_start
  ) buckets
),

provider_breakdown as (
  select coalesce(jsonb_agg(provider_json order by requests desc), '[]'::jsonb) as value
  from (
    select
      r.provider,
      count(*) as requests,
      jsonb_build_object(
        'provider', r.provider,
        'requests', count(*),
        'uptime_pct',
          case when count(*) > 0
            then (count(*) filter (where r.success_bool) * 100.0 / count(*))
            else null end,

        'median_throughput',
          case when count(*) filter (where r.throughput is not null) > 0
            then percentile_cont(0.5) within group (order by r.throughput) filter (where r.throughput is not null)
            else null end,

        'median_latency_ms',
          case when count(*) filter (where r.latency_ms is not null) > 0
            then percentile_cont(0.5) within group (order by r.latency_ms) filter (where r.latency_ms is not null)
            else null end,

        'median_generation_ms',
          case when count(*) filter (where r.generation_ms is not null) > 0
            then percentile_cont(0.5) within group (order by r.generation_ms) filter (where r.generation_ms is not null)
            else null end
      ) as provider_json
    from requests r
    group by r.provider
  ) rows
),

tokens as (
  select jsonb_build_object(
    'total_tokens',
      coalesce(sum(
        coalesce(
          nullif((usage->>'total_tokens')::numeric, 0),
          coalesce((usage->>'input_tokens')::numeric, 0)
          + coalesce((usage->>'output_tokens')::numeric, 0)
        )
      ), 0)
  ) as value
  from requests
)

select jsonb_build_object(
  'model_ids', (select coalesce(jsonb_agg(model_id), '[]'::jsonb) from model_ids),
  'summary', (select value from summary),
  'hourly', (select value from hourly),
  'providers', (select value from provider_breakdown),
  'tokens', (select value from tokens)
);
$function$;

CREATE OR REPLACE FUNCTION public.get_model_performance_overview (
  p_model_id text
)
  RETURNS TABLE (
    last_24h            jsonb,
    prev_24h            jsonb,
    hourly_24h          jsonb,
    provider_uptime_24h jsonb,
    hourly_5d           jsonb,
    time_of_day_5d      jsonb,
    cumulative_tokens   jsonb
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$with params as (
    select p_model_id as model_id
),
anchors as (
    select
        date_trunc('hour', now() at time zone 'utc') as now_hour,
        (select release_date from private.v2_rpc_models_compat where model_id = p_model_id limit 1) as release_date
),
windows as (
    select
        now_hour,
        now_hour - interval '24 hours' as last24_start,
        now_hour - interval '48 hours' as prev24_start,
        now_hour - interval '120 hours' as last5d_start
    from anchors
),
-- Resolve the request's actual route, not every route belonging to its model.
requests_all as materialized (
    select fact.occurred_at as created_at, fact.success::boolean as success_bool,
        fact.latency_ms, fact.throughput, fact.generation_ms, route.provider_slug as provider
    from public.v2_request_facts fact
    left join public.v2_model_provider_routes route on route.provider_model_id = fact.provider_model_id
    cross join windows w
    where coalesce(fact.routed_model_slug, fact.requested_model_slug, fact.requested_model_input) = p_model_id
      and fact.occurred_at >= w.last5d_start and fact.occurred_at < w.now_hour
),
requests_last24 as (
    select * from requests_all, windows w
    where created_at >= w.last24_start and created_at < w.now_hour
),
requests_prev24 as (
    select * from requests_all, windows w
    where created_at >= w.prev24_start and created_at < w.last24_start
),
requests_5d as (
    select * from requests_all, windows w
    where created_at >= w.last5d_start and created_at < w.now_hour
),
median_or_null as (
    select 1 as dummy
),
last_24h as (
    select jsonb_build_object(
        'avg_throughput', case when count(*) filter (where throughput is not null) > 0
            then percentile_cont(0.5) within group (order by throughput) filter (where throughput is not null)
            else null end,
        'avg_latency_ms', case when count(*) filter (where latency_ms is not null) > 0
            then percentile_cont(0.5) within group (order by latency_ms) filter (where latency_ms is not null)
            else null end,
        'avg_generation_ms', case when count(*) filter (where generation_ms is not null) > 0
            then percentile_cont(0.5) within group (order by generation_ms) filter (where generation_ms is not null)
            else null end,
        'uptime_pct', case when count(*) > 0 then (count(*) filter (where success_bool) * 100.0 / count(*)) else null end,
        'total_requests', count(*),
        'successful_requests', count(*) filter (where success_bool)
    ) as value
    from requests_last24
),
prev_24h as (
    select jsonb_build_object(
        'avg_throughput', case when count(*) filter (where throughput is not null) > 0
            then percentile_cont(0.5) within group (order by throughput) filter (where throughput is not null)
            else null end,
        'avg_latency_ms', case when count(*) filter (where latency_ms is not null) > 0
            then percentile_cont(0.5) within group (order by latency_ms) filter (where latency_ms is not null)
            else null end,
        'avg_generation_ms', case when count(*) filter (where generation_ms is not null) > 0
            then percentile_cont(0.5) within group (order by generation_ms) filter (where generation_ms is not null)
            else null end,
        'uptime_pct', case when count(*) > 0 then (count(*) filter (where success_bool) * 100.0 / count(*)) else null end,
        'total_requests', count(*),
        'successful_requests', count(*) filter (where success_bool)
    ) as value
    from requests_prev24
),
hourly_24h as (
    select coalesce(jsonb_agg(bucket_json order by bucket_start), '[]'::jsonb) as value
    from (
        select
            s.bucket_start,
            jsonb_build_object(
                'bucket', s.bucket_start,
                'avg_throughput', case when count(r.*) filter (where r.throughput is not null) > 0
                    then percentile_cont(0.5) within group (order by r.throughput) filter (where r.throughput is not null)
                    else null end,
                'avg_latency_ms', case when count(r.*) filter (where r.latency_ms is not null) > 0
                    then percentile_cont(0.5) within group (order by r.latency_ms) filter (where r.latency_ms is not null)
                    else null end,
                'avg_generation_ms', case when count(r.*) filter (where r.generation_ms is not null) > 0
                    then percentile_cont(0.5) within group (order by r.generation_ms) filter (where r.generation_ms is not null)
                    else null end,
                'requests', count(r.*),
                'success_pct', case when count(r.*) > 0 then (count(*) filter (where r.success_bool) * 100.0 / count(r.*)) else null end,
                'worst_provider_success_pct',
                    (
                        select min(pct) from (
                            select case when count(*) > 0 then (count(*) filter (where r2.success_bool) * 100.0 / count(*)) else null end as pct
                            from requests_last24 r2
                            where r2.created_at >= s.bucket_start
                              and r2.created_at < s.bucket_start + interval '1 hour'
                            group by r2.provider
                        ) provider_stats
                    )
            ) as bucket_json
        from (
            select generate_series(w.last24_start, w.now_hour, interval '1 hour') as bucket_start
            from windows w
        ) s
        left join requests_last24 r
            on r.created_at >= s.bucket_start
           and r.created_at < s.bucket_start + interval '1 hour'
        group by s.bucket_start
    ) buckets
),
provider_uptime_24h as (
    select coalesce(jsonb_agg(provider_json order by requests desc), '[]'::jsonb) as value
    from (
        select
            r.provider,
            count(*) as requests,
            jsonb_build_object(
                'provider', r.provider,
                'provider_name', coalesce(p.api_provider_name, r.provider),
                'avg_throughput', case when count(*) filter (where r.throughput is not null) > 0
                    then percentile_cont(0.5) within group (order by r.throughput) filter (where r.throughput is not null)
                    else null end,
                'avg_latency_ms', case when count(*) filter (where r.latency_ms is not null) > 0
                    then percentile_cont(0.5) within group (order by r.latency_ms) filter (where r.latency_ms is not null)
                    else null end,
                'avg_generation_ms', case when count(*) filter (where r.generation_ms is not null) > 0
                    then percentile_cont(0.5) within group (order by r.generation_ms) filter (where r.generation_ms is not null)
                    else null end,
                'requests', count(*),
                'uptime_pct', case when count(*) > 0 then (count(*) filter (where r.success_bool) * 100.0 / count(*)) else null end,
                'uptime_buckets',
                    (
                        select jsonb_agg(bucket_json order by bucket_end asc)
                        from (
                            select
                                bucket_end,
                                jsonb_build_object(
                                    'start', bucket_end - interval '6 hours',
                                    'end', bucket_end,
                                    'success_pct', case when count(pr.*) > 0 then (count(*) filter (where pr.success_bool) * 100.0 / count(pr.*)) else null end
                                ) as bucket_json
                            from (
                                select generate_series(
                                    w.last24_start,
                                    w.now_hour,
                                    interval '6 hours'
                                ) as bucket_end
                                from windows w
                            ) buckets
                            left join requests_last24 pr
                                on pr.provider = r.provider
                               and pr.created_at > buckets.bucket_end - interval '6 hours'
                               and pr.created_at <= buckets.bucket_end
                            group by bucket_end
                        ) per_bucket
                    )
            ) as provider_json
        from requests_last24 r
        left join private.v2_rpc_providers_compat p on p.api_provider_id = r.provider
        group by r.provider, p.api_provider_name
    ) provider_rows
),
hourly_5d as (
    select coalesce(jsonb_agg(bucket_json order by bucket_start), '[]'::jsonb) as value
    from (
        select
            s.bucket_start,
            jsonb_build_object(
                'bucket', s.bucket_start,
                'avg_throughput', case when count(r.*) filter (where r.throughput is not null) > 0
                    then percentile_cont(0.5) within group (order by r.throughput) filter (where r.throughput is not null)
                    else null end,
                'avg_latency_ms', case when count(r.*) filter (where r.latency_ms is not null) > 0
                    then percentile_cont(0.5) within group (order by r.latency_ms) filter (where r.latency_ms is not null)
                    else null end,
                'avg_generation_ms', case when count(r.*) filter (where r.generation_ms is not null) > 0
                    then percentile_cont(0.5) within group (order by r.generation_ms) filter (where r.generation_ms is not null)
                    else null end,
                'requests', count(r.*),
                'success_pct', case when count(r.*) > 0 then (count(*) filter (where r.success_bool) * 100.0 / count(r.*)) else null end
            ) as bucket_json
        from (
            select generate_series(w.last5d_start, w.now_hour, interval '1 hour') as bucket_start
            from windows w
        ) s
        left join requests_5d r
            on r.created_at >= s.bucket_start
           and r.created_at < s.bucket_start + interval '1 hour'
        group by s.bucket_start
    ) buckets
),
time_of_day_5d as (
    select coalesce(jsonb_agg(hour_json order by hour), '[]'::jsonb) as value
    from (
        select
            hour,
            jsonb_build_object(
                'hour', hour,
                'avg_throughput', case when count(*) filter (where throughput is not null) > 0
                    then percentile_cont(0.5) within group (order by throughput) filter (where throughput is not null)
                    else null end,
                'avg_latency_ms', case when count(*) filter (where latency_ms is not null) > 0
                    then percentile_cont(0.5) within group (order by latency_ms) filter (where latency_ms is not null)
                    else null end,
                'avg_generation_ms', case when count(*) filter (where generation_ms is not null) > 0
                    then percentile_cont(0.5) within group (order by generation_ms) filter (where generation_ms is not null)
                    else null end,
                'sample_count', count(*)
            ) as hour_json
        from (
            select
                extract(hour from created_at) as hour,
                throughput,
                latency_ms,
                generation_ms
            from requests_5d
        ) r
        group by hour
    ) hours
),
-- Count each request's token total once; total_tokens already includes input/output.
token_totals as (
    select coalesce(sum(tokens.total_tokens), 0) as total_tokens
    from public.v2_request_facts fact
    left join lateral (
        select coalesce(
            sum(usage.quantity) filter (where usage.meter_key = 'total_tokens'),
            sum(usage.quantity) filter (where usage.meter_key in ('input_tokens', 'output_tokens')),
            sum(usage.quantity) filter (where usage.meter_key in ('input_text_tokens', 'output_text_tokens')),
            sum(usage.quantity) filter (where usage.meter_key in ('prompt_tokens', 'completion_tokens')),
            0
        ) as total_tokens
        from public.v2_request_usage usage
        where usage.request_event_id = fact.request_event_id
    ) tokens on true
    where coalesce(fact.routed_model_slug, fact.requested_model_slug, fact.requested_model_input) = p_model_id
)
select
    (select value from last_24h) as last_24h,
    (select value from prev_24h) as prev_24h,
    (select value from hourly_24h) as hourly_24h,
    (select value from provider_uptime_24h) as provider_uptime_24h,
    (select value from hourly_5d) as hourly_5d,
    (select value from time_of_day_5d) as time_of_day_5d,
    jsonb_build_object(
        'release_date', (select release_date from anchors),
        'total_tokens', (select total_tokens from token_totals)
    ) as cumulative_tokens;$function$;

CREATE OR REPLACE FUNCTION public.get_model_provider_health_metrics (
  p_model_ids    text[],
  p_provider_ids text[]  DEFAULT NULL::text[],
  p_window_days  integer DEFAULT 30,
  p_bucket_hours integer DEFAULT 24
)
  RETURNS TABLE (
    provider_id             text,
    provider_name           text,
    requests                bigint,
    requests_30m            bigint,
    success_requests        bigint,
    failed_requests         bigint,
    neutral_requests        bigint,
    rate_limited_requests   bigint,
    health_requests         bigint,
    health_success_requests bigint,
    uptime_pct              numeric,
    request_success_pct     numeric,
    avg_latency_ms_30m      numeric,
    avg_throughput_30m      numeric,
    avg_latency_ms          numeric,
    p50_latency_ms          numeric,
    p95_latency_ms          numeric,
    avg_generation_ms       numeric,
    avg_throughput          numeric,
    total_tokens            bigint,
    input_tokens_1h         bigint,
    output_tokens_1h        bigint,
    cached_read_tokens_1h   bigint,
    input_tokens            bigint,
    output_tokens           bigint,
    finish_reason_counts    jsonb,
    error_code_counts       jsonb,
    buckets                 jsonb,
    last_request_at         timestamp with time zone
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  with params as (
    select
      greatest(1, least(coalesce(p_window_days, 30), 90))::integer as window_days,
      greatest(1, least(coalesce(p_bucket_hours, 24), 24 * 7))::integer as bucket_hours,
      now() as now_ts
  ),
  provider_filter as (
    select distinct nullif(btrim(input.provider_id), '') as provider_id
    from unnest(coalesce(p_provider_ids, array[]::text[])) as input(provider_id)
    where nullif(btrim(input.provider_id), '') is not null
  ),
  model_filter as (
    select distinct nullif(btrim(input.model_id), '') as model_id
    from unnest(coalesce(p_model_ids, array[]::text[])) as input(model_id)
    where nullif(btrim(input.model_id), '') is not null
  ),
  base as (
    select
      coalesce(nullif(gr.provider, ''), 'unknown') as provider_id,
      gr.created_at,
      gr.success,
      gr.status_code,
      lower(coalesce(gr.error_code, '')) as error_code,
      lower(nullif(btrim(coalesce(gr.finish_reason, '')), '')) as finish_reason,
      gr.latency_ms,
      gr.generation_ms,
      gr.throughput,
      public.gateway_usage_total_tokens(gr.usage)::bigint as total_tokens,
      coalesce(
        public.gateway_usage_numeric_field(
          gr.usage,
          'input_tokens',
          'prompt_tokens',
          'inputTokens',
          'promptTokens',
          'total_input_tokens',
          'totalInputTokens'
        ),
        0
      )::bigint as input_tokens,
      coalesce(
        public.gateway_usage_numeric_field(
          gr.usage,
          'output_tokens',
          'completion_tokens',
          'generated_tokens',
          'response_tokens',
          'outputTokens',
          'completionTokens',
          'total_output_tokens',
          'totalOutputTokens'
        ),
        0
      )::bigint as output_tokens
      ,
      coalesce(
        public.gateway_usage_numeric_field(
          gr.usage,
          'cached_read_text_tokens',
          'cached_read_image_tokens',
          'cached_read_audio_tokens',
          'cached_read_video_tokens',
          'cached_read_tokens',
          'cache_read_input_tokens'
        ),
        0
      )::bigint as cached_read_tokens
    from private.v2_rpc_gateway_requests_compat gr
    join params p on true
    where gr.created_at >= p.now_ts - make_interval(days => p.window_days)
      and exists (
        select 1
        from model_filter mf
        where mf.model_id in (
          nullif(gr.model_id, ''),
          nullif(gr.canonical_model_id, ''),
          nullif(gr.requested_model_id, ''),
          nullif(gr.routed_model_id, ''),
          public.resolve_public_model_id(gr.model_id, gr.provider)
        )
      )
      and gr.provider is not null
      and gr.provider <> ''
      and (
        p_provider_ids is null
        or exists (
          select 1
          from provider_filter pf
          where pf.provider_id = gr.provider
        )
      )
  ),
  classified as (
    select
      b.*,
      case
        when b.success is true then 'success'
        when b.status_code = 429
          or b.error_code like '%rate limit%'
          or b.error_code like '%rate_limit%'
          or b.error_code like '%ratelimit%'
          or b.error_code like '%too many requests%'
          or b.error_code like '%quota exceeded%'
        then 'neutral'
        when b.error_code like '%abort%'
          or b.error_code like '%cancel%'
          or b.error_code like '%client_closed%'
        then 'neutral'
        else 'failure'
      end as health_outcome,
      case
        when b.status_code = 429
          or b.error_code like '%rate limit%'
          or b.error_code like '%rate_limit%'
          or b.error_code like '%ratelimit%'
          or b.error_code like '%too many requests%'
          or b.error_code like '%quota exceeded%'
        then true
        else false
      end as is_rate_limited
    from base b
  ),
  aggregates as (
    select
      c.provider_id,
      count(*)::bigint as requests,
      count(*) filter (where c.created_at >= (select now_ts from params) - interval '30 minutes')::bigint as requests_30m,
      count(*) filter (where c.success is true)::bigint as success_requests,
      count(*) filter (where c.health_outcome = 'failure')::bigint as failed_requests,
      count(*) filter (where c.health_outcome = 'neutral')::bigint as neutral_requests,
      count(*) filter (where c.is_rate_limited)::bigint as rate_limited_requests,
      count(*) filter (where c.health_outcome <> 'neutral')::bigint as health_requests,
      count(*) filter (where c.health_outcome = 'success')::bigint as health_success_requests,
      avg(c.latency_ms) filter (
        where c.success is true
          and c.latency_ms is not null
          and c.created_at >= (select now_ts from params) - interval '30 minutes'
      )::numeric as avg_latency_ms_30m,
      avg(c.throughput) filter (
        where c.success is true
          and c.throughput is not null
          and c.created_at >= (select now_ts from params) - interval '30 minutes'
      )::numeric as avg_throughput_30m,
      avg(c.latency_ms) filter (where c.success is true and c.latency_ms is not null)::numeric as avg_latency_ms,
      percentile_cont(0.5) within group (order by c.latency_ms)
        filter (where c.success is true and c.latency_ms is not null)::numeric as p50_latency_ms,
      percentile_cont(0.95) within group (order by c.latency_ms)
        filter (where c.success is true and c.latency_ms is not null)::numeric as p95_latency_ms,
      avg(c.generation_ms) filter (where c.success is true and c.generation_ms is not null)::numeric as avg_generation_ms,
      avg(c.throughput) filter (where c.success is true and c.throughput is not null)::numeric as avg_throughput,
      coalesce(sum(c.total_tokens), 0)::bigint as total_tokens,
      coalesce(sum(c.input_tokens) filter (where c.created_at >= (select now_ts from params) - interval '1 hour'), 0)::bigint as input_tokens_1h,
      coalesce(sum(c.output_tokens) filter (where c.created_at >= (select now_ts from params) - interval '1 hour'), 0)::bigint as output_tokens_1h,
      coalesce(sum(c.cached_read_tokens) filter (where c.created_at >= (select now_ts from params) - interval '1 hour'), 0)::bigint as cached_read_tokens_1h,
      coalesce(sum(c.input_tokens), 0)::bigint as input_tokens,
      coalesce(sum(c.output_tokens), 0)::bigint as output_tokens,
      max(c.created_at) as last_request_at
    from classified c
    group by c.provider_id
  ),
  finish_reasons as (
    select
      x.provider_id,
      jsonb_object_agg(x.finish_reason, x.reason_count order by x.reason_count desc, x.finish_reason) as finish_reason_counts
    from (
      select
        c.provider_id,
        c.finish_reason,
        count(*)::bigint as reason_count
      from classified c
      where c.success is true
        and c.finish_reason is not null
        and c.finish_reason <> ''
        and c.finish_reason <> 'error'
      group by c.provider_id, c.finish_reason
    ) x
    group by x.provider_id
  ),
  error_codes as (
    select
      x.provider_id,
      jsonb_object_agg(x.error_code, x.error_count order by x.error_count desc, x.error_code) as error_code_counts
    from (
      select
        c.provider_id,
        coalesce(nullif(c.error_code, ''), 'unknown') as error_code,
        count(*)::bigint as error_count
      from classified c
      where c.health_outcome = 'failure'
      group by c.provider_id, coalesce(nullif(c.error_code, ''), 'unknown')
    ) x
    group by x.provider_id
  ),
  bucketed as (
    select
      b.provider_id,
      jsonb_agg(
        jsonb_build_object(
          'start', b.bucket_start,
          'end', b.bucket_start + make_interval(hours => (select bucket_hours from params)),
          'requests', b.requests,
          'success_requests', b.success_requests,
          'health_requests', b.health_requests,
          'health_success_requests', b.health_success_requests,
          'uptime_pct',
            case
              when b.health_requests > 0
              then round((b.health_success_requests::numeric / b.health_requests::numeric) * 100, 2)
              else null
            end,
          'request_success_pct',
            case
              when b.requests > 0
              then round((b.success_requests::numeric / b.requests::numeric) * 100, 2)
              else null
            end,
          'avg_latency_ms', b.avg_latency_ms,
          'avg_throughput', b.avg_throughput
        )
        order by b.bucket_start
      ) as buckets
    from (
      select
        c.provider_id,
        date_bin(
          make_interval(hours => p.bucket_hours),
          c.created_at,
          timestamp with time zone '2000-01-01 00:00:00+00'
        ) as bucket_start,
        count(*)::bigint as requests,
        count(*) filter (where c.success is true)::bigint as success_requests,
        count(*) filter (where c.health_outcome <> 'neutral')::bigint as health_requests,
        count(*) filter (where c.health_outcome = 'success')::bigint as health_success_requests,
        avg(c.latency_ms) filter (where c.success is true and c.latency_ms is not null)::numeric as avg_latency_ms,
        avg(c.throughput) filter (where c.success is true and c.throughput is not null)::numeric as avg_throughput
      from classified c
      join params p on true
      group by c.provider_id, bucket_start
    ) b
    group by b.provider_id
  )
  select
    coalesce(pf.provider_id, a.provider_id) as provider_id,
    coalesce(dap.api_provider_name, coalesce(pf.provider_id, a.provider_id)) as provider_name,
    coalesce(a.requests, 0)::bigint as requests,
    coalesce(a.requests_30m, 0)::bigint as requests_30m,
    coalesce(a.success_requests, 0)::bigint as success_requests,
    coalesce(a.failed_requests, 0)::bigint as failed_requests,
    coalesce(a.neutral_requests, 0)::bigint as neutral_requests,
    coalesce(a.rate_limited_requests, 0)::bigint as rate_limited_requests,
    coalesce(a.health_requests, 0)::bigint as health_requests,
    coalesce(a.health_success_requests, 0)::bigint as health_success_requests,
    case
      when coalesce(a.health_requests, 0) > 0
      then round((a.health_success_requests::numeric / a.health_requests::numeric) * 100, 2)
      else null
    end as uptime_pct,
    case
      when coalesce(a.requests, 0) > 0
      then round((a.success_requests::numeric / a.requests::numeric) * 100, 2)
      else null
    end as request_success_pct,
    round(a.avg_latency_ms_30m, 2) as avg_latency_ms_30m,
    round(a.avg_throughput_30m, 2) as avg_throughput_30m,
    round(a.avg_latency_ms, 2) as avg_latency_ms,
    round(a.p50_latency_ms, 2) as p50_latency_ms,
    round(a.p95_latency_ms, 2) as p95_latency_ms,
    round(a.avg_generation_ms, 2) as avg_generation_ms,
    round(a.avg_throughput, 2) as avg_throughput,
    coalesce(a.total_tokens, 0)::bigint as total_tokens,
    coalesce(a.input_tokens_1h, 0)::bigint as input_tokens_1h,
    coalesce(a.output_tokens_1h, 0)::bigint as output_tokens_1h,
    coalesce(a.cached_read_tokens_1h, 0)::bigint as cached_read_tokens_1h,
    coalesce(a.input_tokens, 0)::bigint as input_tokens,
    coalesce(a.output_tokens, 0)::bigint as output_tokens,
    coalesce(fr.finish_reason_counts, '{}'::jsonb) as finish_reason_counts,
    coalesce(ec.error_code_counts, '{}'::jsonb) as error_code_counts,
    coalesce(b.buckets, '[]'::jsonb) as buckets,
    a.last_request_at
  from aggregates a
  full join provider_filter pf on pf.provider_id = a.provider_id
  left join private.v2_rpc_providers_compat dap
    on dap.api_provider_id = coalesce(pf.provider_id, a.provider_id)
  left join finish_reasons fr
    on fr.provider_id = a.provider_id
  left join error_codes ec
    on ec.provider_id = a.provider_id
  left join bucketed b
    on b.provider_id = a.provider_id
  where p_provider_ids is null or pf.provider_id is not null
  order by coalesce(a.requests, 0) desc, coalesce(pf.provider_id, a.provider_id);
$function$;

CREATE OR REPLACE FUNCTION public.get_model_provider_runtime_stats (
  p_model_ids    text[],
  p_provider_ids text[] DEFAULT NULL::text[]
)
  RETURNS TABLE (
    provider        text,
    latency_ms_30m  numeric,
    throughput_30m  numeric,
    latency_ms_3d   numeric,
    throughput_3d   numeric,
    requests_30m    bigint,
    requests_3d     bigint,
    successful_3d   bigint,
    day0_requests   bigint,
    day0_successful bigint,
    day1_requests   bigint,
    day1_successful bigint,
    day2_requests   bigint,
    day2_successful bigint
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  with anchors as (
    select
      now() as now_ts,
      now() - interval '30 minutes' as min_30m,
      now() - interval '72 hours' as min_3d,
      (date_trunc('day', now() at time zone 'utc') at time zone 'utc') as day0_start
  ),
  base as (
    select
      gr.provider,
      gr.created_at,
      gr.latency_ms,
      gr.throughput,
      gr.success,
      gr.status_code,
      lower(coalesce(gr.error_code, '')) as error_code
    from private.v2_rpc_gateway_requests_compat gr
    join anchors a on true
    where gr.created_at >= a.min_3d
      and gr.model_id = any(p_model_ids)
      and gr.provider is not null
      and gr.provider <> ''
      and (p_provider_ids is null or gr.provider = any(p_provider_ids))
  ),
  classified as (
    select
      b.*,
      case
        when b.success is true then 'count_success'
        when b.status_code is not null and b.status_code > 0 and b.status_code < 400 then 'count_success'
        when split_part(b.error_code, ':', 1) = 'user'
          or b.error_code like '%invalid_json%'
          or b.error_code like '%validation%'
          or b.error_code like '%unsupported_param%'
          or b.error_code like '%unsupported_model_or_endpoint%'
          or b.error_code like '%unsupported_modalities%'
          or b.error_code like '%bad_request%'
          or b.error_code like '%missing_required%'
        then 'exclude'
        when split_part(b.error_code, ':', 1) = 'gateway'
          or (
            split_part(b.error_code, ':', 1) = 'system' and (
              b.error_code like '%gateway%'
              or b.error_code like '%routing%'
              or b.error_code like '%breaker%'
              or b.error_code like '%provider_status_not_ready%'
              or b.error_code like '%no_key%'
              or b.error_code like '%missing_api_key%'
              or b.error_code like '%provider_key%'
              or b.error_code like '%pricing_not_configured%'
              or b.error_code like '%no_provider_pricing%'
              or b.error_code like '%all_candidates_failed%'
              or b.error_code like '%executor%'
              or b.error_code like '%internal%'
            )
          )
          or b.error_code like '%gateway%'
          or b.error_code like '%routing%'
          or b.error_code like '%breaker%'
          or b.error_code like '%provider_status_not_ready%'
          or b.error_code like '%no_key%'
          or b.error_code like '%missing_api_key%'
          or b.error_code like '%provider_key%'
          or b.error_code like '%pricing_not_configured%'
          or b.error_code like '%no_provider_pricing%'
          or b.error_code like '%all_candidates_failed%'
          or b.error_code like '%executor%'
          or b.error_code like '%internal%'
        then 'exclude'
        when b.status_code in (408, 429) or b.status_code >= 500 then 'count_failure'
        when b.status_code between 400 and 499 then 'exclude'
        else 'count_failure'
      end as uptime_outcome
    from base b
  ),
  aggregated as (
    select
      c.provider,
      percentile_cont(0.5) within group (order by c.latency_ms)
        filter (where c.created_at >= a.min_30m and c.latency_ms is not null) as latency_ms_30m,
      percentile_cont(0.5) within group (order by c.throughput)
        filter (where c.created_at >= a.min_30m and c.throughput is not null) as throughput_30m,
      percentile_cont(0.5) within group (order by c.latency_ms)
        filter (where c.latency_ms is not null) as latency_ms_3d,
      percentile_cont(0.5) within group (order by c.throughput)
        filter (where c.throughput is not null) as throughput_3d,
      count(*) filter (where c.created_at >= a.min_30m) as requests_30m,
      count(*) filter (where c.uptime_outcome <> 'exclude') as requests_3d,
      count(*) filter (where c.uptime_outcome = 'count_success') as successful_3d,
      count(*) filter (
        where c.uptime_outcome <> 'exclude'
          and c.created_at >= a.day0_start
          and c.created_at < a.day0_start + interval '1 day'
      ) as day0_requests,
      count(*) filter (
        where c.uptime_outcome = 'count_success'
          and c.created_at >= a.day0_start
          and c.created_at < a.day0_start + interval '1 day'
      ) as day0_successful,
      count(*) filter (
        where c.uptime_outcome <> 'exclude'
          and c.created_at >= a.day0_start - interval '1 day'
          and c.created_at < a.day0_start
      ) as day1_requests,
      count(*) filter (
        where c.uptime_outcome = 'count_success'
          and c.created_at >= a.day0_start - interval '1 day'
          and c.created_at < a.day0_start
      ) as day1_successful,
      count(*) filter (
        where c.uptime_outcome <> 'exclude'
          and c.created_at >= a.day0_start - interval '2 day'
          and c.created_at < a.day0_start - interval '1 day'
      ) as day2_requests,
      count(*) filter (
        where c.uptime_outcome = 'count_success'
          and c.created_at >= a.day0_start - interval '2 day'
          and c.created_at < a.day0_start - interval '1 day'
      ) as day2_successful
    from classified c
    join anchors a on true
    group by c.provider
  ),
  provider_filter as (
    select unnest(p_provider_ids) as provider
    where p_provider_ids is not null
  )
  select
    coalesce(pf.provider, ag.provider) as provider,
    ag.latency_ms_30m,
    ag.throughput_30m,
    ag.latency_ms_3d,
    ag.throughput_3d,
    coalesce(ag.requests_30m, 0)::bigint as requests_30m,
    coalesce(ag.requests_3d, 0)::bigint as requests_3d,
    coalesce(ag.successful_3d, 0)::bigint as successful_3d,
    coalesce(ag.day0_requests, 0)::bigint as day0_requests,
    coalesce(ag.day0_successful, 0)::bigint as day0_successful,
    coalesce(ag.day1_requests, 0)::bigint as day1_requests,
    coalesce(ag.day1_successful, 0)::bigint as day1_successful,
    coalesce(ag.day2_requests, 0)::bigint as day2_requests,
    coalesce(ag.day2_successful, 0)::bigint as day2_successful
  from aggregated ag
  full join provider_filter pf on pf.provider = ag.provider
  where p_provider_ids is null or pf.provider is not null
  order by coalesce(pf.provider, ag.provider);
$function$;

CREATE OR REPLACE FUNCTION public.get_model_time_of_day_metrics (
  p_model_id text,
  p_days     integer DEFAULT 7
)
  RETURNS TABLE (
    hour                 integer,
    median_throughput    numeric,
    median_latency_ms    numeric,
    median_generation_ms numeric,
    samples              bigint
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
	with windowed as (
		select
			date_part('hour', created_at at time zone 'UTC')::int as hour,
			throughput,
			latency_ms,
			generation_ms
		from gateway_requests
		where model_id = p_model_id
			and created_at >= timezone('UTC', now()) - (interval '1 day' * p_days)
	)
	select
		hour,
		percentile_cont(0.5) within group (order by throughput) as median_throughput,
		percentile_cont(0.5) within group (order by latency_ms) as median_latency_ms,
		percentile_cont(0.5) within group (order by generation_ms) as median_generation_ms,
		count(*) as samples
	from windowed
	group by hour
	order by hour;
$function$;

CREATE OR REPLACE FUNCTION public.get_model_token_trajectory (
  p_model_id text
)
  RETURNS TABLE (
    release_date         timestamp with time zone,
    deprecation_date     timestamp with time zone,
    points               jsonb,
    token_milestones     jsonb,
    successor_milestones jsonb
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$with model_row as (
  select model_id, release_date, deprecation_date
  from private.v2_rpc_models_compat
  where model_id = p_model_id
  limit 1
),

-- Build the set of gateway_requests.model_id values to include
model_ids as (
  select p_model_id as model_id
  union
  select
    pm.provider_id || '/' || regexp_replace(pm.api_model_id, '^' || pm.provider_id || '/', '')
  from private.v2_rpc_routes_compat pm
  where pm.internal_model_id = p_model_id
),

anchors as (
  select
    mr.release_date,
    mr.deprecation_date,
    -- choose today's UTC day (not "greatest" vs release day; that could invert the range)
    date_trunc('day', now() at time zone 'utc') as today,
    date_trunc('day', mr.release_date) as start_day
  from model_row mr
),

daily_tokens as (
  select
    date_trunc('day', gr.created_at at time zone 'utc') as day,
    sum(
      coalesce(
        nullif((gr.usage ->> 'total_tokens')::numeric, 0),
        coalesce((gr.usage ->> 'input_tokens')::numeric, 0)
        + coalesce((gr.usage ->> 'output_tokens')::numeric, 0)
      )
    ) as tokens
  from private.v2_rpc_gateway_requests_compat gr
  cross join model_row mr
  where gr.model_id in (select model_id from model_ids)
    and mr.release_date is not null
    and gr.created_at >= mr.release_date
  group by 1
),

point_series as (
  select
    gs.day,
    coalesce(dt.tokens, 0) as tokens,
    sum(coalesce(dt.tokens, 0)) over (order by gs.day) as cumulative_tokens,
    floor(extract(epoch from (gs.day - (select release_date from model_row))) / 86400)::int as days_since_release
  from (
    select generate_series(
      (select start_day from anchors),
      (select today from anchors),
      interval '1 day'
    ) as day
  ) gs
  left join daily_tokens dt on dt.day = gs.day
),

points_json as (
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'date', to_char(day, 'YYYY-MM-DD"T"00:00:00.000Z'),
        'tokens', tokens,
        'cumulativeTokens', cumulative_tokens,
        'daysSinceRelease', days_since_release
      )
      order by day
    ),
    '[]'::jsonb
  ) as value
  from point_series
),

milestones as (
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'threshold', threshold,
        'reachedOn', reached_on,
        'daysSinceRelease', days_since_release
      )
      order by threshold
    ),
    '[]'::jsonb
  ) as value
  from (
    select
      threshold,
      (select to_char(ps.day, 'YYYY-MM-DD"T"00:00:00.000Z')
       from point_series ps
       where ps.cumulative_tokens >= threshold
       order by ps.day asc
       limit 1) as reached_on,
      (select ps.days_since_release
       from point_series ps
       where ps.cumulative_tokens >= threshold
       order by ps.day asc
       limit 1) as days_since_release
    from unnest(array[1000000, 10000000, 100000000, 1000000000]) as threshold
  ) m
),

successors as (
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'modelId', dm.model_id,
        'name', coalesce(dm.name, dm.model_id),
        'releaseDate', dm.release_date,
        'daysSinceRelease',
          case
            when mr.release_date is null or dm.release_date is null then null
            else floor(extract(epoch from (dm.release_date - mr.release_date)) / 86400)::int
          end
      )
    ),
    '[]'::jsonb
  ) as value
  from private.v2_rpc_models_compat dm
  cross join model_row mr
  where dm.previous_model_id = p_model_id
)

select
  (select release_date from model_row) as release_date,
  (select deprecation_date from model_row) as deprecation_date,
  (select value from points_json) as points,
  (select value from milestones) as token_milestones,
  (select value from successors) as successor_milestones
where (select release_date from model_row) is not null;$function$;

CREATE OR REPLACE FUNCTION public.get_model_usage_daily_breakdown (
  p_model_ids    text[],
  p_provider_ids text[] DEFAULT NULL::text[],
  p_since        date   DEFAULT (CURRENT_DATE - 30),
  p_until        date   DEFAULT CURRENT_DATE
)
  RETURNS TABLE (
    day_bucket                  date,
    model_id                    text,
    provider_id                 text,
    endpoint                    text,
    requests                    bigint,
    success_requests            bigint,
    failed_requests             bigint,
    neutral_requests            bigint,
    rate_limited_requests       bigint,
    total_tokens                bigint,
    input_tokens                bigint,
    output_tokens               bigint,
    reasoning_tokens            bigint,
    input_text_tokens           bigint,
    output_text_tokens          bigint,
    input_image_tokens          bigint,
    output_image_tokens         bigint,
    input_audio_tokens          bigint,
    output_audio_tokens         bigint,
    input_video_tokens          bigint,
    output_video_tokens         bigint,
    image_inputs                bigint,
    image_outputs               bigint,
    audio_inputs                bigint,
    audio_outputs               bigint,
    video_inputs                bigint,
    video_outputs               bigint,
    cached_read_tokens          bigint,
    cached_write_tokens         bigint,
    cached_read_text_tokens     bigint,
    cached_write_text_tokens    bigint,
    cached_write_text_tokens_5m bigint,
    cached_write_text_tokens_1h bigint,
    cached_read_image_tokens    bigint,
    cached_write_image_tokens   bigint,
    cached_read_audio_tokens    bigint,
    cached_write_audio_tokens   bigint,
    cached_read_video_tokens    bigint,
    cached_write_video_tokens   bigint,
    input_quad_tokens           bigint,
    output_quad_tokens          bigint,
    total_quad_tokens           bigint,
    text_quad_tokens            bigint,
    rerank_quad_tokens          bigint,
    embedding_quad_tokens       bigint,
    moderation_quad_tokens      bigint,
    ocr_quad_tokens             bigint,
    image_megapixels            numeric,
    audio_seconds               numeric,
    video_pixel_seconds         numeric,
    input_characters            bigint,
    output_characters           bigint,
    total_characters            bigint,
    total_cost_nanos            bigint,
    avg_latency_ms              numeric,
    avg_generation_ms           numeric,
    avg_throughput              numeric
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  with model_filter as (
    select distinct nullif(btrim(input.model_id), '') as model_id
    from unnest(coalesce(p_model_ids, array[]::text[])) as input(model_id)
    where nullif(btrim(input.model_id), '') is not null
  ),
  provider_filter as (
    select distinct nullif(btrim(input.provider_id), '') as provider_id
    from unnest(coalesce(p_provider_ids, array[]::text[])) as input(provider_id)
    where nullif(btrim(input.provider_id), '') is not null
  )
  select
    d.day_bucket,
    d.model_id,
    d.provider_id,
    d.endpoint,
    d.requests,
    d.success_requests,
    d.failed_requests,
    d.neutral_requests,
    d.rate_limited_requests,
    d.total_tokens,
    d.input_tokens,
    d.output_tokens,
    d.reasoning_tokens,
    d.input_text_tokens,
    d.output_text_tokens,
    d.input_image_tokens,
    d.output_image_tokens,
    d.input_audio_tokens,
    d.output_audio_tokens,
    d.input_video_tokens,
    d.output_video_tokens,
    d.image_inputs,
    d.image_outputs,
    d.audio_inputs,
    d.audio_outputs,
    d.video_inputs,
    d.video_outputs,
    d.cached_read_tokens,
    d.cached_write_tokens,
    d.cached_read_text_tokens,
    d.cached_write_text_tokens,
    d.cached_write_text_tokens_5m,
    d.cached_write_text_tokens_1h,
    d.cached_read_image_tokens,
    d.cached_write_image_tokens,
    d.cached_read_audio_tokens,
    d.cached_write_audio_tokens,
    d.cached_read_video_tokens,
    d.cached_write_video_tokens,
    d.input_quad_tokens,
    d.output_quad_tokens,
    d.total_quad_tokens,
    d.text_quad_tokens,
    d.rerank_quad_tokens,
    d.embedding_quad_tokens,
    d.moderation_quad_tokens,
    d.ocr_quad_tokens,
    d.image_megapixels,
    d.audio_seconds,
    d.video_pixel_seconds,
    d.input_characters,
    d.output_characters,
    d.total_characters,
    d.total_cost_nanos,
    case when d.latency_samples > 0 then round(d.latency_sum_ms::numeric / d.latency_samples::numeric, 2) else null end as avg_latency_ms,
    case when d.generation_samples > 0 then round(d.generation_sum_ms::numeric / d.generation_samples::numeric, 2) else null end as avg_generation_ms,
    case when d.throughput_samples > 0 then round(d.throughput_sum::numeric / d.throughput_samples::numeric, 2) else null end as avg_throughput
  from public.v2_rpc_gateway_model_usage_daily d
  where d.day_bucket >= p_since
    and d.day_bucket <= p_until
    and exists (
      select 1 from model_filter mf where mf.model_id = d.model_id
    )
    and (
      p_provider_ids is null
      or array_length(p_provider_ids, 1) is null
      or exists (
        select 1 from provider_filter pf where pf.provider_id = d.provider_id
      )
    )
  order by d.day_bucket asc, d.provider_id asc, d.endpoint asc;
$function$;

CREATE OR REPLACE FUNCTION public.get_monitor_history_filter_options()
  RETURNS TABLE (
    option_kind  text,
    option_value text,
    option_label text
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  (
    select
      'model'::text as option_kind,
      e.model_id as option_value,
      e.model_label as option_label
    from public.monitor_history_events e
    where e.model_id is not null
      and btrim(e.model_id) <> ''
    group by e.model_id, e.model_label
  )
  union all
  (
    select
      'provider'::text as option_kind,
      e.provider_slug as option_value,
      e.provider_label as option_label
    from public.monitor_history_events e
    where e.provider_slug is not null
      and btrim(e.provider_slug) <> ''
    group by e.provider_slug, e.provider_label
  )
  order by option_kind asc, option_label asc, option_value asc;
$function$;

CREATE OR REPLACE FUNCTION public.get_monitor_history_page (
  p_model         text    DEFAULT NULL::text,
  p_provider      text    DEFAULT NULL::text,
  p_change_kind   text    DEFAULT NULL::text,
  p_commit_offset integer DEFAULT 0,
  p_commit_limit  integer DEFAULT 18
)
  RETURNS TABLE (
    event_id       text,
    committed_at   timestamp with time zone,
    provider_kind  text,
    model_id       text,
    endpoint       text,
    field          text,
    old_value      jsonb,
    new_value      jsonb,
    percent_change double precision,
    action         text,
    commit_sha     text,
    entity_id      text,
    entity_type    text,
    org_id         text
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  with filtered as not materialized (
    select e.*
    from public.monitor_history_events e
    where (
      p_model is null
      or btrim(p_model) = ''
      or e.model_id = p_model
    )
      and (
        p_provider is null
        or btrim(p_provider) = ''
        or e.provider_slug = p_provider
      )
      and (
        p_change_kind is null
        or btrim(p_change_kind) = ''
        or p_change_kind = 'all'
        or e.change_kind = p_change_kind
      )
  ),
  visible_commits as (
    select
      filtered.commit_sha,
      max(filtered.committed_at) as committed_at
    from filtered
    group by filtered.commit_sha
    order by max(filtered.committed_at) desc, filtered.commit_sha desc
    offset greatest(coalesce(p_commit_offset, 0), 0)
    limit greatest(coalesce(p_commit_limit, 18), 1)
  )
  select
    e.event_id,
    e.committed_at,
    e.provider_kind,
    e.model_id,
    e.endpoint,
    e.field,
    e.old_value,
    e.new_value,
    e.percent_change,
    e.action,
    e.commit_sha,
    e.entity_id,
    e.entity_type,
    e.org_id
  from filtered e
  join visible_commits vc
    on vc.commit_sha = e.commit_sha
  order by
    vc.committed_at desc,
    e.committed_at desc,
    lower(coalesce(e.org_id, '')) asc,
    lower(coalesce(e.model_id, '')) asc,
    case coalesce(e.action, '')
      when 'added' then 0
      when 'changed' then 1
      when 'removed' then 2
      else 3
    end asc,
    case coalesce(e.entity_type, '')
      when 'organisation' then 0
      when 'model' then 1
      when 'family' then 2
      when 'api-provider' then 3
      when 'benchmark' then 4
      when 'alias' then 5
      when 'subscription-plan' then 6
      when 'pricing' then 7
      else 8
    end asc,
    case when e.endpoint is null or btrim(e.endpoint) = '' then 0 else 1 end asc,
    e.event_id asc;
$function$;

CREATE OR REPLACE FUNCTION public.get_monitor_history_stats (
  p_model       text DEFAULT NULL::text,
  p_provider    text DEFAULT NULL::text,
  p_change_kind text DEFAULT NULL::text
)
  RETURNS TABLE (
    total_changes bigint,
    total_commits bigint,
    generated_at  timestamp with time zone,
    last_sha      text,
    source_base   text,
    source_head   text
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  with filtered as (
    select e.*
    from public.monitor_history_events e
    where (
      p_model is null
      or btrim(p_model) = ''
      or e.model_id = p_model
    )
      and (
        p_provider is null
        or btrim(p_provider) = ''
        or e.provider_slug = p_provider
      )
      and (
        p_change_kind is null
        or btrim(p_change_kind) = ''
        or p_change_kind = 'all'
        or e.change_kind = p_change_kind
      )
  ),
  counts as (
    select
      count(*)::bigint as total_changes,
      count(distinct filtered.commit_sha)::bigint as total_commits
    from filtered
  ),
  state as (
    select
      s.generated_at,
      s.last_sha,
      s.source_base,
      s.source_head
    from public.monitor_history_sync_state s
    where s.sync_key = 'catalog'
    limit 1
  )
  select
    counts.total_changes,
    counts.total_commits,
    state.generated_at,
    state.last_sha,
    state.source_base,
    state.source_head
  from counts
  left join state on true;
$function$;

CREATE OR REPLACE FUNCTION public.get_monitor_model_rows (
  p_include_hidden boolean DEFAULT false
)
  RETURNS TABLE (
    model_id                     text,
    model_name                   text,
    model_release_date           date,
    model_retirement_date        date,
    model_status                 text,
    model_input_types            text,
    model_output_types           text,
    organisation_id              text,
    organisation_name            text,
    hidden                       boolean,
    provider_api_model_id        text,
    provider_id                  text,
    api_model_id                 text,
    provider_model_slug          text,
    is_active_gateway            boolean,
    input_modalities             text[],
    output_modalities            text[],
    quantization_scheme          text,
    context_length               integer,
    provider_max_output_tokens   integer,
    effective_from               timestamp with time zone,
    effective_to                 timestamp with time zone,
    capability_id                text,
    capability_params            jsonb,
    capability_status            text,
    capability_max_input_tokens  integer,
    capability_max_output_tokens integer,
    api_provider_name            text,
    provider_link                text,
    input_price                  numeric,
    output_price                 numeric,
    standard_input_price         numeric,
    standard_output_price        numeric,
    standard_input_price_label   text,
    standard_input_price_unit    text,
    standard_output_price_label  text,
    standard_output_price_unit   text,
    from_price                   numeric,
    from_price_unit              text,
    pricing_tier                 text,
    is_free_variant              boolean,
    weekly_tokens_model          bigint,
    weekly_tokens_model_provider bigint,
    weekly_throughput_model      numeric,
    weekly_latency_model         numeric
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  with normalized_weekly_requests as (
    select
      coalesce(
        nullif(gr.canonical_model_id, ''),
        public.resolve_public_model_id(gr.model_id, gr.provider),
        nullif(gr.model_id, '')
      ) as canonical_model_id,
      coalesce(nullif(gr.provider, ''), 'unknown') as provider_id,
      public.gateway_usage_total_tokens(gr.usage)::bigint as total_tokens,
      gr.throughput::numeric as throughput,
      gr.latency_ms::numeric as latency_ms
    from private.v2_rpc_gateway_requests_compat gr
    where gr.created_at >= now() - interval '7 days'
  ),
  weekly_model_usage as (
    select
      r.canonical_model_id as model_id,
      sum(r.total_tokens)::bigint as weekly_tokens_model,
      round(avg(r.throughput), 2) as weekly_throughput_model,
      round(avg(r.latency_ms), 0) as weekly_latency_model
    from normalized_weekly_requests r
    where r.canonical_model_id is not null
    group by r.canonical_model_id
  ),
  weekly_model_provider_usage as (
    select
      r.canonical_model_id as model_id,
      r.provider_id,
      sum(r.total_tokens)::bigint as weekly_tokens_model_provider
    from normalized_weekly_requests r
    where r.canonical_model_id is not null
      and r.provider_id <> 'unknown'
    group by r.canonical_model_id, r.provider_id
  ),
  active_pricing_rules as (
    select
      pr.model_key,
      pr.meter,
      pr.unit,
      pr.unit_size,
      pr.price_per_unit,
      coalesce(nullif(lower(pr.pricing_plan), ''), 'standard') as pricing_plan,
      case
        when lower(coalesce(pr.meter, '')) like '%token%'
          or lower(coalesce(pr.unit, '')) in ('token', 'tokens')
          then pr.price_per_unit * (1000000 / nullif(pr.unit_size, 0))
        when lower(coalesce(pr.unit, '')) in ('minute', 'minutes', 'min', 'mins', 'm')
          then pr.price_per_unit / nullif(pr.unit_size, 0) / 60
        when lower(coalesce(pr.unit, '')) in ('hour', 'hours', 'hr', 'hrs', 'h')
          then pr.price_per_unit / nullif(pr.unit_size, 0) / 3600
        else pr.price_per_unit / nullif(pr.unit_size, 0)
      end as display_price,
      case
        when lower(coalesce(pr.meter, '')) like '%token%'
          or lower(coalesce(pr.unit, '')) in ('token', 'tokens')
          then '1M tokens'
        when lower(coalesce(pr.unit, '')) in ('minute', 'minutes', 'min', 'mins', 'm')
          then 'second'
        when lower(coalesce(pr.unit, '')) in ('hour', 'hours', 'hr', 'hrs', 'h')
          then 'second'
        when lower(coalesce(pr.unit, '')) in ('second', 'seconds', 'sec', 'secs', 's')
          then 'second'
        when lower(coalesce(pr.unit, '')) in ('image', 'images')
          then 'image'
        when lower(coalesce(pr.unit, '')) in ('video', 'videos')
          then 'video'
        when lower(coalesce(pr.unit, '')) in ('character', 'characters', 'char', 'chars')
          then 'character'
        else nullif(lower(coalesce(pr.unit, '')), '')
      end as display_unit,
      case
        when lower(coalesce(pr.meter, '')) in ('input_text_tokens', 'input_tokens') then 'input'
        when lower(coalesce(pr.meter, '')) = 'input_audio_tokens' then 'input'
        when lower(coalesce(pr.meter, '')) = 'input_image_tokens' then 'input'
        when lower(coalesce(pr.meter, '')) = 'input_video_tokens' then 'input'
        when lower(coalesce(pr.meter, '')) in ('output_text_tokens', 'output_tokens') then 'output'
        when lower(coalesce(pr.meter, '')) = 'output_audio_tokens' then 'output'
        when lower(coalesce(pr.meter, '')) = 'output_image_tokens' then 'output'
        when lower(coalesce(pr.meter, '')) = 'output_video_tokens' then 'output'
        else null
      end as standard_side,
      case
        when lower(coalesce(pr.meter, '')) in ('input_text_tokens', 'input_tokens') then 'Text Input'
        when lower(coalesce(pr.meter, '')) = 'input_audio_tokens' then 'Audio Input'
        when lower(coalesce(pr.meter, '')) = 'input_image_tokens' then 'Image Input'
        when lower(coalesce(pr.meter, '')) = 'input_video_tokens' then 'Video Input'
        when lower(coalesce(pr.meter, '')) in ('output_text_tokens', 'output_tokens') then 'Text Output'
        when lower(coalesce(pr.meter, '')) = 'output_audio_tokens' then 'Audio Output'
        when lower(coalesce(pr.meter, '')) = 'output_image_tokens' then 'Image Output'
        when lower(coalesce(pr.meter, '')) = 'output_video_tokens' then 'Video Output'
        else null
      end as standard_label,
      case
        when lower(coalesce(pr.meter, '')) in ('input_text_tokens', 'input_tokens', 'output_text_tokens', 'output_tokens') then 0
        when lower(coalesce(pr.meter, '')) in ('input_audio_tokens', 'output_audio_tokens') then 1
        when lower(coalesce(pr.meter, '')) in ('input_image_tokens', 'output_image_tokens') then 2
        when lower(coalesce(pr.meter, '')) in ('input_video_tokens', 'output_video_tokens') then 3
        else 99
      end as standard_priority
    from private.v2_rpc_pricing_compat pr
    where (pr.effective_from is null or pr.effective_from <= now())
      and (pr.effective_to is null or now() < pr.effective_to)
  ),
  provider_rows as (
    select
      pm.*,
      coalesce(
        nullif(btrim(pm.model_id), ''),
        public.resolve_public_model_id(nullif(btrim(pm.api_model_id), ''), pm.provider_id),
        nullif(btrim(pm.api_model_id), '')
      ) as canonical_model_id
    from private.v2_rpc_routes_compat pm
    where pm.api_model_id is not null
      and btrim(pm.api_model_id) <> ''
  ),
  ranked_standard_rules as (
    select
      apr.model_key,
      apr.standard_side,
      apr.standard_label,
      apr.display_unit,
      apr.display_price,
      row_number() over (
        partition by apr.model_key, apr.standard_side
        order by apr.standard_priority asc, apr.display_price asc nulls last, apr.standard_label asc
      ) as row_num
    from active_pricing_rules apr
    where apr.pricing_plan = 'standard'
      and apr.standard_side is not null
      and apr.display_price is not null
      and apr.display_unit is not null
  ),
  standard_price_choices as (
    select
      rsr.model_key,
      max(case when rsr.standard_side = 'input' and rsr.row_num = 1 then rsr.display_price end) as standard_input_price,
      max(case when rsr.standard_side = 'output' and rsr.row_num = 1 then rsr.display_price end) as standard_output_price,
      max(case when rsr.standard_side = 'input' and rsr.row_num = 1 then rsr.standard_label end) as standard_input_price_label,
      max(case when rsr.standard_side = 'input' and rsr.row_num = 1 then rsr.display_unit end) as standard_input_price_unit,
      max(case when rsr.standard_side = 'output' and rsr.row_num = 1 then rsr.standard_label end) as standard_output_price_label,
      max(case when rsr.standard_side = 'output' and rsr.row_num = 1 then rsr.display_unit end) as standard_output_price_unit
    from ranked_standard_rules rsr
    group by rsr.model_key
  ),
  pricing_summary as (
    select
      apr.model_key,
      min(apr.price_per_unit * (1000000 / nullif(apr.unit_size, 0))) filter (
        where apr.pricing_plan = 'standard'
          and lower(coalesce(apr.meter, '')) in ('input_text_tokens', 'input_tokens')
      ) as input_price,
      min(apr.price_per_unit * (1000000 / nullif(apr.unit_size, 0))) filter (
        where apr.pricing_plan = 'standard'
          and lower(coalesce(apr.meter, '')) in ('output_text_tokens', 'output_tokens')
      ) as output_price,
      spc.standard_input_price,
      spc.standard_output_price,
      spc.standard_input_price_label,
      spc.standard_input_price_unit,
      spc.standard_output_price_label,
      spc.standard_output_price_unit,
      case
        when count(distinct apr.display_unit) filter (
          where apr.display_price is not null
            and apr.display_unit is not null
        ) = 1
          then min(apr.display_price) filter (
            where apr.display_price is not null
              and apr.display_unit is not null
          )
        else null
      end as from_price,
      case
        when count(distinct apr.display_unit) filter (
          where apr.display_price is not null
            and apr.display_unit is not null
        ) = 1
          then min(apr.display_unit) filter (
            where apr.display_price is not null
              and apr.display_unit is not null
          )
        else null
      end as from_price_unit,
      case
        when apr.model_key like '%:free:%' then 'free'
        when bool_or(apr.pricing_plan = 'standard') then 'standard'
        else min(apr.pricing_plan)
      end as pricing_tier
    from active_pricing_rules apr
    left join standard_price_choices spc
      on spc.model_key = apr.model_key
    group by
      apr.model_key,
      spc.standard_input_price,
      spc.standard_output_price,
      spc.standard_input_price_label,
      spc.standard_input_price_unit,
      spc.standard_output_price_label,
      spc.standard_output_price_unit
  )
  select
    pm.canonical_model_id as model_id,
    dm.name as model_name,
    dm.release_date as model_release_date,
    dm.retirement_date as model_retirement_date,
    dm.status as model_status,
    dm.input_types as model_input_types,
    dm.output_types as model_output_types,
    dm.organisation_id,
    org.name as organisation_name,
    coalesce(dm.hidden, false) as hidden,
    pm.provider_api_model_id,
    pm.provider_id,
    pm.api_model_id,
    pm.provider_model_slug,
    pm.is_active_gateway,
    pm.input_modalities,
    pm.output_modalities,
    pm.quantization_scheme,
    pm.context_length,
    pm.max_output_tokens as provider_max_output_tokens,
    pm.effective_from,
    pm.effective_to,
    cap.capability_id,
    cap.params as capability_params,
    cap.status as capability_status,
    cap.max_input_tokens as capability_max_input_tokens,
    cap.max_output_tokens as capability_max_output_tokens,
    provider.api_provider_name,
    provider.link as provider_link,
    ps.input_price,
    ps.output_price,
    ps.standard_input_price,
    ps.standard_output_price,
    ps.standard_input_price_label,
    ps.standard_input_price_unit,
    ps.standard_output_price_label,
    ps.standard_output_price_unit,
    ps.from_price,
    ps.from_price_unit,
    coalesce(ps.pricing_tier, case when pm.api_model_id like '%:free%' then 'free' else 'standard' end) as pricing_tier,
    (pm.api_model_id like '%:free%') as is_free_variant,
    wmu.weekly_tokens_model,
    wmpu.weekly_tokens_model_provider,
    wmu.weekly_throughput_model,
    wmu.weekly_latency_model
  from provider_rows pm
  join private.v2_rpc_capabilities_compat cap
    on cap.provider_api_model_id = pm.provider_api_model_id
  left join private.v2_rpc_models_compat dm
    on dm.model_id = pm.canonical_model_id
  left join private.v2_rpc_labs_compat org
    on org.organisation_id = dm.organisation_id
  left join private.v2_rpc_providers_compat provider
    on provider.api_provider_id = pm.provider_id
  left join pricing_summary ps
    on ps.model_key = pm.provider_id || ':' || pm.api_model_id || ':' || cap.capability_id
  left join weekly_model_usage wmu
    on wmu.model_id = pm.canonical_model_id
  left join weekly_model_provider_usage wmpu
    on wmpu.model_id = pm.canonical_model_id
   and wmpu.provider_id = pm.provider_id
  where (p_include_hidden or coalesce(dm.hidden, false) = false)
  order by pm.provider_api_model_id asc, cap.capability_id asc;
$function$;

REVOKE ALL ON FUNCTION "public"."get_monitor_model_rows"(boolean) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.get_monthly_release_share_all (
  p_months integer DEFAULT 12
)
  RETURNS TABLE (
    month_start     date,
    iso             text,
    releases        integer,
    global_releases integer
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
with base as (
    select
        date_trunc('month', coalesce(m.release_date, m.announcement_date))::date as month_start,
        coalesce(o.country_code, '') as iso
    from private.v2_rpc_models_compat m
    join private.v2_rpc_labs_compat o on o.organisation_id = m.organisation_id
    where coalesce(m.release_date, m.announcement_date) is not null
),
bounds as (
    select date_trunc('month', now())::date - (interval '1 month' * (p_months - 1)) as min_month
),
monthly as (
    select
        month_start,
        lower(iso) as iso,
        count(*)::int as releases
    from base
    where month_start >= (select min_month from bounds)
    group by month_start, iso
)
select
    m.month_start,
    m.iso,
    m.releases,
    sum(m.releases) over(partition by m.month_start) as global_releases
from monthly m
order by m.month_start, m.iso;
$function$;

CREATE OR REPLACE FUNCTION public.get_private_geography_usage (
  p_workspace_id uuid,
  p_from         timestamp with time zone,
  p_to           timestamp with time zone
)
  RETURNS TABLE (
    country_code       text,
    continent_code     text,
    requests           bigint,
    tokens             numeric,
    spend_nanos        numeric,
    successes          bigint,
    average_latency_ms numeric
  )
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  with scoped_facts as materialized (
    select
      f.request_event_id,
      f.edge_country,
      f.edge_continent,
      f.cost_nanos,
      f.success,
      f.latency_ms
    from public.v2_request_facts f
    where f.workspace_id = p_workspace_id
      and f.occurred_at >= p_from
      and f.occurred_at < p_to
      and f.edge_country is not null
  ),
  request_tokens as (
    select
      f.request_event_id,
      coalesce(
        nullif(sum(u.quantity) filter (
          where u.meter_key in ('input_tokens', 'output_tokens')
        ), 0),
        sum(u.quantity) filter (
          where u.meter_key in (
            'input_text_tokens', 'output_text_tokens',
            'input_image_tokens', 'output_image_tokens',
            'input_audio_tokens', 'output_audio_tokens',
            'input_video_tokens', 'output_video_tokens'
          )
        ),
        0
      ) as tokens
    from scoped_facts f
    left join public.v2_request_usage u
      on u.request_event_id = f.request_event_id
    group by f.request_event_id
  )
  select
    f.edge_country,
    max(f.edge_continent),
    count(*)::bigint,
    coalesce(sum(t.tokens), 0),
    coalesce(sum(f.cost_nanos), 0)::numeric,
    count(*) filter (where f.success)::bigint,
    avg(f.latency_ms)::numeric
  from scoped_facts f
  left join request_tokens t on t.request_event_id = f.request_event_id
  group by f.edge_country
  order by count(*) desc, f.edge_country;
$function$;

REVOKE ALL ON FUNCTION "public"."get_private_geography_usage"(uuid, timestamp WITH time zone, timestamp WITH time zone) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.get_private_usage_facets (
  p_workspace_id uuid,
  p_from         timestamp with time zone,
  p_to           timestamp with time zone
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
select coalesce(jsonb_agg(to_jsonb(facet) order by canonical_model_id, provider, app_id), '[]'::jsonb)
from (
  select distinct usage.model_slug as canonical_model_id, route.provider_slug as provider, usage.app_id
  from public.v2_private_usage_daily usage
  left join public.v2_model_provider_routes route using (provider_model_id)
  where usage.workspace_id = p_workspace_id
    and usage.usage_date >= p_from::date and usage.usage_date <= p_to::date
    and usage.usage_date::timestamptz >= p_from
    and usage.usage_date::timestamptz <= p_to
) facet;
$function$;

REVOKE ALL ON FUNCTION "public"."get_private_usage_facets"(uuid, timestamp WITH time zone, timestamp WITH time zone) FROM PUBLIC, "anon";

CREATE OR REPLACE FUNCTION public.get_private_usage_summary (
  p_workspace_id uuid,
  p_from         timestamp with time zone,
  p_to           timestamp with time zone
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
with scoped as materialized (
  select coalesce(nullif(usage.model_slug, ''), 'unknown') as model,
    coalesce(nullif(route.provider_slug, ''), 'unknown') as provider,
    usage.requests, usage.cost_nanos, usage.latency_sum_ms, usage.latency_count
  from public.v2_private_usage_daily usage
  left join public.v2_model_provider_routes route using (provider_model_id)
  where usage.workspace_id = p_workspace_id
    -- Native date predicates use the existing workspace/date index. Retain
    -- timestamp comparisons to preserve partial-day and session-timezone behavior.
    and usage.usage_date >= p_from::date and usage.usage_date <= p_to::date
    and usage.usage_date::timestamptz >= p_from
    and usage.usage_date::timestamptz <= p_to
), models as (
  select model, sum(requests) as requests, sum(cost_nanos) / 1e9 as cost,
    (sum(latency_sum_ms) filter (where latency_count > 0 and latency_sum_ms > 0))::numeric
      / nullif(sum(latency_count) filter (where latency_count > 0 and latency_sum_ms > 0), 0) as speed_ms
  from scoped group by model
), providers as (
  select provider, sum(requests) as requests from scoped group by provider
)
select jsonb_build_object(
  'topModel', (select jsonb_build_object('name', model, 'requests', requests) from models order by requests desc, model limit 1),
  'topProvider', (select jsonb_build_object('name', provider, 'requests', requests) from providers order by requests desc, provider limit 1),
  'mostExpensive', (select jsonb_build_object('name', model, 'cost', cost) from models order by cost desc, model limit 1),
  'fastestModel', (select jsonb_build_object('name', model, 'speedMs', round(speed_ms)) from models where speed_ms > 0 order by speed_ms, model limit 1)
);
$function$;

REVOKE ALL ON FUNCTION "public"."get_private_usage_summary"(uuid, timestamp WITH time zone, timestamp WITH time zone) FROM PUBLIC, "anon";

CREATE OR REPLACE FUNCTION public.get_provider_token_usage (
  provider_id text,
  since_ts    timestamp with time zone
)
  RETURNS TABLE (
    total_tokens bigint
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
	select coalesce(
		sum(
			NULLIF(
				usage->>'total_tokens',
				''
			)::bigint
		),
		0
	) as total_tokens
	from gateway_requests
	where provider = provider_id
	  and created_at >= since_ts;
$function$;

CREATE OR REPLACE FUNCTION public.get_public_app_groups (
  p_references text[]
)
  RETURNS TABLE (
    reference      text,
    app_id         text,
    app_name       text,
    app_url        text,
    app_image_url  text,
    app_category   text,
    app_is_active  boolean,
    app_is_public  boolean,
    app_last_seen  timestamp with time zone,
    app_created_at timestamp with time zone,
    app_updated_at timestamp with time zone,
    member_ids     text[],
    public_slug    text
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  with groups as (
    select aa.*, array[aa.id::text] as member_ids,
      public.api_app_public_slug(aa.title, aa.url, aa.id::text) as public_slug
    from public.api_apps aa
    where aa.is_public = true and aa.is_active = true
  ), requested as (
    select unnest(coalesce(p_references, array[]::text[])) as reference
  )
  select requested.reference, groups.id::text, groups.title, groups.url,
    groups.image_url, groups.category, groups.is_active, groups.is_public,
    groups.last_seen, groups.created_at, groups.updated_at, groups.member_ids,
    groups.public_slug
  from requested
  join groups on requested.reference = groups.public_slug
    or requested.reference = groups.id::text;
$function$;

REVOKE ALL ON FUNCTION "public"."get_public_app_groups"(text[]) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.get_public_catalog_pricing_summaries()
  RETURNS TABLE (
    api_model_id                       text,
    lowest_input_price                 numeric,
    lowest_output_price                numeric,
    lowest_standard_input_price        numeric,
    lowest_standard_output_price       numeric,
    lowest_standard_input_price_label  text,
    lowest_standard_input_price_unit   text,
    lowest_standard_output_price_label text,
    lowest_standard_output_price_unit  text,
    lowest_from_price                  numeric,
    lowest_from_price_unit             text,
    pricing_detail_rows                jsonb
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public'
  AS $function$
  with unexpired as (
    select
      regexp_replace(rule.model_key, '^[^:]+:(.*):[^:]+$', '\1') as api_model_id,
      lower(coalesce(rule.meter, '')) as meter,
      lower(coalesce(rule.unit, '')) as unit,
      rule.note,
      rule.unit_size::numeric as unit_size,
      rule.price_per_unit::numeric as price_per_unit,
      coalesce(rule.effective_from <= now(), true) as is_active
    from private.v2_rpc_pricing_compat rule
    where lower(coalesce(rule.pricing_plan, 'standard')) = 'standard'
      and (rule.effective_to is null or rule.effective_to > now())
      and rule.model_key ~ '^[^:]+:.+:[^:]+$'
  ),
  eligible as (
    select
      unexpired.*,
      bool_or(is_active) over (partition by api_model_id) as has_active
    from unexpired
  ),
  normalized as (
    select
      eligible.*,
      case
        when note ~* '\$[0-9.]+\s*/\s*minute' then (substring(note from '\$([0-9.]+)\s*/\s*minute'))::numeric
        when price_per_unit is null or unit_size is null or unit_size <= 0 then null
        when meter like '%token%' or unit in ('token', 'tokens') then price_per_unit * (1000000::numeric / unit_size)
        when unit in ('minute', 'minutes', 'min', 'mins', 'm') then price_per_unit / unit_size / 60
        when unit in ('hour', 'hours', 'hr', 'hrs', 'h') then price_per_unit / unit_size / 3600
        else price_per_unit / unit_size
      end as display_price,
      case
        when note ~* '\$[0-9.]+\s*/\s*minute' then 'minute'
        when meter like '%token%' or unit in ('token', 'tokens') then '1M tokens'
        when unit in ('minute', 'minutes', 'min', 'mins', 'm', 'hour', 'hours', 'hr', 'hrs', 'h', 'second', 'seconds', 'sec', 'secs', 's') then 'second'
        when unit in ('image', 'images') then 'image'
        when unit in ('video', 'videos') then 'video'
        when unit in ('character', 'characters', 'char', 'chars') then 'character'
        else nullif(unit, '')
      end as display_unit,
      case
        when meter in ('input_text_tokens', 'input_tokens') then 'Text Input'
        when meter in ('input_audio_tokens', 'input_audio') then 'Audio Input'
        when meter in ('input_image_tokens', 'input_image') then 'Image Input'
        when meter in ('input_video_tokens', 'input_video') then 'Video Input'
        when meter in ('output_text_tokens', 'output_tokens') then 'Text Output'
        when meter in ('output_audio_tokens', 'output_audio', 'output_audio_seconds') then 'Audio Output'
        when meter in ('output_image_tokens', 'output_image') then 'Image Output'
        when meter in ('output_video_tokens', 'output_video', 'output_video_seconds') then 'Video Output'
        else null
      end as display_label,
      case
        when meter in ('input_text_tokens', 'input_tokens', 'input_audio_tokens', 'input_audio', 'input_image_tokens', 'input_image', 'input_video_tokens', 'input_video') then 'input'
        when meter in ('output_text_tokens', 'output_tokens', 'output_audio_tokens', 'output_audio', 'output_audio_seconds', 'output_image_tokens', 'output_image', 'output_video_tokens', 'output_video', 'output_video_seconds') then 'output'
        else null
      end as side
    from eligible
    where is_active or not has_active
  ),
  grouped as (
    select
      api_model_id,
      min(display_price) filter (where side = 'input') as input_price,
      min(display_price) filter (where side = 'output') as output_price,
      (array_agg(display_label order by display_price) filter (where side = 'input' and display_price is not null and display_label is not null))[1] as input_label,
      (array_agg(display_unit order by display_price) filter (where side = 'input' and display_price is not null and display_unit is not null))[1] as input_unit,
      (array_agg(display_label order by display_price) filter (where side = 'output' and display_price is not null and display_label is not null))[1] as output_label,
      (array_agg(display_unit order by display_price) filter (where side = 'output' and display_price is not null and display_unit is not null))[1] as output_unit,
      min(display_price) as from_price,
      case when count(distinct display_unit) filter (where display_price is not null and display_unit is not null) = 1
        then min(display_unit) filter (where display_price is not null and display_unit is not null)
        else null
      end as from_unit
    from normalized
    where display_price is not null and display_unit is not null
    group by api_model_id
  )
  select
    grouped.api_model_id,
    grouped.input_price,
    grouped.output_price,
    grouped.input_price,
    grouped.output_price,
    grouped.input_label,
    grouped.input_unit,
    grouped.output_label,
    grouped.output_unit,
    case when grouped.from_unit is not null then grouped.from_price else null end,
    grouped.from_unit,
    coalesce(details.rows, '[]'::jsonb)
  from grouped
  left join lateral (
    select jsonb_agg(
      jsonb_build_object(
        'label', detail.display_label,
        'value',
          case
            when detail.display_price = 0 then '$0'
            when detail.display_price < 0.001 then '$' || to_char(detail.display_price, 'FM999999999990.0000')
            when detail.display_price < 0.1 then '$' || to_char(detail.display_price, 'FM999999999990.000')
            when detail.display_price < 1 then '$' || to_char(detail.display_price, 'FM999999999990.00')
            else '$' || trim(trailing '.' from trim(trailing '0' from to_char(detail.display_price, 'FM999999999990.00')))
          end || ' / ' || detail.display_unit
      ) order by detail.display_price, detail.display_label
    ) as rows
    from (
      select distinct display_label, display_price, display_unit
      from normalized
      where normalized.api_model_id = grouped.api_model_id
        and side is not null
        and display_label is not null
        and display_price is not null
        and display_unit is not null
      order by display_price, display_label
      limit 6
    ) detail
  ) details on true;
$function$;

CREATE OR REPLACE FUNCTION public.get_public_compare_realtime (
  p_model_ids      text[],
  p_window_minutes integer DEFAULT 30
)
  RETURNS TABLE (
    model_id                text,
    realtime_requests       bigint,
    realtime_latency_p50    numeric,
    realtime_throughput_p50 numeric
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public'
  AS $function$
  with selected as (
    select model.model_id
    from private.v2_rpc_models_compat model
    where model.hidden = false
      and model.model_id = any(coalesce(p_model_ids, array[]::text[]))
  ),
  aliases as (
    select selected.model_id, selected.model_id as alias_id from selected
    union
    select selected.model_id, provider_model.model_id
    from selected
    join private.v2_rpc_routes_compat provider_model
      on provider_model.model_id = selected.model_id or provider_model.api_model_id = selected.model_id
    where provider_model.model_id is not null and btrim(provider_model.model_id) <> ''
    union
    select selected.model_id, provider_model.api_model_id
    from selected
    join private.v2_rpc_routes_compat provider_model
      on provider_model.model_id = selected.model_id or provider_model.api_model_id = selected.model_id
    where provider_model.api_model_id is not null and btrim(provider_model.api_model_id) <> ''
  ),
  realtime_samples as (
    select
      alias.model_id,
      request.latency_ms::numeric as latency_ms,
      case
        when request.throughput > 0 then request.throughput::numeric
        when request.generation_ms > 0 then
          coalesce(
            case when request.usage->>'output_tokens' ~ '^[0-9]+(?:\.[0-9]+)?$' then (request.usage->>'output_tokens')::numeric end,
            case when request.usage->>'completion_tokens' ~ '^[0-9]+(?:\.[0-9]+)?$' then (request.usage->>'completion_tokens')::numeric end,
            case when request.usage->>'generated_tokens' ~ '^[0-9]+(?:\.[0-9]+)?$' then (request.usage->>'generated_tokens')::numeric end,
            case when request.usage->>'response_tokens' ~ '^[0-9]+(?:\.[0-9]+)?$' then (request.usage->>'response_tokens')::numeric end,
            case when request.usage->>'total_tokens' ~ '^[0-9]+(?:\.[0-9]+)?$' then (request.usage->>'total_tokens')::numeric end
          ) * 1000 / request.generation_ms
        else null
      end as throughput
    from aliases alias
    join private.v2_rpc_gateway_requests_compat request on request.model_id = alias.alias_id
    where request.created_at >= now() - make_interval(mins => greatest(1, least(coalesce(p_window_minutes, 30), 1440)))
      and request.created_at <= now()
  ),
  realtime as (
    select
      sample.model_id,
      count(*)::bigint as requests,
      percentile_cont(0.5) within group (order by sample.latency_ms) filter (where sample.latency_ms > 0)::numeric as latency_p50,
      percentile_cont(0.5) within group (order by sample.throughput) filter (where sample.throughput > 0)::numeric as throughput_p50
    from realtime_samples sample
    group by sample.model_id
  )
  select
    selected.model_id,
    coalesce(realtime.requests, 0),
    realtime.latency_p50,
    realtime.throughput_p50
  from selected
  left join realtime on realtime.model_id = selected.model_id
  order by array_position(p_model_ids, selected.model_id);
$function$;

CREATE OR REPLACE FUNCTION public.get_public_context_length_distribution (
  p_days           integer DEFAULT 30,
  p_min_requests   bigint  DEFAULT 1,
  p_min_workspaces bigint  DEFAULT 1
)
  RETURNS TABLE (
    bucket_key      text,
    bucket_label    text,
    bucket_order    integer,
    min_tokens      bigint,
    max_tokens      bigint,
    requests        bigint,
    share_percent   numeric,
    workspace_count bigint
  )
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  with scoped_requests as materialized (
    select fact.request_event_id, fact.workspace_id
    from public.v2_request_facts fact
    where fact.occurred_at >= now() - make_interval(days => greatest(1, least(coalesce(p_days, 30), 365)))
  ),
  per_request as (
    select
      request.request_event_id,
      request.workspace_id,
      coalesce(sum(usage.quantity) filter (
        where usage.meter_key in ('input_tokens', 'input_text_tokens', 'prompt_tokens')
      ), 0)::bigint as input_tokens
    from scoped_requests request
    left join public.v2_request_usage usage
      on usage.request_event_id = request.request_event_id
     and usage.meter_key in ('input_tokens', 'input_text_tokens', 'prompt_tokens')
    group by request.request_event_id, request.workspace_id
  ),
  eligible as (
    select * from per_request where input_tokens > 0
  ),
  totals as (
    select count(*)::bigint as requests, count(distinct workspace_id)::bigint as workspaces
    from eligible
  ),
  bucketed as (
    select
      workspace_id,
      case
        when input_tokens < 4096 then 'under_4k'
        when input_tokens < 16384 then '4k_16k'
        when input_tokens < 32768 then '16k_32k'
        when input_tokens < 65536 then '32k_64k'
        when input_tokens < 131072 then '64k_128k'
        else '128k_plus'
      end as bucket_key
    from eligible
  ),
  buckets(bucket_key, bucket_label, bucket_order, min_tokens, max_tokens) as (
    values
      ('under_4k', 'Under 4K', 1, 0::bigint, 4095::bigint),
      ('4k_16k', '4Kâ€“16K', 2, 4096::bigint, 16383::bigint),
      ('16k_32k', '16Kâ€“32K', 3, 16384::bigint, 32767::bigint),
      ('32k_64k', '32Kâ€“64K', 4, 32768::bigint, 65535::bigint),
      ('64k_128k', '64Kâ€“128K', 5, 65536::bigint, 131071::bigint),
      ('128k_plus', '128K+', 6, 131072::bigint, null::bigint)
  ),
  counts as (
    select bucket_key, count(*)::bigint as requests, count(distinct workspace_id)::bigint as workspace_count
    from bucketed
    group by bucket_key
  )
  select
    bucket.bucket_key,
    bucket.bucket_label,
    bucket.bucket_order,
    bucket.min_tokens,
    bucket.max_tokens,
    coalesce(counts.requests, 0)::bigint,
    case when total.requests > 0
      then round(coalesce(counts.requests, 0)::numeric / total.requests::numeric * 100, 2)
      else 0
    end,
    coalesce(counts.workspace_count, 0)::bigint
  from buckets bucket
  cross join totals total
  left join counts on counts.bucket_key = bucket.bucket_key
  where total.requests >= greatest(coalesce(p_min_requests, 1), 1)
    and total.workspaces >= greatest(coalesce(p_min_workspaces, 1), 1)
  order by bucket.bucket_order;
$function$;

REVOKE ALL ON FUNCTION "public"."get_public_context_length_distribution"(integer, bigint, bigint) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.get_public_country_summaries()
  RETURNS TABLE (
    iso                 text,
    total_organisations bigint,
    total_models        bigint
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public'
  AS $function$
  select
    upper(btrim(organisation.country_code)) as iso,
    count(distinct organisation.organisation_id)::bigint as total_organisations,
    count(model.model_id)::bigint as total_models
  from private.v2_rpc_labs_compat organisation
  left join private.v2_rpc_models_compat model
    on model.organisation_id = organisation.organisation_id
    and model.hidden = false
  where organisation.country_code is not null
    and btrim(organisation.country_code) <> ''
  group by upper(btrim(organisation.country_code))
  order by total_models desc, iso;
$function$;

CREATE OR REPLACE FUNCTION public.get_public_fastest_models (
  p_days  integer DEFAULT 30,
  p_limit integer DEFAULT 20
)
  RETURNS TABLE (
    model_id           text,
    provider           text,
    requests           bigint,
    cost_per_1m_tokens numeric,
    median_latency_ms  numeric,
    p95_latency_ms     numeric,
    median_throughput  numeric,
    success_rate       numeric
  )
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select performance.*
  from public.get_public_model_performance(
    greatest(1, least(coalesce(p_days, 30), 365)) * 24,
    0
  ) performance
  where performance.median_throughput is not null
     or performance.median_latency_ms is not null
  order by performance.requests desc
  limit greatest(1, least(coalesce(p_limit, 20), 100));
$function$;

REVOKE ALL ON FUNCTION "public"."get_public_fastest_models"(integer, integer) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.get_public_free_router_overview()
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO 'public'
  AS $function$
  with active_free_rules as (
    select distinct
      split_part(rule.model_key, ':', 1) as provider_id,
      regexp_replace(regexp_replace(rule.model_key, '^[^:]+:', ''), ':[^:]+$', '') as api_model_id
    from private.v2_rpc_pricing_compat rule
    where rule.model_key ilike '%:free:%'
      and now() >= coalesce(rule.effective_from, '-infinity'::timestamptz)
      and now() < coalesce(rule.effective_to, 'infinity'::timestamptz)
  ),
  eligible as (
    select
      coalesce(nullif(provider_model.model_id, ''), provider_model.api_model_id) as model_id,
      provider_model.api_model_id,
      provider_model.provider_id,
      provider_model.input_modalities,
      provider_model.output_modalities
    from private.v2_rpc_routes_compat provider_model
    join active_free_rules rule
      on rule.provider_id = provider_model.provider_id
      and rule.api_model_id = provider_model.api_model_id
    where provider_model.is_active_gateway = true
      and now() >= coalesce(provider_model.effective_from, '-infinity'::timestamptz)
      and now() < coalesce(provider_model.effective_to, 'infinity'::timestamptz)
  ),
  eligible_models as (
    select
      eligible.model_id,
      case when count(distinct eligible.api_model_id) = 1 then min(eligible.api_model_id) else eligible.model_id end as display_api_model_id,
      count(distinct eligible.provider_id)::bigint as provider_count,
      coalesce((select array_agg(distinct value order by value) from eligible input_row cross join lateral unnest(coalesce(input_row.input_modalities, array[]::text[])) value where input_row.model_id = eligible.model_id and btrim(value) <> ''), array[]::text[]) as input_modalities,
      coalesce((select array_agg(distinct value order by value) from eligible output_row cross join lateral unnest(coalesce(output_row.output_modalities, array[]::text[])) value where output_row.model_id = eligible.model_id and btrim(value) <> ''), array[]::text[]) as output_modalities
    from eligible
    group by eligible.model_id
  ),
  usage as (
    select
      request.routed_model_id as model_id,
      count(*)::bigint as requests_30d,
      coalesce(sum(greatest(coalesce(request.cost_nanos, 0), 0)), 0)::numeric as total_cost_nanos_30d,
      max(request.created_at) as last_routed_at
    from private.v2_rpc_gateway_requests_compat request
    join eligible_models eligible on eligible.model_id = request.routed_model_id
    where request.requested_model_id = 'phaseo/free'
      and request.created_at >= now() - interval '30 days'
    group by request.routed_model_id
  ),
  model_rows as (
    select
      eligible.model_id,
      eligible.provider_count,
      coalesce(usage.requests_30d, 0)::bigint as requests_30d,
      coalesce(usage.total_cost_nanos_30d, 0)::numeric as total_cost_nanos_30d,
      jsonb_build_object(
        'modelId', eligible.model_id,
        'displayApiModelId', eligible.display_api_model_id,
        'name', coalesce(nullif(model.name, ''), eligible.model_id),
        'organisationId', coalesce(model.organisation_id, ''),
        'organisationName', coalesce(nullif(organisation.name, ''), model.organisation_id, 'Unknown'),
        'providerCount', eligible.provider_count,
        'inputModalities', case when cardinality(eligible.input_modalities) > 0 then eligible.input_modalities else coalesce(regexp_split_to_array(nullif(btrim(model.input_types), ''), '\\s*,\\s*'), array[]::text[]) end,
        'outputModalities', case when cardinality(eligible.output_modalities) > 0 then eligible.output_modalities else coalesce(regexp_split_to_array(nullif(btrim(model.output_types), ''), '\\s*,\\s*'), array[]::text[]) end,
        'usage', jsonb_build_object(
          'requests30d', coalesce(usage.requests_30d, 0),
          'totalCostNanos30d', coalesce(usage.total_cost_nanos_30d, 0),
          'lastRoutedAt', usage.last_routed_at
        )
      ) as payload
    from eligible_models eligible
    join private.v2_rpc_models_compat model on model.model_id = eligible.model_id and model.hidden = false
    left join private.v2_rpc_labs_compat organisation on organisation.organisation_id = model.organisation_id
    left join usage on usage.model_id = eligible.model_id
  )
  select jsonb_build_object(
    'summary', jsonb_build_object(
      'eligibleModels', count(*),
      'eligibleProviders', (select count(distinct provider_id) from eligible),
      'routedRequests30d', coalesce(sum(requests_30d), 0),
      'totalCostNanos30d', coalesce(sum(total_cost_nanos_30d), 0)
    ),
    'models', coalesce(jsonb_agg(payload order by requests_30d desc, model_id), '[]'::jsonb)
  )
  from model_rows;
$function$;

CREATE OR REPLACE FUNCTION public.get_public_geographic_distribution (
  p_time_range text    DEFAULT 'week'::text,
  p_limit      integer DEFAULT 20
)
  RETURNS TABLE (
    country      text,
    country_code text,
    requests     bigint,
    tokens       bigint,
    share_pct    numeric
  )
  LANGUAGE plpgsql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
DECLARE
  v_since timestamptz;
  v_now timestamptz := now();
BEGIN
  CASE p_time_range
    WHEN 'today' THEN v_since := date_trunc('day', v_now);
    WHEN 'week' THEN v_since := v_now - interval '7 days';
    WHEN 'month' THEN v_since := date_trunc('month', v_now);
    ELSE v_since := v_now - interval '7 days';
  END CASE;

  RETURN QUERY
  WITH totals AS (
    SELECT COUNT(*)::numeric as total_requests
    FROM private.v2_rpc_gateway_requests_compat
    WHERE created_at >= v_since
  )
  SELECT
    COALESCE(gr.location, 'Unknown') as country,
    COALESCE(gr.location, 'XX') as country_code,
    COUNT(*)::bigint as requests,
    SUM(COALESCE((gr.usage->>'total_tokens')::bigint, 0))::bigint as tokens,
    ROUND((COUNT(*) / t.total_requests * 100)::numeric, 2) as share_pct
  FROM private.v2_rpc_gateway_requests_compat gr, totals t
  WHERE gr.created_at >= v_since
  GROUP BY gr.location
  HAVING COUNT(*) >= 50
  ORDER BY requests DESC
  LIMIT p_limit;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_public_geography_usage (
  p_from           timestamp with time zone DEFAULT (now() - '30 days'::interval),
  p_to             timestamp with time zone DEFAULT now(),
  p_min_requests   bigint                   DEFAULT 1,
  p_min_workspaces bigint                   DEFAULT 1
)
  RETURNS TABLE (
    country_code    text,
    requests        bigint,
    tokens          numeric,
    share_percent   numeric,
    workspace_count bigint
  )
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  with scoped_facts as materialized (
    select request_event_id, workspace_id, edge_country
    from public.v2_request_facts
    where occurred_at >= p_from
      and occurred_at < p_to
      and edge_country is not null
  ),
  request_tokens as (
    select
      fact.request_event_id,
      coalesce(
        nullif(sum(usage.quantity) filter (
          where usage.meter_key in ('input_tokens', 'output_tokens')
        ), 0),
        sum(usage.quantity) filter (
          where usage.meter_key in (
            'input_text_tokens', 'output_text_tokens',
            'input_image_tokens', 'output_image_tokens',
            'input_audio_tokens', 'output_audio_tokens',
            'input_video_tokens', 'output_video_tokens'
          )
        ),
        0
      ) as tokens
    from scoped_facts fact
    left join public.v2_request_usage usage
      on usage.request_event_id = fact.request_event_id
    group by fact.request_event_id
  ),
  countries as (
    select
      fact.edge_country as country_code,
      count(*)::bigint as requests,
      coalesce(sum(tokens.tokens), 0) as tokens,
      count(distinct fact.workspace_id)::bigint as workspace_count
    from scoped_facts fact
    left join request_tokens tokens
      on tokens.request_event_id = fact.request_event_id
    group by fact.edge_country
  )
  select
    country.country_code,
    country.requests,
    country.tokens,
    case
      when sum(country.requests) over () > 0
        then round(country.requests::numeric / sum(country.requests) over () * 100, 2)
      else 0
    end as share_percent,
    country.workspace_count
  from countries country
  where country.requests >= greatest(coalesce(p_min_requests, 1), 1)
    and country.workspace_count >= greatest(coalesce(p_min_workspaces, 1), 1)
  order by country.requests desc, country.country_code;
$function$;

REVOKE ALL ON FUNCTION "public"."get_public_geography_usage"(timestamp WITH time zone, timestamp WITH time zone, bigint, bigint) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.get_public_image_input_timeseries (
  p_time_range text    DEFAULT 'year'::text,
  p_top_n      integer DEFAULT 20
)
  RETURNS TABLE (
    bucket   timestamp with time zone,
    model_id text,
    requests bigint,
    tokens   numeric,
    colour   text
  )
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select series.*
  from public.get_public_modality_usage_timeseries(
    'image_inputs',
    coalesce(p_time_range, 'year'),
    greatest(1, least(coalesce(p_top_n, 20), 100))
  ) series;
$function$;

REVOKE ALL ON FUNCTION "public"."get_public_image_input_timeseries"(text, integer) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.get_public_intelligence_index (
  p_limit integer DEFAULT 20
)
  RETURNS TABLE (
    benchmark_id      text,
    benchmark_name    text,
    benchmark_type    text,
    category          text,
    model_id          text,
    model_name        text,
    organisation_id   text,
    organisation_name text,
    score             numeric,
    rank              bigint,
    total_models      bigint
  )
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  with scored as (
    select
      benchmark.benchmark_id,
      benchmark.name as benchmark_name,
      benchmark.benchmark_type,
      benchmark.category,
      model.model_slug as model_id,
      model.name as model_name,
      model.lab_slug as organisation_id,
      lab.name as organisation_name,
      result.score_numeric as score,
      row_number() over (order by result.score_numeric desc, model.name, model.model_slug) as rank,
      count(*) over () as total_models
    from public.v2_benchmark_results result
    join public.v2_benchmarks benchmark
      on benchmark.benchmark_id = result.benchmark_id
    join public.v2_models model
      on model.model_slug = result.model_slug
     and model.hidden = false
    left join public.v2_labs lab
      on lab.lab_slug = model.lab_slug
    where result.benchmark_id = 'aa-intelligence-index-v4'
      and result.score_numeric is not null
  )
  select *
  from scored
  where rank <= greatest(1, least(coalesce(p_limit, 20), 100))
  order by rank;
$function$;

REVOKE ALL ON FUNCTION "public"."get_public_intelligence_index"(integer) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.get_public_market_share (
  p_dimension  text DEFAULT 'organization'::text,
  p_time_range text DEFAULT 'week'::text
)
  RETURNS TABLE (
    name      text,
    requests  bigint,
    tokens    bigint,
    share_pct numeric
  )
  LANGUAGE plpgsql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_today date := (now() at time zone 'utc')::date;
  v_since date;
begin
  case p_time_range
    when 'today' then v_since := v_today;
    when 'week' then v_since := v_today - 7;
    when 'month' then v_since := v_today - 30;
    else v_since := v_today - 7;
  end case;

  if p_dimension = 'organization' then
    return query
    with base as (
      select
        d.model_id,
        sum(d.success_requests)::bigint as requests,
        sum(d.total_tokens)::bigint as tokens
      from (
with meters as (
  select
    meter.rollup_id,
    jsonb_object_agg(meter.meter_key, meter.quantity) as values
  from public.v2_public_usage_daily_meters meter
  join public.v2_public_usage_daily scoped on scoped.rollup_id = meter.rollup_id
  where scoped.usage_date >= v_since
  group by meter.rollup_id
)
select
  usage.usage_date as day_bucket,
  usage.model_slug as model_id,
  route.provider_slug as provider_id,
  usage.successful_requests as success_requests,
  coalesce(
    (meters.values->>'total_tokens')::numeric,
    (meters.values->>'input_tokens')::numeric + (meters.values->>'output_tokens')::numeric,
    (meters.values->>'input_text_tokens')::numeric + (meters.values->>'output_text_tokens')::numeric,
    0
  )::bigint as total_tokens
from public.v2_public_usage_daily usage
left join public.v2_model_provider_routes route
  on route.provider_model_id = usage.provider_model_id
left join meters on meters.rollup_id = usage.rollup_id
) d
      where d.day_bucket >= v_since
        and lower(d.model_id) not in ('unknown', 'other')
      group by d.model_id
    ),
    grouped as (
      select
        coalesce(org.name, dm.organisation_id) as org_name,
        sum(b.requests)::bigint as req_count,
        sum(b.tokens)::bigint as tok_count
      from base b
      join private.v2_rpc_models_compat dm on dm.model_id = b.model_id
      left join private.v2_rpc_labs_compat org on dm.organisation_id = org.organisation_id
      where dm.organisation_id is not null
      group by org.name, dm.organisation_id
    ),
    totals as (
      select sum(g.req_count)::numeric as total_requests
      from grouped g
    )
    select
      g.org_name as name,
      g.req_count as requests,
      g.tok_count as tokens,
      round((g.req_count::numeric / nullif(t.total_requests, 0) * 100)::numeric, 2) as share_pct
    from grouped g
    cross join totals t
    where g.req_count > 0
    order by g.req_count desc;
  else
    return query
    with grouped as (
      select
        d.provider_id as provider,
        sum(d.success_requests)::bigint as req_count,
        sum(d.total_tokens)::bigint as tok_count
      from (
with meters as (
  select
    meter.rollup_id,
    jsonb_object_agg(meter.meter_key, meter.quantity) as values
  from public.v2_public_usage_daily_meters meter
  join public.v2_public_usage_daily scoped on scoped.rollup_id = meter.rollup_id
  where scoped.usage_date >= v_since
  group by meter.rollup_id
)
select
  usage.usage_date as day_bucket,
  usage.model_slug as model_id,
  route.provider_slug as provider_id,
  usage.successful_requests as success_requests,
  coalesce(
    (meters.values->>'total_tokens')::numeric,
    (meters.values->>'input_tokens')::numeric + (meters.values->>'output_tokens')::numeric,
    (meters.values->>'input_text_tokens')::numeric + (meters.values->>'output_text_tokens')::numeric,
    0
  )::bigint as total_tokens
from public.v2_public_usage_daily usage
left join public.v2_model_provider_routes route
  on route.provider_model_id = usage.provider_model_id
left join meters on meters.rollup_id = usage.rollup_id
) d
      where d.day_bucket >= v_since
        and d.provider_id is not null
        and d.provider_id <> ''
        and lower(d.provider_id) not in ('unknown', 'other')
      group by d.provider_id
    ),
    totals as (
      select sum(g.req_count)::numeric as total_requests
      from grouped g
    )
    select
      g.provider as name,
      g.req_count as requests,
      g.tok_count as tokens,
      round((g.req_count::numeric / nullif(t.total_requests, 0) * 100)::numeric, 2) as share_pct
    from grouped g
    cross join totals t
    where g.req_count > 0
    order by g.req_count desc;
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_public_market_share_timeseries (
  p_dimension   text    DEFAULT 'organization'::text,
  p_time_range  text    DEFAULT 'year'::text,
  p_bucket_size text    DEFAULT 'week'::text,
  p_top_n       integer DEFAULT 8
)
  RETURNS TABLE (
    bucket   timestamp with time zone,
    name     text,
    requests bigint,
    tokens   bigint,
    colour   text
  )
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
declare
  v_since timestamptz;
  v_dimension text := lower(coalesce(p_dimension, 'provider'));
  v_bucket_size text := lower(coalesce(p_bucket_size, 'day'));
begin
  case lower(coalesce(p_time_range, 'week'))
    when '24h' then v_since := now() - interval '24 hours';
    when 'today' then v_since := date_trunc('day', now());
    when 'week' then v_since := now() - interval '7 days';
    when 'month' then v_since := now() - interval '30 days';
    when 'year' then v_since := now() - interval '1 year';
    else v_since := now() - interval '1 year';
  end case;

  return query
  with source_rows as (
    select
      case
        when v_bucket_size = 'hour' then date_trunc('hour', usage.bucket_15m)
        when v_bucket_size = 'day' then date_trunc('day', usage.bucket_15m)
        when v_bucket_size = 'month' then date_trunc('month', usage.bucket_15m)
        else date_trunc('week', usage.bucket_15m)
      end as time_bucket,
      usage.canonical_model_id as model_slug,
      usage.provider,
      usage.requests,
      usage.total_tokens
    from (
with meters as (
  select
    meter.rollup_id,
    coalesce(
      max(meter.quantity) filter (where meter.meter_key = 'total_tokens'),
      sum(meter.quantity) filter (where meter.meter_key in ('input_tokens', 'output_tokens')),
      sum(meter.quantity) filter (where meter.meter_key in ('input_text_tokens', 'output_text_tokens')),
      0
    )::numeric as total_tokens
  from public.v2_public_usage_hourly_meters meter
  join public.v2_public_usage_hourly scoped on scoped.rollup_id = meter.rollup_id
  where v_bucket_size = 'hour' and scoped.bucket_start >= v_since
  group by meter.rollup_id
)
select
  usage.bucket_start as bucket_15m,
  usage.model_slug as canonical_model_id,
  route.provider_slug as provider,
  usage.app_id,
  usage.requests,
  usage.successful_requests as success_requests,
  coalesce(meters.total_tokens, 0) as total_tokens,
  usage.cost_nanos::bigint as total_cost_nanos,
  usage.latency_sum_ms,
  usage.latency_count as latency_samples,
  usage.throughput_sum,
  usage.throughput_count as throughput_samples,
  usage.generation_sum_ms,
  usage.generation_count as generation_samples
from public.v2_public_usage_hourly usage
join public.v2_model_provider_routes route
  on route.provider_model_id = usage.provider_model_id
  and coalesce(route.is_stealth, false) = false
  and route.routing_enabled = true
  and route.status in ('active', 'degraded')
  and (route.effective_from is null or route.effective_from <= now())
  and (route.effective_to is null or route.effective_to > now())
join public.v2_models model
  on model.model_slug = usage.model_slug
  and model.hidden = false
  and model.status <> 'disabled'
left join meters on meters.rollup_id = usage.rollup_id
) usage
    where v_bucket_size = 'hour'
      and usage.bucket_15m >= v_since

    union all

    select
      case
        when v_bucket_size = 'day' then usage.day_bucket::timestamptz
        when v_bucket_size = 'month' then date_trunc('month', usage.day_bucket::timestamp)::timestamptz
        else date_trunc('week', usage.day_bucket::timestamp)::timestamptz
      end as time_bucket,
      usage.canonical_model_id as model_slug,
      usage.provider,
      usage.requests,
      usage.total_tokens
    from (
with meters as (
  select
    meter.rollup_id,
    coalesce(
      max(meter.quantity) filter (where meter.meter_key = 'total_tokens'),
      sum(meter.quantity) filter (where meter.meter_key in ('input_tokens', 'output_tokens')),
      sum(meter.quantity) filter (where meter.meter_key in ('input_text_tokens', 'output_text_tokens')),
      0
    )::numeric as total_tokens
  from public.v2_public_usage_daily_meters meter
  join public.v2_public_usage_daily scoped on scoped.rollup_id = meter.rollup_id
  where v_bucket_size <> 'hour' and scoped.usage_date >= (v_since at time zone 'utc')::date
  group by meter.rollup_id
)
select
  usage.usage_date as day_bucket,
  usage.model_slug as canonical_model_id,
  route.provider_slug as provider,
  usage.app_id,
  usage.requests,
  usage.successful_requests as success_requests,
  coalesce(meters.total_tokens, 0) as total_tokens,
  usage.cost_nanos::bigint as total_cost_nanos,
  usage.latency_sum_ms,
  usage.latency_count as latency_samples,
  usage.throughput_sum,
  usage.throughput_count as throughput_samples,
  usage.generation_sum_ms,
  usage.generation_count as generation_samples
from public.v2_public_usage_daily usage
join public.v2_model_provider_routes route
  on route.provider_model_id = usage.provider_model_id
  and coalesce(route.is_stealth, false) = false
  and route.routing_enabled = true
  and route.status in ('active', 'degraded')
  and (route.effective_from is null or route.effective_from <= now())
  and (route.effective_to is null or route.effective_to > now())
join public.v2_models model
  on model.model_slug = usage.model_slug
  and model.hidden = false
  and model.status <> 'disabled'
left join meters on meters.rollup_id = usage.rollup_id
) usage
    where v_bucket_size <> 'hour'
      and usage.day_bucket >= (v_since at time zone 'utc')::date
  ),
  grouped as (
    select
      source.time_bucket,
      case
        when v_dimension = 'organization' then coalesce(nullif(lab.name, ''), nullif(model.lab_slug, ''), 'Unknown')
        else source.provider
      end as group_name,
      sum(source.requests)::bigint as request_count,
      sum(source.total_tokens)::bigint as token_count,
      case
        when v_dimension = 'organization' then max(lab.metadata ->> 'colour')
        else max(provider.metadata ->> 'colour')
      end as group_colour
    from source_rows source
    left join public.v2_models model on model.model_slug = source.model_slug
    left join public.v2_labs lab on lab.lab_slug = model.lab_slug
    left join public.v2_providers provider on provider.provider_slug = source.provider
    where (
      v_dimension = 'organization'
      and model.lab_slug is not null
    ) or (
      v_dimension <> 'organization'
      and source.provider is not null
      and source.provider <> ''
    )
    group by source.time_bucket, group_name
  ),
  top_groups as (
    select grouped.group_name
    from grouped
    group by grouped.group_name
    order by sum(grouped.request_count) desc, grouped.group_name
    limit greatest(coalesce(p_top_n, 8), 1)
  ),
  bucketed as (
    select
      grouped.time_bucket,
      case
        when grouped.group_name in (select top_groups.group_name from top_groups) then grouped.group_name
        else 'Other'
      end as group_name,
      sum(grouped.request_count)::bigint as request_count,
      sum(grouped.token_count)::bigint as token_count,
      max(case
        when grouped.group_name in (select top_groups.group_name from top_groups) then grouped.group_colour
        else null
      end) as group_colour
    from grouped
    group by grouped.time_bucket, group_name
  )
  select
    bucketed.time_bucket as bucket,
    bucketed.group_name as name,
    bucketed.request_count as requests,
    bucketed.token_count as tokens,
    bucketed.group_colour as colour
  from bucketed
  order by bucketed.time_bucket, bucketed.request_count desc;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_public_modality_usage_timeseries (
  p_metric     text,
  p_time_range text    DEFAULT 'year'::text,
  p_top_n      integer DEFAULT 20
)
  RETURNS TABLE (
    bucket   timestamp with time zone,
    model_id text,
    requests bigint,
    tokens   numeric,
    colour   text
  )
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
declare
  v_since date;
begin
  case p_time_range
    when '24h' then v_since := (now() at time zone 'utc')::date - 1;
    when 'today' then v_since := (now() at time zone 'utc')::date;
    when 'week' then v_since := (now() at time zone 'utc')::date - 7;
    when 'month' then v_since := (now() at time zone 'utc')::date - 30;
    when 'year' then v_since := (now() at time zone 'utc')::date - 365;
    else v_since := (now() at time zone 'utc')::date - 365;
  end case;

  return query
  with daily as (
    select
      (date_trunc('week', d.day_bucket::timestamp) at time zone 'UTC') as time_bucket,
      d.model_id,
      sum(d.requests)::bigint as req_count,
      sum(
        case p_metric
          when 'text_tokens' then d.input_text_tokens + d.output_text_tokens
          when 'image_inputs' then d.image_inputs
          when 'image_outputs' then d.image_outputs
          when 'audio_tokens' then d.input_audio_tokens + d.output_audio_tokens
          when 'audio_seconds' then d.audio_seconds
          when 'speech_seconds' then d.speech_seconds
          when 'transcription_seconds' then d.transcription_seconds
          when 'video_tokens' then d.input_video_tokens + d.output_video_tokens
          when 'video_seconds' then d.video_seconds
          when 'cached_tokens' then d.cached_read_tokens + d.cached_write_tokens
          when 'embedding_tokens' then d.embedding_tokens
          when 'rerank_quad_tokens' then d.rerank_quad_tokens
          else 0
        end
      )::numeric as metric_value
    from public.v2_rpc_gateway_model_usage_daily d
    where d.day_bucket >= v_since
    group by 1, 2
  ),
  ranked_daily as (
    select
      d.*,
      row_number() over (
        partition by d.time_bucket
        order by d.metric_value desc, d.req_count desc, d.model_id
      ) as bucket_rank
    from daily d
    where lower(d.model_id) not in ('unknown', 'other')
      and d.metric_value > 0
  ),
  bucketed as (
    select
      d.time_bucket,
      case
        when rd.bucket_rank <= greatest(1, least(coalesce(p_top_n, 20), 100)) then d.model_id
        else 'Other'
      end as model_group,
      sum(d.req_count)::bigint as req_count,
      sum(d.metric_value)::numeric as metric_value
    from daily d
    left join ranked_daily rd
      on rd.time_bucket = d.time_bucket
      and rd.model_id = d.model_id
    where d.metric_value > 0
      and lower(d.model_id) <> 'unknown'
    group by d.time_bucket, model_group
  )
  select
    b.time_bucket as bucket,
    b.model_group as model_id,
    b.req_count as requests,
    b.metric_value as tokens,
    case
      when b.model_group = 'Other' then null
      else org.colour
    end as colour
  from bucketed b
  left join public.v2_models dm on dm.model_slug = b.model_group
  left join public.v2_labs org on dm.lab_slug = org.lab_slug
  order by b.time_bucket, b.metric_value desc;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_public_model_catalogue_rows (
  p_include_hidden boolean DEFAULT false
)
  RETURNS TABLE (
    model_id                           text,
    name                               text,
    organisation_id                    text,
    organisation_name                  text,
    organisation_colour                text,
    primary_date                       date,
    primary_timestamp                  numeric,
    primary_group_key                  text,
    gateway_status                     text,
    gateway_provider_count             integer,
    gateway_active_provider_count      integer,
    gateway_endpoints                  text[],
    gateway_input_modalities           text[],
    gateway_output_modalities          text[],
    gateway_features                   text[],
    gateway_provider_names             text[],
    gateway_active_provider_names      text[],
    gateway_provider_details           jsonb,
    gateway_api_model_ids              text[],
    context_lengths                    integer[],
    supported_parameters               text[],
    lowest_input_price                 numeric,
    lowest_output_price                numeric,
    lowest_standard_input_price        numeric,
    lowest_standard_output_price       numeric,
    lowest_standard_input_price_label  text,
    lowest_standard_input_price_unit   text,
    lowest_standard_output_price_label text,
    lowest_standard_output_price_unit  text,
    lowest_from_price                  numeric,
    lowest_from_price_unit             text,
    pricing_detail_rows                jsonb,
    popularity_tokens_week             numeric,
    throughput_week                    numeric,
    latency_week                       numeric
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  with source_rows as (
    select
      r.*,
      case
        when lower(coalesce(r.capability_status, '')) = 'disabled' then 'disabled'
        when lower(coalesce(r.capability_status, '')) in ('deranked', 'de_ranked', 'deranked_lvl1', 'deranked_lvl_1') then 'deranked_lvl1'
        when lower(coalesce(r.capability_status, '')) in ('deranked_lvl2', 'deranked_lvl_2') then 'deranked_lvl2'
        when lower(coalesce(r.capability_status, '')) in ('deranked_lvl3', 'deranked_lvl_3') then 'deranked_lvl3'
        when lower(coalesce(r.capability_status, '')) in ('coming_soon', 'comingsoon') then 'coming_soon'
        when lower(coalesce(r.capability_status, '')) = 'inactive' then 'inactive'
        when coalesce(r.is_active_gateway, false) then 'active'
        else 'inactive'
      end as normalized_gateway_status
    from public.get_monitor_model_rows(p_include_hidden) r
    where r.model_id is not null
      and btrim(r.model_id) <> ''
  ),
  model_provider_status as (
    select
      sr.model_id,
      sr.provider_id,
      max(sr.api_provider_name) as api_provider_name,
      min(
        case sr.normalized_gateway_status
          when 'active' then 1
          when 'coming_soon' then 2
          when 'deranked_lvl1' then 3
          when 'deranked_lvl2' then 4
          when 'deranked_lvl3' then 5
          when 'inactive' then 6
          when 'disabled' then 7
          else 8
        end
      ) as status_rank
    from source_rows sr
    where sr.provider_id is not null
      and btrim(sr.provider_id) <> ''
    group by sr.model_id, sr.provider_id
  ),
  provider_details as (
    select
      mps.model_id,
      jsonb_agg(
        jsonb_build_object(
          'id', mps.provider_id,
          'name', coalesce(nullif(mps.api_provider_name, ''), mps.provider_id),
          'status',
            case mps.status_rank
              when 1 then 'active'
              when 2 then 'coming_soon'
              when 3 then 'deranked_lvl1'
              when 4 then 'deranked_lvl2'
              when 5 then 'deranked_lvl3'
              when 6 then 'inactive'
              when 7 then 'disabled'
              else 'inactive'
            end,
          'is_active', mps.status_rank in (1, 3, 4, 5)
        )
        order by mps.status_rank asc, coalesce(nullif(mps.api_provider_name, ''), mps.provider_id) asc
      ) as details
    from model_provider_status mps
    group by mps.model_id
  ),
  model_features as (
    select
      sr.model_id,
      array_remove(array[
        case when bool_or(coalesce(sr.is_free_variant, false)) then 'free' end,
        case when bool_or(coalesce(sr.capability_params::text, '') ilike '%reasoning%' or coalesce(sr.capability_params::text, '') ilike '%thinking%') then 'reasoning' end,
        case when bool_or(coalesce(sr.capability_params::text, '') ilike '%tool%' or coalesce(sr.capability_params::text, '') ilike '%function_call%') then 'tools' end,
        case when bool_or(coalesce(sr.capability_params::text, '') ilike '%structured_output%' or coalesce(sr.capability_params::text, '') ilike '%response_format%' or coalesce(sr.capability_params::text, '') ilike '%json_schema%') then 'structured_outputs' end,
        case when bool_or(coalesce(sr.capability_params::text, '') ilike '%web_search%' or coalesce(sr.capability_params::text, '') ilike '%websearch%' or coalesce(sr.capability_params::text, '') ilike '%native_web_search%') then 'web_search' end
      ], null) as features
    from source_rows sr
    group by sr.model_id
  ),
  model_supported_parameters as (
    select
      sr.model_id,
      coalesce(
        array_agg(distinct key order by key) filter (
          where key is not null
            and length(key) >= 2
            and key not in ('type', 'title', 'description', 'default', 'minimum', 'maximum', 'enum', 'oneof', 'anyof', 'allof', 'items', 'properties', 'required', 'nullable', 'additionalproperties', '$schema', '$id', 'strict')
        ),
        array[]::text[]
      ) as supported_parameters
    from source_rows sr
    left join lateral jsonb_object_keys(
      case
        when jsonb_typeof(sr.capability_params) = 'object' then sr.capability_params
        else '{}'::jsonb
      end
    ) as keys(key) on true
    group by sr.model_id
  ),
  grouped as (
    select
      sr.model_id,
      max(sr.model_name) as name,
      max(sr.organisation_id) as organisation_id,
      max(sr.organisation_name) as organisation_name,
      max(org.colour) as organisation_colour,
      max(sr.model_release_date) as primary_date,
      max(extract(epoch from sr.model_release_date::timestamptz) * 1000) as primary_timestamp,
      max(to_char(sr.model_release_date, 'YYYY-MM')) as primary_group_key,
      count(distinct sr.provider_id) filter (where sr.provider_id is not null and btrim(sr.provider_id) <> '')::integer as gateway_provider_count,
      count(distinct sr.provider_id) filter (
        where sr.provider_id is not null
          and btrim(sr.provider_id) <> ''
          and sr.normalized_gateway_status in ('active', 'deranked_lvl1', 'deranked_lvl2', 'deranked_lvl3')
      )::integer as gateway_active_provider_count,
      bool_or(sr.normalized_gateway_status = 'coming_soon') as has_coming_soon_provider,
      array_agg(distinct sr.capability_id order by sr.capability_id) filter (where sr.capability_id is not null and btrim(sr.capability_id) <> '') as gateway_endpoints,
      array_agg(distinct input_modality order by input_modality) filter (where input_modality is not null and btrim(input_modality) <> '') as gateway_input_modalities,
      array_agg(distinct output_modality order by output_modality) filter (where output_modality is not null and btrim(output_modality) <> '') as gateway_output_modalities,
      array_agg(distinct coalesce(nullif(sr.api_provider_name, ''), sr.provider_id) order by coalesce(nullif(sr.api_provider_name, ''), sr.provider_id)) filter (where sr.provider_id is not null and btrim(sr.provider_id) <> '') as gateway_provider_names,
      array_agg(distinct coalesce(nullif(sr.api_provider_name, ''), sr.provider_id) order by coalesce(nullif(sr.api_provider_name, ''), sr.provider_id)) filter (
        where sr.provider_id is not null
          and btrim(sr.provider_id) <> ''
          and sr.normalized_gateway_status in ('active', 'deranked_lvl1', 'deranked_lvl2', 'deranked_lvl3')
      ) as gateway_active_provider_names,
      array_agg(distinct sr.api_model_id order by sr.api_model_id) filter (where sr.api_model_id is not null and btrim(sr.api_model_id) <> '') as gateway_api_model_ids,
      array_agg(distinct coalesce(sr.context_length, sr.capability_max_input_tokens) order by coalesce(sr.context_length, sr.capability_max_input_tokens)) filter (where coalesce(sr.context_length, sr.capability_max_input_tokens) > 0) as context_lengths,
      min(sr.input_price) filter (where sr.normalized_gateway_status in ('active', 'deranked_lvl1', 'deranked_lvl2', 'deranked_lvl3') and sr.input_price > 0) as lowest_input_price,
      min(sr.output_price) filter (where sr.normalized_gateway_status in ('active', 'deranked_lvl1', 'deranked_lvl2', 'deranked_lvl3') and sr.output_price > 0) as lowest_output_price,
      min(sr.standard_input_price) filter (where sr.normalized_gateway_status in ('active', 'deranked_lvl1', 'deranked_lvl2', 'deranked_lvl3') and sr.standard_input_price > 0) as lowest_standard_input_price,
      min(sr.standard_output_price) filter (where sr.normalized_gateway_status in ('active', 'deranked_lvl1', 'deranked_lvl2', 'deranked_lvl3') and sr.standard_output_price > 0) as lowest_standard_output_price,
      min(sr.standard_input_price_label) filter (where sr.standard_input_price_label is not null) as lowest_standard_input_price_label,
      min(sr.standard_input_price_unit) filter (where sr.standard_input_price_unit is not null) as lowest_standard_input_price_unit,
      min(sr.standard_output_price_label) filter (where sr.standard_output_price_label is not null) as lowest_standard_output_price_label,
      min(sr.standard_output_price_unit) filter (where sr.standard_output_price_unit is not null) as lowest_standard_output_price_unit,
      min(sr.from_price) filter (where sr.normalized_gateway_status in ('active', 'deranked_lvl1', 'deranked_lvl2', 'deranked_lvl3') and sr.from_price >= 0) as lowest_from_price,
      case
        when count(distinct sr.from_price_unit) filter (where sr.from_price_unit is not null and btrim(sr.from_price_unit) <> '') = 1
          then min(sr.from_price_unit) filter (where sr.from_price_unit is not null and btrim(sr.from_price_unit) <> '')
        else null
      end as lowest_from_price_unit,
      max(sr.weekly_tokens_model)::numeric as popularity_tokens_week,
      max(sr.weekly_throughput_model)::numeric as throughput_week,
      max(sr.weekly_latency_model)::numeric as latency_week
    from source_rows sr
    left join private.v2_rpc_labs_compat org
      on org.organisation_id = sr.organisation_id
    left join lateral unnest(coalesce(sr.input_modalities, array[]::text[])) as input_values(input_modality) on true
    left join lateral unnest(coalesce(sr.output_modalities, array[]::text[])) as output_values(output_modality) on true
    group by sr.model_id
  )
  select
    g.model_id,
    coalesce(nullif(g.name, ''), g.model_id) as name,
    coalesce(g.organisation_id, split_part(g.model_id, '/', 1)) as organisation_id,
    g.organisation_name,
    g.organisation_colour,
    g.primary_date,
    g.primary_timestamp,
    g.primary_group_key,
    case
      when g.gateway_active_provider_count > 0 then 'active'
      when g.has_coming_soon_provider then 'coming_soon'
      when g.gateway_provider_count > 0 then 'inactive'
      else 'not_listed'
    end as gateway_status,
    g.gateway_provider_count,
    g.gateway_active_provider_count,
    coalesce(g.gateway_endpoints, array[]::text[]) as gateway_endpoints,
    coalesce(g.gateway_input_modalities, array[]::text[]) as gateway_input_modalities,
    coalesce(g.gateway_output_modalities, array[]::text[]) as gateway_output_modalities,
    coalesce(mf.features, array[]::text[]) as gateway_features,
    coalesce(g.gateway_provider_names, array[]::text[]) as gateway_provider_names,
    coalesce(g.gateway_active_provider_names, array[]::text[]) as gateway_active_provider_names,
    coalesce(pd.details, '[]'::jsonb) as gateway_provider_details,
    coalesce(g.gateway_api_model_ids, array[]::text[]) as gateway_api_model_ids,
    coalesce(g.context_lengths, array[]::integer[]) as context_lengths,
    coalesce(msp.supported_parameters, array[]::text[]) as supported_parameters,
    g.lowest_input_price,
    g.lowest_output_price,
    g.lowest_standard_input_price,
    g.lowest_standard_output_price,
    g.lowest_standard_input_price_label,
    g.lowest_standard_input_price_unit,
    g.lowest_standard_output_price_label,
    g.lowest_standard_output_price_unit,
    g.lowest_from_price,
    g.lowest_from_price_unit,
    '[]'::jsonb as pricing_detail_rows,
    g.popularity_tokens_week,
    g.throughput_week,
    g.latency_week
  from grouped g
  left join provider_details pd on pd.model_id = g.model_id
  left join model_features mf on mf.model_id = g.model_id
  left join model_supported_parameters msp on msp.model_id = g.model_id
  order by g.primary_timestamp desc nulls last, g.organisation_name asc nulls last, g.name asc;
$function$;

CREATE OR REPLACE FUNCTION public.get_public_model_performance (
  p_hours        integer DEFAULT 24,
  p_min_requests integer DEFAULT 0
)
  RETURNS TABLE (
    model_id           text,
    provider           text,
    requests           bigint,
    cost_per_1m_tokens numeric,
    median_latency_ms  numeric,
    p95_latency_ms     numeric,
    median_throughput  numeric,
    success_rate       numeric
  )
  LANGUAGE plpgsql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_since date := ((now() at time zone 'utc')::date - greatest(ceil(greatest(p_hours, 1)::numeric / 24.0)::int, 1));
begin
  return query
  with grouped as (
    select
      d.model_id,
      d.provider_id as provider,
      sum(d.requests)::bigint as req_count,
      sum(d.total_tokens)::bigint as total_tok,
      sum(d.total_cost_nanos)::bigint as total_cost_nano,
      sum(d.success_requests)::bigint as success_req_count,
      sum(d.latency_sum_ms)::numeric as latency_sum,
      sum(d.latency_samples)::bigint as latency_samples,
      sum(d.throughput_sum)::numeric as throughput_sum,
      sum(d.throughput_samples)::bigint as throughput_samples
    from public.v2_rpc_gateway_model_usage_daily d
    where d.day_bucket >= v_since
      and lower(d.model_id) not in ('unknown', 'other')
      and d.provider_id is not null
      and d.provider_id <> ''
    group by d.model_id, d.provider_id
  )
  select
    g.model_id,
    g.provider,
    g.req_count as requests,
    case
      when g.total_tok > 0 then
        round((g.total_cost_nano::numeric / 1000000000.0) / (g.total_tok::numeric / 1000000.0), 2)
      else 0
    end as cost_per_1m_tokens,
    round(
      case when g.latency_samples > 0
        then g.latency_sum / g.latency_samples::numeric
        else null
      end,
      0
    ) as median_latency_ms,
    round(
      case when g.latency_samples > 0
        then g.latency_sum / g.latency_samples::numeric
        else null
      end,
      0
    ) as p95_latency_ms,
    round(
      case when g.throughput_samples > 0
        then g.throughput_sum / g.throughput_samples::numeric
        else null
      end,
      2
    ) as median_throughput,
    round(
      case when g.req_count > 0
        then g.success_req_count::numeric / g.req_count::numeric
        else null
      end,
      4
    ) as success_rate
  from grouped g
  where g.req_count >= p_min_requests
  order by g.req_count desc;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_public_model_rankings (
  p_time_range text    DEFAULT 'week'::text,
  p_metric     text    DEFAULT 'tokens'::text,
  p_limit      integer DEFAULT 50
)
  RETURNS TABLE (
    model_id          text,
    provider          text,
    requests          bigint,
    total_tokens      bigint,
    input_tokens      bigint,
    output_tokens     bigint,
    total_cost_usd    numeric,
    median_latency_ms numeric,
    median_throughput numeric,
    success_rate      numeric,
    rank              integer,
    prev_rank         integer,
    trend             text
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public'
  AS $function$
  with bounds as (
    select
      case p_time_range when 'today' then current_date when 'month' then current_date - 30 when 'year' then current_date - 365 else current_date - 7 end as since_date,
      case p_time_range when 'today' then current_date - 1 when 'month' then current_date - 60 when 'year' then current_date - 730 else current_date - 14 end as previous_since,
      case p_time_range when 'today' then current_date when 'month' then current_date - 30 when 'year' then current_date - 365 else current_date - 7 end as previous_until
  ),
  meters as (
    select meter.rollup_id,
      sum(meter.quantity) filter (where meter.meter_key in ('input_tokens','output_tokens'))::bigint as total_tokens,
      sum(meter.quantity) filter (where meter.meter_key = 'input_tokens')::bigint as input_tokens,
      sum(meter.quantity) filter (where meter.meter_key = 'output_tokens')::bigint as output_tokens
    from public.v2_public_usage_daily_meters meter
    -- Broad yearly rankings keep the efficient full meter aggregate. For
    -- shorter periods, exclude historical meters before grouping.
    where p_time_range = 'year' or exists (
      select 1 from public.v2_public_usage_daily scoped cross join bounds
      where scoped.rollup_id = meter.rollup_id
        and scoped.usage_date >= bounds.previous_since
        and lower(scoped.model_slug) not in ('unknown','other')
    )
    group by meter.rollup_id
  ),
  all_periods as (
    select usage.usage_date, usage.model_slug, route.provider_slug as provider,
      usage.requests, usage.successful_requests, usage.latency_sum_ms, usage.latency_count,
      usage.throughput_sum, usage.throughput_count,
      coalesce(meter.total_tokens,0) as total_tokens,
      coalesce(meter.input_tokens,0) as input_tokens,
      coalesce(meter.output_tokens,0) as output_tokens
    from public.v2_public_usage_daily usage
    left join public.v2_model_provider_routes route on route.provider_model_id = usage.provider_model_id
    left join meters meter on meter.rollup_id = usage.rollup_id
    cross join bounds
    where usage.usage_date >= bounds.previous_since
      and lower(usage.model_slug) not in ('unknown','other')
  ),
  current_period as (
    select row.model_slug, coalesce(row.provider,'unknown') as provider,
      sum(row.requests)::bigint as requests, sum(row.successful_requests)::bigint as successes,
      sum(row.total_tokens)::bigint as total_tokens, sum(row.input_tokens)::bigint as input_tokens,
      sum(row.output_tokens)::bigint as output_tokens, sum(row.latency_sum_ms)::numeric as latency_sum,
      sum(row.latency_count)::bigint as latency_count, sum(row.throughput_sum)::numeric as throughput_sum,
      sum(row.throughput_count)::bigint as throughput_count
    from all_periods row cross join bounds where row.usage_date >= bounds.since_date
    group by row.model_slug, coalesce(row.provider,'unknown')
  ),
  previous_period as (
    select row.model_slug, coalesce(row.provider,'unknown') as provider,
      sum(row.requests)::bigint as requests, sum(row.total_tokens)::bigint as total_tokens
    from all_periods row cross join bounds
    where row.usage_date >= bounds.previous_since and row.usage_date < bounds.previous_until
    group by row.model_slug, coalesce(row.provider,'unknown')
  ),
  current_ranked as (
    select current_period.*, row_number() over (order by case p_metric when 'requests' then requests::numeric when 'cost' then 0 else total_tokens::numeric end desc, model_slug, provider)::integer as position
    from current_period where requests > 0
  ),
  previous_ranked as (
    select previous_period.*, row_number() over (order by case p_metric when 'requests' then requests::numeric when 'cost' then 0 else total_tokens::numeric end desc, model_slug, provider)::integer as position
    from previous_period where requests > 0
  )
  select current.model_slug, current.provider, current.requests, current.total_tokens,
    current.input_tokens, current.output_tokens, 0::numeric,
    round(current.latency_sum / nullif(current.latency_count,0), 0),
    round(current.throughput_sum / nullif(current.throughput_count,0), 2),
    round(current.successes::numeric / nullif(current.requests,0), 4),
    current.position, previous.position,
    case when previous.position is null then 'new' when current.position < previous.position then 'up' when current.position > previous.position then 'down' else 'same' end
  from current_ranked current
  left join previous_ranked previous using (model_slug, provider)
  order by current.position
  limit greatest(1, least(coalesce(p_limit,50),250));
$function$;

CREATE OR REPLACE FUNCTION public.get_public_model_retention_rankings (
  p_weeks               integer DEFAULT 10,
  p_limit               integer DEFAULT 20,
  p_min_workspace_weeks integer DEFAULT 25,
  p_min_workspaces      integer DEFAULT 5,
  p_min_weeks           integer DEFAULT 2
)
  RETURNS TABLE (
    model_id                  text,
    retention_rate            numeric,
    returning_workspace_weeks bigint,
    workspace_weeks           bigint,
    unique_workspaces         bigint,
    weeks_observed            integer,
    confidence_low            numeric,
    confidence_high           numeric,
    first_cohort_week         date,
    last_cohort_week          date,
    rank                      integer
  )
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  with bounds as (
    select date_trunc('week', now() at time zone 'utc')::date as current_week,
      greatest(1, least(coalesce(p_weeks, 10), 52))::integer as requested_weeks
  ),
  eligible_transitions as (
    select cohort.week_start as cohort_week, cohort.model_id, cohort.workspace_hash,
      (returned.workspace_hash is not null) as returned
    from public.public_model_workspace_usage_weekly cohort
    cross join bounds
    left join public.public_model_workspace_usage_weekly returned
      on returned.week_start = cohort.week_start + 7
     and returned.model_id = cohort.model_id
     and returned.workspace_hash = cohort.workspace_hash
    where cohort.week_start >= bounds.current_week - (bounds.requested_weeks + 1) * interval '1 week'
      and cohort.week_start < bounds.current_week - interval '1 week'
  ),
  aggregated as (
    select transition.model_id,
      count(*)::bigint as workspace_weeks,
      count(*) filter (where transition.returned)::bigint as returning_workspace_weeks,
      count(distinct transition.workspace_hash)::bigint as unique_workspaces,
      count(distinct transition.cohort_week)::integer as weeks_observed,
      min(transition.cohort_week)::date as first_cohort_week,
      max(transition.cohort_week)::date as last_cohort_week
    from eligible_transitions transition
    group by transition.model_id
    having count(*) >= greatest(25, coalesce(p_min_workspace_weeks, 25))
      and count(distinct transition.workspace_hash) >= greatest(5, coalesce(p_min_workspaces, 5))
      and count(distinct transition.cohort_week) >= greatest(2, coalesce(p_min_weeks, 2))
  ),
  scored as (
    select aggregate.*,
      aggregate.returning_workspace_weeks::numeric / nullif(aggregate.workspace_weeks, 0) as rate,
      1.96::numeric as z
    from aggregated aggregate
  ),
  confidence as (
    select scored.*,
      (scored.rate + scored.z * scored.z / (2 * scored.workspace_weeks))
        / (1 + scored.z * scored.z / scored.workspace_weeks) as centre,
      scored.z * sqrt(
        (scored.rate * (1 - scored.rate) + scored.z * scored.z / (4 * scored.workspace_weeks))
        / scored.workspace_weeks
      ) / (1 + scored.z * scored.z / scored.workspace_weeks) as margin
    from scored
  ),
  ranked as (
    select confidence.*,
      row_number() over (
        order by confidence.rate desc, confidence.workspace_weeks desc, confidence.model_id
      )::integer as position
    from confidence
  )
  select ranked.model_id, round(ranked.rate * 100, 1), ranked.returning_workspace_weeks,
    ranked.workspace_weeks, ranked.unique_workspaces, ranked.weeks_observed,
    round(greatest(0, ranked.centre - ranked.margin) * 100, 1),
    round(least(1, ranked.centre + ranked.margin) * 100, 1),
    ranked.first_cohort_week, ranked.last_cohort_week, ranked.position
  from ranked
  order by ranked.position
  limit greatest(1, least(coalesce(p_limit, 20), 100));
$function$;

REVOKE ALL ON FUNCTION "public"."get_public_model_retention_rankings"(integer, integer, integer, integer, integer) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.get_public_models_page_payload (
  p_region          text DEFAULT NULL::text,
  p_service_tier    text DEFAULT NULL::text,
  p_organisation_id text DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO 'public'
  AS $function$
  select case when p_region is null and p_service_tier is null then (
    select coalesce(
      jsonb_agg(
        payload order by
          nullif(payload->>'primary_timestamp', '')::numeric desc nulls last,
          model.created_at desc nulls last,
          position
      ),
      '[]'::jsonb
    )
    from public.get_public_models_page_rows() with ordinality as rows(payload, position)
    left join public.v2_models model on model.model_slug = payload->>'model_id'
    where p_organisation_id is null or payload->>'organisation_id' = p_organisation_id
  ) else (
    select coalesce(
      jsonb_agg(
        payload order by
          nullif(payload->>'primary_timestamp', '')::numeric desc nulls last,
          model.created_at desc nulls last,
          position
      ),
      '[]'::jsonb
    )
    from public.get_v2_public_models_page_rows(p_region, p_service_tier)
      with ordinality as rows(payload, position)
    left join public.v2_models model on model.model_slug = payload->>'model_id'
    where p_organisation_id is null or payload->>'organisation_id' = p_organisation_id
  ) end;
$function$;

REVOKE ALL ON FUNCTION "public"."get_public_models_page_payload"(text, text, text) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.get_public_models_page_rows()
  RETURNS SETOF jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO 'public'
  AS $function$
  with routed as materialized (
    select payload
    from public.get_v2_public_models_page_rows(null, null) payload
  ),
  catalogue_only as (
    select jsonb_build_object(
      'model_id', model.model_slug,
      'name', model.name,
      'description', model.description,
      'organisation_id', model.lab_slug,
      'organisation_name', lab.name,
      'primary_date', coalesce(model.released_at, model.announced_at),
      'primary_timestamp', extract(epoch from coalesce(model.released_at, model.announced_at)) * 1000,
      'primary_group_key', to_char(coalesce(model.released_at, model.announced_at), 'YYYY-MM'),
      'status', case
        when lower(coalesce(nullif(model.catalogue_status, 'unknown'), model.status, '')) = 'rumoured' then 'Rumoured'
        when lower(coalesce(nullif(model.catalogue_status, 'unknown'), model.status, '')) = 'announced' then 'Announced'
        when lower(coalesce(nullif(model.catalogue_status, 'unknown'), model.status, '')) = 'preview' then 'Preview'
        when lower(coalesce(nullif(model.catalogue_status, 'unknown'), model.status, '')) = 'available' then 'Available'
        when lower(coalesce(nullif(model.catalogue_status, 'unknown'), model.status, '')) = 'limited_access' then 'Limited Access'
        when lower(coalesce(nullif(model.catalogue_status, 'unknown'), model.status, '')) = 'deprecated' then 'Deprecated'
        when lower(coalesce(nullif(model.catalogue_status, 'unknown'), model.status, '')) = 'retired' then 'Retired'
        when lower(coalesce(nullif(model.catalogue_status, 'unknown'), model.status, '')) = 'withheld' then 'Withheld'
        else null
      end,
      'deprecation_date', model.deprecated_at,
      'retirement_date', model.retired_at,
      'removal_date', model.removal_date,
      'gateway_status', case when model.status = 'draft' then 'coming_soon' else 'not_active' end,
      'gateway_provider_count', 0,
      'gateway_active_provider_count', 0,
      'gateway_endpoints', array[]::text[],
      'gateway_input_modalities', model.input_modalities,
      'gateway_output_modalities', model.output_modalities,
      'gateway_features', array[]::text[],
      'gateway_tiers', array[]::text[],
      'gateway_provider_names', array[]::text[],
      'gateway_active_provider_names', array[]::text[],
      'gateway_execution_regions', array[]::text[],
      'gateway_provider_details', '[]'::jsonb,
      'gateway_api_model_ids', array[]::text[],
      'context_lengths', array[]::integer[],
      'supported_parameters', array[]::text[],
      'pricing_detail_rows', '[]'::jsonb,
      'gateway_monitor_rows', '[]'::jsonb,
      'popularity_tokens_week', null,
      'throughput_week', null,
      'latency_week', null
    ) as payload
    from public.v2_models model
    join public.v2_labs lab on lab.lab_slug = model.lab_slug
    where model.hidden = false
      and model.status <> 'disabled'
      and not exists (
        select 1
        from routed
        where routed.payload->>'model_id' = model.model_slug
      )
  )
  select rows.payload
  from (
    select payload from routed
    union all
    select payload from catalogue_only
  ) rows
  order by
    rows.payload->>'primary_timestamp' desc nulls last,
    rows.payload->>'organisation_name',
    rows.payload->>'name';
$function$;

REVOKE ALL ON FUNCTION "public"."get_public_models_page_rows"() FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.get_public_monitor_rows_payload()
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO 'public'
  AS $function$
  select coalesce(jsonb_agg(to_jsonb(row)), '[]'::jsonb)
  from public.get_monitor_model_rows(false) as row;
$function$;

REVOKE ALL ON FUNCTION "public"."get_public_monitor_rows_payload"() FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.get_public_multimodal_breakdown (
  p_time_range text DEFAULT 'week'::text
)
  RETURNS TABLE (
    model_id                  text,
    text_tokens               bigint,
    audio_tokens              bigint,
    video_tokens              bigint,
    cached_tokens             bigint,
    image_count               bigint,
    input_text_tokens         bigint,
    output_text_tokens        bigint,
    input_image_tokens        bigint,
    output_image_tokens       bigint,
    image_inputs              bigint,
    image_outputs             bigint,
    image_megapixels          numeric,
    input_audio_tokens        bigint,
    output_audio_tokens       bigint,
    audio_inputs              bigint,
    audio_outputs             bigint,
    audio_seconds             numeric,
    input_video_tokens        bigint,
    output_video_tokens       bigint,
    video_inputs              bigint,
    video_outputs             bigint,
    video_seconds             numeric,
    video_pixel_seconds       numeric,
    cached_read_tokens        bigint,
    cached_write_tokens       bigint,
    cached_read_text_tokens   bigint,
    cached_write_text_tokens  bigint,
    cached_read_image_tokens  bigint,
    cached_write_image_tokens bigint,
    cached_read_audio_tokens  bigint,
    cached_write_audio_tokens bigint,
    cached_read_video_tokens  bigint,
    cached_write_video_tokens bigint,
    input_quad_tokens         bigint,
    output_quad_tokens        bigint,
    total_quad_tokens         bigint,
    text_quad_tokens          bigint,
    rerank_quad_tokens        bigint,
    embedding_tokens          bigint,
    embedding_quad_tokens     bigint,
    total_requests            bigint,
    total_cost_nanos          bigint,
    avg_latency_ms            numeric,
    avg_generation_ms         numeric,
    avg_throughput            numeric
  )
  LANGUAGE plpgsql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_since date;
begin
  case p_time_range
    when 'today' then v_since := (now() at time zone 'utc')::date;
    when 'week' then v_since := (now() at time zone 'utc')::date - 7;
    when 'month' then v_since := (now() at time zone 'utc')::date - 30;
    else v_since := (now() at time zone 'utc')::date - 7;
  end case;

  return query
  select
    d.model_id,
    sum(d.input_text_tokens + d.output_text_tokens)::bigint as text_tokens,
    sum(d.input_audio_tokens + d.output_audio_tokens)::bigint as audio_tokens,
    sum(d.input_video_tokens + d.output_video_tokens)::bigint as video_tokens,
    sum(d.cached_read_tokens + d.cached_write_tokens)::bigint as cached_tokens,
    sum(d.image_inputs + d.image_outputs)::bigint as image_count,
    sum(d.input_text_tokens)::bigint as input_text_tokens,
    sum(d.output_text_tokens)::bigint as output_text_tokens,
    sum(d.input_image_tokens)::bigint as input_image_tokens,
    sum(d.output_image_tokens)::bigint as output_image_tokens,
    sum(d.image_inputs)::bigint as image_inputs,
    sum(d.image_outputs)::bigint as image_outputs,
    sum(d.image_megapixels)::numeric as image_megapixels,
    sum(d.input_audio_tokens)::bigint as input_audio_tokens,
    sum(d.output_audio_tokens)::bigint as output_audio_tokens,
    sum(d.audio_inputs)::bigint as audio_inputs,
    sum(d.audio_outputs)::bigint as audio_outputs,
    sum(d.audio_seconds)::numeric as audio_seconds,
    sum(d.input_video_tokens)::bigint as input_video_tokens,
    sum(d.output_video_tokens)::bigint as output_video_tokens,
    sum(d.video_inputs)::bigint as video_inputs,
    sum(d.video_outputs)::bigint as video_outputs,
    sum(d.video_seconds)::numeric as video_seconds,
    sum(d.video_pixel_seconds)::numeric as video_pixel_seconds,
    sum(d.cached_read_tokens)::bigint as cached_read_tokens,
    sum(d.cached_write_tokens)::bigint as cached_write_tokens,
    sum(d.cached_read_text_tokens)::bigint as cached_read_text_tokens,
    sum(d.cached_write_text_tokens)::bigint as cached_write_text_tokens,
    sum(d.cached_read_image_tokens)::bigint as cached_read_image_tokens,
    sum(d.cached_write_image_tokens)::bigint as cached_write_image_tokens,
    sum(d.cached_read_audio_tokens)::bigint as cached_read_audio_tokens,
    sum(d.cached_write_audio_tokens)::bigint as cached_write_audio_tokens,
    sum(d.cached_read_video_tokens)::bigint as cached_read_video_tokens,
    sum(d.cached_write_video_tokens)::bigint as cached_write_video_tokens,
    sum(d.input_quad_tokens)::bigint as input_quad_tokens,
    sum(d.output_quad_tokens)::bigint as output_quad_tokens,
    sum(d.total_quad_tokens)::bigint as total_quad_tokens,
    sum(d.text_quad_tokens)::bigint as text_quad_tokens,
    sum(d.rerank_quad_tokens)::bigint as rerank_quad_tokens,
    sum(d.embedding_tokens)::bigint as embedding_tokens,
    sum(d.embedding_quad_tokens)::bigint as embedding_quad_tokens,
    sum(d.requests)::bigint as total_requests,
    sum(d.total_cost_nanos)::bigint as total_cost_nanos,
    case
      when sum(d.latency_samples) > 0
      then round(sum(d.latency_sum_ms)::numeric / sum(d.latency_samples)::numeric, 2)
      else null
    end as avg_latency_ms,
    case
      when sum(d.generation_samples) > 0
      then round(sum(d.generation_sum_ms)::numeric / sum(d.generation_samples)::numeric, 2)
      else null
    end as avg_generation_ms,
    case
      when sum(d.throughput_samples) > 0
      then round(sum(d.throughput_sum)::numeric / sum(d.throughput_samples)::numeric, 2)
      else null
    end as avg_throughput
  from public.v2_rpc_gateway_model_usage_daily d
  where d.day_bucket >= v_since
    and lower(d.model_id) not in ('unknown', 'other')
  group by d.model_id
  having
    sum(d.input_text_tokens + d.output_text_tokens) > 0
    or sum(d.input_image_tokens + d.output_image_tokens) > 0
    or sum(d.image_inputs + d.image_outputs) > 0
    or sum(d.input_audio_tokens + d.output_audio_tokens) > 0
    or sum(d.audio_seconds) > 0
    or sum(d.input_video_tokens + d.output_video_tokens) > 0
    or sum(d.video_seconds) > 0
    or sum(d.rerank_quad_tokens) > 0
    or sum(d.embedding_tokens) > 0
  order by (
    sum(d.input_text_tokens + d.output_text_tokens)
    + sum(d.input_image_tokens + d.output_image_tokens)
    + sum(d.input_audio_tokens + d.output_audio_tokens)
    + sum(d.input_video_tokens + d.output_video_tokens)
    + sum(d.embedding_tokens)
    + sum(d.rerank_quad_tokens)
  ) desc;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_public_provider_index()
  RETURNS TABLE (
    provider_slug               text,
    provider_name               text,
    colour                      text,
    country_code                text,
    subdivision_code            text,
    default_execution_regions   text[],
    default_data_regions        text[],
    provider_family_id          text,
    offer_label                 text,
    offer_scope                 text,
    is_gateway_provider         boolean,
    provider_status             text,
    byok_available              boolean,
    prompt_training_policy      text,
    data_policy_tier            text,
    zero_data_retention         text,
    data_retention_days         integer,
    privacy_policy_url          text,
    terms_of_service_url        text,
    total_model_ids             text[],
    active_model_ids            text[],
    free_model_ids              text[],
    requests_24h                bigint,
    tokens_24h                  numeric,
    tokens_30d                  numeric,
    last_updated_at             timestamp with time zone,
    text_input_model_ids        text[],
    text_output_model_ids       text[],
    image_input_model_ids       text[],
    image_output_model_ids      text[],
    video_input_model_ids       text[],
    video_output_model_ids      text[],
    audio_input_model_ids       text[],
    audio_output_model_ids      text[],
    moderation_input_model_ids  text[],
    moderation_output_model_ids text[],
    embedding_input_model_ids   text[],
    embedding_output_model_ids  text[]
  )
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  with providers as (
    select
      provider.provider_slug,
      provider.name,
      provider.country_code,
      provider.subdivision_code,
      provider.default_execution_regions,
      provider.default_data_regions,
      provider.lab_slug,
      provider.metadata,
      provider.routable,
      provider.routing_enabled,
      provider.status,
      provider.byok_available,
      provider.prompt_training_policy,
      provider.data_policy_tier,
      provider.zero_data_retention,
      provider.data_retention_days
    from public.v2_providers provider
    where lower(provider.provider_slug) not in ('inception', 'inceptron', 'nextbit')
      and (
        provider.status <> 'external'
        or exists (
          select 1
          from public.v2_model_provider_routes route_override
          where route_override.provider_slug = provider.provider_slug
            and route_override.routing_enabled = true
            and coalesce(route_override.metadata->>'external_routing_override', 'false') = 'true'
        )
      )
  ),
  eligible_routes as (
    select
      route.provider_slug,
      route.model_slug,
      route.routing_enabled,
      route.status,
      route.effective_from,
      route.effective_to,
      route.updated_at,
      model.variant_kind,
      case
        when cardinality(route.input_modalities) > 0 then route.input_modalities
        else model.input_modalities
      end as input_modalities,
      case
        when cardinality(route.output_modalities) > 0 then route.output_modalities
        else model.output_modalities
      end as output_modalities
    from public.v2_model_provider_routes route
    join providers provider using (provider_slug)
    join public.v2_models model using (model_slug)
    where not model.hidden
      and (
        provider.status <> 'external'
        or coalesce(route.metadata->>'external_routing_override', 'false') = 'true'
      )
  ),
  coverage as (
    select
      route.provider_slug,
      array_agg(distinct route.model_slug order by route.model_slug) as total_model_ids,
      array_agg(distinct route.model_slug order by route.model_slug) filter (
        where route.routing_enabled
          and route.status in ('active', 'degraded')
          and (route.effective_from is null or route.effective_from <= now())
          and (route.effective_to is null or route.effective_to > now())
      ) as active_model_ids,
      array_agg(distinct route.model_slug order by route.model_slug) filter (
        where route.variant_kind = 'free' or lower(route.model_slug) like '%:free'
      ) as free_model_ids,
      max(route.updated_at) as last_updated_at,
      array_agg(distinct route.model_slug order by route.model_slug) filter (where 'text' = any(route.input_modalities)) as text_input_model_ids,
      array_agg(distinct route.model_slug order by route.model_slug) filter (where 'text' = any(route.output_modalities)) as text_output_model_ids,
      array_agg(distinct route.model_slug order by route.model_slug) filter (where 'image' = any(route.input_modalities)) as image_input_model_ids,
      array_agg(distinct route.model_slug order by route.model_slug) filter (where 'image' = any(route.output_modalities)) as image_output_model_ids,
      array_agg(distinct route.model_slug order by route.model_slug) filter (where 'video' = any(route.input_modalities)) as video_input_model_ids,
      array_agg(distinct route.model_slug order by route.model_slug) filter (where 'video' = any(route.output_modalities)) as video_output_model_ids,
      array_agg(distinct route.model_slug order by route.model_slug) filter (where 'audio' = any(route.input_modalities) or 'music' = any(route.input_modalities)) as audio_input_model_ids,
      array_agg(distinct route.model_slug order by route.model_slug) filter (where 'audio' = any(route.output_modalities) or 'music' = any(route.output_modalities)) as audio_output_model_ids,
      array_agg(distinct route.model_slug order by route.model_slug) filter (where 'moderation' = any(route.input_modalities)) as moderation_input_model_ids,
      array_agg(distinct route.model_slug order by route.model_slug) filter (where 'moderation' = any(route.output_modalities)) as moderation_output_model_ids,
      array_agg(distinct route.model_slug order by route.model_slug) filter (where 'embedding' = any(route.input_modalities) or 'embeddings' = any(route.input_modalities)) as embedding_input_model_ids,
      array_agg(distinct route.model_slug order by route.model_slug) filter (where 'embedding' = any(route.output_modalities) or 'embeddings' = any(route.output_modalities)) as embedding_output_model_ids
    from eligible_routes route
    group by route.provider_slug
  ),
  usage as (
    select
      summary.provider as provider_slug,
      summary.requests_24h,
      summary.tokens_24h,
      summary.tokens_30d
    from public.get_public_provider_usage_summary() summary
  )
  select
    provider.provider_slug,
    provider.name,
    nullif(provider.metadata->>'colour', ''),
    coalesce(provider.country_code, ''),
    provider.subdivision_code,
    provider.default_execution_regions,
    provider.default_data_regions,
    coalesce(nullif(provider.metadata->>'provider_family_id', ''), provider.lab_slug),
    nullif(provider.metadata->>'offer_label', ''),
    nullif(provider.metadata->>'offer_scope', ''),
    provider.routable
      and provider.routing_enabled
      and provider.status in ('active', 'degraded'),
    provider.status,
    provider.byok_available,
    provider.prompt_training_policy,
    provider.data_policy_tier,
    case when provider.zero_data_retention then 'default' else 'unsupported' end,
    provider.data_retention_days,
    nullif(provider.metadata->>'privacy_policy_url', ''),
    nullif(provider.metadata->>'terms_of_service_url', ''),
    coverage.total_model_ids,
    coalesce(coverage.active_model_ids, array[]::text[]),
    coalesce(coverage.free_model_ids, array[]::text[]),
    coalesce(usage.requests_24h, 0),
    coalesce(usage.tokens_24h, 0),
    coalesce(usage.tokens_30d, 0),
    coverage.last_updated_at,
    coalesce(coverage.text_input_model_ids, array[]::text[]),
    coalesce(coverage.text_output_model_ids, array[]::text[]),
    coalesce(coverage.image_input_model_ids, array[]::text[]),
    coalesce(coverage.image_output_model_ids, array[]::text[]),
    coalesce(coverage.video_input_model_ids, array[]::text[]),
    coalesce(coverage.video_output_model_ids, array[]::text[]),
    coalesce(coverage.audio_input_model_ids, array[]::text[]),
    coalesce(coverage.audio_output_model_ids, array[]::text[]),
    coalesce(coverage.moderation_input_model_ids, array[]::text[]),
    coalesce(coverage.moderation_output_model_ids, array[]::text[]),
    coalesce(coverage.embedding_input_model_ids, array[]::text[]),
    coalesce(coverage.embedding_output_model_ids, array[]::text[])
  from providers provider
  join coverage using (provider_slug)
  left join usage using (provider_slug)
  order by provider.name, provider.provider_slug;
$function$;

REVOKE ALL ON FUNCTION "public"."get_public_provider_index"() FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.get_public_provider_usage_summary()
  RETURNS TABLE (
    provider     text,
    requests_24h bigint,
    tokens_24h   numeric,
    tokens_30d   numeric
  )
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  with hourly as (
    select
      usage.provider,
      coalesce(sum(usage.requests), 0)::bigint as requests_24h,
      coalesce(sum(usage.total_tokens), 0)::numeric as tokens_24h
    from (
with meters as (
  select
    meter.rollup_id,
    coalesce(
      max(meter.quantity) filter (where meter.meter_key = 'total_tokens'),
      sum(meter.quantity) filter (where meter.meter_key in ('input_tokens', 'output_tokens')),
      sum(meter.quantity) filter (where meter.meter_key in ('input_text_tokens', 'output_text_tokens')),
      0
    )::numeric as total_tokens
  from public.v2_public_usage_hourly_meters meter
  join public.v2_public_usage_hourly scoped on scoped.rollup_id = meter.rollup_id
  where scoped.bucket_start >= now() - interval '24 hours'
  group by meter.rollup_id
)
select
  usage.bucket_start as bucket_15m,
  usage.model_slug as canonical_model_id,
  route.provider_slug as provider,
  usage.app_id,
  usage.requests,
  usage.successful_requests as success_requests,
  coalesce(meters.total_tokens, 0) as total_tokens,
  usage.cost_nanos::bigint as total_cost_nanos,
  usage.latency_sum_ms,
  usage.latency_count as latency_samples,
  usage.throughput_sum,
  usage.throughput_count as throughput_samples,
  usage.generation_sum_ms,
  usage.generation_count as generation_samples
from public.v2_public_usage_hourly usage
join public.v2_model_provider_routes route
  on route.provider_model_id = usage.provider_model_id
  and coalesce(route.is_stealth, false) = false
  and route.routing_enabled = true
  and route.status in ('active', 'degraded')
  and (route.effective_from is null or route.effective_from <= now())
  and (route.effective_to is null or route.effective_to > now())
join public.v2_models model
  on model.model_slug = usage.model_slug
  and model.hidden = false
  and model.status <> 'disabled'
left join meters on meters.rollup_id = usage.rollup_id
) usage
    where usage.provider is not null
      and usage.bucket_15m >= now() - interval '24 hours'
    group by usage.provider
  ),
  daily as (
    select
      usage.provider,
      coalesce(sum(usage.total_tokens), 0)::numeric as tokens_30d
    from (
with meters as (
  select
    meter.rollup_id,
    coalesce(
      max(meter.quantity) filter (where meter.meter_key = 'total_tokens'),
      sum(meter.quantity) filter (where meter.meter_key in ('input_tokens', 'output_tokens')),
      sum(meter.quantity) filter (where meter.meter_key in ('input_text_tokens', 'output_text_tokens')),
      0
    )::numeric as total_tokens
  from public.v2_public_usage_daily_meters meter
  join public.v2_public_usage_daily scoped on scoped.rollup_id = meter.rollup_id
  where scoped.usage_date >= current_date - 29
  group by meter.rollup_id
)
select
  usage.usage_date as day_bucket,
  usage.model_slug as canonical_model_id,
  route.provider_slug as provider,
  usage.app_id,
  usage.requests,
  usage.successful_requests as success_requests,
  coalesce(meters.total_tokens, 0) as total_tokens,
  usage.cost_nanos::bigint as total_cost_nanos,
  usage.latency_sum_ms,
  usage.latency_count as latency_samples,
  usage.throughput_sum,
  usage.throughput_count as throughput_samples,
  usage.generation_sum_ms,
  usage.generation_count as generation_samples
from public.v2_public_usage_daily usage
join public.v2_model_provider_routes route
  on route.provider_model_id = usage.provider_model_id
  and coalesce(route.is_stealth, false) = false
  and route.routing_enabled = true
  and route.status in ('active', 'degraded')
  and (route.effective_from is null or route.effective_from <= now())
  and (route.effective_to is null or route.effective_to > now())
join public.v2_models model
  on model.model_slug = usage.model_slug
  and model.hidden = false
  and model.status <> 'disabled'
left join meters on meters.rollup_id = usage.rollup_id
) usage
    where usage.provider is not null
      and usage.day_bucket >= current_date - 29
    group by usage.provider
  ),
  providers as (
    select hourly.provider from hourly
    union
    select daily.provider from daily
  )
  select
    providers.provider,
    coalesce(hourly.requests_24h, 0),
    coalesce(hourly.tokens_24h, 0),
    coalesce(daily.tokens_30d, 0)
  from providers
  left join hourly using (provider)
  left join daily using (provider)
  order by providers.provider;
$function$;

CREATE OR REPLACE FUNCTION public.get_public_reliability_metrics (
  p_time_range   text    DEFAULT 'week'::text,
  p_min_requests integer DEFAULT 100
)
  RETURNS TABLE (
    model_id            text,
    provider            text,
    total_requests      bigint,
    successful_requests bigint,
    success_rate        numeric,
    median_latency_ms   numeric,
    p95_latency_ms      numeric,
    p99_latency_ms      numeric,
    common_errors       jsonb
  )
  LANGUAGE plpgsql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
DECLARE
  v_since timestamptz;
  v_now timestamptz := now();
BEGIN
  CASE p_time_range
    WHEN 'today' THEN v_since := date_trunc('day', v_now);
    WHEN 'week' THEN v_since := v_now - interval '7 days';
    WHEN 'month' THEN v_since := date_trunc('month', v_now);
    ELSE v_since := v_now - interval '7 days';
  END CASE;

  RETURN QUERY
  WITH error_aggregates AS (
    SELECT
      gr.model_id,
      gr.provider,
      jsonb_agg(
        jsonb_build_object(
          'error_code', gr.error_code,
          'count', error_count
        ) ORDER BY error_count DESC
      ) FILTER (WHERE gr.error_code IS NOT NULL) as errors
    FROM private.v2_rpc_gateway_requests_compat gr
    CROSS JOIN LATERAL (
      SELECT COUNT(*) as error_count
      FROM private.v2_rpc_gateway_requests_compat gr2
      WHERE gr2.model_id = gr.model_id
        AND gr2.provider = gr.provider
        AND gr2.error_code = gr.error_code
        AND gr2.created_at >= v_since
    ) ec
    WHERE gr.created_at >= v_since
      AND gr.error_code IS NOT NULL
    GROUP BY gr.model_id, gr.provider
  )
  SELECT
    gr.model_id,
    gr.provider,
    COUNT(*)::bigint as total_requests,
    COUNT(*) FILTER (WHERE gr.success)::bigint as successful_requests,
    ROUND(AVG(CASE WHEN gr.success THEN 1.0 ELSE 0.0 END)::numeric, 4) as success_rate,
    ROUND(percentile_cont(0.5) WITHIN GROUP (ORDER BY gr.latency_ms)::numeric, 0) as median_latency_ms,
    ROUND(percentile_cont(0.95) WITHIN GROUP (ORDER BY gr.latency_ms)::numeric, 0) as p95_latency_ms,
    ROUND(percentile_cont(0.99) WITHIN GROUP (ORDER BY gr.latency_ms)::numeric, 0) as p99_latency_ms,
    COALESCE(ea.errors, '[]'::jsonb) as common_errors
  FROM private.v2_rpc_gateway_requests_compat gr
  LEFT JOIN error_aggregates ea ON gr.model_id = ea.model_id AND gr.provider = ea.provider
  WHERE gr.created_at >= v_since
    AND gr.model_id IS NOT NULL
    AND gr.provider IS NOT NULL
  GROUP BY gr.model_id, gr.provider, ea.errors
  HAVING COUNT(*) >= p_min_requests
  ORDER BY success_rate ASC, total_requests DESC;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_public_search_index()
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO 'public'
  AS $function$
  with visible_models as (
    select
      model.model_id,
      model.name,
      model.organisation_id,
      organisation.name as organisation_name,
      coalesce(model.release_date, model.announcement_date) as primary_date
    from private.v2_rpc_models_compat model
    left join private.v2_rpc_labs_compat organisation
      on organisation.organisation_id = model.organisation_id
    where model.hidden = false
  ),
  active_provider_counts as (
    select
      provider_model.provider_id,
      count(distinct coalesce(
        nullif(btrim(provider_model.api_model_id), ''),
        nullif(btrim(provider_model.provider_api_model_id), ''),
        nullif(btrim(provider_model.model_id), '')
      )) filter (
        where provider_model.is_active_gateway = true
          and (provider_model.effective_from is null or provider_model.effective_from <= now())
          and (provider_model.effective_to is null or provider_model.effective_to > now())
      )::bigint as active_models
    from private.v2_rpc_routes_compat provider_model
    group by provider_model.provider_id
  )
  select jsonb_build_object(
    'm', coalesce((
      select jsonb_agg(
        jsonb_build_array(
          model.model_id,
          model.name,
          model.organisation_name,
          '/models/' || model.model_id,
          model.organisation_id,
          case
            when model.primary_date is null then null
            else to_char(model.primary_date, 'FMMonth YYYY')
          end
        )
        order by model.primary_date desc nulls last, model.name, model.model_id
      )
      from visible_models model
    ), '[]'::jsonb),
    'o', coalesce((
      select jsonb_agg(
        jsonb_build_array(
          organisation.organisation_id,
          coalesce(nullif(organisation.name, ''), organisation.organisation_id),
          null,
          '/organisations/' || organisation.organisation_id,
          organisation.organisation_id
        )
        order by coalesce(nullif(organisation.name, ''), organisation.organisation_id), organisation.organisation_id
      )
      from private.v2_rpc_labs_compat organisation
    ), '[]'::jsonb),
    'b', coalesce((
      select jsonb_agg(
        jsonb_build_array(
          benchmark.id,
          benchmark.name,
          coalesce(benchmark.total_models, 0)::text || ' models',
          '/benchmarks/' || benchmark.id
        )
        order by benchmark.name, benchmark.id
      )
      from private.v2_rpc_benchmarks_compat benchmark
    ), '[]'::jsonb),
    'p', coalesce((
      select jsonb_agg(
        jsonb_build_array(
          provider.api_provider_id,
          provider.api_provider_name,
          coalesce(provider_counts.active_models, 0)::text || ' active models',
          '/api-providers/' || provider.api_provider_id,
          provider.api_provider_id
        )
        order by provider.api_provider_name, provider.api_provider_id
      )
      from private.v2_rpc_providers_compat provider
      left join active_provider_counts provider_counts
        on provider_counts.provider_id = provider.api_provider_id
    ), '[]'::jsonb),
    's', '[]'::jsonb,
    'c', '[]'::jsonb,
    'v', coalesce((
      select generation
      from public.web_cache_generations
      where scope = 'search'
    ), 1)
  );
$function$;

REVOKE ALL ON FUNCTION "public"."get_public_search_index"() FROM PUBLIC, "anon";

CREATE OR REPLACE FUNCTION public.get_public_summary_stats()
  RETURNS TABLE (
    total_requests_24h bigint,
    total_tokens_24h   bigint,
    total_models       integer,
    total_providers    integer,
    avg_latency_ms     numeric,
    success_rate_24h   numeric
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public'
  AS $function$
  with meters as (
    select meter.rollup_id, sum(meter.quantity) filter (where meter.meter_key in ('input_tokens','output_tokens'))::bigint as tokens
    from public.v2_public_usage_hourly_meters meter group by meter.rollup_id
  ), aggregate as (
    select sum(usage.requests)::bigint as requests, sum(coalesce(meters.tokens,0))::bigint as tokens,
      count(distinct usage.model_slug)::integer as models, count(distinct route.provider_slug)::integer as providers,
      sum(usage.latency_sum_ms)::numeric as latency_sum, sum(usage.latency_count)::bigint as latency_count,
      sum(usage.successful_requests)::bigint as successes
    from public.v2_public_usage_hourly usage
    left join meters on meters.rollup_id = usage.rollup_id
    left join public.v2_model_provider_routes route on route.provider_model_id = usage.provider_model_id
    where usage.bucket_start >= now() - interval '24 hours'
  )
  select coalesce(requests,0), coalesce(tokens,0), coalesce(models,0), coalesce(providers,0),
    round(latency_sum / nullif(latency_count,0),0), round(successes::numeric / nullif(requests,0),4)
  from aggregate;
$function$;

CREATE OR REPLACE FUNCTION public.get_public_text_leaderboard_timeseries (
  p_time_range text    DEFAULT 'year'::text,
  p_top_n      integer DEFAULT 20
)
  RETURNS TABLE (
    bucket   timestamp with time zone,
    model_id text,
    requests bigint,
    tokens   numeric,
    colour   text
  )
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select series.*
  from public.get_public_modality_usage_timeseries(
    'text_tokens',
    coalesce(p_time_range, 'year'),
    greatest(1, least(coalesce(p_top_n, 20), 100))
  ) series;
$function$;

REVOKE ALL ON FUNCTION "public"."get_public_text_leaderboard_timeseries"(text, integer) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.get_public_tool_call_timeseries (
  p_time_range  text    DEFAULT 'year'::text,
  p_bucket_size text    DEFAULT 'week'::text,
  p_top_n       integer DEFAULT 10
)
  RETURNS TABLE (
    bucket   timestamp with time zone,
    model_id text,
    requests bigint,
    tokens   bigint,
    colour   text
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public'
  AS $function$
  with bounds as (
    select case p_time_range
      when 'today' then current_date
      when 'week' then current_date - 7
      when 'month' then current_date - 30
      when 'year' then current_date - 365
      else current_date - 365
    end as since_date
  ),
  top_models as (
    select usage.model_slug
    from public.v2_public_usage_daily usage
    cross join bounds
    where usage.usage_date >= bounds.since_date
      and usage.tool_call_count > 0
      and lower(usage.model_slug) not in ('unknown', 'other')
    group by usage.model_slug
    order by sum(usage.tool_call_count) desc, usage.model_slug
    limit greatest(1, least(coalesce(p_top_n, 10), 100))
  )
  select
    (
      case p_bucket_size
        when 'day' then date_trunc('day', usage.usage_date::timestamp)
        else date_trunc('week', usage.usage_date::timestamp)
      end at time zone 'UTC'
    ) as bucket,
    usage.model_slug as model_id,
    sum(usage.tool_call_count)::bigint as requests,
    0::bigint as tokens,
    null::text as colour
  from public.v2_public_usage_daily usage
  join top_models on top_models.model_slug = usage.model_slug
  cross join bounds
  where usage.usage_date >= bounds.since_date
    and usage.tool_call_count > 0
  group by 1, usage.model_slug
  order by 1, sum(usage.tool_call_count) desc, usage.model_slug;
$function$;

CREATE OR REPLACE FUNCTION public.get_public_top_apps (
  p_limit      integer DEFAULT 20,
  p_time_range text    DEFAULT 'week'::text
)
  RETURNS TABLE (
    app_id        text,
    app_name      text,
    requests      bigint,
    tokens        bigint,
    unique_models integer
  )
  LANGUAGE plpgsql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_today date := (now() at time zone 'utc')::date;
  v_since date;
begin
  case p_time_range
    when 'today' then v_since := v_today;
    when 'week' then v_since := v_today - 7;
    when '4w' then v_since := v_today - 28;
    when 'month' then v_since := v_today - 30;
    else v_since := v_today - 7;
  end case;

  return query
  with eligible_usage as (
    select
      public.api_app_url_group_key(aa.url, aa.id::text) as url_group,
      aa.id::text as member_id,
      aa.title as member_name,
      aa.last_seen,
      d.model_id,
      d.requests,
      d.tokens
    from public.v2_rpc_public_app_model_usage_daily d
    join public.api_apps aa on aa.id::text = d.app_id
    where d.day_bucket >= v_since
      and aa.is_public = true
      and aa.is_active = true
  ),
  member_totals as (
    select
      url_group,
      member_id,
      member_name,
      last_seen,
      sum(eligible_usage.requests)::bigint as member_requests,
      sum(eligible_usage.tokens)::bigint as member_tokens
    from eligible_usage
    group by
      eligible_usage.url_group,
      eligible_usage.member_id,
      eligible_usage.member_name,
      eligible_usage.last_seen
  ),
  representatives as (
    select distinct on (url_group)
      url_group,
      member_id,
      member_name
    from member_totals
    order by
      url_group,
      member_tokens desc,
      member_requests desc,
      last_seen desc nulls last,
      member_id
  ),
  group_totals as (
    select
      url_group,
      sum(eligible_usage.requests)::bigint as request_count,
      sum(eligible_usage.tokens)::bigint as token_count,
      count(distinct eligible_usage.model_id)::integer as model_count
    from eligible_usage
    group by eligible_usage.url_group
  )
  select
    representatives.member_id,
    representatives.member_name,
    group_totals.request_count,
    group_totals.token_count,
    group_totals.model_count
  from group_totals
  join representatives using (url_group)
  order by group_totals.token_count desc, group_totals.request_count desc
  limit greatest(p_limit, 1);
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_public_top_models_with_metadata (
  p_time_range text    DEFAULT 'week'::text,
  p_limit      integer DEFAULT 6
)
  RETURNS TABLE (
    model_id          text,
    model_name        text,
    organisation_id   text,
    organisation_name text,
    total_tokens      bigint
  )
  LANGUAGE plpgsql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_since timestamptz;
  v_now timestamptz := now();
begin
  case p_time_range
    when 'today' then
      v_since := date_trunc('day', v_now);
    when 'week' then
      v_since := v_now - interval '7 days';
    when 'month' then
      v_since := date_trunc('month', v_now);
    else
      v_since := v_now - interval '7 days';
  end case;

  return query
  with base_requests as (
    select
      gr.provider,
      gr.model_id as raw_model_id,
      public.gateway_usage_total_tokens(gr.usage) as tokens
    from private.v2_rpc_gateway_requests_compat gr
    where gr.created_at >= v_since
      and gr.model_id is not null
      and gr.provider is not null
      and gr.provider <> ''
  ),
  resolved as (
    select
      br.raw_model_id,
      br.tokens,
      public.resolve_public_model_id(br.raw_model_id, br.provider) as canonical_model_id
    from base_requests br
  ),
  enriched as (
    select
      coalesce(r.canonical_model_id, r.raw_model_id) as resolved_model_id,
      coalesce(dm.name, r.raw_model_id) as resolved_model_name,
      coalesce(dm.organisation_id, org_guess.organisation_id) as resolved_org_id,
      coalesce(org.name, org_guess.name) as resolved_org_name,
      r.tokens
    from resolved r
    left join private.v2_rpc_models_compat dm
      on dm.model_id = r.canonical_model_id
    left join private.v2_rpc_labs_compat org
      on org.organisation_id = dm.organisation_id
    left join lateral (
      select o.organisation_id, o.name
      from private.v2_rpc_labs_compat o
      where lower(o.organisation_id) = lower(split_part(r.raw_model_id, '/', 1))
         or lower(o.name) = lower(split_part(r.raw_model_id, '/', 1))
      order by
        case
          when lower(o.organisation_id) = lower(split_part(r.raw_model_id, '/', 1))
            then 0
          else 1
        end
      limit 1
    ) org_guess on true
  ),
  aggregated as (
    select
      e.resolved_model_id,
      max(e.resolved_model_name) as resolved_model_name,
      max(e.resolved_org_id) as resolved_org_id,
      max(e.resolved_org_name) as resolved_org_name,
      sum(e.tokens)::bigint as summed_tokens
    from enriched e
    where e.tokens >= 0
    group by e.resolved_model_id
  )
  select
    a.resolved_model_id as model_id,
    a.resolved_model_name as model_name,
    a.resolved_org_id as organisation_id,
    a.resolved_org_name as organisation_name,
    a.summed_tokens as total_tokens
  from aggregated a
  order by a.summed_tokens desc
  limit greatest(1, p_limit);
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_public_trending_apps (
  p_limit           integer DEFAULT 20,
  p_min_week_tokens bigint  DEFAULT 0
)
  RETURNS TABLE (
    app_id               text,
    app_name             text,
    current_week_tokens  bigint,
    previous_week_tokens bigint,
    growth_tokens        bigint,
    growth_pct           numeric
  )
  LANGUAGE plpgsql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_today date := (now() at time zone 'utc')::date;
begin
  return query
  with eligible_usage as (
    select
      public.api_app_url_group_key(aa.url, aa.id::text) as url_group,
      aa.id::text as member_id,
      aa.title as member_name,
      aa.last_seen,
      d.day_bucket,
      d.tokens
    from public.v2_rpc_public_app_model_usage_daily d
    join public.api_apps aa on aa.id::text = d.app_id
    where d.day_bucket >= v_today - 14
      and aa.is_public = true
      and aa.is_active = true
  ),
  member_totals as (
    select
      url_group,
      member_id,
      member_name,
      last_seen,
      sum(eligible_usage.tokens)::bigint as member_tokens
    from eligible_usage
    group by
      eligible_usage.url_group,
      eligible_usage.member_id,
      eligible_usage.member_name,
      eligible_usage.last_seen
  ),
  representatives as (
    select distinct on (url_group)
      url_group,
      member_id,
      member_name
    from member_totals
    order by
      url_group,
      member_tokens desc,
      last_seen desc nulls last,
      member_id
  ),
  weekly as (
    select
      url_group,
      sum(eligible_usage.tokens) filter (
        where eligible_usage.day_bucket >= v_today - 7
      )::bigint as week_0_tokens,
      sum(eligible_usage.tokens) filter (
        where eligible_usage.day_bucket >= v_today - 14
          and eligible_usage.day_bucket < v_today - 7
      )::bigint as week_1_tokens
    from eligible_usage
    group by eligible_usage.url_group
  )
  select
    representatives.member_id,
    representatives.member_name,
    coalesce(weekly.week_0_tokens, 0)::bigint,
    coalesce(weekly.week_1_tokens, 0)::bigint,
    (coalesce(weekly.week_0_tokens, 0) - coalesce(weekly.week_1_tokens, 0))::bigint,
    case
      when coalesce(weekly.week_1_tokens, 0) > 0 then
        round(
          (
            (coalesce(weekly.week_0_tokens, 0) - coalesce(weekly.week_1_tokens, 0))::numeric
            / weekly.week_1_tokens::numeric
          ) * 100,
          2
        )
      when coalesce(weekly.week_0_tokens, 0) > 0 then null
      else 0
    end
  from weekly
  join representatives using (url_group)
  where coalesce(weekly.week_0_tokens, 0) > coalesce(weekly.week_1_tokens, 0)
    and coalesce(weekly.week_0_tokens, 0) >= p_min_week_tokens
  order by
    (coalesce(weekly.week_0_tokens, 0) - coalesce(weekly.week_1_tokens, 0)) desc,
    coalesce(weekly.week_0_tokens, 0) desc
  limit greatest(p_limit, 1);
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_public_trending_models (
  p_limit        integer DEFAULT 20,
  p_min_requests integer DEFAULT 0
)
  RETURNS TABLE (
    model_id               text,
    provider               text,
    current_week_requests  bigint,
    previous_week_requests bigint,
    two_weeks_ago_requests bigint,
    velocity               numeric,
    momentum_score         numeric
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public'
  AS $function$
  with weekly as (
    select usage.model_slug, coalesce(route.provider_slug,'unknown') as provider,
      sum(usage.requests) filter (where usage.usage_date >= current_date - 7)::bigint as week_0,
      sum(usage.requests) filter (where usage.usage_date >= current_date - 14 and usage.usage_date < current_date - 7)::bigint as week_1,
      sum(usage.requests) filter (where usage.usage_date >= current_date - 21 and usage.usage_date < current_date - 14)::bigint as week_2
    from public.v2_public_usage_daily usage
    left join public.v2_model_provider_routes route on route.provider_model_id = usage.provider_model_id
    where usage.usage_date >= current_date - 21 and lower(usage.model_slug) not in ('unknown','other')
    group by usage.model_slug, coalesce(route.provider_slug,'unknown')
  )
  select model_slug, provider, coalesce(week_0,0), coalesce(week_1,0), coalesce(week_2,0),
    ((coalesce(week_0,0)-coalesce(week_1,0))-(coalesce(week_1,0)-coalesce(week_2,0)))::numeric,
    (((coalesce(week_0,0)-coalesce(week_1,0))-(coalesce(week_1,0)-coalesce(week_2,0)))*2.0 + (coalesce(week_0,0)-coalesce(week_1,0)))::numeric
  from weekly
  where coalesce(week_0,0) >= p_min_requests and coalesce(week_0,0) > coalesce(week_1,0)
  order by 7 desc limit greatest(1, least(coalesce(p_limit,20),100));
$function$;

CREATE OR REPLACE FUNCTION public.get_public_unique_user_timeseries (
  p_time_range  text    DEFAULT 'year'::text,
  p_bucket_size text    DEFAULT 'week'::text,
  p_top_n       integer DEFAULT 10
)
  RETURNS TABLE (
    bucket   timestamp with time zone,
    model_id text,
    requests bigint,
    tokens   bigint,
    users    bigint,
    colour   text
  )
  LANGUAGE plpgsql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
#variable_conflict use_column
declare
  v_since date;
begin
  case p_time_range
    when '24h' then v_since := (now() at time zone 'utc')::date - 1;
    when 'today' then v_since := (now() at time zone 'utc')::date;
    when 'week' then v_since := (now() at time zone 'utc')::date - 7;
    when 'month' then v_since := (now() at time zone 'utc')::date - 30;
    when 'year' then v_since := (now() at time zone 'utc')::date - 365;
    else v_since := (now() at time zone 'utc')::date - 365;
  end case;

  return query
  with actor_rows as (
    select
      case
        when p_bucket_size = 'month' then date_trunc('month', d.day_bucket::timestamp)::timestamptz
        when p_bucket_size = 'day' then d.day_bucket::timestamptz
        else date_trunc('week', d.day_bucket::timestamp)::timestamptz
      end as time_bucket,
      d.model_id,
      d.actor_hash,
      sum(d.requests)::bigint as req_count,
      sum(d.tokens)::bigint as tok_count
    from public.public_model_user_usage_daily d
    where d.day_bucket >= v_since
      and lower(d.model_id) not in ('unknown', 'other')
    group by 1, 2, 3
  ),
  base as (
    select
      ar.time_bucket,
      ar.model_id,
      sum(ar.req_count)::bigint as req_count,
      sum(ar.tok_count)::bigint as tok_count,
      count(distinct ar.actor_hash)::bigint as user_count
    from actor_rows ar
    group by ar.time_bucket, ar.model_id
  ),
  ranked_base as (
    select
      b.*,
      row_number() over (
        partition by b.time_bucket
        order by b.user_count desc, b.tok_count desc, b.req_count desc, b.model_id
      ) as bucket_rank
    from base b
    where b.user_count > 0
  ),
  bucketed as (
    select
      ar.time_bucket,
      case
        when rb.bucket_rank <= greatest(p_top_n, 1) then ar.model_id
        else 'Other'
      end as model_group,
      sum(ar.req_count)::bigint as req_count,
      sum(ar.tok_count)::bigint as tok_count,
      count(distinct ar.actor_hash)::bigint as user_count
    from actor_rows ar
    left join ranked_base rb
      on rb.time_bucket = ar.time_bucket
      and rb.model_id = ar.model_id
    group by ar.time_bucket, model_group
  )
  select
    b.time_bucket as bucket,
    b.model_group as model_id,
    b.req_count as requests,
    b.tok_count as tokens,
    b.user_count as users,
    case
      when b.model_group = 'Other' then null
      else org.colour
    end as colour
  from bucketed b
  left join private.v2_rpc_models_compat dm on dm.model_id = b.model_group
  left join private.v2_rpc_labs_compat org on dm.organisation_id = org.organisation_id
  where b.user_count > 0
  order by b.time_bucket, b.user_count desc, b.tok_count desc;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_public_usage_timeseries (
  p_time_range  text    DEFAULT 'week'::text,
  p_bucket_size text    DEFAULT 'hour'::text,
  p_top_n       integer DEFAULT 10
)
  RETURNS TABLE (
    bucket   timestamp with time zone,
    model_id text,
    requests bigint,
    tokens   bigint,
    colour   text
  )
  LANGUAGE plpgsql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
#variable_conflict use_column
declare
  v_since date;
begin
  case p_time_range
    when '24h' then v_since := (now() at time zone 'utc')::date - 1;
    when 'today' then v_since := (now() at time zone 'utc')::date;
    when 'week' then v_since := (now() at time zone 'utc')::date - 7;
    when 'month' then v_since := (now() at time zone 'utc')::date - 30;
    when 'year' then v_since := (now() at time zone 'utc')::date - 365;
    else v_since := (now() at time zone 'utc')::date - 7;
  end case;
  return query
  with base as (
    select
      case
        when p_bucket_size = 'month' then date_trunc('month', d.day_bucket::timestamp)::timestamptz
        when p_bucket_size = 'week' then date_trunc('week', d.day_bucket::timestamp)::timestamptz
        else d.day_bucket::timestamptz
      end as time_bucket,
      d.model_id,
      sum(d.requests)::bigint as req_count,
      sum(d.total_tokens)::bigint as tok_count
    from public.v2_rpc_gateway_model_usage_daily d
    where d.day_bucket >= v_since
    group by 1, 2
  ),
  ranked_base as (
    select
      b.*,
      row_number() over (
        partition by b.time_bucket
        order by b.tok_count desc, b.req_count desc, b.model_id
      ) as bucket_rank
    from base b
    where lower(b.model_id) not in ('unknown', 'other')
      and b.tok_count > 0
  ),
  bucketed as (
    select
      b.time_bucket,
      case
        when rb.bucket_rank <= greatest(p_top_n, 1) then b.model_id
        else 'Other'
      end as model_group,
      sum(b.req_count)::bigint as req_count,
      sum(b.tok_count)::bigint as tok_count
    from base b
    left join ranked_base rb
      on rb.time_bucket = b.time_bucket
      and rb.model_id = b.model_id
    where lower(b.model_id) <> 'unknown'
      and b.tok_count > 0
    group by b.time_bucket, model_group
  )
  select
    b.time_bucket as bucket,
    b.model_group as model_id,
    b.req_count as requests,
    b.tok_count as tokens,
    case
      when b.model_group = 'Other' then null
      else org.colour
    end as colour
  from bucketed b
  left join private.v2_rpc_models_compat dm on dm.model_id = b.model_group
  left join private.v2_rpc_labs_compat org on dm.organisation_id = org.organisation_id
  where b.tok_count > 0
  order by b.time_bucket, b.tok_count desc;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_release_gaps_by_org (
  p_iso text DEFAULT NULL::text
)
  RETURNS TABLE (
    organisation_id   text,
    organisation_name text,
    country_code      text,
    releases          integer,
    median_gap_days   numeric,
    p90_gap_days      numeric
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
with org_models as (
    select
        m.organisation_id,
        coalesce(o.name, m.organisation_id) as organisation_name,
        coalesce(o.country_code, '') as country_code,
        coalesce(m.release_date, m.announcement_date)::date as d
    from private.v2_rpc_models_compat m
    join private.v2_rpc_labs_compat o on o.organisation_id = m.organisation_id
    where coalesce(m.release_date, m.announcement_date) is not null
      and (p_iso is null or lower(o.country_code) = lower(p_iso))
    group by m.organisation_id, organisation_name, country_code, d
),
ordered as (
    select
        organisation_id,
        organisation_name,
        country_code,
        d,
        lead(d) over(partition by organisation_id order by d) as next_d
    from org_models
),
gaps as (
    select
        organisation_id,
        organisation_name,
        country_code,
        (next_d - d)::numeric as gap_days
    from ordered
    where next_d is not null
      and next_d > d -- ignore zero/negative gaps
      and (next_d - d) >= 1 -- ignore sub-day gaps
)
select
    organisation_id,
    organisation_name,
    country_code,
    (select count(*) from org_models om where om.organisation_id = gaps.organisation_id)::int as releases,
    percentile_cont(0.5) within group (order by gap_days) as median_gap_days,
    percentile_cont(0.9) within group (order by gap_days) as p90_gap_days
from gaps
group by organisation_id, organisation_name, country_code
order by median_gap_days nulls last;
$function$;

CREATE OR REPLACE FUNCTION public.get_top_apps_stats (
  p_provider text,
  p_since    timestamp with time zone,
  p_limit    integer                  DEFAULT 20
)
  RETURNS TABLE (
    app_id       text,
    title        text,
    url          text,
    total_tokens bigint
  )
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
BEGIN
    RETURN QUERY
    SELECT
        a.id::text as app_id,
        a.title,
        a.url,
        COALESCE(SUM((gr.usage->>'total_tokens')::bigint), 0)::bigint as total_tokens
    FROM api_apps a
    LEFT JOIN gateway_requests gr ON gr.app_id = a.id
        AND gr.provider = p_provider
        AND gr.created_at >= p_since
        AND gr.success = true
    WHERE a.is_active = true
        AND a.last_seen >= p_since
        AND gr.app_id IS NOT NULL
    GROUP BY a.id, a.title, a.url
    HAVING COALESCE(SUM((gr.usage->>'total_tokens')::bigint), 0) > 0
    ORDER BY total_tokens DESC
    LIMIT p_limit;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_top_models_stats_tokens (
  p_provider text,
  p_since    timestamp with time zone,
  p_limit    integer
)
  RETURNS TABLE (
    model_id            text,
    model_name          text,
    provider_model_slug text,
    request_count       bigint,
    median_latency_ms   numeric,
    median_throughput   numeric,
    total_tokens        bigint
  )
  LANGUAGE plpgsql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
begin
  return query
  with grouped as (
    select
      r.canonical_model_id as model_id,
      sum(r.requests)::bigint as request_count,
      sum(r.total_tokens)::bigint as total_tokens,
      sum(r.latency_sum_ms) as latency_sum_ms,
      sum(r.latency_samples)::bigint as latency_samples,
      sum(r.throughput_sum) as throughput_sum,
      sum(r.throughput_samples)::bigint as throughput_samples
    from public.v2_web_public_usage_hourly r
    where r.provider = p_provider
      and r.bucket_15m >= p_since
      and r.canonical_model_id is not null
    group by r.canonical_model_id
  )
  select
    g.model_id,
    coalesce(dm.name, g.model_id) as model_name,
    max(dapm.provider_model_slug) as provider_model_slug,
    g.request_count,
    case
      when g.latency_samples > 0 then g.latency_sum_ms / g.latency_samples
      else null
    end as median_latency_ms,
    case
      when g.throughput_samples > 0 then g.throughput_sum / g.throughput_samples
      else null
    end as median_throughput,
    g.total_tokens
  from grouped g
  left join private.v2_rpc_models_compat dm on dm.model_id = g.model_id
  left join private.v2_rpc_routes_compat dapm
    on dapm.provider_id = p_provider
   and (dapm.model_id = g.model_id or dapm.api_model_id = g.model_id)
  group by
    g.model_id,
    coalesce(dm.name, g.model_id),
    g.request_count,
    g.total_tokens,
    g.latency_sum_ms,
    g.latency_samples,
    g.throughput_sum,
    g.throughput_samples
  order by g.request_count desc
  limit p_limit;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_usage_chart_rollup (
  p_team   uuid,
  p_from   timestamp with time zone,
  p_to     timestamp with time zone,
  p_bucket text,
  p_key_id uuid                     DEFAULT NULL::uuid
)
  RETURNS TABLE (
    bucket   timestamp with time zone,
    provider text,
    model_id text,
    requests bigint,
    tokens   bigint,
    cost     numeric
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
with base as (
    select
        gr.created_at,
        coalesce(nullif(gr.provider, ''), 'unknown') as provider,
        coalesce(
            nullif(gr.canonical_model_id, ''),
            public.resolve_public_model_id(gr.model_id, gr.provider),
            nullif(gr.model_id, ''),
            'unknown'
        ) as model_id,
        1::bigint as requests,
        public.gateway_usage_total_tokens(gr.usage)::bigint as total_tokens,
        coalesce(gr.cost_nanos, 0)::bigint as total_cost_nanos
    from private.v2_rpc_gateway_requests_compat gr
    where gr.workspace_id = p_team
      and gr.success is true
      and gr.created_at >= p_from
      and gr.created_at <= p_to
      and (p_key_id is null or gr.key_id = p_key_id)
),
bucketed as (
    select
        case
            when p_bucket = '5min' then
                date_trunc('minute', created_at)
                - make_interval(mins => (extract(minute from created_at)::int % 5))
            when p_bucket = 'hour' then date_trunc('hour', created_at)
            when p_bucket = 'day' then date_trunc('day', created_at)
            when p_bucket = 'month' then date_trunc('month', created_at)
            else date_trunc('day', created_at)
        end as bucket,
        provider,
        model_id,
        requests,
        total_tokens::bigint as tokens,
        total_cost_nanos::numeric / 1e9 as cost
    from base
)
select
    bucket,
    provider,
    model_id,
    sum(requests)::bigint as requests,
    sum(tokens)::bigint as tokens,
    sum(cost)::numeric as cost
from bucketed
group by bucket, provider, model_id
order by bucket asc;
$function$;

CREATE OR REPLACE FUNCTION public.get_usage_daily_app (
  p_since timestamp with time zone DEFAULT (now() - '30 days'::interval)
)
  RETURNS TABLE (
    day_bucket     timestamp with time zone,
    app_id         uuid,
    requests       bigint,
    total_tokens   bigint,
    total_cost_usd numeric,
    unique_models  integer,
    success_rate   numeric
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  select
    d.day_bucket,
    d.app_id,
    d.requests::bigint as requests,
    d.total_tokens::bigint as total_tokens,
    round(d.total_cost_nanos / 1000000000.0, 4) as total_cost_usd,
    d.unique_models::integer as unique_models,
    round(
      case when d.requests > 0
        then (d.success_requests::numeric / d.requests::numeric)
        else null
      end,
      4
    ) as success_rate
  from public.v2_rpc_gateway_usage_rollup_daily_app d
  where d.day_bucket >= (date_trunc('day', p_since at time zone 'utc') at time zone 'utc')
  order by d.day_bucket desc, d.requests desc;
$function$;

CREATE OR REPLACE FUNCTION public.get_usage_model_apps (
  p_model_ids text[],
  p_limit     integer                  DEFAULT 24,
  p_since     timestamp with time zone DEFAULT NULL::timestamp WITH time zone
)
  RETURNS TABLE (
    app_id           uuid,
    requests         bigint,
    success_requests bigint,
    total_tokens     bigint,
    title            text,
    image_url        text,
    url              text,
    last_seen        timestamp with time zone
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  with normalized_limit as (
    select greatest(1, least(coalesce(p_limit, 24), 100)) as value
  ),
  app_totals as (
    select
      d.app_id,
      sum(d.requests)::bigint as requests,
      sum(d.success_requests)::bigint as success_requests,
      sum(d.total_tokens)::bigint as total_tokens
    from public.v2_web_public_usage_daily d
    where array_length(p_model_ids, 1) is not null
      and d.canonical_model_id = any(p_model_ids)
      and (
        p_since is null
        or d.day_bucket >= (date_trunc('day', p_since at time zone 'utc') at time zone 'utc')
      )
    group by d.app_id
  )
  select
    t.app_id,
    t.requests,
    t.success_requests,
    t.total_tokens,
    coalesce(a.title, t.app_id::text) as title,
    nullif(trim(a.image_url), '') as image_url,
    nullif(trim(a.url), '') as url,
    a.last_seen
  from app_totals t
  join public.api_apps a
    on a.id = t.app_id
  where coalesce(a.is_public, false) = true
  order by t.total_tokens desc, t.requests desc, t.app_id asc
  limit (select value from normalized_limit);
$function$;

CREATE OR REPLACE FUNCTION public.get_usage_tokens_weekly_model_provider (
  p_since timestamp with time zone DEFAULT (now() - '56 days'::interval)
)
  RETURNS TABLE (
    week_bucket    timestamp with time zone,
    model_id       text,
    provider       text,
    requests       bigint,
    total_tokens   bigint,
    total_cost_usd numeric,
    success_rate   numeric
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  with normalized_requests as (
    select
      date_trunc('week', gr.created_at) as week_bucket,
      coalesce(
        nullif(gr.canonical_model_id, ''),
        public.resolve_public_model_id(gr.model_id, gr.provider),
        nullif(gr.model_id, '')
      ) as canonical_model_id,
      coalesce(nullif(gr.provider, ''), 'unknown') as provider_id,
      gr.success,
      public.gateway_usage_total_tokens(gr.usage)::bigint as total_tokens,
      coalesce(gr.cost_nanos, 0)::bigint as total_cost_nanos
    from private.v2_rpc_gateway_requests_compat gr
    where gr.created_at >= p_since
  ),
  grouped as (
    select
      nr.week_bucket,
      nr.canonical_model_id as model_id,
      nr.provider_id as provider,
      count(*)::bigint as requests,
      sum(nr.total_tokens)::bigint as total_tokens,
      sum(nr.total_cost_nanos)::bigint as total_cost_nanos,
      count(*) filter (where nr.success is true)::bigint as success_requests
    from normalized_requests nr
    where nr.canonical_model_id is not null
      and nr.provider_id <> 'unknown'
    group by nr.week_bucket, nr.canonical_model_id, nr.provider_id
  )
  select
    g.week_bucket,
    g.model_id,
    g.provider,
    g.requests,
    g.total_tokens,
    round(g.total_cost_nanos / 1000000000.0, 4) as total_cost_usd,
    round(
      case
        when g.requests > 0 then g.success_requests::numeric / g.requests::numeric
        else null
      end,
      4
    ) as success_rate
  from grouped g
  order by g.week_bucket desc, g.total_tokens desc;
$function$;

CREATE OR REPLACE FUNCTION public.get_v2_model_aliases (
  p_model_slug text
)
  RETURNS TABLE (
    alias_slug text,
    alias_type text
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public'
  AS $function$
  select alias.alias_slug, alias.alias_type
  from public.v2_model_aliases alias
  where alias.model_slug = lower(trim(p_model_slug))
    and alias.enabled = true
    and (alias.effective_from is null or alias.effective_from <= now())
    and (alias.effective_to is null or alias.effective_to > now())
  order by alias.alias_slug;
$function$;

CREATE OR REPLACE FUNCTION public.get_v2_model_apps (
  p_model_slug text,
  p_limit      integer DEFAULT 24
)
  RETURNS TABLE (
    app_id           uuid,
    title            text,
    image_url        text,
    url              text,
    last_seen        timestamp with time zone,
    requests         bigint,
    success_requests bigint,
    total_tokens     numeric
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
  with app_usage as (
    select rollup.app_id,
      sum(rollup.requests)::bigint as requests,
      sum(rollup.successful_requests)::bigint as success_requests,
      sum(coalesce(meters.total_tokens, 0))::numeric as total_tokens,
      max(rollup.usage_date)::timestamptz as last_seen
    from public.v2_public_usage_daily rollup
    left join lateral (
      select sum(quantity) as total_tokens
      from public.v2_public_usage_daily_meters meter
      where meter.rollup_id = rollup.rollup_id
        and meter.meter_key in ('input_tokens', 'output_tokens', 'reasoning_tokens')
    ) meters on true
    where rollup.model_slug = lower(trim(p_model_slug))
      and rollup.app_id is not null
    group by rollup.app_id
  )
  select usage.app_id, apps.title, apps.image_url, apps.url, usage.last_seen,
    usage.requests, usage.success_requests, usage.total_tokens
  from app_usage usage
  join public.api_apps apps on apps.id = usage.app_id
  where coalesce(apps.is_public, false)
    and usage.requests >= 10
  order by usage.total_tokens desc, usage.requests desc, usage.app_id
  limit greatest(1, least(coalesce(p_limit, 24), 100));
$function$;

REVOKE ALL ON FUNCTION "public"."get_v2_model_apps"(text, integer) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.get_v2_model_availability (
  p_model_slug   text,
  p_region       text DEFAULT NULL::text,
  p_service_tier text DEFAULT 'standard'::text
)
  RETURNS TABLE (
    is_gateway_active     boolean,
    active_provider_count integer,
    active_route_count    integer,
    regions               text[],
    service_tiers         text[]
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public'
  AS $function$
  with candidates as (
    select *
    from public.get_v2_routing_candidates(
      lower(trim(p_model_slug)), null, p_region, p_service_tier
    )
  )
  select
    count(*) filter (where candidate.routing_enabled) > 0,
    (count(distinct candidate.provider_slug) filter (where candidate.routing_enabled))::integer,
    (count(distinct candidate.provider_model_id) filter (where candidate.routing_enabled))::integer,
    coalesce(array_agg(distinct region order by region) filter (where region is not null), '{}'::text[]),
    coalesce(array_agg(distinct candidate.service_tier_slug order by candidate.service_tier_slug), '{}'::text[])
  from candidates candidate
  cross join lateral (values (candidate.execution_region), (candidate.data_region)) regions(region);
$function$;

CREATE OR REPLACE FUNCTION public.get_v2_model_benchmarks (
  p_model_slug text
)
  RETURNS TABLE (
    result_id        uuid,
    benchmark_id     text,
    score            text,
    score_numeric    numeric,
    is_self_reported boolean,
    other_info       text,
    source_link      text,
    result_rank      integer,
    occur_idx        integer,
    variant          text,
    result_key       text,
    benchmark_name   text,
    category         text,
    link             text,
    total_models     integer,
    ascending_order  boolean,
    benchmark_type   text,
    created_at       timestamp with time zone,
    updated_at       timestamp with time zone
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public'
  AS $function$
  select result.result_id, result.benchmark_id, result.score, result.score_numeric, result.is_self_reported,
    result.other_info, result.source_link, result.rank, result.occur_idx, result.variant, result.result_key,
    benchmark.name, benchmark.category, benchmark.link, benchmark.total_models, benchmark.ascending_order,
    benchmark.benchmark_type, result.created_at, result.updated_at
  from public.v2_benchmark_results result
  join public.v2_benchmarks benchmark on benchmark.benchmark_id = result.benchmark_id
  where result.model_slug = lower(trim(p_model_slug)) and (result.effective_to is null or result.effective_to>now())
  order by benchmark.name, result.rank nulls last, result.created_at desc;
$function$;

CREATE OR REPLACE FUNCTION public.get_v2_model_cached_input_metrics (
  p_model_slug      text,
  p_cloudflare_colo text DEFAULT NULL::text,
  p_stream_mode     text DEFAULT 'all'::text,
  p_context_bucket  text DEFAULT 'all'::text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
with params as (
  select
    lower(trim(p_model_slug)) model_slug,
    nullif(upper(trim(p_cloudflare_colo)), '') cloudflare_colo,
    case when lower(p_stream_mode) in ('stream', 'non_stream') then lower(p_stream_mode) else 'all' end stream_mode,
    case when lower(p_context_bucket) in ('lte_4k', '4k_16k', '16k_64k', 'gt_64k') then lower(p_context_bucket) else 'all' end context_bucket,
    now() now_ts
),
visible_model as (
  select model.model_slug
  from public.v2_models model
  cross join params
  where model.model_slug = params.model_slug
    and model.hidden = false
    and model.status <> 'disabled'
),
scoped_facts as (
  select
    fact.request_event_id,
    fact.occurred_at,
    fact.stream,
    fact.cloudflare_colo,
    fact.safe_metadata,
    route.provider_slug provider_id
  from public.v2_request_facts fact
  join visible_model on visible_model.model_slug = coalesce(fact.routed_model_slug, fact.requested_model_slug)
  left join public.v2_model_provider_routes route on route.provider_model_id = fact.provider_model_id
  cross join params
  where fact.occurred_at >= params.now_ts - interval '7 days'
    and (params.cloudflare_colo is null or upper(trim(fact.cloudflare_colo)) = params.cloudflare_colo)
    and (params.stream_mode = 'all' or fact.stream = (params.stream_mode = 'stream'))
),
usage_by_request as (
  select
    usage.request_event_id,
    sum(usage.quantity) filter (where usage.meter_key = 'input_tokens')::numeric input_tokens,
    sum(usage.quantity) filter (where usage.meter_key = 'cached_input_tokens')::numeric cached_input_tokens,
    bool_or(usage.meter_key = 'cached_input_tokens') cache_telemetry_observed
  from scoped_facts fact
  join public.v2_request_usage usage on usage.request_event_id = fact.request_event_id
  where usage.meter_key in ('input_tokens', 'cached_input_tokens')
  group by usage.request_event_id
),
classified as (
  select
    date_trunc('hour', fact.occurred_at) bucket_start,
    fact.occurred_at::date usage_day,
    fact.provider_id,
    usage.input_tokens,
    usage.cached_input_tokens,
    usage.cache_telemetry_observed,
    -- Existing observations predate this metadata bit and came from
    -- OpenAI-compatible responses, where cached tokens are a subset of input.
    coalesce((fact.safe_metadata ->> 'cached_input_tokens_are_subset_of_input')::boolean, true) cached_input_is_subset,
    case
      when usage.input_tokens is null then null
      when coalesce((fact.safe_metadata ->> 'cached_input_tokens_are_subset_of_input')::boolean, true)
        then usage.input_tokens
      else usage.input_tokens + coalesce(usage.cached_input_tokens, 0)
    end context_input_tokens
  from scoped_facts fact
  left join usage_by_request usage on usage.request_event_id = fact.request_event_id
  cross join params
),
base as (
  select classified.*
  from classified
  cross join params
  where (
      params.context_bucket = 'all'
      or (params.context_bucket = 'lte_4k' and context_input_tokens <= 4096)
      or (params.context_bucket = '4k_16k' and context_input_tokens > 4096 and context_input_tokens <= 16384)
      or (params.context_bucket = '16k_64k' and context_input_tokens > 16384 and context_input_tokens <= 65536)
      or (params.context_bucket = 'gt_64k' and context_input_tokens > 65536)
    )
),
hourly as (
  select
    bucket_start,
    count(*)::bigint requests,
    count(*) filter (where cache_telemetry_observed)::bigint telemetry_requests,
    sum(input_tokens + case when cached_input_is_subset then 0 else coalesce(cached_input_tokens, 0) end)
      filter (where cache_telemetry_observed and input_tokens > 0)::numeric input_tokens,
    sum(cached_input_tokens) filter (where cache_telemetry_observed and input_tokens > 0)::numeric cached_input_tokens
  from base
  where bucket_start >= (select now_ts from params) - interval '24 hours'
  group by bucket_start
),
provider_daily as (
  select
    usage_day,
    provider_id,
    count(*)::bigint requests,
    count(*) filter (where cache_telemetry_observed)::bigint telemetry_requests,
    sum(input_tokens + case when cached_input_is_subset then 0 else coalesce(cached_input_tokens, 0) end)
      filter (where cache_telemetry_observed and input_tokens > 0)::numeric input_tokens,
    sum(cached_input_tokens) filter (where cache_telemetry_observed and input_tokens > 0)::numeric cached_input_tokens
  from base
  where provider_id is not null
  group by usage_day, provider_id
)
select jsonb_build_object(
  'hourly_24h', coalesce((
    select jsonb_agg(jsonb_build_object(
      'bucket', bucket_start,
      'requests', requests,
      'telemetry_requests', telemetry_requests,
      'effective_input_tokens', input_tokens,
      'cached_input_tokens', cached_input_tokens,
      'cached_input_pct', case when input_tokens > 0 then least(100, cached_input_tokens * 100.0 / input_tokens) else null end
    ) order by bucket_start)
    from hourly
    where requests >= 1 and telemetry_requests > 0
  ), '[]'::jsonb),
  'provider_daily_7d', coalesce((
    select jsonb_agg(jsonb_build_object(
      'day', daily.usage_day,
      'provider', daily.provider_id,
      'provider_name', provider.name,
      'requests', daily.requests,
      'telemetry_requests', daily.telemetry_requests,
      'effective_input_tokens', daily.input_tokens,
      'cached_input_tokens', daily.cached_input_tokens,
      'cached_input_pct', case when daily.input_tokens > 0 then least(100, daily.cached_input_tokens * 100.0 / daily.input_tokens) else null end
    ) order by daily.usage_day, daily.provider_id)
    from provider_daily daily
    join public.v2_providers provider on provider.provider_slug = daily.provider_id
    where daily.requests >= 1 and daily.telemetry_requests > 0
  ), '[]'::jsonb)
);
$function$;

REVOKE ALL ON FUNCTION "public"."get_v2_model_cached_input_metrics"(text, text, text, text) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.get_v2_model_effective_pricing_daily (
  p_model_slug   text,
  p_provider_ids text[] DEFAULT NULL::text[],
  p_since        date   DEFAULT NULL::date,
  p_until        date   DEFAULT NULL::date
)
  RETURNS TABLE (
    day_bucket          date,
    provider_id         text,
    pricing_plan        text,
    input_tokens        numeric,
    output_tokens       numeric,
    cached_read_tokens  numeric,
    cached_write_tokens numeric,
    input_cost_nanos    numeric,
    output_cost_nanos   numeric,
    total_cost_nanos    numeric
  )
  LANGUAGE sql
  STABLE
  SET search_path TO 'public'
  AS $function$
  select
    usage.usage_date,
    usage.provider_id,
    usage.pricing_plan,
    usage.input_tokens,
    usage.output_tokens,
    usage.cached_read_tokens,
    usage.cached_write_tokens,
    usage.input_cost_nanos,
    usage.output_cost_nanos,
    usage.total_cost_nanos
  from public.v2_public_effective_pricing_daily usage
  where usage.model_slug = lower(trim(p_model_slug))
    and (p_provider_ids is null or usage.provider_id = any(p_provider_ids))
    and (p_since is null or usage.usage_date >= p_since)
    and (p_until is null or usage.usage_date <= p_until)
  order by usage.usage_date, usage.provider_id, usage.pricing_plan;
$function$;

