  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
select health.*
from public.v2_models model
cross join lateral public.get_v2_model_provider_health_metrics_unfiltered(
  model.model_slug,
  p_window_days,
