CREATE OR REPLACE FUNCTION public.link_provider_personal_account (
  p_user_id       uuid,
  p_provider_slug text,
  p_proof_subject text,
  p_proof_method  text DEFAULT 'catalog_domain_match'::text
)
  RETURNS uuid
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  v_workspace_id uuid;
begin
  if p_proof_method not in ('catalog_domain_match', 'domain_file', 'self_declared') then
    raise exception 'invalid_provider_proof_method';
  end if;
  -- Serialize submissions from one account, including different provider slugs.
  perform 1 from public.users where user_id = p_user_id for update;
  if not found then
    raise exception 'provider_account_user_missing';
  end if;

  select l.workspace_id into v_workspace_id from public.provider_account_links l
  join public.workspaces w on w.id = l.workspace_id
  where l.provider_slug = p_provider_slug and l.linked_by = p_user_id
    and l.status = 'active' and w.owner_user_id = p_user_id;
  if found then return v_workspace_id; end if;

  select id into v_workspace_id from public.workspaces
  where owner_user_id = p_user_id and workspace_kind = 'personal'
  order by created_at, id limit 1;

  if v_workspace_id is null then
    insert into public.workspaces (name, slug, owner_user_id, workspace_kind)
    values ('Personal', replace(p_user_id::text, '-', '')::text || '-p', p_user_id, 'personal')
    returning id into v_workspace_id;
  end if;

  insert into public.workspace_members (workspace_id, user_id, role)
  values (v_workspace_id, p_user_id, 'owner')
  on conflict on constraint workspace_members_pkey do nothing;
  insert into public.workspace_settings (workspace_id) values (v_workspace_id)
  on conflict on constraint workspace_settings_pkey do nothing;

  insert into public.provider_account_links
    (provider_slug, workspace_id, linked_by, role, status, proof_method, proof_subject, verified_at)
  values (p_provider_slug, v_workspace_id, p_user_id, 'owner', 'active',
    p_proof_method, p_proof_subject, case when p_proof_method = 'self_declared' then null else now() end);

  update public.users set default_workspace_id = v_workspace_id
  where user_id = p_user_id and lower(coalesce(role::text, 'user')) <> 'admin';
  return v_workspace_id;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."link_provider_personal_account"(uuid, text, text, text) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.lock_workspace_budget_change()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_workspace_id uuid;
begin
  v_workspace_id := case when tg_op = 'DELETE' then old.workspace_id else new.workspace_id end;
  perform pg_advisory_xact_lock(hashtextextended(v_workspace_id::text, 0));
  if tg_op = 'UPDATE' then
    new.updated_at := now();
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."lock_workspace_budget_change"() FROM PUBLIC, "anon", "authenticated", "service_role";

CREATE OR REPLACE FUNCTION public.machine_payment_attach_job (
  p_authorization_id uuid,
  p_job_kind         text,
  p_job_id           text
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
begin
  if p_job_kind not in ('video','batch') or nullif(trim(p_job_id),'') is null then raise exception 'invalid_job'; end if;
  update public.machine_payment_authorizations set job_kind=p_job_kind, job_id=p_job_id, status='executing'
  where id=p_authorization_id and status in ('claimed','executing') and (job_id is null or (job_kind=p_job_kind and job_id=p_job_id));
  if not found then raise exception 'authorization_job_conflict'; end if;
end $function$;

REVOKE ALL ON FUNCTION "public"."machine_payment_attach_job"(uuid, text, text) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.machine_payment_claim_authorization (
  p_challenge_id              uuid,
  p_protocol                  public.machine_payment_protocol,
  p_mode                      public.machine_payment_mode,
  p_payer_id                  text,
  p_external_authorization_id text,
  p_credential_fingerprint    text,
  p_request_hash              text,
  p_pricing_snapshot_hash     text,
  p_max_amount_nanos          bigint,
  p_expires_at                timestamp with time zone,
  p_request_id                text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare v_challenge public.machine_payment_challenges; v_auth public.machine_payment_authorizations;
begin
  select * into v_challenge from public.machine_payment_challenges where id = p_challenge_id for update;
  if not found or v_challenge.status <> 'open' or v_challenge.expires_at <= now() then raise exception 'challenge_unavailable'; end if;
  if not (p_protocol = any(v_challenge.allowed_protocols)) then raise exception 'protocol_not_allowed'; end if;
  if v_challenge.request_hash <> p_request_hash or v_challenge.pricing_snapshot_hash <> p_pricing_snapshot_hash then raise exception 'payment_binding_mismatch'; end if;
  if p_max_amount_nanos < v_challenge.amount_nanos or p_expires_at <= now() then raise exception 'authorization_insufficient_or_expired'; end if;
  insert into public.machine_payment_authorizations(challenge_id, protocol, mode, payer_id, external_authorization_id, request_hash, pricing_snapshot_hash, max_amount_nanos, credential_fingerprint, expires_at, claimed_request_id, status, claimed_at)
  values (p_challenge_id, p_protocol, p_mode, p_payer_id, p_external_authorization_id, p_request_hash, p_pricing_snapshot_hash, p_max_amount_nanos, p_credential_fingerprint, least(p_expires_at, v_challenge.expires_at), p_request_id, 'claimed', now()) returning * into v_auth;
  update public.machine_payment_challenges set status = 'authorized', updated_at = now() where id = p_challenge_id;
  insert into public.machine_payment_events(authorization_id, challenge_id, event_type, idempotency_key)
  values (v_auth.id, p_challenge_id, 'authorization.claimed', 'authorization.claimed:' || v_auth.id);
  return jsonb_build_object('kind','machine_payment','protocol',v_auth.protocol,'payerId',v_auth.payer_id,'authorizationId',v_auth.id,'challengeId',v_auth.challenge_id,'requestHash',v_auth.request_hash,'pricingSnapshotHash',v_auth.pricing_snapshot_hash,'maxAmountNanos',v_auth.max_amount_nanos,'currency',v_auth.currency,'mode',v_auth.mode);
exception when unique_violation then raise exception 'payment_replay_detected';
end $function$;

REVOKE ALL
  ON FUNCTION "public"."machine_payment_claim_authorization"(uuid, public.machine_payment_protocol, public.machine_payment_mode, text, text, text, text, text, bigint, timestamp
    WITH time zone, text)
  FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.machine_payment_create_challenge (
  p_request_hash          text,
  p_pricing_snapshot_hash text,
  p_endpoint              text,
  p_model                 text,
  p_amount_nanos          bigint,
  p_allowed_protocols     public.machine_payment_protocol[],
  p_expires_at            timestamp with time zone,
  p_metadata              jsonb                             DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare v_row public.machine_payment_challenges;
begin
  if p_expires_at <= now() or p_expires_at > now() + interval '15 minutes' then raise exception 'invalid_challenge_expiry'; end if;
  if p_amount_nanos <= 0 or coalesce(array_length(p_allowed_protocols, 1), 0) = 0 then raise exception 'invalid_challenge'; end if;
  insert into public.machine_payment_challenges(request_hash, pricing_snapshot_hash, endpoint, model, amount_nanos, allowed_protocols, expires_at, metadata)
  values (p_request_hash, p_pricing_snapshot_hash, p_endpoint, p_model, p_amount_nanos, p_allowed_protocols, p_expires_at, coalesce(p_metadata, '{}'::jsonb)) returning * into v_row;
  insert into public.machine_payment_events(challenge_id, event_type, idempotency_key, payload)
  values (v_row.id, 'challenge.created', 'challenge.created:' || v_row.id, jsonb_build_object('amount_nanos', v_row.amount_nanos));
  return to_jsonb(v_row);
end $function$;

REVOKE ALL
  ON FUNCTION "public"."machine_payment_create_challenge"(text, text, text, text, bigint, public.machine_payment_protocol[], timestamp WITH time zone, jsonb)
  FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.machine_payment_protocol_store_cas (
  p_key              text,
  p_expected_version bigint,
  p_delete           boolean,
  p_value            jsonb,
  p_expires_at       timestamp with time zone DEFAULT NULL::timestamp WITH time zone
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
begin
  if p_expected_version = 0 then
    insert into public.machine_payment_protocol_store(key,value,expires_at) values(p_key,p_value,p_expires_at) on conflict do nothing;
  elsif p_delete then
    delete from public.machine_payment_protocol_store where key=p_key and version=p_expected_version;
  else
    update public.machine_payment_protocol_store set value=p_value,version=version+1,expires_at=p_expires_at,updated_at=now() where key=p_key and version=p_expected_version;
  end if;
  if not found then raise exception 'store_version_conflict'; end if;
end $function$;

REVOKE ALL ON FUNCTION "public"."machine_payment_protocol_store_cas"(text, bigint, boolean, jsonb, timestamp WITH time zone) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.machine_payment_protocol_store_put (
  p_key        text,
  p_value      jsonb,
  p_expires_at timestamp with time zone DEFAULT NULL::timestamp WITH time zone
)
  RETURNS void
  LANGUAGE sql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
  insert into public.machine_payment_protocol_store(key,value,expires_at) values(p_key,p_value,p_expires_at)
  on conflict(key) do update set value=excluded.value,version=machine_payment_protocol_store.version+1,expires_at=excluded.expires_at,updated_at=now();
$function$;

REVOKE ALL ON FUNCTION "public"."machine_payment_protocol_store_put"(text, jsonb, timestamp WITH time zone) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.machine_payment_protocol_store_try_claim (
  p_key        text,
  p_expires_at timestamp with time zone
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
begin
  insert into public.machine_payment_protocol_store(key,value,expires_at)
  values(p_key,jsonb_build_object('type','mppx:replay','expires',extract(epoch from p_expires_at)*1000),p_expires_at)
  on conflict(key) do update set value=excluded.value,version=machine_payment_protocol_store.version+1,expires_at=excluded.expires_at,updated_at=now()
  where machine_payment_protocol_store.expires_at is not null and machine_payment_protocol_store.expires_at <= now();
  return found;
end $function$;

REVOKE ALL ON FUNCTION "public"."machine_payment_protocol_store_try_claim"(text, timestamp WITH time zone) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.machine_payment_settle_once (
  p_authorization_id    uuid,
  p_request_id          text,
  p_actual_amount_nanos bigint,
  p_usage               jsonb   DEFAULT NULL::jsonb,
  p_provider            text    DEFAULT NULL::text,
  p_receipt             jsonb   DEFAULT NULL::jsonb,
  p_release             boolean DEFAULT false
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare v_auth public.machine_payment_authorizations; v_settlement public.machine_payment_settlements;
begin
  select * into v_auth from public.machine_payment_authorizations where id = p_authorization_id for update;
  if not found or v_auth.claimed_request_id <> p_request_id then raise exception 'authorization_not_claimed_for_request'; end if;
  if v_auth.status in ('settled','released') then
    select * into v_settlement from public.machine_payment_settlements where authorization_id = v_auth.id;
    return jsonb_build_object('idempotent',true,'authorization_id',v_auth.id,'status',v_auth.status,'actual_amount_nanos',coalesce(v_settlement.actual_amount_nanos,0),'receipt',v_settlement.receipt);
  end if;
  if p_actual_amount_nanos < 0 or p_actual_amount_nanos > v_auth.max_amount_nanos then raise exception 'settlement_exceeds_authorization'; end if;
  insert into public.machine_payment_settlements(authorization_id, request_id, actual_amount_nanos, provider, usage, receipt)
  values (v_auth.id, p_request_id, case when p_release then 0 else p_actual_amount_nanos end, p_provider, p_usage, p_receipt) returning * into v_settlement;
  update public.machine_payment_authorizations
  set status = (case when p_release then 'released' else 'settled' end)::public.machine_payment_authorization_status,
      settled_at = now()
  where id = v_auth.id;
  insert into public.machine_payment_events(authorization_id, challenge_id, event_type, idempotency_key, payload)
  values (v_auth.id, v_auth.challenge_id, case when p_release then 'authorization.released' else 'authorization.settled' end, 'authorization.finalized:' || v_auth.id, jsonb_build_object('actual_amount_nanos',v_settlement.actual_amount_nanos));
  return jsonb_build_object('idempotent',false,'authorization_id',v_auth.id,'status',case when p_release then 'released' else 'settled' end,'actual_amount_nanos',v_settlement.actual_amount_nanos);
end $function$;

REVOKE ALL ON FUNCTION "public"."machine_payment_settle_once"(uuid, text, bigint, jsonb, text, jsonb, boolean) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.management_create_workspace_department (
  p_workspace_id  uuid,
