REVOKE ALL ON FUNCTION "public"."management_create_workspace_department"(uuid, text, text, text, text, uuid, text) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.management_decide_workspace_join_request (
  p_workspace_id  uuid,
  p_request_id    uuid,
  p_decision      text,
  p_actor_user_id uuid
)
  RETURNS TABLE (
    id                uuid,
    workspace_id      uuid,
    requester_user_id uuid,
    invite_id         uuid,
    status            public.join_request_status,
    decided_at        timestamp with time zone,
    decided_by        uuid
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_request public.workspace_join_requests%rowtype;
  v_role public.workspace_role := 'member'::public.workspace_role;
  v_status public.join_request_status;
begin
  if p_actor_user_id is null then
    raise exception using errcode = '23514', message = 'Decision actor is required';
  end if;
  if p_decision not in ('approve', 'reject') then
    raise exception using errcode = '23514', message = 'Decision must be approve or reject';
  end if;

  select * into v_request
  from public.workspace_join_requests request
  where request.id = p_request_id
    and request.workspace_id = p_workspace_id
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'Join request not found';
  end if;
  if v_request.status <> 'pending'::public.join_request_status then
    raise exception using errcode = '23514', message = 'Join request already decided';
  end if;

  if p_decision = 'approve' then
    if v_request.invite_id is not null then
      update public.workspace_invites invite
      set uses_count = coalesce(invite.uses_count, 0) + 1
      where invite.id = v_request.invite_id
        and invite.workspace_id = p_workspace_id
        and (invite.expires_at is null or invite.expires_at > now())
        and (invite.max_uses is null or coalesce(invite.uses_count, 0) < invite.max_uses)
      returning invite.role into v_role;
      if not found then
        raise exception using errcode = '23514', message = 'Invite is no longer valid';
      end if;
    end if;

    insert into public.workspace_members (workspace_id, user_id, role)
    values (p_workspace_id, v_request.requester_user_id, v_role)
    on conflict (workspace_id, user_id) do nothing;
    v_status := 'approved'::public.join_request_status;
  else
    v_status := 'denied'::public.join_request_status;
  end if;

  return query
  update public.workspace_join_requests request
  set status = v_status,
      decided_by = p_actor_user_id,
      decided_at = now()
  where request.id = v_request.id
    and request.status = 'pending'::public.join_request_status
  returning request.id, request.workspace_id, request.requester_user_id,
    request.invite_id, request.status, request.decided_at, request.decided_by;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."management_decide_workspace_join_request"(uuid, uuid, text, uuid) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.management_delete_workspace_department (
  p_workspace_id  uuid,
  p_department_id uuid,
  p_actor_user_id uuid,
  p_request_id    text DEFAULT NULL::text
)
  RETURNS public.workspace_departments
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare deleted public.workspace_departments;
begin
  select * into deleted from public.workspace_departments
  where id=p_department_id and workspace_id=p_workspace_id and source_type='manual' for update;
  if deleted is null then raise exception 'Department not found'; end if;
  delete from public.workspace_department_grants where workspace_id=p_workspace_id and department_id=p_department_id;
  update public.workspace_member_overrides set
    department_override_enabled=false, department_id=null, department_position=null, updated_at=now()
  where workspace_id=p_workspace_id and department_id=p_department_id;
  perform public.refresh_workspace_effective_entitlements(p_workspace_id,p_actor_user_id,'department_deleted');
  delete from public.workspace_departments where id=p_department_id and workspace_id=p_workspace_id returning * into deleted;
  insert into public.workspace_directory_audit_events(workspace_id,actor_user_id,action,target_type,target_id,before_state,request_id)
  values(p_workspace_id,p_actor_user_id,'workspace.department.delete','workspace_department',p_department_id::text,to_jsonb(deleted),p_request_id);
  return deleted;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."management_delete_workspace_department"(uuid, uuid, uuid, text) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.management_delete_workspace_department_member (
  p_workspace_id  uuid,
  p_department_id uuid,
  p_user_id       uuid,
  p_actor_user_id uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  delete from public.workspace_department_grants
  where workspace_id=p_workspace_id and department_id=p_department_id and user_id=p_user_id and source_type='manual';
  if not found then return false; end if;
  perform public.refresh_workspace_effective_entitlements(p_workspace_id,p_actor_user_id,'department_membership_deleted');
  return true;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."management_delete_workspace_department_member"(uuid, uuid, uuid, uuid) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.management_set_workspace_department_member (
  p_workspace_id  uuid,
  p_department_id uuid,
  p_user_id       uuid,
  p_position      text,
  p_primary       boolean,
  p_actor_user_id uuid,
  p_request_id    text    DEFAULT NULL::text
)
  RETURNS public.workspace_department_grants
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare saved public.workspace_department_grants;
begin
  if not exists(select 1 from public.workspace_members where workspace_id=p_workspace_id and user_id=p_user_id) then
    raise exception 'Workspace member not found';
  end if;
  if not exists(select 1 from public.workspace_departments where workspace_id=p_workspace_id and id=p_department_id) then
    raise exception 'Department not found';
  end if;
  if p_position not in ('member','lead') then raise exception 'Invalid department position'; end if;
  if p_primary then
    update public.workspace_department_grants set is_primary=false,updated_at=now()
    where workspace_id=p_workspace_id and user_id=p_user_id and source_type='manual';
  end if;
  insert into public.workspace_department_grants(
    workspace_id,user_id,department_id,source_type,source_id,position,is_primary,updated_at
  ) values (
    p_workspace_id,p_user_id,p_department_id,'manual',p_user_id,p_position,coalesce(p_primary,false),now()
  ) on conflict(workspace_id,user_id,department_id,source_type,source_id) do update set
    position=excluded.position,is_primary=excluded.is_primary,updated_at=excluded.updated_at
  returning * into saved;
  perform public.refresh_workspace_effective_entitlements(p_workspace_id,p_actor_user_id,'department_membership_updated');
  return saved;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."management_set_workspace_department_member"(uuid, uuid, uuid, text, boolean, uuid, text) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.management_update_workspace_department (
  p_workspace_id  uuid,
  p_department_id uuid,
  p_name          text,
  p_description   text,
  p_icon          text,
  p_color         text,
  p_actor_user_id uuid,
  p_request_id    text DEFAULT NULL::text
)
  RETURNS public.workspace_departments
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare before_row public.workspace_departments; updated public.workspace_departments;
begin
  select * into before_row from public.workspace_departments
  where id=p_department_id and workspace_id=p_workspace_id for update;
  if before_row is null then raise exception 'Department not found'; end if;
  update public.workspace_departments set
    name=btrim(p_name), description=p_description, icon=p_icon, color=p_color,
    name_overridden=case when source_type='scim_group' and btrim(p_name) is distinct from directory_name then true else name_overridden end,
    updated_at=now()
  where id=p_department_id and workspace_id=p_workspace_id returning * into updated;
  perform public.refresh_workspace_effective_entitlements(p_workspace_id,p_actor_user_id,'department_updated');
  insert into public.workspace_directory_audit_events(workspace_id,actor_user_id,action,target_type,target_id,before_state,after_state,request_id)
  values(p_workspace_id,p_actor_user_id,'workspace.department.update','workspace_department',p_department_id::text,to_jsonb(before_row),to_jsonb(updated),p_request_id);
  return updated;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."management_update_workspace_department"(uuid, uuid, text, text, text, text, uuid, text) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.marketplace_preset_fork_counts (
  preset_ids uuid[]
)
  RETURNS TABLE (
    preset_id         uuid,
    fork_count        bigint,
    direct_fork_count bigint,
    descendant_count  bigint
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
  select requested.id,
    (select count(*) from public.presets direct where direct.source_preset_id = requested.id and direct.archived_at is null),
    (select count(*) from public.presets direct where direct.source_preset_id = requested.id and direct.archived_at is null),
    (select count(*) from public.preset_lineage lineage join public.presets child on child.id = lineage.descendant_preset_id
      where lineage.ancestor_preset_id = requested.id and lineage.depth > 0 and child.archived_at is null)
  from unnest(preset_ids) requested(id);
$function$;

REVOKE ALL ON FUNCTION "public"."marketplace_preset_fork_counts"(uuid[]) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.merge_v2_gateway_app_history (
  p_workspace_id  uuid,
  p_source_app_id uuid,
  p_target_app_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_app_count integer;
  v_gateway_requests integer := 0;
  v_request_facts integer := 0;
  v_since timestamptz;
  v_until timestamptz;
begin
  if p_workspace_id is null or p_source_app_id is null or p_target_app_id is null
     or p_source_app_id = p_target_app_id then
    raise exception using errcode = '22023', message = 'invalid_app_merge';
  end if;

  select count(*)::integer into v_app_count
  from public.api_apps app
  where app.workspace_id = p_workspace_id
    and app.id in (p_source_app_id, p_target_app_id);
  if v_app_count <> 2 then
    raise exception using errcode = '23503', message = 'app_merge_target_not_found';
  end if;

  select min(fact.occurred_at), max(fact.occurred_at)
  into v_since, v_until
  from public.v2_request_facts fact
  where fact.workspace_id = p_workspace_id
    and fact.app_id = p_source_app_id;

  update public.gateway_requests request
  set app_id = p_target_app_id
  where request.workspace_id = p_workspace_id
    and request.app_id = p_source_app_id;
  get diagnostics v_gateway_requests = row_count;

  update public.v2_request_facts fact
  set app_id = p_target_app_id
  where fact.workspace_id = p_workspace_id
    and fact.app_id = p_source_app_id;
  get diagnostics v_request_facts = row_count;

  -- Remove the source grains before deleting the app. Otherwise their foreign
  -- keys become null and retain stale traffic under an unattributed bucket.
  delete from public.v2_private_usage_daily rollup
  where rollup.workspace_id = p_workspace_id
    and rollup.app_id = p_source_app_id;
  delete from public.v2_public_usage_daily rollup
  where rollup.app_id = p_source_app_id;
  delete from public.v2_public_usage_hourly rollup
  where rollup.app_id = p_source_app_id;

  if v_since is not null then
    perform public.refresh_v2_analytics_range(
      v_since,
      v_until + interval '1 microsecond',
      p_workspace_id
    );
  end if;

  delete from public.api_apps app
  where app.workspace_id = p_workspace_id
    and app.id = p_source_app_id;

  return jsonb_build_object(
    'gateway_requests', v_gateway_requests,
    'request_facts', v_request_facts
  );
end;
$function$;

REVOKE ALL ON FUNCTION "public"."merge_v2_gateway_app_history"(uuid, uuid, uuid) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.monthly_spend_prev_cents (
  p_workspace_id uuid
)
  RETURNS bigint
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  v_user_id uuid := auth.uid();
  v_current_month_start_ts timestamptz := (date_trunc('month', now() at time zone 'UTC') at time zone 'UTC');
  v_prev_month_start_ts timestamptz := ((date_trunc('month', now() at time zone 'UTC') - interval '1 month') at time zone 'UTC');
  v_prev_month_nanos bigint := 0;
  v_prev_month_cents bigint := 0;
begin
  if p_workspace_id is null then
    raise exception 'workspace_id_required';
  end if;

  if v_user_id is null then
    raise exception 'unauthorized';
  end if;

  if not exists (
    select 1
    from public.workspace_members wm
    where wm.workspace_id = p_workspace_id
      and wm.user_id = v_user_id
  ) and not exists (
    select 1
    from public.workspaces w
    where w.id = p_workspace_id
      and w.owner_user_id = v_user_id
  ) then
    raise exception 'workspace_forbidden';
  end if;

  select coalesce(sum(gr.cost_nanos), 0)::bigint
  into v_prev_month_nanos
  from private.v2_rpc_gateway_requests_compat gr
  where gr.workspace_id = p_workspace_id
    and gr.success is true
    and gr.created_at >= v_prev_month_start_ts
    and gr.created_at < v_current_month_start_ts;

  v_prev_month_cents := floor(v_prev_month_nanos::numeric / 10000000.0)::bigint;
  return v_prev_month_cents;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."monthly_spend_prev_cents"(uuid) FROM PUBLIC, "anon";

CREATE OR REPLACE FUNCTION public.mtd_spend_cents (
  p_workspace_id uuid
)
  RETURNS bigint
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  v_user_id uuid := auth.uid();
  v_now_utc timestamptz := now();
  v_current_month_start_ts timestamptz := (date_trunc('month', now() at time zone 'UTC') at time zone 'UTC');
  v_mtd_nanos bigint := 0;
  v_mtd_cents bigint := 0;
begin
  if p_workspace_id is null then
    raise exception 'workspace_id_required';
  end if;

  if v_user_id is null then
    raise exception 'unauthorized';
  end if;

  if not exists (
    select 1
    from public.workspace_members wm
    where wm.workspace_id = p_workspace_id
      and wm.user_id = v_user_id
  ) and not exists (
    select 1
    from public.workspaces w
    where w.id = p_workspace_id
      and w.owner_user_id = v_user_id
  ) then
    raise exception 'workspace_forbidden';
  end if;

  select coalesce(sum(gr.cost_nanos), 0)::bigint
  into v_mtd_nanos
  from private.v2_rpc_gateway_requests_compat gr
  where gr.workspace_id = p_workspace_id
    and gr.success is true
    and gr.created_at >= v_current_month_start_ts
    and gr.created_at <= v_now_utc;

  v_mtd_cents := floor(v_mtd_nanos::numeric / 10000000.0)::bigint;
  return v_mtd_cents;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."mtd_spend_cents"(uuid) FROM PUBLIC, "anon";

CREATE OR REPLACE FUNCTION public.mtd_spend_cents (
  p_team  uuid,
  p_basis text DEFAULT 'top_up'::text
)
  RETURNS bigint
  LANGUAGE plpgsql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$declare
  month_start_utc timestamptz :=
    (date_trunc('month', (now() at time zone 'Europe/London'))
     at time zone 'Europe/London');
  total bigint;
begin
  select coalesce(sum(amount_nanos),0)::bigint into total
  from credit_ledger
  where team_id = p_team
    and created_at >= month_start_utc
    and created_at <  now()
    and kind in ('top_up','auto_top_up');
  return total;
end;$function$;

CREATE OR REPLACE FUNCTION public.mutate_v2_admin_catalogue (
  p_actor_user_id uuid,
  p_resource_type text,
  p_action        text,
  p_resource_id   text,
  p_payload       jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare v_before jsonb; v_after jsonb; v_uuid uuid;
begin
  if not exists (select 1 from public.users where user_id = p_actor_user_id and lower(coalesce(role::text, '')) = 'admin') then raise exception 'actor must have the admin role'; end if;
  if p_action not in ('create','update','delete') then raise exception 'unsupported catalogue action'; end if;

  if p_resource_type = 'organisations' then
    select to_jsonb(t) into v_before from public.v2_labs t where lab_slug = p_resource_id;
    if p_action = 'delete' then delete from public.v2_labs where lab_slug = p_resource_id;
    else
      insert into public.v2_labs (lab_slug,name,country_code,subdivision_code,description,status,metadata,updated_at)
      values (p_resource_id,p_payload->>'name',coalesce(nullif(p_payload->>'country_code',''),'xx'),nullif(p_payload->>'subdivision_code',''),nullif(p_payload->>'description',''),'active',jsonb_strip_nulls(jsonb_build_object('colour',p_payload->>'colour','source','admin')),now())
      on conflict (lab_slug) do update set name=excluded.name,country_code=excluded.country_code,subdivision_code=excluded.subdivision_code,description=excluded.description,metadata=public.v2_labs.metadata||excluded.metadata,updated_at=now();
      delete from public.v2_lab_links where lab_slug=p_resource_id;
      insert into public.v2_lab_links(lab_slug,platform,url) select p_resource_id,x->>'platform',x->>'url' from jsonb_array_elements(coalesce(p_payload->'social_links','[]'::jsonb)) x;
    end if;
    select to_jsonb(t) into v_after from public.v2_labs t where lab_slug = p_resource_id;
  elsif p_resource_type = 'providers' then
    select to_jsonb(t) into v_before from public.v2_providers t where provider_slug=p_resource_id;
    if p_action='delete' then delete from public.v2_providers where provider_slug=p_resource_id;
    else
      insert into public.v2_providers(provider_slug,name,status,country_code,subdivision_code,base_url,default_execution_regions,byok_available,metadata,updated_at)
      values(p_resource_id,p_payload->>'api_provider_name',lower(coalesce(nullif(p_payload->>'status',''),'active')),coalesce(nullif(p_payload->>'country_code',''),'xx'),nullif(p_payload->>'subdivision_code',''),nullif(p_payload->>'link',''),case when jsonb_typeof(p_payload->'default_execution_regions') = 'array' then array(select jsonb_array_elements_text(p_payload->'default_execution_regions')) else null end,coalesce((p_payload->>'byok_available')::boolean,false),jsonb_strip_nulls(jsonb_build_object('description',p_payload->>'description','prompt_training_policy',p_payload->>'prompt_training_policy','prompt_training_notes',p_payload->>'prompt_training_notes','prompt_training_source_url',p_payload->>'prompt_training_source_url','data_policy_tier',p_payload->>'data_policy_tier','data_policy_confidence',p_payload->>'data_policy_confidence','data_policy_contract_mode',p_payload->>'data_policy_contract_mode','data_policy_contract_notes',p_payload->>'data_policy_contract_notes','source','admin')),now())
      on conflict(provider_slug) do update set name=excluded.name,status=excluded.status,country_code=excluded.country_code,subdivision_code=excluded.subdivision_code,base_url=excluded.base_url,default_execution_regions=case when p_payload ? 'default_execution_regions' then excluded.default_execution_regions else public.v2_providers.default_execution_regions end,byok_available=case when p_payload ? 'byok_available' then excluded.byok_available else public.v2_providers.byok_available end,metadata=public.v2_providers.metadata||excluded.metadata,updated_at=now();
    end if;
    select to_jsonb(t) into v_after from public.v2_providers t where provider_slug=p_resource_id;
  elsif p_resource_type = 'benchmarks' then
    select to_jsonb(t) into v_before from public.v2_benchmarks t where benchmark_id=p_resource_id;
    if p_action='delete' then delete from public.v2_benchmarks where benchmark_id=p_resource_id;
    else
      insert into public.v2_benchmarks(benchmark_id,name,category,link,ascending_order,updated_at)
      values(p_resource_id,p_payload->>'name',nullif(p_payload->>'category',''),nullif(p_payload->>'link',''),coalesce((p_payload->>'ascending_order')::boolean,false),now())
      on conflict(benchmark_id) do update set name=excluded.name,category=excluded.category,link=excluded.link,ascending_order=excluded.ascending_order,updated_at=now();
    end if;
    select to_jsonb(t) into v_after from public.v2_benchmarks t where benchmark_id=p_resource_id;
  elsif p_resource_type = 'subscription-plans' then
    begin
      v_uuid := p_resource_id::uuid;
    exception when invalid_text_representation then
      raise exception 'subscription plan id must be a UUID';
    end;
    select to_jsonb(t) into v_before from public.v2_subscription_plans t where plan_uuid=v_uuid;
    if p_action='delete' then delete from public.v2_subscription_plans where plan_uuid=v_uuid;
    else
      insert into public.v2_subscription_plans(plan_uuid,plan_id,name,lab_slug,description,frequency,price,currency,link,other_info,updated_at)
      values(v_uuid,p_payload->>'plan_id',p_payload->>'name',nullif(p_payload->>'organisation_id',''),nullif(p_payload->>'description',''),nullif(p_payload->>'frequency',''),nullif(p_payload->>'price','')::numeric,nullif(p_payload->>'currency',''),nullif(p_payload->>'link',''),coalesce(p_payload->'other_info','{}'::jsonb)||jsonb_build_object('source','admin'),now())
      on conflict(plan_uuid) do update set plan_id=excluded.plan_id,name=excluded.name,lab_slug=excluded.lab_slug,description=excluded.description,frequency=excluded.frequency,price=excluded.price,currency=excluded.currency,link=excluded.link,other_info=public.v2_subscription_plans.other_info||excluded.other_info,updated_at=now();
    end if;
    select to_jsonb(t) into v_after from public.v2_subscription_plans t where plan_uuid=v_uuid;
  elsif p_resource_type = 'models' then
    select to_jsonb(t) into v_before from public.v2_models t where model_slug=p_resource_id;
    if p_action='delete' then delete from public.v2_models where model_slug=p_resource_id;
    else
      insert into public.v2_models(model_slug,lab_slug,name,status,hidden,input_modalities,output_modalities,family_slug,announced_at,released_at,deprecated_at,retired_at,metadata,updated_at)
      values(p_resource_id,p_payload->>'organisationId',p_payload->>'name',lower(coalesce(nullif(p_payload->>'status',''),'active')),coalesce((p_payload->>'hidden')::boolean,false),string_to_array(coalesce(p_payload->>'inputTypes',''),','),string_to_array(coalesce(p_payload->>'outputTypes',''),','),nullif(p_payload->>'familyId',''),nullif(p_payload->>'announcementDate','')::timestamptz,nullif(p_payload->>'releaseDate','')::timestamptz,nullif(p_payload->>'deprecationDate','')::timestamptz,nullif(p_payload->>'retirementDate','')::timestamptz,jsonb_strip_nulls(jsonb_build_object('license',p_payload->>'license','previous_model_id',p_payload->>'previousModelId','source','admin')),now())
      on conflict(model_slug) do update set lab_slug=case when p_payload ? 'organisationId' then excluded.lab_slug else public.v2_models.lab_slug end,name=coalesce(p_payload->>'name',public.v2_models.name),status=case when p_payload ? 'status' then excluded.status else public.v2_models.status end,hidden=case when p_payload ? 'hidden' then excluded.hidden else public.v2_models.hidden end,input_modalities=case when p_payload ? 'inputTypes' then excluded.input_modalities else public.v2_models.input_modalities end,output_modalities=case when p_payload ? 'outputTypes' then excluded.output_modalities else public.v2_models.output_modalities end,family_slug=case when p_payload ? 'familyId' then excluded.family_slug else public.v2_models.family_slug end,announced_at=case when p_payload ? 'announcementDate' then excluded.announced_at else public.v2_models.announced_at end,released_at=case when p_payload ? 'releaseDate' then excluded.released_at else public.v2_models.released_at end,deprecated_at=case when p_payload ? 'deprecationDate' then excluded.deprecated_at else public.v2_models.deprecated_at end,retired_at=case when p_payload ? 'retirementDate' then excluded.retired_at else public.v2_models.retired_at end,metadata=public.v2_models.metadata||excluded.metadata,updated_at=now();
    end if;
    select to_jsonb(t) into v_after from public.v2_models t where model_slug=p_resource_id;
  else raise exception 'unsupported catalogue resource'; end if;

  insert into public.v2_catalogue_admin_changes(actor_user_id,resource_type,resource_id,action,before_state,after_state)
  values(p_actor_user_id,p_resource_type,p_resource_id,p_action,v_before,v_after);
  insert into public.v2_catalogue_source_overrides(source_type,source_key,disposition,actor_user_id,resource_id,updated_at)
  values(p_resource_type,p_resource_id,case when p_action='delete' then 'suppressed' else 'database_managed' end,p_actor_user_id,p_resource_id,now())
  on conflict(source_type,source_key) do update set disposition=excluded.disposition,actor_user_id=excluded.actor_user_id,resource_id=excluded.resource_id,updated_at=now();
  return jsonb_build_object('before',v_before,'after',v_after);
end $function$;

REVOKE ALL ON FUNCTION "public"."mutate_v2_admin_catalogue"(uuid, text, text, text, jsonb) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.mutate_v2_admin_model_aliases (
  p_actor_user_id uuid,
  p_model_slug    text,
  p_aliases       jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_before jsonb;
  v_after jsonb;
begin
  if not exists(select 1 from public.users where user_id=p_actor_user_id and lower(coalesce(role::text,''))='admin') then raise exception 'actor must have the admin role'; end if;
  if not exists(select 1 from public.v2_models where model_slug=p_model_slug) then raise exception 'model not found'; end if;
  select coalesce(jsonb_agg(to_jsonb(t) order by alias_slug),'[]'::jsonb) into v_before from public.v2_model_aliases t where model_slug=p_model_slug;
  perform set_config('phaseo.catalogue_actor',p_actor_user_id::text,true);
  if exists(select 1 from jsonb_array_elements(p_aliases) x join public.v2_model_aliases a on a.alias_slug=lower(trim(x->>'alias_slug')) where a.model_slug<>p_model_slug) then raise exception 'alias belongs to another model'; end if;
  insert into public.v2_model_aliases(alias_slug,model_slug,alias_type,enabled,effective_from,effective_to,metadata,updated_at)
  select lower(trim(x->>'alias_slug')),p_model_slug,coalesce(nullif(x->>'alias_type',''),'public'),coalesce((x->>'enabled')::boolean,true),nullif(x->>'effective_from','')::timestamptz,nullif(x->>'effective_to','')::timestamptz,coalesce(x->'metadata','{}'::jsonb)||jsonb_build_object('source','admin'),now()
  from jsonb_array_elements(coalesce(p_aliases,'[]'::jsonb)) x
  on conflict(alias_slug) do update set alias_type=excluded.alias_type,enabled=excluded.enabled,effective_from=excluded.effective_from,effective_to=excluded.effective_to,metadata=excluded.metadata,updated_at=now();
  select coalesce(jsonb_agg(to_jsonb(t) order by alias_slug),'[]'::jsonb) into v_after from public.v2_model_aliases t where model_slug=p_model_slug;
  insert into public.v2_catalogue_admin_changes(actor_user_id,resource_type,resource_id,action,before_state,after_state)
  values(p_actor_user_id,'model_aliases',p_model_slug,'save',v_before,v_after);
  insert into public.v2_catalogue_source_overrides(source_type,source_key,disposition,actor_user_id,resource_id,updated_at)
  values('model',p_model_slug,'database_managed',p_actor_user_id,p_model_slug,now())
  on conflict(source_type,source_key) do update set disposition='database_managed',actor_user_id=excluded.actor_user_id,resource_id=excluded.resource_id,updated_at=now();
  return v_after;
end $function$;

REVOKE ALL ON FUNCTION "public"."mutate_v2_admin_model_aliases"(uuid, text, jsonb) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.mutate_v2_admin_model_graph (
  p_actor_user_id uuid,
  p_model_slug    text,
  p_payload       jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare v_before jsonb; v_after jsonb;
begin
  if not exists(select 1 from public.users where user_id=p_actor_user_id and lower(coalesce(role::text,''))='admin') then raise exception 'actor must have the admin role'; end if;
  perform set_config('phaseo.catalogue_actor', p_actor_user_id::text, true);
  select to_jsonb(t) into v_before from public.v2_models t where model_slug=p_model_slug for update;
  if v_before is null then raise exception 'model not found'; end if;

  update public.v2_models set
    name=coalesce(p_payload->>'name',name), lab_slug=coalesce(p_payload->>'organisation_id',lab_slug),
    status=coalesce(lower(p_payload->>'status'),status), hidden=coalesce((p_payload->>'hidden')::boolean,hidden),
    family_slug=case when p_payload ? 'family_id' then nullif(p_payload->>'family_id','') else family_slug end,
    input_modalities=case when p_payload ? 'input_types' then string_to_array(coalesce(p_payload->>'input_types',''),',') else input_modalities end,
    output_modalities=case when p_payload ? 'output_types' then string_to_array(coalesce(p_payload->>'output_types',''),',') else output_modalities end,
    announced_at=case when p_payload ? 'announcement_date' then nullif(p_payload->>'announcement_date','')::timestamptz else announced_at end,
    released_at=case when p_payload ? 'release_date' then nullif(p_payload->>'release_date','')::timestamptz else released_at end,
    deprecated_at=case when p_payload ? 'deprecation_date' then nullif(p_payload->>'deprecation_date','')::timestamptz else deprecated_at end,
    retired_at=case when p_payload ? 'retirement_date' then nullif(p_payload->>'retirement_date','')::timestamptz else retired_at end,
    metadata=metadata||jsonb_strip_nulls(jsonb_build_object('license',p_payload->>'license','previous_model_id',p_payload->>'previous_model_id','source','admin')),updated_at=now()
  where model_slug=p_model_slug;

  if p_payload ? 'family' then
    insert into public.v2_model_families(family_slug,lab_slug,name,metadata,updated_at)
    values(p_payload->'family'->>'family_id',(select lab_slug from public.v2_models where model_slug=p_model_slug),p_payload->'family'->>'family_name',jsonb_strip_nulls(jsonb_build_object('description',p_payload->'family'->>'family_description','source','admin')),now())
    on conflict(family_slug) do update set name=excluded.name,metadata=public.v2_model_families.metadata||excluded.metadata,updated_at=now();
    update public.v2_models set family_slug=p_payload->'family'->>'family_id',updated_at=now() where model_slug=p_model_slug;
  end if;

  if p_payload ? 'model_details' then
    delete from public.v2_model_details where model_slug=p_model_slug;
    insert into public.v2_model_details(model_slug,detail_name,detail_value,detail_order)
    select p_model_slug,x->>'detail_name',coalesce(x->'detail_value',to_jsonb(x->>'detail_value')),100+row_number() over()
    from jsonb_array_elements(p_payload->'model_details') x;
  end if;
  if p_payload ? 'links' then
    delete from public.v2_model_links where model_slug=p_model_slug;
    insert into public.v2_model_links(model_slug,link_kind,title,url,metadata)
    select p_model_slug,coalesce(nullif(x->>'kind',''),x->>'platform'),coalesce(nullif(x->>'title',''),x->>'platform'),x->>'url',jsonb_build_object('source','admin') from jsonb_array_elements(p_payload->'links') x;
  end if;
  if p_payload ? 'benchmark_results' then
    if exists(select 1 from jsonb_array_elements(p_payload->'benchmark_results') x
      join public.v2_benchmark_results r on r.result_id::text=x->>'id' where r.model_slug<>p_model_slug)
      then raise exception 'benchmark result belongs to another model'; end if;
    insert into public.v2_benchmark_results(result_id,model_slug,benchmark_id,score,score_numeric,is_self_reported,other_info,source_link,variant,effective_to,updated_at)
    select coalesce(nullif(x->>'id','')::uuid,gen_random_uuid()),p_model_slug,x->>'benchmark_id',x->>'score',
      case when (x->>'score')~'^[-+]?[0-9]*\.?[0-9]+$' then (x->>'score')::numeric end,
      coalesce((x->>'is_self_reported')::boolean,false),nullif(x->>'other_info',''),nullif(x->>'source_link',''),nullif(x->>'variant',''),nullif(x->>'effective_to','')::timestamptz,now()
    from jsonb_array_elements(p_payload->'benchmark_results') x
    on conflict(result_id) do update set benchmark_id=excluded.benchmark_id,score=excluded.score,score_numeric=excluded.score_numeric,
      is_self_reported=excluded.is_self_reported,other_info=excluded.other_info,source_link=excluded.source_link,variant=excluded.variant,effective_to=excluded.effective_to,updated_at=now();
  end if;
  if p_payload ? 'subscription_plan_models' then
    insert into public.v2_subscription_plan_models(plan_uuid,model_slug,model_info,rate_limit,other_info,effective_to)
    select (x->>'plan_uuid')::uuid,p_model_slug,coalesce(x->'model_info','{}'::jsonb),coalesce(x->'rate_limit','{}'::jsonb),coalesce(x->'other_info','{}'::jsonb),nullif(x->>'effective_to','')::timestamptz
    from jsonb_array_elements(p_payload->'subscription_plan_models') x
    on conflict(plan_uuid,model_slug) do update set model_info=excluded.model_info,rate_limit=excluded.rate_limit,other_info=excluded.other_info,effective_to=excluded.effective_to;
  end if;
  if p_payload ? 'provider_models' then
    if exists(select 1 from jsonb_array_elements(p_payload->'provider_models') x
      join public.v2_model_provider_routes r on r.provider_model_id=x->>'id'
      where r.model_slug<>p_model_slug) then raise exception 'provider route belongs to another model'; end if;
    insert into public.v2_model_provider_routes(provider_model_id,model_slug,provider_slug,provider_model_slug,status,routing_enabled,input_modalities,output_modalities,context_length,max_output_tokens,effective_from,effective_to,metadata,updated_at)
    select
      case when coalesce(x->>'id','') like 'new-%' or coalesce(x->>'id','')='' then (x->>'provider_id')||':'||p_model_slug||':'||coalesce(nullif(x->>'provider_model_slug',''),x->>'api_model_id') else x->>'id' end,
      p_model_slug,x->>'provider_id',coalesce(nullif(x->>'provider_model_slug',''),x->>'api_model_id'),'active',coalesce((x->>'is_active_gateway')::boolean,false),
      case when jsonb_typeof(x->'input_modalities')='array' then array(select jsonb_array_elements_text(x->'input_modalities')) else string_to_array(coalesce(x->>'input_modalities',''),',') end,
      case when jsonb_typeof(x->'output_modalities')='array' then array(select jsonb_array_elements_text(x->'output_modalities')) else string_to_array(coalesce(x->>'output_modalities',''),',') end,
      nullif(x->>'context_length','')::integer,nullif(x->>'max_output_tokens','')::integer,nullif(x->>'effective_from','')::timestamptz,nullif(x->>'effective_to','')::timestamptz,
      jsonb_strip_nulls(jsonb_build_object('prompt_training_policy_override',x->>'prompt_training_policy_override','prompt_training_override_notes',x->>'prompt_training_override_notes','prompt_training_override_source_url',x->>'prompt_training_override_source_url','quantization_scheme',x->>'quantization_scheme','source','admin')),now()
    from (
      select distinct on (
        case when coalesce(entry.value->>'id','') like 'new-%' or coalesce(entry.value->>'id','')=''
          then (entry.value->>'provider_id')||':'||p_model_slug||':'||coalesce(nullif(entry.value->>'provider_model_slug',''),entry.value->>'api_model_id')
          else entry.value->>'id' end
      ) entry.value
      from jsonb_array_elements(p_payload->'provider_models') with ordinality entry(value, position)
      order by
        case when coalesce(entry.value->>'id','') like 'new-%' or coalesce(entry.value->>'id','')=''
          then (entry.value->>'provider_id')||':'||p_model_slug||':'||coalesce(nullif(entry.value->>'provider_model_slug',''),entry.value->>'api_model_id')
          else entry.value->>'id' end,
        entry.position desc
    ) deduplicated(x)
    on conflict(provider_model_id) do update set provider_slug=excluded.provider_slug,provider_model_slug=excluded.provider_model_slug,status=public.v2_model_provider_routes.status,routing_enabled=excluded.routing_enabled,input_modalities=excluded.input_modalities,output_modalities=excluded.output_modalities,context_length=excluded.context_length,max_output_tokens=excluded.max_output_tokens,effective_from=excluded.effective_from,effective_to=excluded.effective_to,metadata=public.v2_model_provider_routes.metadata||excluded.metadata,updated_at=now();
  end if;
  if p_payload ? 'provider_capabilities' then
    if exists (
      select 1 from jsonb_array_elements(p_payload->'provider_capabilities') x
      where not exists (
        select 1 from public.v2_model_provider_routes route
        where route.model_slug=p_model_slug and route.provider_slug=x->>'provider_id'
          and route.provider_model_slug=coalesce(nullif(x->>'provider_model_slug',''),x->>'api_model_id') and (nullif(x->>'provider_model_id','') is null or route.provider_model_id=x->>'provider_model_id')
      )
    ) then raise exception 'provider capability does not match a model route'; end if;
    insert into public.v2_route_capabilities(provider_model_id,capability_id,status,params,effective_from,effective_to,metadata,updated_at)
    select route.provider_model_id,x->>'capability_id',case when x->>'status' like 'deranked_%' then 'degraded' else coalesce(nullif(x->>'status',''),'active') end,coalesce(x->'params','{}'::jsonb),nullif(x->>'effective_from','')::timestamptz,nullif(x->>'effective_to','')::timestamptz,jsonb_build_object('editor_status',x->>'status','source','admin'),now()
    from jsonb_array_elements(p_payload->'provider_capabilities') x join public.v2_model_provider_routes route on route.model_slug=p_model_slug and route.provider_slug=x->>'provider_id' and route.provider_model_slug=coalesce(nullif(x->>'provider_model_slug',''),x->>'api_model_id') and (nullif(x->>'provider_model_id','') is null or route.provider_model_id=x->>'provider_model_id')
    on conflict(provider_model_id,capability_id) do update set status=excluded.status,params=excluded.params,
      effective_from=excluded.effective_from,effective_to=excluded.effective_to,
      metadata=public.v2_route_capabilities.metadata||excluded.metadata,updated_at=now();
  end if;
  select to_jsonb(t) into v_after from public.v2_models t where model_slug=p_model_slug;
  insert into public.v2_catalogue_admin_changes(actor_user_id,resource_type,resource_id,action,before_state,after_state)
  values(p_actor_user_id,'model_graph',p_model_slug,'save',v_before,v_after);
  insert into public.v2_catalogue_source_overrides(source_type,source_key,disposition,actor_user_id,resource_id,updated_at)
  values('model',p_model_slug,'database_managed',p_actor_user_id,p_model_slug,now()) on conflict(source_type,source_key) do update set disposition='database_managed',actor_user_id=excluded.actor_user_id,updated_at=now();
  return jsonb_build_object('model',v_after);
end $function$;

REVOKE ALL ON FUNCTION "public"."mutate_v2_admin_model_graph"(uuid, text, jsonb) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.mutate_v2_admin_model_graph_editable (
  p_actor_user_id uuid,
  p_model_slug    text,
  p_payload       jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_graph_payload jsonb := coalesce(p_payload, '{}'::jsonb) - 'provider_models' - 'provider_capabilities';
  v_result jsonb;
begin
  v_result := public.mutate_v2_admin_model_graph_with_successor(
    p_actor_user_id,
    p_model_slug,
    v_graph_payload
  );

  if p_payload ? 'provider_models' or p_payload ? 'provider_capabilities' then
    -- Older graph functions do not set the history actor themselves.
    perform set_config('phaseo.catalogue_actor', p_actor_user_id::text, true);
  end if;

  if p_payload ? 'provider_models' then
    perform catalogue_private.apply_v2_admin_model_provider_routes(
      p_actor_user_id,
      p_model_slug,
      p_payload->'provider_models'
    );
  end if;

  if p_payload ? 'provider_capabilities' then
    perform catalogue_private.apply_v2_admin_model_capabilities(
      p_actor_user_id,
      p_model_slug,
      p_payload->'provider_capabilities'
    );
  end if;

  return v_result;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."mutate_v2_admin_model_graph_editable"(uuid, text, jsonb) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.mutate_v2_admin_model_graph_with_successor (
  p_actor_user_id uuid,
  p_model_slug    text,
  p_payload       jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_result jsonb;
begin
  v_result := public.mutate_v2_admin_model_graph(p_actor_user_id, p_model_slug, p_payload);
  if p_payload ? 'replacement_model_id' then
    perform public.set_v2_model_recommended_successor(p_actor_user_id, p_model_slug, p_payload->>'replacement_model_id');
  end if;
  return v_result;
end $function$;

REVOKE ALL ON FUNCTION "public"."mutate_v2_admin_model_graph_with_successor"(uuid, text, jsonb) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.mutate_v2_admin_model_notice (
  p_actor_user_id uuid,
  p_model_slug    text,
  p_notice        jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_before jsonb;
  v_after jsonb;
begin
  if not exists(select 1 from public.users where user_id=p_actor_user_id and lower(coalesce(role::text,''))='admin') then raise exception 'actor must have the admin role'; end if;
  if not exists(select 1 from public.v2_models where model_slug=p_model_slug) then raise exception 'model not found'; end if;
  if p_notice is not null and (jsonb_typeof(p_notice)<>'object' or jsonb_typeof(p_notice->'markdown') is distinct from 'string' or length(p_notice->>'markdown')>20000 or coalesce(p_notice->>'tone','') not in ('info','warning','critical')) then raise exception 'invalid model notice'; end if;
  perform pg_advisory_xact_lock(hashtextextended('model-notice:'||p_model_slug,0));
  perform set_config('phaseo.catalogue_actor',p_actor_user_id::text,true);
  select to_jsonb(t) into v_before from public.v2_model_page_notices t where model_slug=p_model_slug for update;
  if p_notice is null or nullif(trim(p_notice->>'markdown'),'') is null then
    delete from public.v2_model_page_notices where model_slug=p_model_slug;
  else
    insert into public.v2_model_page_notices(model_slug,tone,markdown,updated_at)
    values(p_model_slug,p_notice->>'tone',trim(p_notice->>'markdown'),now())
    on conflict(model_slug) do update set tone=excluded.tone,markdown=excluded.markdown,updated_at=now();
  end if;
  select to_jsonb(t) into v_after from public.v2_model_page_notices t where model_slug=p_model_slug;
  insert into public.v2_catalogue_admin_changes(actor_user_id,resource_type,resource_id,action,before_state,after_state)
  values(p_actor_user_id,'model_notice',p_model_slug,case when v_after is null then 'delete' when v_before is null then 'create' else 'update' end,v_before,v_after);
  insert into public.v2_catalogue_source_overrides(source_type,source_key,disposition,actor_user_id,resource_id,updated_at)
  values('model',p_model_slug,'database_managed',p_actor_user_id,p_model_slug,now())
  on conflict(source_type,source_key) do update set disposition='database_managed',actor_user_id=excluded.actor_user_id,resource_id=excluded.resource_id,updated_at=now();
  return v_after;
end $function$;

REVOKE ALL ON FUNCTION "public"."mutate_v2_admin_model_notice"(uuid, text, jsonb) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.mutate_v2_admin_model_with_successor (
  p_actor_user_id uuid,
  p_action        text,
  p_model_slug    text,
  p_payload       jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_result jsonb;
begin
  v_result := public.mutate_v2_admin_catalogue(p_actor_user_id, 'models', p_action, p_model_slug, p_payload);
  if p_payload ? 'replacementModelId' then
    perform public.set_v2_model_recommended_successor(p_actor_user_id, p_model_slug, p_payload->>'replacementModelId');
  end if;
  return v_result;
end $function$;

REVOKE ALL ON FUNCTION "public"."mutate_v2_admin_model_with_successor"(uuid, text, text, jsonb) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.mutate_v2_admin_pricing_sku (
  p_actor_user_id uuid,
  p_model_slug    text,
  p_action        text,
  p_sku           jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO 'public'
  AS $function$
declare
  v_sku_id uuid;
  v_provider_model_id text;
  v_existing public.v2_pricing_skus%rowtype;
  v_before jsonb;
  v_after jsonb;
  v_meter jsonb;
  v_resource_id text;
  v_starts timestamptz;
  v_version integer;
begin
  if p_actor_user_id is null then
    raise exception 'actor_user_id is required';
  end if;
  if coalesce(trim(p_model_slug), '') = '' then
    raise exception 'model_slug is required';
  end if;
  if p_action not in ('save', 'end_date') then
    raise exception 'unsupported pricing mutation action';
  end if;
  if not exists (
    select 1 from public.users
    where user_id = p_actor_user_id
      and lower(coalesce(role::text, '')) = 'admin'
  ) then
    raise exception 'actor must have the admin role';
  end if;

  if nullif(p_sku->>'sku_id', '') is not null then
    begin
      v_sku_id := (p_sku->>'sku_id')::uuid;
    exception when invalid_text_representation then
      raise exception 'sku_id must be a UUID';
    end;
  end if;

  if v_sku_id is not null then
    select * into v_existing
    from public.v2_pricing_skus
    where sku_id = v_sku_id for update;

    if found then
      select jsonb_build_object(
        'sku', to_jsonb(v_existing),
        'meters', coalesce((
          select jsonb_agg(to_jsonb(meter) order by meter.meter_order, meter.meter_key)
          from public.v2_pricing_sku_meters meter
          where meter.sku_id = v_sku_id
        ), '[]'::jsonb)
      ) into v_before;

      if not exists (
        select 1
        from public.v2_model_provider_routes route
        where route.provider_model_id = v_existing.provider_model_id
          and route.model_slug = p_model_slug
      ) then
        raise exception 'pricing SKU does not belong to the requested model';
      end if;
    end if;
  end if;

  if v_sku_id is not null and v_before is null then
    raise exception 'pricing SKU not found';
  end if;
  perform set_config('phaseo.catalogue_actor', p_actor_user_id::text, true);
  if p_action = 'end_date' then
    if v_before is null then raise exception 'pricing SKU not found'; end if;
    v_starts := nullif(p_sku->>'effective_to','')::timestamptz;
    if v_starts is null or v_starts <= v_existing.effective_from then
      raise exception 'end date must be after the start date';
    end if;
    if v_existing.effective_to is not null and v_existing.effective_to <= now() then
      raise exception 'historical prices cannot be changed';
    end if;
    if exists(select 1 from public.v2_pricing_skus where provider_model_id=v_existing.provider_model_id and sku_code=v_existing.sku_code and version>v_existing.version) then
      raise exception 'a superseded version cannot be changed';
    end if;
    update public.v2_pricing_skus set effective_to=v_starts,updated_at=now() where sku_id=v_sku_id;
    select jsonb_build_object('sku',to_jsonb(t),'meters',v_before->'meters') into v_after
      from public.v2_pricing_skus t where sku_id=v_sku_id;
    insert into public.v2_catalogue_admin_changes(actor_user_id,resource_type,resource_id,action,before_state,after_state)
      values(p_actor_user_id,'pricing_sku',v_sku_id::text,'update',v_before,v_after);
    if nullif(v_existing.metadata->>'source_key','') is not null then
      insert into public.v2_catalogue_source_overrides(source_type,source_key,disposition,actor_user_id,resource_id,updated_at)
        values('pricing_rule',v_existing.metadata->>'source_key','database_managed',p_actor_user_id,v_sku_id::text,now())
        on conflict(source_type,source_key) do update set disposition=excluded.disposition,actor_user_id=excluded.actor_user_id,resource_id=excluded.resource_id,updated_at=now();
    end if;
    return v_after;
  end if;

  v_provider_model_id := nullif(trim(p_sku->>'provider_model_id'), '');
  if v_provider_model_id is null then
    raise exception 'provider_model_id is required';
  end if;
  if not exists (
    select 1
    from public.v2_model_provider_routes route
    where route.provider_model_id = v_provider_model_id
      and route.model_slug = p_model_slug
  ) then
    raise exception 'provider route does not belong to the requested model';
  end if;
  if jsonb_typeof(coalesce(p_sku->'meters', '[]'::jsonb)) <> 'array'
     or jsonb_array_length(coalesce(p_sku->'meters', '[]'::jsonb)) = 0 then
    raise exception 'at least one pricing meter is required';
  end if;

  -- Serialize versions of a price family, including concurrent new prices.
  perform pg_advisory_xact_lock(hashtextextended(v_provider_model_id||':'||lower(trim(p_sku->>'sku_code')),0));
  v_starts := coalesce(nullif(p_sku->>'effective_from','')::timestamptz,now());
  if v_before is not null then
    if v_existing.provider_model_id <> v_provider_model_id or v_existing.sku_code <> lower(trim(p_sku->>'sku_code')) then
      raise exception 'a price revision must keep its provider route and price code';
    end if;
    if v_existing.effective_to is not null then raise exception 'end-dated prices cannot be revised; add a new price group'; end if;
    if v_starts <= v_existing.effective_from then raise exception 'revision must start after the previous version'; end if;
    update public.v2_pricing_skus set effective_to=v_starts,updated_at=now() where sku_id=v_sku_id;
  elsif exists(select 1 from public.v2_pricing_skus where provider_model_id=v_provider_model_id and sku_code=lower(trim(p_sku->>'sku_code'))) then
    raise exception 'price group already exists; reload and create a revision';
  end if;
  select coalesce(max(version),0)+1 into v_version from public.v2_pricing_skus
    where provider_model_id=v_provider_model_id and sku_code=lower(trim(p_sku->>'sku_code'));
  v_sku_id := gen_random_uuid();
  insert into public.v2_pricing_skus (
    sku_id,
    provider_model_id,
    sku_code,
    version,
    operation,
    status,
    region,
    service_tier_slug,
    display_name,
    description,
    currency,
    effective_from,
    effective_to,
    metadata,
    updated_at
  ) values (
    v_sku_id,
    v_provider_model_id,
    lower(trim(p_sku->>'sku_code')),
    v_version,
    coalesce(nullif(trim(p_sku->>'operation'), ''), 'inference'),
    coalesce(nullif(trim(p_sku->>'status'), ''), 'active'),
    nullif(trim(p_sku->>'region'), ''),
    coalesce(nullif(trim(p_sku->>'service_tier_slug'), ''), 'standard'),
    trim(p_sku->>'display_name'),
    nullif(trim(p_sku->>'description'), ''),
    upper(coalesce(nullif(trim(p_sku->>'currency'), ''), 'USD')),
    v_starts,
    nullif(p_sku->>'effective_to', '')::timestamptz,
    coalesce(p_sku->'metadata', '{}'::jsonb) || jsonb_build_object(
      'source', 'admin',
      'authored_by', p_actor_user_id,
      'authored_at', now()
    ),
    now()
  )
  ;

  for v_meter in select value from jsonb_array_elements(p_sku->'meters')
  loop
    insert into public.v2_pricing_sku_meters (
      sku_id,
      meter_key,
      modality,
      direction,
      unit,
      unit_quantity,
      price_nanos,
      display_label,
      display_unit,
      billable,
      meter_order,
      metadata
    ) values (
      v_sku_id,
      lower(trim(v_meter->>'meter_key')),
      lower(trim(v_meter->>'modality')),
      nullif(lower(trim(v_meter->>'direction')), ''),
      lower(trim(v_meter->>'unit')),
      (v_meter->>'unit_quantity')::numeric,
      (v_meter->>'price_nanos')::numeric,
      trim(v_meter->>'display_label'),
      trim(v_meter->>'display_unit'),
      coalesce((v_meter->>'billable')::boolean, true),
      coalesce((v_meter->>'meter_order')::integer, 100),
      coalesce(v_meter->'metadata', '{}'::jsonb) || jsonb_build_object('source', 'admin')
    );
  end loop;

  select jsonb_build_object(
    'sku', to_jsonb(sku),
    'meters', coalesce((
      select jsonb_agg(to_jsonb(meter) order by meter.meter_order, meter.meter_key)
      from public.v2_pricing_sku_meters meter
      where meter.sku_id = v_sku_id
    ), '[]'::jsonb)
  ) into v_after
  from public.v2_pricing_skus sku
  where sku.sku_id = v_sku_id;

  v_resource_id := v_sku_id::text;
  insert into public.v2_catalogue_admin_changes (
    actor_user_id, resource_type, resource_id, action, before_state, after_state
  ) values (
    p_actor_user_id,
    'pricing_sku',
    v_resource_id,
    case when v_before is null then 'create' else 'update' end,
    v_before,
    v_after
  );

  if nullif(p_sku->'metadata'->>'source_key', '') is not null then
    insert into public.v2_catalogue_source_overrides (
      source_type, source_key, disposition, actor_user_id, resource_id, updated_at
    ) values (
      'pricing_rule', p_sku->'metadata'->>'source_key', 'database_managed', p_actor_user_id, v_resource_id, now()
    )
    on conflict (source_type, source_key) do update set
      disposition = excluded.disposition,
      actor_user_id = excluded.actor_user_id,
      resource_id = excluded.resource_id,
      updated_at = now();
  end if;

  return v_after;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."mutate_v2_admin_pricing_sku"(uuid, text, text, jsonb) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.mutate_v2_admin_provider_offer (
  p_actor_user_id uuid,
  p_action        text,
  p_provider_slug text,
  p_payload       jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_before jsonb; v_after jsonb; v_family text; v_parent text; v_scope text; v_mode text; v_field text;
  v_exec text[]; v_data text[]; v_metadata jsonb;
begin
  if not exists(select 1 from public.users where user_id=p_actor_user_id and lower(coalesce(role::text,''))='admin') then raise exception 'actor must have the admin role'; end if;
  if p_action not in ('create','update') then raise exception 'unsupported provider action'; end if;
  if nullif(trim(p_payload->>'api_provider_name'),'') is null then raise exception 'provider name required'; end if;
  perform pg_advisory_xact_lock(hashtextextended('provider-offer:'||p_provider_slug,0));
  select to_jsonb(p) into v_before from public.v2_providers p where provider_slug=p_provider_slug for update;
  if p_action='create' and v_before is not null then raise exception 'provider already exists'; end if;
  if p_action='update' and v_before is null then raise exception 'provider not found'; end if;
  v_scope=coalesce(p_payload->>'offer_scope',v_before->>'offer_scope','global');
  v_mode=coalesce(p_payload->>'residency_mode',v_before->>'residency_mode','unknown');
  if v_scope not in ('global','regional','specialized') then raise exception 'invalid offer scope'; end if;
  if v_mode not in ('unknown','provider_managed','customer_selectable','account_selected') then raise exception 'invalid residency mode'; end if;
  v_parent=nullif(trim(p_payload->>'parent_provider_slug'),'');
  v_family=coalesce(v_before->>'provider_family_slug',p_provider_slug);
  if v_parent is not null then
    if v_parent=p_provider_slug then raise exception 'provider cannot be its own parent'; end if;
    select coalesce(provider_family_slug,provider_slug) into v_family from public.v2_providers where provider_slug=v_parent;
    if not found then raise exception 'parent provider not found'; end if;
  elsif p_action='create' and v_scope='regional' then raise exception 'regional offers require a parent provider';
  end if;
  foreach v_field in array array['default_execution_regions','default_data_regions'] loop
    if p_payload ? v_field then
      if jsonb_typeof(p_payload->v_field) not in ('array','null') then raise exception 'invalid region list'; end if;
      if jsonb_typeof(p_payload->v_field)='array' and exists(select 1 from jsonb_array_elements(p_payload->v_field) x where jsonb_typeof(x)<>'string' or trim(x#>>'{}') !~ '^[a-zA-Z0-9][a-zA-Z0-9_-]{0,63}$') then raise exception 'invalid region'; end if;
    end if;
  end loop;
  v_exec=case when jsonb_typeof(coalesce(p_payload->'default_execution_regions',v_before->'default_execution_regions'))='array' then array(select distinct lower(trim(value)) from jsonb_array_elements_text(coalesce(p_payload->'default_execution_regions',v_before->'default_execution_regions'))) else null end;
  v_data=case when jsonb_typeof(coalesce(p_payload->'default_data_regions',v_before->'default_data_regions'))='array' then array(select distinct lower(trim(value)) from jsonb_array_elements_text(coalesce(p_payload->'default_data_regions',v_before->'default_data_regions'))) else null end;
  if v_scope='regional' and (coalesce(cardinality(v_exec),0)=0 or 'global'=any(v_exec)) then raise exception 'regional offers require specific execution regions'; end if;
  if v_scope='regional' and nullif(trim(coalesce(p_payload->>'offer_label',v_before->>'offer_label')),'') is null then raise exception 'regional offer label required'; end if;
  v_metadata=coalesce(v_before->'metadata','{}'::jsonb);
  foreach v_field in array array['description','link','prompt_training_policy','prompt_training_notes','prompt_training_source_url','data_policy_tier','data_policy_confidence','data_policy_contract_mode','data_policy_contract_notes'] loop
    if p_payload ? v_field then v_metadata=v_metadata||jsonb_build_object(v_field,p_payload->v_field); end if;
  end loop;
  if p_payload ? 'parent_provider_slug' then v_metadata=v_metadata||jsonb_build_object('parent_provider_slug',v_parent); end if;
  perform set_config('phaseo.catalogue_actor',p_actor_user_id::text,true);
  insert into public.v2_providers(provider_slug,name,provider_family_slug,offer_scope,offer_label,residency_mode,default_execution_regions,default_data_regions,country_code,subdivision_code,base_url,byok_available,credential_mode,status,routing_enabled,routable,metadata,updated_at)
  values(p_provider_slug,trim(p_payload->>'api_provider_name'),v_family,v_scope,
    case when p_payload ? 'offer_label' then nullif(trim(p_payload->>'offer_label'),'') else v_before->>'offer_label' end,
    v_mode,v_exec,v_data,coalesce(nullif(p_payload->>'country_code',''),v_before->>'country_code','xx'),case when p_payload ? 'subdivision_code' then nullif(trim(p_payload->>'subdivision_code'),'') else v_before->>'subdivision_code' end,
    case when p_payload ? 'base_url' then nullif(trim(p_payload->>'base_url'),'') else v_before->>'base_url' end,
    coalesce((p_payload->>'byok_available')::boolean,(v_before->>'byok_available')::boolean,false), coalesce(p_payload->>'credential_mode',v_before->>'credential_mode','managed_and_byok'), lower(coalesce(p_payload->>'status',v_before->>'status','active')),false,false,v_metadata,now())
  on conflict(provider_slug) do update set name=excluded.name,provider_family_slug=excluded.provider_family_slug,offer_scope=excluded.offer_scope,offer_label=excluded.offer_label,residency_mode=excluded.residency_mode,default_execution_regions=excluded.default_execution_regions,default_data_regions=excluded.default_data_regions,country_code=excluded.country_code,subdivision_code=excluded.subdivision_code,base_url=excluded.base_url,byok_available=excluded.byok_available,credential_mode=excluded.credential_mode,status=excluded.status,metadata=excluded.metadata,updated_at=now();
  select to_jsonb(p) into v_after from public.v2_providers p where provider_slug=p_provider_slug;
  insert into public.v2_catalogue_admin_changes(actor_user_id,resource_type,resource_id,action,before_state,after_state) values(p_actor_user_id,'providers',p_provider_slug,p_action,v_before,v_after);
  insert into public.v2_catalogue_source_overrides(source_type,source_key,disposition,actor_user_id,resource_id,updated_at) values('providers',p_provider_slug,'database_managed',p_actor_user_id,p_provider_slug,now()) on conflict(source_type,source_key) do update set disposition=excluded.disposition,actor_user_id=excluded.actor_user_id,updated_at=now();
  return v_after;
end $function$;

REVOKE ALL ON FUNCTION "public"."mutate_v2_admin_provider_offer"(uuid, text, text, jsonb) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.mutate_v2_admin_provider_residency (
  p_actor_user_id uuid,
  p_provider_slug text,
  p_policy        jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare v_before jsonb; v_after jsonb; v_field text;
begin
  if not exists(select 1 from public.users where user_id=p_actor_user_id and lower(coalesce(role::text,''))='admin') then raise exception 'actor must have the admin role'; end if;
  if p_policy->>'residency_mode' is null or p_policy->>'residency_mode' not in ('unknown','provider_managed','customer_selectable','account_selected') then raise exception 'invalid residency mode'; end if;
  foreach v_field in array array['default_execution_regions','default_data_regions'] loop
    if not (p_policy ? v_field) or jsonb_typeof(p_policy->v_field) not in ('array','null') then raise exception 'region list required'; end if;
    if jsonb_typeof(p_policy->v_field)='array' then
      if jsonb_array_length(p_policy->v_field)>100 or exists(select 1 from jsonb_array_elements(p_policy->v_field) x where jsonb_typeof(x)<>'string' or trim(x#>>'{}') !~ '^[a-zA-Z0-9][a-zA-Z0-9_-]{0,63}$') then raise exception 'invalid region'; end if;
    end if;
  end loop;
  select to_jsonb(p) into v_before from public.v2_providers p where provider_slug=p_provider_slug for update;
  if v_before is null then raise exception 'provider not found'; end if;
  perform set_config('phaseo.catalogue_actor',p_actor_user_id::text,true);
  update public.v2_providers set
    residency_mode=p_policy->>'residency_mode',
    default_execution_regions=case when jsonb_typeof(p_policy->'default_execution_regions')='array' then array(select distinct lower(trim(value)) from jsonb_array_elements_text(p_policy->'default_execution_regions')) else null end,
    default_data_regions=case when jsonb_typeof(p_policy->'default_data_regions')='array' then array(select distinct lower(trim(value)) from jsonb_array_elements_text(p_policy->'default_data_regions')) else null end,
    updated_at=now() where provider_slug=p_provider_slug;
  select to_jsonb(p) into v_after from public.v2_providers p where provider_slug=p_provider_slug;
  insert into public.v2_catalogue_admin_changes(actor_user_id,resource_type,resource_id,action,before_state,after_state) values(p_actor_user_id,'providers',p_provider_slug,'update',v_before,v_after);
  insert into public.v2_catalogue_source_overrides(source_type,source_key,disposition,actor_user_id,resource_id,updated_at) values('providers',p_provider_slug,'database_managed',p_actor_user_id,p_provider_slug,now()) on conflict(source_type,source_key) do update set disposition=excluded.disposition,actor_user_id=excluded.actor_user_id,updated_at=now();
  return v_after;
end $function$;

REVOKE ALL ON FUNCTION "public"."mutate_v2_admin_provider_residency"(uuid, text, jsonb) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.mutate_v2_admin_provider_route (
  p_actor_user_id uuid,
  p_model_slug    text,
  p_route         jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_provider_slug text := nullif(trim(p_route->>'provider_slug'),'');
  v_provider_model_slug text := nullif(trim(p_route->>'provider_model_slug'),'');
  v_provider_model_id text := nullif(trim(p_route->>'provider_model_id'),'');
  v_before jsonb;
  v_after jsonb;
begin
  if not exists(select 1 from public.users where user_id=p_actor_user_id and lower(coalesce(role::text,''))='admin') then raise exception 'actor must have the admin role'; end if;
  if not exists(select 1 from public.v2_models where model_slug=p_model_slug) then raise exception 'model not found'; end if;
  if v_provider_slug is null or not exists(select 1 from public.v2_providers where provider_slug=v_provider_slug) then raise exception 'provider not found'; end if;
  if v_provider_model_slug is null then raise exception 'provider_model_slug is required'; end if;
  if v_provider_model_id is null then
    v_provider_model_id := case when coalesce((p_route->>'is_stealth')::boolean,false) then 'stealth:'||gen_random_uuid()::text else v_provider_slug||':'||p_model_slug||':'||v_provider_model_slug end;
  end if;
  if coalesce((p_route->>'is_stealth')::boolean,false) and v_provider_model_id not like 'stealth:%' then
    raise exception 'A public route cannot be converted to stealth. Create a new stealth route to preserve its pricing and usage history.';
  end if;
  select to_jsonb(t) into v_before from public.v2_model_provider_routes t where provider_model_id=v_provider_model_id for update;
  if v_before is not null and v_before->>'model_slug'<>p_model_slug then raise exception 'provider route belongs to another model'; end if;
  perform set_config('phaseo.catalogue_actor',p_actor_user_id::text,true);
  insert into public.v2_model_provider_routes(
    provider_model_id,model_slug,provider_slug,provider_model_slug,status,
    provider_availability_status,phaseo_status,access_scope,routing_enabled,is_stealth,
    input_modalities,output_modalities,regions,context_length,max_output_tokens,
    effective_from,effective_to,metadata,updated_at
  ) values (
    v_provider_model_id,p_model_slug,v_provider_slug,v_provider_model_slug,
    coalesce(nullif(p_route->>'status',''),'active'),
    coalesce(nullif(p_route->>'provider_availability_status',''),'unknown'),
    coalesce(nullif(p_route->>'phaseo_status',''),'disabled'),
    coalesce(nullif(p_route->>'access_scope',''),'public'),
    coalesce((p_route->>'routing_enabled')::boolean,false),
    coalesce((p_route->>'is_stealth')::boolean,false),
    case when jsonb_typeof(p_route->'input_modalities')='array' then array(select jsonb_array_elements_text(p_route->'input_modalities')) else '{}'::text[] end,
    case when jsonb_typeof(p_route->'output_modalities')='array' then array(select jsonb_array_elements_text(p_route->'output_modalities')) else '{}'::text[] end,
    case when jsonb_typeof(p_route->'regions')='array' then array(select jsonb_array_elements_text(p_route->'regions')) else '{}'::text[] end,
    nullif(p_route->>'context_length','')::integer,nullif(p_route->>'max_output_tokens','')::integer,
    nullif(p_route->>'effective_from','')::timestamptz,nullif(p_route->>'effective_to','')::timestamptz,
    coalesce(p_route->'metadata','{}'::jsonb)||jsonb_build_object('source','admin'),now()
  ) on conflict(provider_model_id) do update set
    provider_slug=excluded.provider_slug,provider_model_slug=excluded.provider_model_slug,status=excluded.status,
    provider_availability_status=case when p_route ? 'provider_availability_status' then excluded.provider_availability_status else public.v2_model_provider_routes.provider_availability_status end,
    phaseo_status=case when p_route ? 'phaseo_status' then excluded.phaseo_status else public.v2_model_provider_routes.phaseo_status end,
    access_scope=case when p_route ? 'access_scope' then excluded.access_scope else public.v2_model_provider_routes.access_scope end,
    is_stealth=case when p_route ? 'is_stealth' then excluded.is_stealth else public.v2_model_provider_routes.is_stealth end,
    routing_enabled=excluded.routing_enabled,
    input_modalities=excluded.input_modalities,output_modalities=excluded.output_modalities,
    regions=excluded.regions,context_length=excluded.context_length,max_output_tokens=excluded.max_output_tokens,
    effective_from=excluded.effective_from,effective_to=excluded.effective_to,
    metadata=public.v2_model_provider_routes.metadata||excluded.metadata,updated_at=now();
  if exists(
    select 1 from public.v2_model_provider_routes t
    where t.provider_model_id=v_provider_model_id and t.routing_enabled
      and (t.phaseo_status <> 'enabled' or t.access_scope <> 'public'
        or t.provider_availability_status not in ('available','preview','limited_access'))
  ) then raise exception 'routing requires an enabled public route with available provider access'; end if;
  select to_jsonb(t) into v_after from public.v2_model_provider_routes t where provider_model_id=v_provider_model_id;
  insert into public.v2_catalogue_admin_changes(actor_user_id,resource_type,resource_id,action,before_state,after_state)
  values(p_actor_user_id,'provider_route',v_provider_model_id,case when v_before is null then 'create' else 'update' end,v_before,v_after);
  insert into public.v2_catalogue_source_overrides(source_type,source_key,disposition,actor_user_id,resource_id,updated_at)
  values('provider_route',v_provider_model_id,'database_managed',p_actor_user_id,v_provider_model_id,now())
  on conflict(source_type,source_key) do update set disposition='database_managed',actor_user_id=excluded.actor_user_id,resource_id=excluded.resource_id,updated_at=now();
  return v_after;
end $function$;

REVOKE ALL ON FUNCTION "public"."mutate_v2_admin_provider_route"(uuid, text, jsonb) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.mutate_v2_admin_registry (
  p_actor_user_id uuid,
  p_resource      text,
  p_values        jsonb,
  p_before        jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_table text; v_keys text[]; v_allowed text[]; v_identity jsonb; v_existing jsonb;
  v_columns text; v_select text; v_updates text; v_result jsonb;
begin
  if not exists(select 1 from public.users where user_id=p_actor_user_id and lower(coalesce(role::text,''))='admin') then raise exception 'actor must have the admin role'; end if;
  case p_resource
    when 'families' then v_table:='v2_model_families'; v_keys:=array['family_slug']; v_allowed:=array['family_slug','lab_slug','name','metadata'];
    when 'service-tiers' then v_table:='v2_service_tiers'; v_keys:=array['service_tier_slug']; v_allowed:=array['service_tier_slug','display_name','description','status','metadata'];
    when 'meters' then v_table:='v2_meter_definitions'; v_keys:=array['meter_key']; v_allowed:=array['meter_key','display_name','modality','direction','unit','default_unit_quantity','description','status','metadata'];
    when 'regions' then v_table:='v2_provider_regions'; v_keys:=array['provider_region_id']; v_allowed:=array['provider_region_id','provider_slug','region_code','display_name','execution_supported','data_residency_supported','status','routing_enabled','metadata'];
    when 'variants' then v_table:='v2_route_variants'; v_keys:=array['variant_id']; v_allowed:=array['variant_id','provider_model_id','variant_key','provider_region_id','execution_region','data_region','service_tier_slug','status','routing_enabled','endpoint_label','metadata'];
    when 'plans' then v_table:='v2_subscription_plans'; v_keys:=array['plan_uuid']; v_allowed:=array['plan_uuid','plan_id','name','lab_slug','description','frequency','price','currency','link','other_info','effective_to'];
    when 'plan-features' then v_table:='v2_subscription_plan_features'; v_keys:=array['plan_uuid','feature_name']; v_allowed:=array['plan_uuid','feature_name','feature_value','feature_description','other_info','effective_to'];
    else raise exception 'unknown registry';
  end case;
  if p_values is null or jsonb_typeof(p_values)<>'object' then raise exception 'record must be an object'; end if;
  if exists(select 1 from jsonb_object_keys(p_values) key where not key=any(v_allowed)) then raise exception 'unknown record field'; end if;
  if exists(select 1 from unnest(v_keys) key where nullif(p_values->>key,'') is null) then raise exception 'record identity required'; end if;
  select jsonb_object_agg(key,p_values->key) into v_identity from unnest(v_keys) key;
  if p_before is not null and not p_before @> v_identity then raise exception 'record identity cannot change'; end if;
  execute format('select to_jsonb(t) from public.%I t where to_jsonb(t) @> $1 for update',v_table) into v_existing using v_identity;
  if v_existing is distinct from p_before then raise exception 'Record changed. Reload before saving.'; end if;
  if p_resource='regions' and v_existing is not null and (p_values->>'provider_slug' is distinct from v_existing->>'provider_slug' or p_values->>'region_code' is distinct from v_existing->>'region_code') then raise exception 'provider region identity cannot change'; end if;
  if p_resource='variants' then
    if v_existing is not null and (p_values->>'provider_model_id' is distinct from v_existing->>'provider_model_id' or p_values->>'variant_key' is distinct from v_existing->>'variant_key') then raise exception 'route variant identity cannot change'; end if;
    if p_values->>'provider_region_id' is not null and not exists(select 1 from public.v2_provider_regions r join public.v2_model_provider_routes m on m.provider_slug=r.provider_slug where r.provider_region_id=(p_values->>'provider_region_id')::uuid and m.provider_model_id=p_values->>'provider_model_id') then raise exception 'region belongs to another provider'; end if;
  end if;
  if p_resource in ('regions','variants') and p_values->>'status' in ('disabled','retired','deprecated') then p_values:=p_values||jsonb_build_object('routing_enabled',false); end if;
  if p_resource<>'plan-features' then p_values:=p_values||jsonb_build_object('updated_at',now()); end if;
  perform set_config('phaseo.catalogue_actor',p_actor_user_id::text,true);
  select string_agg(format('%I',key),','), string_agg(format('(jsonb_populate_record(null::public.%I,$1)).%I',v_table,key),','), string_agg(format('%I=(jsonb_populate_record(null::public.%I,$1)).%I',key,v_table,key),',')
    into v_columns,v_select,v_updates from jsonb_object_keys(p_values) key;
  if v_existing is null then
    execute format('insert into public.%I (%s) select %s returning to_jsonb(%I.*)',v_table,v_columns,v_select,v_table) into v_result using p_values;
  else
    execute format('update public.%I t set %s where to_jsonb(t) @> $2 returning to_jsonb(t)',v_table,v_updates) into v_result using p_values,v_identity;
  end if;
  return v_result;
end $function$;

REVOKE ALL ON FUNCTION "public"."mutate_v2_admin_registry"(uuid, text, jsonb, jsonb) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.normalize_gateway_request_embedding_tokens()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
begin
  new.usage_embedding_tokens :=
    case
      when coalesce(new.endpoint, '') = 'embeddings' then
        public.gateway_usage_nonnegative_bigint(
          coalesce(
            public.gateway_usage_numeric_field(
              new.usage,
              'embedding_tokens',
              'input_tokens',
              'prompt_tokens',
              'total_tokens'
            ),
            new.usage_embedding_tokens,
            0
          )
        )
      else greatest(coalesce(new.usage_embedding_tokens, 0), 0)
    end;
  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."normalize_gateway_request_embedding_tokens"() FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.normalize_gateway_request_usage()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_usage jsonb := coalesce(new.usage, '{}'::jsonb);
  v_input_tokens bigint;
  v_output_tokens bigint;
  v_total_tokens bigint;
  v_reasoning_tokens bigint;
  v_input_image_tokens bigint;
  v_output_image_tokens bigint;
  v_input_audio_tokens bigint;
  v_output_audio_tokens bigint;
  v_input_video_tokens bigint;
  v_output_video_tokens bigint;
begin
  v_total_tokens := public.gateway_usage_total_tokens(v_usage);

  v_input_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'input_tokens',
      'prompt_tokens',
      'inputTokens',
      'promptTokens',
      'promptTokenCount',
      'total_input_tokens',
      'totalInputTokens'
    ), 0)
  );
  v_output_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'output_tokens',
      'completion_tokens',
      'outputTokens',
      'completionTokens',
      'candidatesTokenCount',
      'total_output_tokens',
      'totalOutputTokens'
    ), 0)
  );
  v_reasoning_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'reasoning_tokens',
      'reasoning_output_tokens',
      'output_reasoning_tokens',
      'completion_tokens_details.reasoning_tokens',
      'output_tokens_details.reasoning_tokens'
    ), 0)
  );
  v_input_image_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'input_image_tokens',
      'image_input_tokens',
      'prompt_image_tokens',
      'input_tokens_details.image_tokens',
      'prompt_tokens_details.image_tokens'
    ), 0)
  );
  v_output_image_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'output_image_tokens',
      'image_output_tokens',
      'generated_image_tokens',
      'completion_tokens_details.image_tokens',
      'output_tokens_details.image_tokens'
    ), 0)
  );
  v_input_audio_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'input_audio_tokens',
      'audio_input_tokens',
      'prompt_audio_tokens',
      'input_tokens_details.audio_tokens',
      'prompt_tokens_details.audio_tokens'
    ), 0)
  );
  v_output_audio_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'output_audio_tokens',
      'audio_output_tokens',
      'completion_tokens_details.audio_tokens',
      'output_tokens_details.audio_tokens'
    ), 0)
  );
  v_input_video_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'input_video_tokens',
      'video_input_tokens',
      'input_tokens_details.video_tokens',
      'prompt_tokens_details.video_tokens'
    ), 0)
  );
  v_output_video_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'output_video_tokens',
      'video_output_tokens',
      'completion_tokens_details.video_tokens',
      'output_tokens_details.video_tokens'
    ), 0)
  );

  if v_total_tokens < v_input_tokens + v_output_tokens + v_reasoning_tokens then
    v_total_tokens := v_input_tokens + v_output_tokens + v_reasoning_tokens;
  end if;

  new.usage_total_tokens := coalesce(v_total_tokens, 0);
  new.usage_input_tokens := v_input_tokens;
  new.usage_output_tokens := v_output_tokens;
  new.usage_reasoning_tokens := v_reasoning_tokens;
  new.usage_input_image_tokens := v_input_image_tokens;
  new.usage_output_image_tokens := v_output_image_tokens;
  new.usage_input_audio_tokens := v_input_audio_tokens;
  new.usage_output_audio_tokens := v_output_audio_tokens;
  new.usage_input_video_tokens := v_input_video_tokens;
  new.usage_output_video_tokens := v_output_video_tokens;
  new.usage_input_text_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(
      public.gateway_usage_numeric_field(v_usage, 'input_text_tokens', 'text_input_tokens'),
      greatest(v_input_tokens - v_input_image_tokens - v_input_audio_tokens - v_input_video_tokens, 0)
    )
  );
  new.usage_output_text_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(
      public.gateway_usage_numeric_field(v_usage, 'output_text_tokens', 'text_output_tokens'),
      greatest(v_output_tokens - v_output_image_tokens - v_output_audio_tokens - v_output_video_tokens - v_reasoning_tokens, 0)
    )
  );

  new.usage_image_inputs := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'input_image_count',
      'image_input_count',
      'image_inputs',
      'input_images'
    ), 0)
  );
  new.usage_image_outputs := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'output_image_count',
      'image_output_count',
      'image_outputs',
      'output_images',
      'generated_images',
      'image_count'
    ), 0)
  );
  new.usage_audio_inputs := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'input_audio_count',
      'audio_input_count',
      'audio_inputs',
      'input_audio'
    ), 0)
  );
  new.usage_audio_outputs := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'output_audio_count',
      'audio_output_count',
      'audio_outputs',
      'output_audio'
    ), 0)
  );
  new.usage_video_inputs := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'input_video_count',
      'video_input_count',
      'video_inputs',
      'input_videos'
    ), 0)
  );
  new.usage_video_outputs := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'output_video_count',
      'video_output_count',
      'video_outputs',
      'output_videos',
      'video_count'
    ), 0)
  );

  new.usage_cached_read_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'cached_read_tokens',
      'cache_read_input_tokens',
      'input_tokens_details.cached_tokens',
      'prompt_tokens_details.cached_tokens'
    ), 0)
  );
  new.usage_cached_write_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(
      v_usage,
      'cached_write_tokens',
      'cache_creation_input_tokens',
      'output_tokens_details.cached_tokens'
    ), 0)
  );
  new.usage_cached_read_text_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_read_text_tokens'), 0)
  );
  new.usage_cached_write_text_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(
      public.gateway_usage_numeric_field(v_usage, 'cached_write_text_tokens'),
      coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_write_text_tokens_5m', 'cache_creation.ephemeral_5m_input_tokens'), 0) +
        coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_write_text_tokens_1h', 'cache_creation.ephemeral_1h_input_tokens'), 0)
    )
  );
  new.usage_cached_write_text_tokens_5m := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_write_text_tokens_5m', 'cache_creation.ephemeral_5m_input_tokens'), 0)
  );
  new.usage_cached_write_text_tokens_1h := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_write_text_tokens_1h', 'cache_creation.ephemeral_1h_input_tokens'), 0)
  );
  new.usage_cached_read_image_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_read_image_tokens'), 0)
  );
  new.usage_cached_write_image_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_write_image_tokens'), 0)
  );
  new.usage_cached_read_audio_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_read_audio_tokens'), 0)
  );
  new.usage_cached_write_audio_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_write_audio_tokens'), 0)
  );
  new.usage_cached_read_video_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_read_video_tokens'), 0)
  );
  new.usage_cached_write_video_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'cached_write_video_tokens'), 0)
  );
  new.usage_input_quad_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'input_quad_tokens', 'quad_input_tokens'), new.usage_input_quad_tokens)
  );
  new.usage_output_quad_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'output_quad_tokens', 'quad_output_tokens'), new.usage_output_quad_tokens)
  );
  new.usage_total_quad_tokens := public.gateway_usage_nonnegative_bigint(
    greatest(
      coalesce(public.gateway_usage_numeric_field(v_usage, 'total_quad_tokens', 'quad_total_tokens'), new.usage_total_quad_tokens),
      new.usage_input_quad_tokens + new.usage_output_quad_tokens
    )
  );
  new.usage_text_quad_tokens := public.gateway_usage_nonnegative_bigint(
    greatest(
      coalesce(public.gateway_usage_numeric_field(v_usage, 'text_quad_tokens'), new.usage_text_quad_tokens),
      new.usage_total_quad_tokens
    )
  );
  new.usage_rerank_quad_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'rerank_quad_tokens'), new.usage_rerank_quad_tokens)
  );
  new.usage_embedding_quad_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'embedding_quad_tokens'), new.usage_embedding_quad_tokens)
  );
  new.usage_moderation_quad_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'moderation_quad_tokens'), new.usage_moderation_quad_tokens)
  );
  new.usage_ocr_quad_tokens := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'ocr_quad_tokens'), new.usage_ocr_quad_tokens)
  );
  new.usage_image_megapixels := greatest(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'image_megapixels'), new.usage_image_megapixels),
    0
  );
  new.usage_audio_seconds := greatest(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'audio_seconds'), new.usage_audio_seconds),
    0
  );
  new.usage_video_pixel_seconds := greatest(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'video_pixel_seconds'), new.usage_video_pixel_seconds),
    0
  );
  new.usage_input_characters := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'input_characters', 'input_chars'), new.usage_input_characters)
  );
  new.usage_output_characters := public.gateway_usage_nonnegative_bigint(
    coalesce(public.gateway_usage_numeric_field(v_usage, 'output_characters', 'output_chars'), new.usage_output_characters)
  );
  new.usage_total_characters := public.gateway_usage_nonnegative_bigint(
    greatest(
      coalesce(public.gateway_usage_numeric_field(v_usage, 'total_characters', 'total_chars'), new.usage_total_characters),
      new.usage_input_characters + new.usage_output_characters
    )
  );
  new.usage_normalized_at := now();

  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."normalize_gateway_request_usage"() FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.normalize_gateway_request_video_seconds()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
begin
  new.usage_video_seconds := greatest(
    coalesce(
      public.gateway_usage_numeric_field(
        new.usage,
        'video_seconds',
        'input_video_seconds',
        'output_video_seconds'
      ),
      new.usage_video_seconds,
      0
    ),
    0
  );
  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."normalize_gateway_request_video_seconds"() FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.normalize_v2_service_tier (
  p_value text
)
  RETURNS text
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  select case lower(nullif(trim(p_value), ''))
    when 'default' then 'standard'
    when 'fast' then 'priority'
    when 'priority' then 'priority'
    when 'standard' then 'standard'
    when 'ultrafast' then 'ultrafast'
    when 'flex' then 'flex'
    when 'batch' then 'batch'
    else null
  end;
$function$;

REVOKE ALL ON FUNCTION "public"."normalize_v2_service_tier"(text) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.prepare_preset_lineage()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare source_row public.presets%rowtype;
begin
  if new.source_preset_id is null then
    new.root_preset_id := new.id;
    new.fork_depth := 0;
    return new;
  end if;
  select * into source_row from public.presets where id = new.source_preset_id;
  if not found then raise exception 'source_preset_not_found'; end if;
  new.root_preset_id := coalesce(source_row.root_preset_id, source_row.id);
  new.fork_depth := source_row.fork_depth + 1;
  new.source_preset_version_id := coalesce(new.source_preset_version_id, source_row.active_version_id);
  new.upstream_version_id := coalesce(new.upstream_version_id, source_row.active_version_id);
  return new;
end $function$;

REVOKE ALL ON FUNCTION "public"."prepare_preset_lineage"() FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.prevent_catalogue_removal()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
begin raise exception 'saved catalogue records cannot be deleted; set an end date instead'; end $function$;

REVOKE ALL ON FUNCTION "public"."prevent_catalogue_removal"() FROM PUBLIC, "anon", "authenticated", "service_role";

CREATE OR REPLACE FUNCTION public.prevent_published_control_plane_release_mutation()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO 'public'
  AS $function$
begin
  if old.published_once_at is not null then
    if tg_op = 'UPDATE'
      and new.status = 'superseded'
      and new.superseded_at is not null
      and (to_jsonb(new) - 'status' - 'superseded_at') =
        (to_jsonb(old) - 'status' - 'superseded_at') then
      return new;
    end if;
    raise exception 'Published control-plane releases are immutable';
  end if;
  if tg_op = 'UPDATE' and new.status = 'published' then
    new.published_once_at := coalesce(new.published_once_at, new.published_at, now());
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."prevent_published_control_plane_release_mutation"() FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.prevent_published_execution_plan_mutation()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO 'public'
  AS $function$
declare
  old_release_published_at timestamptz;
  new_release_published_at timestamptz;
begin
  if tg_op in ('UPDATE', 'DELETE') then
    select published_once_at into old_release_published_at
      from public.v2_control_plane_releases where release_id = old.release_id;
    if old_release_published_at is not null then
      raise exception 'Execution plans in published releases are immutable';
    end if;
  end if;

  if tg_op in ('INSERT', 'UPDATE') then
    select published_once_at into new_release_published_at
      from public.v2_control_plane_releases where release_id = new.release_id;
    if new_release_published_at is not null then
      raise exception 'Execution plans in published releases are immutable';
    end if;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."prevent_published_execution_plan_mutation"() FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.prevent_reserved_workspace_publisher_handle()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
begin
  new.publisher_handle := lower(trim(new.publisher_handle));
  if exists (
    select 1 from public.workspace_publisher_handle_aliases alias
    where alias.handle = new.publisher_handle
      and alias.workspace_id <> new.id
  ) then
    raise exception 'publisher_handle_reserved' using errcode = '23505';
  end if;
  return new;
end
$function$;

REVOKE ALL ON FUNCTION "public"."prevent_reserved_workspace_publisher_handle"() FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.process_v2_analytics_outbox (
  p_limit integer DEFAULT 250
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_limit integer := greatest(1, least(coalesce(p_limit, 250), 2000));
  v_selected integer := 0;
  v_private_grains integer := 0;
  v_public_daily_grains integer := 0;
  v_public_hourly_grains integer := 0;
  v_rollup_id uuid;
  grain record;
begin
  create temporary table if not exists pg_temp.v2_rollup_batch (
    request_event_id uuid primary key,
    workspace_id uuid not null,
    occurred_at timestamptz not null,
    app_id uuid,
    model_slug text,
    provider_model_id text,
    cloudflare_colo text
  ) on commit drop;
  truncate table pg_temp.v2_rollup_batch;

  insert into pg_temp.v2_rollup_batch (
    request_event_id, workspace_id, occurred_at, app_id, model_slug,
    provider_model_id, cloudflare_colo
  )
  select
    outbox.request_event_id,
    fact.workspace_id,
    fact.occurred_at,
    fact.app_id,
    coalesce(fact.routed_model_slug, fact.requested_model_slug),
    fact.provider_model_id,
    fact.cloudflare_colo
  from public.v2_analytics_outbox outbox
  join public.v2_request_facts fact on fact.request_event_id = outbox.request_event_id
  where outbox.status in ('pending', 'failed')
    and outbox.available_at <= now()
  order by outbox.occurred_at, outbox.request_event_id
  for update of outbox skip locked
  limit case when exists(select 1 from private.v2_analytics_previous_grains)
    then greatest(0,v_limit-least(5,v_limit)) else v_limit end;


  get diagnostics v_selected = row_count;
  create temporary table if not exists pg_temp.v2_previous_grain_batch
    (like private.v2_analytics_previous_grains including defaults) on commit drop;
  truncate table pg_temp.v2_previous_grain_batch;
  alter table pg_temp.v2_previous_grain_batch add column if not exists transaction_id bigint;
  insert into pg_temp.v2_previous_grain_batch(grain_id,workspace_id,occurred_at,app_id,model_slug,provider_model_id,cloudflare_colo,queued_at,transaction_id)
  select previous.* from private.v2_analytics_previous_grains previous
  order by previous.queued_at,previous.grain_id for update skip locked limit greatest(0,v_limit-v_selected);
  insert into pg_temp.v2_rollup_batch
    (request_event_id,workspace_id,occurred_at,app_id,model_slug,provider_model_id,cloudflare_colo)
  select grain_id,workspace_id,occurred_at,app_id,model_slug,provider_model_id,cloudflare_colo
  from pg_temp.v2_previous_grain_batch;
  v_selected := v_selected + (select count(*) from pg_temp.v2_previous_grain_batch);

  if v_selected = 0 then
    return jsonb_build_object(
      'selected', 0,
      'private_grains', 0,
      'public_daily_grains', 0,
      'public_hourly_grains', 0
    );
  end if;

  update public.v2_analytics_outbox outbox
  set status = 'processing', updated_at = now()
  where outbox.request_event_id in (select batch.request_event_id from pg_temp.v2_rollup_batch batch);

  for grain in
    select distinct
      batch.workspace_id,
      batch.occurred_at::date as usage_date,
      batch.app_id,
      batch.model_slug,
      batch.provider_model_id,
      batch.cloudflare_colo
    from pg_temp.v2_rollup_batch batch
    where batch.model_slug is not null
  loop
    delete from public.v2_private_usage_daily rollup
    where rollup.workspace_id = grain.workspace_id
      and rollup.usage_date = grain.usage_date
      and rollup.app_id is not distinct from grain.app_id
      and rollup.model_slug = grain.model_slug
      and rollup.provider_model_id is not distinct from grain.provider_model_id
      and rollup.cloudflare_colo is not distinct from grain.cloudflare_colo;

    insert into public.v2_private_usage_daily (
      usage_date, workspace_id, app_id, model_slug, provider_model_id, cloudflare_colo,
      requests, successful_requests, failed_requests, rate_limited_requests,
      tool_call_count, tool_call_requests, tool_call_successes,
      structured_output_attempts, structured_output_successes,
      latency_sum_ms, latency_count, generation_sum_ms, generation_count,
      throughput_sum, throughput_count, gateway_total_sum_ms, gateway_total_count,
      internal_dispatch_sum_ms, internal_dispatch_count,
      upstream_attempts, failed_upstream_attempts, cached_input_tokens, input_tokens, cost_nanos
    )
    select
      grain.usage_date, grain.workspace_id, grain.app_id, grain.model_slug,
      grain.provider_model_id, grain.cloudflare_colo,
      count(*), count(*) filter (where fact.success), count(*) filter (where not fact.success),
      count(*) filter (where fact.status_code = 429),
      coalesce(sum(fact.tool_call_count), 0),
      count(*) filter (where fact.tool_call_count > 0),
      count(*) filter (where fact.tool_call_count > 0 and fact.tool_call_succeeded is true),
      count(*) filter (where fact.structured_output_attempted),
      count(*) filter (where fact.structured_output_attempted and fact.structured_output_succeeded),
      coalesce(sum(fact.latency_ms), 0), count(fact.latency_ms),
      coalesce(sum(fact.generation_ms), 0), count(fact.generation_ms),
      coalesce(sum(fact.throughput), 0), count(fact.throughput),
      coalesce(sum(fact.gateway_total_ms), 0), count(fact.gateway_total_ms),
      coalesce(sum(fact.internal_dispatch_ms), 0), count(fact.internal_dispatch_ms),
      coalesce(sum(attempts.attempts), 0), coalesce(sum(attempts.failed_attempts), 0),
      coalesce(sum(usage.cached_input_tokens), 0), coalesce(sum(usage.input_tokens), 0),
      coalesce(sum(fact.cost_nanos), 0)
    from public.v2_request_facts fact
    left join lateral (
      select count(*)::bigint as attempts,
        count(*) filter (where not attempt.success)::bigint as failed_attempts
      from public.v2_request_attempts attempt
      where attempt.request_event_id = fact.request_event_id
    ) attempts on true
    left join lateral (
      select
        coalesce(sum(meter.quantity) filter (where meter.meter_key = 'cached_input_tokens'), 0) as cached_input_tokens,
        coalesce(sum(meter.quantity) filter (where meter.meter_key = 'input_tokens'), 0) as input_tokens
      from public.v2_request_usage meter
      where meter.request_event_id = fact.request_event_id
    ) usage on true
    where fact.workspace_id = grain.workspace_id
      and fact.occurred_at >= grain.usage_date::timestamptz
      and fact.occurred_at < (grain.usage_date + 1)::timestamptz
      and fact.app_id is not distinct from grain.app_id
      and coalesce(fact.routed_model_slug, fact.requested_model_slug) = grain.model_slug
      and fact.provider_model_id is not distinct from grain.provider_model_id
      and fact.cloudflare_colo is not distinct from grain.cloudflare_colo
    having count(*) > 0
    returning rollup_id into v_rollup_id;

    insert into public.v2_private_usage_daily_meters (
      rollup_id, meter_key, modality, unit, quantity
    )
    select v_rollup_id, meter.meter_key, meter.modality, meter.unit, sum(meter.quantity)
    from public.v2_request_usage meter
    join public.v2_request_facts fact on fact.request_event_id = meter.request_event_id
    where fact.workspace_id = grain.workspace_id
      and fact.occurred_at >= grain.usage_date::timestamptz
      and fact.occurred_at < (grain.usage_date + 1)::timestamptz
      and fact.app_id is not distinct from grain.app_id
      and coalesce(fact.routed_model_slug, fact.requested_model_slug) = grain.model_slug
      and fact.provider_model_id is not distinct from grain.provider_model_id
      and fact.cloudflare_colo is not distinct from grain.cloudflare_colo
    group by meter.meter_key, meter.modality, meter.unit;

    v_private_grains := v_private_grains + 1;
  end loop;

  for grain in
    select distinct
      batch.occurred_at::date as usage_date,
      batch.app_id,
      batch.model_slug,
      batch.provider_model_id,
      batch.cloudflare_colo
    from pg_temp.v2_rollup_batch batch
    where batch.model_slug is not null
  loop
    delete from public.v2_public_usage_daily rollup
    where rollup.usage_date = grain.usage_date
      and rollup.app_id is not distinct from grain.app_id
      and rollup.model_slug = grain.model_slug
      and rollup.provider_model_id is not distinct from grain.provider_model_id
      and rollup.cloudflare_colo is not distinct from grain.cloudflare_colo;

    insert into public.v2_public_usage_daily (
      usage_date, app_id, model_slug, provider_model_id, cloudflare_colo,
      requests, successful_requests, failed_requests, rate_limited_requests,
      tool_call_count, tool_call_requests, tool_call_successes,
      structured_output_attempts, structured_output_successes,
      latency_sum_ms, latency_count, generation_sum_ms, generation_count,
      throughput_sum, throughput_count, gateway_total_sum_ms, gateway_total_count,
      internal_dispatch_sum_ms, internal_dispatch_count,
      upstream_attempts, failed_upstream_attempts, cached_input_tokens, input_tokens, cost_nanos
    )
    select
      grain.usage_date, grain.app_id, grain.model_slug, grain.provider_model_id, grain.cloudflare_colo,
      count(*), count(*) filter (where fact.success), count(*) filter (where not fact.success),
      count(*) filter (where fact.status_code = 429),
      coalesce(sum(fact.tool_call_count), 0),
      count(*) filter (where fact.tool_call_count > 0),
      count(*) filter (where fact.tool_call_count > 0 and fact.tool_call_succeeded is true),
      count(*) filter (where fact.structured_output_attempted),
      count(*) filter (where fact.structured_output_attempted and fact.structured_output_succeeded),
      coalesce(sum(fact.latency_ms), 0), count(fact.latency_ms),
      coalesce(sum(fact.generation_ms), 0), count(fact.generation_ms),
      coalesce(sum(fact.throughput), 0), count(fact.throughput),
      coalesce(sum(fact.gateway_total_ms), 0), count(fact.gateway_total_ms),
      coalesce(sum(fact.internal_dispatch_ms), 0), count(fact.internal_dispatch_ms),
      coalesce(sum(attempts.attempts), 0), coalesce(sum(attempts.failed_attempts), 0),
      coalesce(sum(usage.cached_input_tokens), 0), coalesce(sum(usage.input_tokens), 0),
      coalesce(sum(fact.cost_nanos), 0)
    from public.v2_request_facts fact
    left join lateral (
      select count(*)::bigint as attempts,
        count(*) filter (where not attempt.success)::bigint as failed_attempts
      from public.v2_request_attempts attempt
      where attempt.request_event_id = fact.request_event_id
    ) attempts on true
    left join lateral (
      select
        coalesce(sum(meter.quantity) filter (where meter.meter_key = 'cached_input_tokens'), 0) as cached_input_tokens,
        coalesce(sum(meter.quantity) filter (where meter.meter_key = 'input_tokens'), 0) as input_tokens
      from public.v2_request_usage meter
      where meter.request_event_id = fact.request_event_id
    ) usage on true
    where fact.occurred_at >= grain.usage_date::timestamptz
      and fact.occurred_at < (grain.usage_date + 1)::timestamptz
      and fact.app_id is not distinct from grain.app_id
      and coalesce(fact.routed_model_slug, fact.requested_model_slug) = grain.model_slug
      and fact.provider_model_id is not distinct from grain.provider_model_id
      and fact.cloudflare_colo is not distinct from grain.cloudflare_colo
    having count(*) > 0
    returning rollup_id into v_rollup_id;

    insert into public.v2_public_usage_daily_meters (
      rollup_id, meter_key, modality, unit, quantity
    )
    select v_rollup_id, meter.meter_key, meter.modality, meter.unit, sum(meter.quantity)
    from public.v2_request_usage meter
    join public.v2_request_facts fact on fact.request_event_id = meter.request_event_id
    where fact.occurred_at >= grain.usage_date::timestamptz
      and fact.occurred_at < (grain.usage_date + 1)::timestamptz
      and fact.app_id is not distinct from grain.app_id
      and coalesce(fact.routed_model_slug, fact.requested_model_slug) = grain.model_slug
      and fact.provider_model_id is not distinct from grain.provider_model_id
      and fact.cloudflare_colo is not distinct from grain.cloudflare_colo
    group by meter.meter_key, meter.modality, meter.unit;

    v_public_daily_grains := v_public_daily_grains + 1;
  end loop;

  for grain in
    select distinct
      date_trunc('hour', batch.occurred_at) as bucket_start,
      batch.app_id,
      batch.model_slug,
      batch.provider_model_id,
      batch.cloudflare_colo
    from pg_temp.v2_rollup_batch batch
    where batch.model_slug is not null
  loop
    delete from public.v2_public_usage_hourly rollup
    where rollup.bucket_start = grain.bucket_start
      and rollup.app_id is not distinct from grain.app_id
      and rollup.model_slug = grain.model_slug
      and rollup.provider_model_id is not distinct from grain.provider_model_id
      and rollup.cloudflare_colo is not distinct from grain.cloudflare_colo;

    insert into public.v2_public_usage_hourly (
      bucket_start, app_id, model_slug, provider_model_id, cloudflare_colo,
      requests, successful_requests, failed_requests, rate_limited_requests,
      tool_call_count, tool_call_requests, tool_call_successes,
      structured_output_attempts, structured_output_successes,
      latency_sum_ms, latency_count, generation_sum_ms, generation_count,
      throughput_sum, throughput_count, gateway_total_sum_ms, gateway_total_count,
      internal_dispatch_sum_ms, internal_dispatch_count,
      upstream_attempts, failed_upstream_attempts, cached_input_tokens, input_tokens, cost_nanos
    )
    select
      grain.bucket_start, grain.app_id, grain.model_slug, grain.provider_model_id, grain.cloudflare_colo,
      count(*), count(*) filter (where fact.success), count(*) filter (where not fact.success),
      count(*) filter (where fact.status_code = 429),
      coalesce(sum(fact.tool_call_count), 0),
      count(*) filter (where fact.tool_call_count > 0),
      count(*) filter (where fact.tool_call_count > 0 and fact.tool_call_succeeded is true),
      count(*) filter (where fact.structured_output_attempted),
      count(*) filter (where fact.structured_output_attempted and fact.structured_output_succeeded),
      coalesce(sum(fact.latency_ms), 0), count(fact.latency_ms),
      coalesce(sum(fact.generation_ms), 0), count(fact.generation_ms),
      coalesce(sum(fact.throughput), 0), count(fact.throughput),
      coalesce(sum(fact.gateway_total_ms), 0), count(fact.gateway_total_ms),
      coalesce(sum(fact.internal_dispatch_ms), 0), count(fact.internal_dispatch_ms),
      coalesce(sum(attempts.attempts), 0), coalesce(sum(attempts.failed_attempts), 0),
      coalesce(sum(usage.cached_input_tokens), 0), coalesce(sum(usage.input_tokens), 0),
      coalesce(sum(fact.cost_nanos), 0)
    from public.v2_request_facts fact
    left join lateral (
      select count(*)::bigint as attempts,
        count(*) filter (where not attempt.success)::bigint as failed_attempts
      from public.v2_request_attempts attempt
      where attempt.request_event_id = fact.request_event_id
    ) attempts on true
    left join lateral (
      select
        coalesce(sum(meter.quantity) filter (where meter.meter_key = 'cached_input_tokens'), 0) as cached_input_tokens,
        coalesce(sum(meter.quantity) filter (where meter.meter_key = 'input_tokens'), 0) as input_tokens
      from public.v2_request_usage meter
      where meter.request_event_id = fact.request_event_id
    ) usage on true
    where fact.occurred_at >= grain.bucket_start
      and fact.occurred_at < grain.bucket_start + interval '1 hour'
      and fact.app_id is not distinct from grain.app_id
      and coalesce(fact.routed_model_slug, fact.requested_model_slug) = grain.model_slug
      and fact.provider_model_id is not distinct from grain.provider_model_id
      and fact.cloudflare_colo is not distinct from grain.cloudflare_colo
    having count(*) > 0
    returning rollup_id into v_rollup_id;

    insert into public.v2_public_usage_hourly_meters (
      rollup_id, meter_key, modality, unit, quantity
    )
    select v_rollup_id, meter.meter_key, meter.modality, meter.unit, sum(meter.quantity)
    from public.v2_request_usage meter
    join public.v2_request_facts fact on fact.request_event_id = meter.request_event_id
    where fact.occurred_at >= grain.bucket_start
      and fact.occurred_at < grain.bucket_start + interval '1 hour'
      and fact.app_id is not distinct from grain.app_id
      and coalesce(fact.routed_model_slug, fact.requested_model_slug) = grain.model_slug
      and fact.provider_model_id is not distinct from grain.provider_model_id
      and fact.cloudflare_colo is not distinct from grain.cloudflare_colo
    group by meter.meter_key, meter.modality, meter.unit;

    v_public_hourly_grains := v_public_hourly_grains + 1;
  end loop;

  insert into public.v2_rollup_refresh_state (
    rollup_name, bucket_start, last_started_at, last_completed_at, source_watermark, status, error_message, updated_at
  )
  select 'private_daily', date_trunc('day', batch.occurred_at), now(), now(), max(batch.occurred_at), 'complete', null, now()
  from pg_temp.v2_rollup_batch batch
  group by date_trunc('day', batch.occurred_at)
  on conflict (rollup_name, bucket_start) do update set
    last_started_at = excluded.last_started_at,
    last_completed_at = excluded.last_completed_at,
    source_watermark = excluded.source_watermark,
    status = excluded.status,
    error_message = null,
    updated_at = now();

  insert into public.v2_rollup_refresh_state (
    rollup_name, bucket_start, last_started_at, last_completed_at, source_watermark, status, error_message, updated_at
  )
  select 'public_hourly', date_trunc('hour', batch.occurred_at), now(), now(), max(batch.occurred_at), 'complete', null, now()
  from pg_temp.v2_rollup_batch batch
  group by date_trunc('hour', batch.occurred_at)
  on conflict (rollup_name, bucket_start) do update set
    last_started_at = excluded.last_started_at,
    last_completed_at = excluded.last_completed_at,
    source_watermark = excluded.source_watermark,
    status = excluded.status,
    error_message = null,
    updated_at = now();

  update public.v2_analytics_outbox outbox
  set status = 'complete', last_error = null, updated_at = now()
  where outbox.request_event_id in (select batch.request_event_id from pg_temp.v2_rollup_batch batch);


  delete from private.v2_analytics_previous_grains
  where grain_id in (select grain_id from pg_temp.v2_previous_grain_batch);
  return jsonb_build_object(
    'selected', v_selected,
    'private_grains', v_private_grains,
    'public_daily_grains', v_public_daily_grains,
    'public_hourly_grains', v_public_hourly_grains
  );
end;
$function$;

REVOKE ALL ON FUNCTION "public"."process_v2_analytics_outbox"(integer) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.promote_provider_catalog_candidate (
  p_run_id               uuid,
  p_submitted_model_slug text
)
  RETURNS text
  LANGUAGE plpgsql
  SET search_path TO 'public'
  AS $function$
declare
  candidate public.provider_catalog_route_candidates%rowtype;
  provider_model_id_value text;
  capability jsonb;
  price jsonb;
  sku_id_value uuid;
  sku_version_value integer;
  variant_id_value uuid;
  route_status text;
  provider_availability text;
  phaseo_status_value text;
  access_scope_value text;
  route_enabled boolean;
  release_due boolean;
begin
  select * into candidate from public.provider_catalog_route_candidates
  where run_id = p_run_id and submitted_model_slug = p_submitted_model_slug for update;
  if not found then raise exception 'provider_catalog_candidate_not_found'; end if;
  if candidate.status <> 'probe_passed' then raise exception 'provider_catalog_probe_required'; end if;
  if exists (
    select 1 from public.provider_catalog_sync_runs newer
    join public.provider_catalog_sync_runs current_run on current_run.id = candidate.run_id
    where newer.provider_slug = candidate.provider_slug and newer.status = 'applied'
      and newer.created_at > current_run.created_at
  ) then raise exception 'provider_catalog_candidate_superseded'; end if;
  if jsonb_array_length(candidate.pricing) = 0 then raise exception 'provider_catalog_pricing_required'; end if;
  if not coalesce((select (metadata ->> 'adapter_ready')::boolean from public.v2_providers where provider_slug = candidate.provider_slug), false) then raise exception 'provider_catalog_adapter_required'; end if;
  if not coalesce((select (metadata ->> 'credentials_ready')::boolean from public.v2_providers where provider_slug = candidate.provider_slug), false) then raise exception 'provider_catalog_credentials_required'; end if;
  if not exists (select 1 from public.v2_providers where provider_slug = candidate.provider_slug and nullif(trim(base_url), '') is not null) then raise exception 'provider_catalog_endpoint_required'; end if;

  select provider_model_id into provider_model_id_value
  from public.v2_model_provider_routes
  where provider_slug = candidate.provider_slug
    and model_slug = candidate.canonical_model_slug
    and provider_model_slug = candidate.provider_model_slug
  order by created_at limit 1;
  if provider_model_id_value is null then
    provider_model_id_value := candidate.provider_slug || ':' || candidate.canonical_model_slug || ':' || candidate.provider_model_slug;
  end if;

  release_due := (candidate.available_from is null or candidate.available_from <= now())
    and (candidate.shutdown_at is null or candidate.shutdown_at > now());

  route_status := case
    when not release_due and candidate.availability in ('ready', 'degraded') then 'disabled'
    when candidate.availability = 'ready' then 'active'
    when candidate.availability = 'degraded' then 'degraded'
    when candidate.availability = 'retired' then 'disabled'
    else 'disabled'
  end;
  provider_availability := case
    when candidate.availability = 'ready' and release_due then 'available'
    when candidate.availability = 'degraded' and release_due then 'preview'
    when candidate.availability = 'deprecated' then 'deprecated'
    when candidate.availability = 'retired' then 'removed'
    else 'coming_soon'
  end;
  phaseo_status_value := case
    when candidate.availability in ('ready', 'degraded') and release_due then 'enabled'
    when candidate.availability = 'deprecated' then 'disabled'
    when candidate.availability = 'retired' then 'disabled'
    else 'testing'
  end;
  access_scope_value := case when candidate.availability in ('ready', 'degraded') and release_due then 'public' else 'internal' end;
  route_enabled := candidate.availability in ('ready', 'degraded') and release_due
    and exists (
      select 1 from public.v2_providers p
      where p.provider_slug = candidate.provider_slug
        and (
          (
            p.metadata ? 'self_serve'
            and p.metadata -> 'self_serve' ->> 'provider_review_status' = 'approved'
            and (p.status = 'not_ready' or (p.status <> 'disabled' and p.routable and p.routing_enabled))
          )
          or (
            not (p.metadata ? 'self_serve')
            and (p.status = 'not_ready' or (p.status <> 'disabled' and p.routable and p.routing_enabled))
          )
        )
    )
    and not exists (select 1 from public.v2_model_provider_routes r
      where r.model_slug = candidate.canonical_model_slug and r.is_stealth);
  if not route_enabled then
    route_status := 'disabled';
    phaseo_status_value := 'testing';
    access_scope_value := 'internal';
  end if;

  insert into public.v2_model_provider_routes (
    provider_model_id, model_slug, provider_slug, provider_model_slug, status,
    routing_enabled, provider_availability_status, phaseo_status, access_scope,
    input_modalities, output_modalities, context_length, max_output_tokens,
    effective_from, effective_to, metadata, updated_at
  ) values (
    provider_model_id_value, candidate.canonical_model_slug, candidate.provider_slug,
    candidate.provider_model_slug, route_status, route_enabled,
    provider_availability, phaseo_status_value, access_scope_value,
    candidate.input_modalities, candidate.output_modalities, candidate.context_length,
    candidate.max_output_tokens, candidate.available_from, candidate.shutdown_at,
    jsonb_build_object(
      'managed_by', 'provider_catalog',
      'source_run_id', candidate.run_id,
      'deprecated_at', candidate.deprecated_at,
      'release_scheduled', not release_due and candidate.availability in ('ready', 'degraded'),
      'release_at', candidate.available_from
    ), now()
  )
  on conflict (provider_model_id) do update set
    provider_model_slug = excluded.provider_model_slug, status = excluded.status,
    routing_enabled = excluded.routing_enabled,
    provider_availability_status = excluded.provider_availability_status,
    phaseo_status = excluded.phaseo_status, access_scope = excluded.access_scope,
    input_modalities = excluded.input_modalities, output_modalities = excluded.output_modalities,
    context_length = excluded.context_length, max_output_tokens = excluded.max_output_tokens,
    effective_from = excluded.effective_from, effective_to = excluded.effective_to,
    metadata = public.v2_model_provider_routes.metadata || excluded.metadata, updated_at = now();

  update public.v2_route_capabilities set status = 'disabled', updated_at = now()
  where provider_model_id = provider_model_id_value;

  for capability in select value from jsonb_array_elements(candidate.capabilities)
  loop
    insert into public.v2_route_capabilities (
      provider_model_id, capability_id, status, max_output_tokens, params,
      effective_from, effective_to, metadata, updated_at
    ) values (
      provider_model_id_value, capability ->> 'id',
      case when route_enabled and candidate.availability = 'ready' then 'active'
           when route_enabled and candidate.availability = 'degraded' then 'degraded'
           when candidate.availability in ('deprecated', 'retired') then 'disabled'
           else 'internal_testing' end,
      candidate.max_output_tokens,
      coalesce((select jsonb_object_agg(p.value, true) from jsonb_array_elements_text(coalesce(capability -> 'parameters', '[]'::jsonb)) as p(value)), '{}'::jsonb),
      candidate.available_from, candidate.shutdown_at,
      jsonb_build_object('managed_by', 'provider_catalog', 'source_run_id', candidate.run_id), now()
    )
    on conflict (provider_model_id, capability_id) do update set
      status = excluded.status, max_output_tokens = excluded.max_output_tokens,
      params = excluded.params, effective_from = excluded.effective_from,
      effective_to = excluded.effective_to,
      metadata = public.v2_route_capabilities.metadata || excluded.metadata, updated_at = now();
  end loop;

  insert into public.v2_route_variants (
    provider_model_id, variant_key, service_tier_slug, status,
    routing_enabled, endpoint_label, metadata, updated_at
  ) values (
    provider_model_id_value, 'global:standard', 'standard',
    case when route_enabled then route_status else 'disabled' end,
    route_enabled, 'Standard',
    jsonb_build_object('managed_by', 'provider_catalog', 'source_run_id', candidate.run_id), now()
  )
  on conflict (provider_model_id, variant_key) do update set
    service_tier_slug = excluded.service_tier_slug,
    status = excluded.status,
    routing_enabled = excluded.routing_enabled,
    endpoint_label = excluded.endpoint_label,
    metadata = public.v2_route_variants.metadata || excluded.metadata,
    updated_at = now()
  returning variant_id into variant_id_value;

  update public.v2_pricing_skus
  set status = 'deprecated', effective_to = now(), updated_at = now()
  where provider_model_id = provider_model_id_value
    and sku_code = 'provider-catalog-standard' and status = 'active';
  select coalesce(max(version), 0) + 1 into sku_version_value
  from public.v2_pricing_skus
  where provider_model_id = provider_model_id_value and sku_code = 'provider-catalog-standard';
  insert into public.v2_pricing_skus (
    provider_model_id, route_variant_id, service_tier_slug, sku_code, version, operation, status, display_name,
    currency, effective_from, metadata
  ) values (
    provider_model_id_value, variant_id_value, 'standard', 'provider-catalog-standard', sku_version_value,
    'inference', 'active', 'Provider catalog pricing', 'USD', coalesce(candidate.available_from, now()),
    jsonb_build_object('managed_by', 'provider_catalog', 'source_run_id', candidate.run_id, 'release_scheduled', not release_due)
  ) returning sku_id into sku_id_value;
  for price in select value from jsonb_array_elements(candidate.pricing)
  loop
    insert into public.v2_pricing_sku_meters (
      sku_id, meter_key, modality, direction, unit, unit_quantity,
      price_nanos, display_label, display_unit, metadata
    ) values (
      sku_id_value, price ->> 'meterKey', price ->> 'modality', nullif(price ->> 'direction', ''),
      price ->> 'unit', (price ->> 'unitQuantity')::numeric,
      (price ->> 'priceNanos')::numeric, price ->> 'displayLabel', price ->> 'displayUnit',
      jsonb_build_object('managed_by', 'provider_catalog', 'source_run_id', candidate.run_id)
    );
  end loop;

  update public.v2_providers
  set status = case
        when route_enabled
          and (status = 'not_ready' or (status = 'disabled' and metadata -> 'self_serve' ->> 'status' = 'submitted'))
          then 'beta'
        else status
      end,
      routable = case when route_enabled then true else routable end,
      routing_enabled = case when route_enabled then true else routing_enabled end,
      updated_at = now()
  where provider_slug = candidate.provider_slug;

  if route_enabled then
    update public.v2_models
    set hidden = false,
        released_at = coalesce(released_at, coalesce(candidate.available_from, now())),
        updated_at = now()
    where model_slug = candidate.canonical_model_slug
      and metadata ->> 'created_from_provider_proposal' = 'true'
      and not exists (select 1 from public.v2_model_provider_routes r where r.model_slug = candidate.canonical_model_slug and r.is_stealth);

    update public.v2_labs lab
    set status = case when lab.status = 'disabled' then 'active' else lab.status end,
        updated_at = now()
    where lab.lab_slug = (select model.lab_slug from public.v2_models model where model.model_slug = candidate.canonical_model_slug)
      and lab.metadata ->> 'created_from_provider_proposal' = 'true';
  end if;

  update public.provider_catalog_route_candidates
  set status = 'promoted', promoted_at = now(), updated_at = now()
  where run_id = p_run_id and submitted_model_slug = p_submitted_model_slug;

  update public.provider_catalog_sync_models
  set route_projection_status = case when route_enabled then 'enabled' else 'staged' end,
      route_projection_error = null
  where run_id = p_run_id and model_slug = p_submitted_model_slug;

  return provider_model_id_value;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."promote_provider_catalog_candidate"(uuid, text) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.protect_data_contribution_settings()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  if current_user in ('anon', 'authenticated') then
    if tg_op = 'INSERT' then
      if new.data_contribution_enabled is distinct from false
        or new.data_contribution_policy_version is not null
        or new.data_contribution_consented_at is not null
        or new.data_contribution_consented_by is not null
        or new.data_contribution_sample_rate_bps is distinct from 10000
        or new.data_contribution_classifier_sample_rate_bps is distinct from 1000
        or new.data_contribution_discount_bps is distinct from 100 then
        raise exception 'data contribution settings are platform controlled'
          using errcode = '42501';
      end if;
    elsif new.data_contribution_enabled is distinct from old.data_contribution_enabled
      or new.data_contribution_policy_version is distinct from old.data_contribution_policy_version
      or new.data_contribution_consented_at is distinct from old.data_contribution_consented_at
      or new.data_contribution_consented_by is distinct from old.data_contribution_consented_by
      or new.data_contribution_sample_rate_bps is distinct from old.data_contribution_sample_rate_bps
      or new.data_contribution_classifier_sample_rate_bps is distinct from old.data_contribution_classifier_sample_rate_bps
      or new.data_contribution_discount_bps is distinct from old.data_contribution_discount_bps then
      raise exception 'data contribution settings are platform controlled'
        using errcode = '42501';
    end if;
  end if;

  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."protect_data_contribution_settings"() FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.protect_users_global_role()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'pg_catalog', 'public'
  AS $function$
begin
  if auth.uid() is not null
     and coalesce(auth.role(), '') <> 'service_role'
     and new.role is distinct from old.role then
    raise exception 'users.role is managed by administrators'
      using errcode = '42501';
  end if;
  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."protect_users_global_role"() FROM PUBLIC, "anon", "authenticated", "service_role";

CREATE OR REPLACE FUNCTION public.provision_department_from_scim_group()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  department_row public.workspace_departments;
  selected_color text;
begin
  selected_color := case substring(md5(new.id::text),1,1)
    when '0' then 'blue' when '1' then 'cyan' when '2' then 'emerald'
    when '3' then 'amber' when '4' then 'orange' when '5' then 'rose'
    when '6' then 'violet' when '7' then 'fuchsia' else 'slate' end;

  insert into public.workspace_departments(
    workspace_id,name,icon,color,source_type,source_id,directory_name
  ) values (
    new.workspace_id,new.display_name,'users',selected_color,'scim_group',new.id,new.display_name
  )
  on conflict (workspace_id,source_type,source_id) where source_id is not null
  do update set
    directory_name=excluded.directory_name,
    name=case when public.workspace_departments.name_overridden then public.workspace_departments.name else excluded.directory_name end,
    updated_at=now()
  returning * into department_row;

  insert into public.scim_group_mappings(
    workspace_id,scim_group_id,department_id,access_role,department_position
  ) values (
    new.workspace_id,new.id,department_row.id,'member','member'
  ) on conflict (scim_group_id,department_id) do nothing;

  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."provision_department_from_scim_group"() FROM PUBLIC, "anon", "authenticated", "service_role";

CREATE OR REPLACE FUNCTION public.provision_personal_workspace (
  p_user_id      uuid,
  p_display_name text DEFAULT NULL::text
)
  RETURNS TABLE (
    workspace_id      uuid,
    created_workspace boolean
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  v_display_name text;
  v_default_workspace_id uuid;
  v_existing_workspace_id uuid;
  v_has_access boolean := false;
  v_default_workspace_is_owner boolean := false;
  v_created_workspace boolean := false;
  v_base_slug text;
  v_slug_attempt text;
  v_attempt integer := 0;
begin
  if p_user_id is null then
    raise exception using errcode = '22023', message = 'missing_user_id';
  end if;

  v_display_name := nullif(trim(coalesce(p_display_name, '')), '');
  if v_display_name is null then
    v_display_name := 'User';
  end if;

  insert into public.users (user_id, display_name)
  values (p_user_id, v_display_name)
  on conflict (user_id) do update
    set display_name = coalesce(nullif(excluded.display_name, ''), public.users.display_name);

  select u.default_workspace_id
  into v_default_workspace_id
  from public.users u
  where u.user_id = p_user_id
  limit 1;

  if v_default_workspace_id is not null then
    select exists (
      select 1
      from public.workspace_members wm
      where wm.workspace_id = v_default_workspace_id
        and wm.user_id = p_user_id

      union all

      select 1
      from public.workspaces w
      where w.id = v_default_workspace_id
        and w.owner_user_id = p_user_id
    )
    into v_has_access;

    select exists (
      select 1
      from public.workspaces w
      where w.id = v_default_workspace_id
        and w.owner_user_id = p_user_id
    )
    into v_default_workspace_is_owner;

    if v_has_access then
      if v_default_workspace_is_owner then
        insert into public.workspace_members (workspace_id, user_id, role)
        values (v_default_workspace_id, p_user_id, 'owner')
        on conflict on constraint workspace_members_pkey do nothing;
      end if;

      insert into public.workspace_settings (workspace_id)
      values (v_default_workspace_id)
      on conflict on constraint workspace_settings_pkey do nothing;

      return query
      select v_default_workspace_id, false;
      return;
    end if;

    update public.users
    set default_workspace_id = null
    where user_id = p_user_id
      and default_workspace_id = v_default_workspace_id;
  end if;

  select w.id
  into v_existing_workspace_id
  from public.workspaces w
  where w.owner_user_id = p_user_id
  order by w.created_at asc
  limit 1;

  if v_existing_workspace_id is null then
    v_base_slug := regexp_replace(lower(v_display_name), '[^a-z0-9]+', '-', 'g');
    v_base_slug := regexp_replace(v_base_slug, '^-+|-+$', '', 'g');
    if v_base_slug = '' then
      v_base_slug := 'user';
    end if;

    -- The public handle format allows 40 characters and '-personal' uses 9.
    v_base_slug := left(v_base_slug, 40 - length('-personal'));
    v_slug_attempt := v_base_slug || '-personal';

    while v_attempt < 8 and v_existing_workspace_id is null loop
      begin
        insert into public.workspaces (name, slug, owner_user_id)
        values ('Personal', v_slug_attempt, p_user_id)
        returning id into v_existing_workspace_id;

        v_created_workspace := true;
      exception
        when unique_violation then
          v_attempt := v_attempt + 1;
          -- Keep the retry suffix before '-personal' so the trigger cannot
          -- truncate away the uniqueness component.
          v_slug_attempt :=
            left(v_base_slug, 40 - length('-personal') - 1 - 8)
            || '-' || substring(md5(gen_random_uuid()::text), 1, 8)
            || '-personal';
      end;
    end loop;

    if v_existing_workspace_id is null then
      select w.id
      into v_existing_workspace_id
      from public.workspaces w
      where w.owner_user_id = p_user_id
      order by w.created_at asc
      limit 1;
    end if;
  end if;

  if v_existing_workspace_id is null then
    raise exception using errcode = 'P0001', message = 'personal_workspace_provision_failed';
  end if;

  insert into public.workspace_members (workspace_id, user_id, role)
  values (v_existing_workspace_id, p_user_id, 'owner')
  on conflict on constraint workspace_members_pkey do nothing;

  insert into public.workspace_settings (workspace_id)
  values (v_existing_workspace_id)
  on conflict on constraint workspace_settings_pkey do nothing;

  update public.users
  set default_workspace_id = v_existing_workspace_id
  where user_id = p_user_id;

  return query
  select v_existing_workspace_id, v_created_workspace;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."provision_personal_workspace"(uuid, text) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.prune_byok_request_metadata (
  p_retention_days integer DEFAULT 90,
  p_batch_size     integer DEFAULT 10000
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_previous_pruning text := current_setting('phaseo.pruning_byok_metadata', true);
  v_cutoff timestamptz;
  v_v2_deleted integer := 0;
  v_legacy_deleted integer := 0;
begin
  if p_retention_days < 90 or p_retention_days > 3650 then
    raise exception 'BYOK metadata retention must be between 90 and 3650 days';
  end if;
  if p_batch_size < 1 or p_batch_size > 50000 then
    raise exception 'BYOK metadata prune batch size must be between 1 and 50000';
  end if;

  v_cutoff := now() - make_interval(days => p_retention_days);

  perform set_config('phaseo.pruning_byok_metadata', 'on', true);
  with candidates as (
    select facts.request_event_id
    from public.v2_request_facts facts
    where (
        facts.byok is true
        or exists (
          select 1
          from public.v2_request_attempts attempt
          where attempt.request_event_id = facts.request_event_id
            and attempt.safe_metadata->>'key_source' = 'byok'
        )
      )
      and facts.occurred_at < v_cutoff
    order by facts.occurred_at, facts.request_event_id
    limit p_batch_size
  )
  delete from public.v2_request_facts facts
  using candidates
  where facts.request_event_id = candidates.request_event_id;
  get diagnostics v_v2_deleted = row_count;

  with candidates as (
    select requests.id, requests.created_at
    from public.gateway_requests requests
    where (
        requests.byok is true
        or exists (
          select 1
          from public.gateway_upstream_requests attempt
          where attempt.gateway_request_id = requests.id
            and attempt.gateway_request_created_at = requests.created_at
            and attempt.key_source = 'byok'
        )
      )
      and requests.created_at < v_cutoff
    order by requests.created_at, requests.id
    limit p_batch_size
  )
  delete from public.gateway_requests requests
  using candidates
  where requests.id = candidates.id
    and requests.created_at = candidates.created_at;
  get diagnostics v_legacy_deleted = row_count;

  perform set_config('phaseo.pruning_byok_metadata', coalesce(v_previous_pruning, ''), true);
  return jsonb_build_object(
    'cutoff', v_cutoff,
    'v2_deleted', v_v2_deleted,
    'legacy_deleted', v_legacy_deleted
  );
exception when others then
  perform set_config('phaseo.pruning_byok_metadata', coalesce(v_previous_pruning, ''), true);
  raise;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."prune_byok_request_metadata"(integer, integer) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.public_leaderboard_model_id (
  p_canonical_model_id text,
  p_model_id           text,
  p_requested_model_id text,
  p_routed_model_id    text,
  p_api_model_id       text,
  p_provider           text,
  p_pricing_plan       text,
  p_is_free_variant    boolean
)
  RETURNS text
  LANGUAGE sql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  select case
    when coalesce(p_is_free_variant, false)
      or lower(coalesce(p_pricing_plan, '')) = 'free'
      or lower(coalesce(p_api_model_id, '')) like '%:free'
      or lower(coalesce(p_routed_model_id, '')) like '%:free'
      or lower(coalesce(p_model_id, '')) like '%:free'
      or lower(coalesce(p_requested_model_id, '')) like '%:free'
      or lower(coalesce(p_canonical_model_id, '')) like '%:free'
    then coalesce(
      nullif(p_api_model_id, ''),
      nullif(p_routed_model_id, ''),
      nullif(p_model_id, ''),
      nullif(p_requested_model_id, ''),
      nullif(p_canonical_model_id, ''),
      public.resolve_public_model_id(p_model_id, p_provider),
      'unknown'
    )
    else coalesce(
      nullif(p_canonical_model_id, ''),
      public.resolve_public_model_id(p_model_id, p_provider),
      nullif(p_routed_model_id, ''),
      nullif(p_requested_model_id, ''),
      nullif(p_api_model_id, ''),
      nullif(p_model_id, ''),
      'unknown'
    )
  end;
$function$;

CREATE OR REPLACE FUNCTION public.publish_preset_version (
  target_preset_id uuid,
  actor_user_id    uuid,
  notes            text DEFAULT NULL::text,
  requested_label  text DEFAULT NULL::text
)
  RETURNS public.preset_versions
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare p public.presets%rowtype; next_number integer; next_label text; date_base text; date_count integer; published public.preset_versions%rowtype;
begin
  select * into p from public.presets where id = target_preset_id and archived_at is null for update;
  if not found then raise exception 'preset_not_found'; end if;
  if p.created_by <> actor_user_id and (
    coalesce(p.draft_visibility, p.visibility) = 'private' or not exists (
      select 1 from public.workspace_members member
      where member.workspace_id = p.workspace_id
        and member.user_id = actor_user_id
        and member.role in ('owner', 'admin')
    )
  ) then raise exception 'preset_publish_forbidden'; end if;
  select coalesce(max(version_number), 0) + 1 into next_number from public.preset_versions where preset_id = p.id;
  if p.versioning_method = 'semver' then
    next_label := regexp_replace(trim(coalesce(requested_label, '')), '^v', '');
    if next_label !~ '^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(-[0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*)?(\+[0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*)?$' then raise exception 'invalid_semver_label'; end if;
  elsif p.versioning_method = 'date' then
    date_base := to_char(current_date, 'YYYY.MM.DD');
    select count(*) into date_count from public.preset_versions where preset_id = p.id and version_label like date_base || '%';
    next_label := case when date_count = 0 then date_base else date_base || '.' || (date_count + 1)::text end;
  else next_label := 'v' || next_number::text;
  end if;
  insert into public.preset_versions (preset_id, version_number, version_label, versioning_method, name, slug, description, config, visibility, release_notes, created_by)
  values (p.id, next_number, next_label, p.versioning_method, p.draft_name, p.draft_slug, p.draft_description, p.draft_config, p.draft_visibility, nullif(trim(notes), ''), actor_user_id)
  returning * into published;
  update public.presets set name = published.name, slug = published.slug, description = published.description,
    config = published.config, visibility = published.visibility, active_version_id = published.id, updated_at = now()
  where id = p.id;
  return published;
end $function$;

REVOKE ALL ON FUNCTION "public"."publish_preset_version"(uuid, uuid, text, text) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.queue_gateway_billing_alert (
  p_alert_id uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  alert public.gateway_billing_alerts%rowtype;
  destination public.notification_destinations%rowtype;
  event_uuid uuid;
begin
  select * into alert from public.gateway_billing_alerts where id = p_alert_id for update;
  if not found or alert.event_id is not null or alert.status <> 'open' then return false; end if;
  select d.* into destination
  from public.gateway_billing_alert_config c
  join public.notification_destinations d on d.id = c.destination_id
  where c.singleton and d.status = 'active' and d.type = 'slack';
  if not found then return false; end if;

  -- email_outbox is the existing notification event store. This event has no
  -- email leg: sent_at closes that legacy drain; Slack delivery has its own status.
  insert into public.email_outbox(kind, template, to_email, subject, workspace_id, dedupe_key, payload, sent_at)
  values ('billing_anomaly', 'notification_only', '', 'Unexpected zero-cost generation',
    destination.workspace_id, 'billing_anomaly:' || alert.id,
    jsonb_build_object(
      'title', 'Unexpected zero-cost generation',
      'message', format('A paid %s job was priced at zero. Workspace: %s. Job: %s. Provider: %s. Review billing and the reservation before releasing credit. Alert: %s.',
        alert.kind, alert.workspace_id, alert.resource_id, coalesce(alert.provider, 'unknown'), alert.id),
      'alert_id', alert.id, 'source_workspace_id', alert.workspace_id,
      'resource_id', alert.resource_id, 'kind', alert.kind, 'reason', alert.reason), now())
  returning id into event_uuid;

  insert into public.notification_routed_events(event_id, workspace_id)
    values(event_uuid, destination.workspace_id);
  insert into public.notification_delivery_attempts(event_id, destination_id, workspace_id)
    values(event_uuid, destination.id, destination.workspace_id);
  update public.gateway_billing_alerts set event_id = event_uuid where id = alert.id;
  return true;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."queue_gateway_billing_alert"(uuid) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.queue_v2_catalogue_price_proposal (
  p_provider_model_id text,
  p_sku_code          text,
  p_proposal_id       text,
  p_source_url        text,
  p_sku               jsonb,
  p_expected_sku      jsonb
)
  RETURNS void
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
begin
  if nullif(p_sku_code,'') is null then raise exception 'price code required'; end if;
  if p_proposal_id is not null and (p_sku is null or p_sku->>'provider_model_id' is distinct from p_provider_model_id or p_sku->>'sku_code' is distinct from p_sku_code) then raise exception 'proposal identity mismatch'; end if;
  perform pg_advisory_xact_lock(hashtextextended('catalogue-proposal:'||p_provider_model_id||':'||p_sku_code,0));
  update public.v2_catalogue_price_proposals set status='superseded',reviewed_at=now()
    where provider_model_id=p_provider_model_id and sku->>'sku_code'=p_sku_code and status='pending' and proposal_id is distinct from p_proposal_id;
  if p_proposal_id is null then return; end if;
  insert into public.v2_catalogue_price_proposals(proposal_id,provider_model_id,source_url,sku,expected_sku)
    values(p_proposal_id,p_provider_model_id,p_source_url,p_sku,p_expected_sku)
    on conflict(proposal_id) do update set status='pending',created_at=now(),reviewed_at=null,reviewed_by=null
      where v2_catalogue_price_proposals.status='superseded';
end $function$;

REVOKE ALL ON FUNCTION "public"."queue_v2_catalogue_price_proposal"(text, text, text, text, jsonb, jsonb) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.reconcile_scim_entitlements (
  p_workspace_id uuid
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  owner_id uuid;
  previous_reconcile_setting text;
begin
  previous_reconcile_setting := current_setting('phaseo.entitlement_reconcile',true);
  select owner_user_id into owner_id from public.workspaces where id=p_workspace_id;
  delete from public.workspace_access_grants where workspace_id=p_workspace_id and source_type='scim_group';
  insert into public.workspace_access_grants(workspace_id,user_id,source_type,source_id,access_role)
  select distinct m.workspace_id,u.auth_user_id,'scim_group',m.id,m.access_role
  from public.scim_group_mappings m join public.scim_group_members gm on gm.group_id=m.scim_group_id and gm.workspace_id=m.workspace_id
  join public.scim_users u on u.id=gm.user_id and u.workspace_id=m.workspace_id
  where m.workspace_id=p_workspace_id and u.active and u.auth_user_id is not null;
  delete from public.workspace_department_grants where workspace_id=p_workspace_id and source_type='scim_group';
  insert into public.workspace_department_grants(workspace_id,user_id,department_id,source_type,source_id,position,is_primary)
  select distinct m.workspace_id,u.auth_user_id,m.department_id,'scim_group',m.id,m.department_position,false
  from public.scim_group_mappings m join public.scim_group_members gm on gm.group_id=m.scim_group_id and gm.workspace_id=m.workspace_id
  join public.scim_users u on u.id=gm.user_id and u.workspace_id=m.workspace_id
  where m.workspace_id=p_workspace_id and u.active and u.auth_user_id is not null;
  update public.workspace_department_grants g set is_primary=true,updated_at=now()
  from public.scim_users u,public.workspace_departments d
  where g.workspace_id=p_workspace_id and g.source_type='scim_group' and g.user_id=u.auth_user_id
    and u.workspace_id=g.workspace_id and u.active and d.id=g.department_id and d.workspace_id=g.workspace_id
    and u.department is not null and d.name_normalized=lower(btrim(u.department));
  perform set_config('phaseo.entitlement_reconcile','on',true);
  insert into public.workspace_members(workspace_id,user_id,role)
  select workspace_id,user_id,(case when bool_or(access_role='owner') then 'owner' when bool_or(access_role='admin') then 'admin' else 'member' end)::public.workspace_role
  from public.workspace_access_grants where workspace_id=p_workspace_id group by workspace_id,user_id
  on conflict(workspace_id,user_id) do update set role=excluded.role;
  delete from public.workspace_members wm where wm.workspace_id=p_workspace_id and wm.user_id<>owner_id
    and not exists(select 1 from public.workspace_access_grants g where g.workspace_id=wm.workspace_id and g.user_id=wm.user_id);
  perform set_config('phaseo.entitlement_reconcile',case when previous_reconcile_setting='on' then 'on' else 'off' end,true);
end $function$;

REVOKE ALL ON FUNCTION "public"."reconcile_scim_entitlements"(uuid) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.reconcile_scim_entitlements_trigger()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  if current_setting('phaseo.scim_group_replace',true)='on' then return coalesce(new,old); end if;
  perform public.reconcile_scim_entitlements(coalesce(new.workspace_id,old.workspace_id));
  return coalesce(new,old);
end $function$;

REVOKE ALL ON FUNCTION "public"."reconcile_scim_entitlements_trigger"() FROM PUBLIC, "anon", "authenticated", "service_role";

CREATE OR REPLACE FUNCTION public.record_gateway_async_webhook_result (
  p_workspace_id    uuid,
  p_kind            text,
  p_internal_id     text,
  p_delivery_key    text,
  p_attempt         jsonb,
  p_retry_state     jsonb                    DEFAULT NULL::jsonb,
  p_delivered_at    timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  p_next_retry_at   timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  p_progress        double precision         DEFAULT NULL::double precision,
  p_telemetry_patch jsonb                    DEFAULT NULL::jsonb,
  p_claim_token     text                     DEFAULT NULL::text
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_meta jsonb;
  v_attempts jsonb;
  v_queue jsonb;
  v_deliveries jsonb;
  v_next_retry_at timestamptz;
  v_telemetry_patch jsonb;
begin
  select coalesce(meta, '{}'::jsonb) into v_meta
  from public.gateway_async_operations
  where workspace_id = p_workspace_id and kind = p_kind and internal_id = p_internal_id
  for update;
  if not found then return; end if;

  -- Lock in the same order as lifecycle updates: operation, then delivery.
  if p_claim_token is not null then
    perform 1 from public.gateway_async_webhook_deliveries
    where workspace_id = p_workspace_id and kind = p_kind
      and internal_id = p_internal_id and delivery_key = p_delivery_key
      and status = 'claimed' and claim_token = p_claim_token
    for update;
    if not found then raise exception 'stale_webhook_delivery_claim'; end if;
  end if;


  v_telemetry_patch := coalesce(p_telemetry_patch, '{}'::jsonb)
    - 'webhookAttempts'
    - 'webhookRetryQueue'
    - 'webhookDeliveries'
    - 'nextWebhookRetryAt'
    - 'lastWebhookDispatchedAt'
    - 'lastWebhookProgress'
    - 'lastWebhookProgressAt';

  v_attempts := coalesce(v_meta->'webhookAttempts', '[]'::jsonb) || jsonb_build_array(p_attempt);
  if jsonb_array_length(v_attempts) > 50 then
    select coalesce(jsonb_agg(value order by ordinality), '[]'::jsonb)
      into v_attempts
    from jsonb_array_elements(v_attempts) with ordinality
    where ordinality > jsonb_array_length(v_attempts) - 50;
  end if;

  v_queue := coalesce(v_meta->'webhookRetryQueue', '{}'::jsonb);
  if p_retry_state is null then
    v_queue := v_queue - p_delivery_key;
  else
    v_queue := jsonb_set(v_queue, array[p_delivery_key], p_retry_state, true);
  end if;

  v_deliveries := coalesce(v_meta->'webhookDeliveries', '{}'::jsonb);
  if p_delivered_at is not null then
    v_deliveries := jsonb_set(v_deliveries, array[p_delivery_key], to_jsonb(p_delivered_at::text), true);
  end if;

  select min(nullif(value->>'nextRetryAt', '')::timestamptz)
    into v_next_retry_at
  from jsonb_each(v_queue);

  v_meta := v_meta || jsonb_build_object(
    'webhookAttempts', v_attempts,
    'webhookRetryQueue', v_queue,
    'webhookDeliveries', v_deliveries,
    'nextWebhookRetryAt', case when v_next_retry_at is null then 'null'::jsonb else to_jsonb(v_next_retry_at::text) end,
    'lastWebhookDispatchedAt', to_jsonb(now()::text)
  ) || v_telemetry_patch;
  if p_progress is not null then
    v_meta := v_meta || jsonb_build_object(
      'lastWebhookProgress', p_progress,
      'lastWebhookProgressAt', to_jsonb(now()::text)
    );
  end if;

  update public.gateway_async_operations
  set meta = v_meta, updated_at = now()
  where workspace_id = p_workspace_id and kind = p_kind and internal_id = p_internal_id;

  update public.gateway_async_webhook_deliveries
  set status = case
        when p_delivered_at is not null then 'delivered'
        when p_next_retry_at is null then 'failed'
        else status
      end,
      claim_token = case when p_next_retry_at is null then null else claim_token end,
      claimed_at = case when p_next_retry_at is null then null else claimed_at end,
      delivered_at = coalesce(p_delivered_at, delivered_at),
      next_attempt_at = p_next_retry_at,
      last_error = p_attempt->>'error_message',
      updated_at = now()
  where workspace_id = p_workspace_id and kind = p_kind
    and internal_id = p_internal_id and delivery_key = p_delivery_key;
end;
$function$;

REVOKE ALL
  ON FUNCTION "public"."record_gateway_async_webhook_result"(uuid, text, text, text, jsonb, jsonb, timestamp WITH time zone, timestamp
    WITH time zone, double precision, jsonb, text)
  FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.record_model_discovery_review_decision (
  p_item_id       uuid,
  p_decision      text,
  p_reason        text,
  p_actor_user_id uuid,
  p_reviewed_at   timestamp with time zone DEFAULT now()
)
  RETURNS SETOF public.model_discovery_review_items
  LANGUAGE plpgsql
  SET search_path TO 'public'
  AS $function$
declare
  updated_item public.model_discovery_review_items;
begin
  if p_decision not in ('in_progress', 'approved', 'rejected', 'snoozed') then
    raise exception 'invalid model discovery review decision';
  end if;

  if p_decision in ('rejected', 'snoozed') and nullif(trim(coalesce(p_reason, '')), '') is null then
    raise exception 'a reason is required for this review decision';
  end if;

  update public.model_discovery_review_items
  set
    status = p_decision,
    reviewed_by = p_actor_user_id,
    reviewed_at = coalesce(p_reviewed_at, now()),
    review_note = case
      when p_decision in ('approved', 'in_progress') then null
      else nullif(trim(p_reason), '')
    end
  where id = p_item_id
  returning * into updated_item;

  if not found then
    return;
  end if;

  insert into public.model_discovery_review_events (
    item_id,
    decision,
    reason,
    actor_user_id
  ) values (
    p_item_id,
    p_decision,
    nullif(trim(p_reason), ''),
    p_actor_user_id
  );

  return next updated_item;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."record_model_discovery_review_decision"(uuid, text, text, uuid, timestamp WITH time zone) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.record_workspace_sso_active_user (
  p_workspace_id uuid,
  p_auth_user_id uuid,
  p_seen_at      timestamp with time zone DEFAULT now()
)
  RETURNS bigint
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_period_start date := date_trunc('month', p_seen_at at time zone 'UTC')::date;
  v_quantity bigint;
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_workspace_id::text || ':' || v_period_start::text, 0)
  );

  insert into public.workspace_sso_monthly_active_users (
    workspace_id,
    period_start,
    auth_user_id,
    first_seen_at,
    last_seen_at
  ) values (
    p_workspace_id,
    v_period_start,
    p_auth_user_id,
    p_seen_at,
    p_seen_at
  )
  on conflict (workspace_id, period_start, auth_user_id) do update set
    last_seen_at = greatest(
      public.workspace_sso_monthly_active_users.last_seen_at,
      excluded.last_seen_at
    );

  select count(*)
    into v_quantity
  from public.workspace_sso_monthly_active_users
  where workspace_id = p_workspace_id
    and period_start = v_period_start;

  insert into public.workspace_addon_usage_monthly (
    workspace_id,
    addon_key,
    metric_key,
    period_start,
    quantity,
    updated_at
  ) values (
    p_workspace_id,
    'identity',
    'sso_mau',
    v_period_start,
    v_quantity,
    now()
  )
  on conflict (workspace_id, addon_key, metric_key, period_start) do update set
    quantity = excluded.quantity,
    updated_at = now();

  return v_quantity;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."record_workspace_sso_active_user"(uuid, uuid, timestamp WITH time zone) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.redeem_credit_code (
  p_code         text,
  p_workspace_id uuid
)
  RETURNS TABLE (
    status               text,
    message              text,
    grant_id             uuid,
    amount_nanos         bigint,
    before_balance_nanos bigint,
    after_balance_nanos  bigint,
    workspace_id         uuid
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_user_id uuid := auth.uid();
  v_code_normalized text;
  v_grant public.credit_grants%rowtype;
  v_wallet public.wallets%rowtype;
  v_team_billing_mode text;
  v_redemption_id uuid;
begin
  if v_user_id is null then
    return query
    select
      'unauthorized'::text,
      'You must be signed in to redeem a credit code.'::text,
      null::uuid,
      null::bigint,
      null::bigint,
      null::bigint,
      p_workspace_id;
    return;
  end if;

  if p_workspace_id is null or not public.is_workspace_member(p_workspace_id) then
    return query
    select
      'team_forbidden'::text,
      'You do not have access to this team.'::text,
      null::uuid,
      null::bigint,
      null::bigint,
      null::bigint,
      p_workspace_id;
    return;
  end if;

  select lower(coalesce(t.billing_mode::text, 'wallet'))
  into v_team_billing_mode
  from public.workspaces t
  where t.id = p_workspace_id;

  if not found then
    return query
    select
      'team_forbidden'::text,
      'You do not have access to this team.'::text,
      null::uuid,
      null::bigint,
      null::bigint,
      null::bigint,
      p_workspace_id;
    return;
  end if;

  if v_team_billing_mode = 'invoice' then
    return query
    select
      'invoice_mode'::text,
      'Credit codes are not available for invoice billing teams.'::text,
      null::uuid,
      null::bigint,
      null::bigint,
      null::bigint,
      p_workspace_id;
    return;
  end if;

  v_code_normalized := upper(trim(coalesce(p_code, '')));

  if v_code_normalized = ''
    or length(v_code_normalized) > 64
    or v_code_normalized !~ '^[A-Z0-9][A-Z0-9_-]{1,63}$'
  then
    return query
    select
      'invalid_code_format'::text,
      'Credit code format is invalid.'::text,
      null::uuid,
      null::bigint,
      null::bigint,
      null::bigint,
      p_workspace_id;
    return;
  end if;

  select *
  into v_grant
  from public.credit_grants cg
  where cg.code_normalized = v_code_normalized
  for update;

  if not found then
    return query
    select
      'not_found'::text,
      'This credit code is invalid.'::text,
      null::uuid,
      null::bigint,
      null::bigint,
      null::bigint,
      p_workspace_id;
    return;
  end if;

  if not coalesce(v_grant.is_active, false) then
    return query
    select
      'inactive'::text,
      'This credit code is inactive.'::text,
      v_grant.id,
      null::bigint,
      null::bigint,
      null::bigint,
      p_workspace_id;
    return;
  end if;

  if v_grant.expires_at is not null and v_grant.expires_at <= now() then
    return query
    select
      'expired'::text,
      'This credit code has expired.'::text,
      v_grant.id,
      null::bigint,
      null::bigint,
      null::bigint,
      p_workspace_id;
    return;
  end if;

  if coalesce(v_grant.redemptions_count, 0) >= v_grant.max_redemptions then
    return query
    select
      'maxed_out'::text,
      'This credit code has reached its redemption limit.'::text,
      v_grant.id,
      null::bigint,
      null::bigint,
      null::bigint,
      p_workspace_id;
    return;
  end if;

  select *
  into v_wallet
  from public.wallets w
  where w.workspace_id = p_workspace_id
  for update;

  if not found then
    return query
    select
      'wallet_not_found'::text,
      'Wallet not found for this team.'::text,
      v_grant.id,
      null::bigint,
      null::bigint,
      null::bigint,
      p_workspace_id;
    return;
  end if;

  insert into public.credit_grant_redemptions (
    grant_id,
    user_id,
    workspace_id,
    amount_nanos
  ) values (
    v_grant.id,
    v_user_id,
    p_workspace_id,
    v_grant.amount_nanos
  )
  on conflict on constraint credit_grant_redemptions_grant_user_unique
  do nothing
  returning id
  into v_redemption_id;

  if v_redemption_id is null then
    return query
    select
      'already_redeemed'::text,
      'You have already redeemed this credit code.'::text,
      v_grant.id,
      null::bigint,
      null::bigint,
      null::bigint,
      p_workspace_id;
    return;
  end if;

  update public.wallets as w
  set balance_nanos = w.balance_nanos + v_grant.amount_nanos,
      updated_at = now()
  where w.workspace_id = p_workspace_id
  returning w.*
  into v_wallet;

  insert into public.credit_ledger (
    workspace_id,
    event_time,
    kind,
    amount_nanos,
    before_balance_nanos,
    after_balance_nanos,
    ref_type,
    ref_id,
    created_at,
    status
  ) values (
    p_workspace_id,
    now(),
    'promo_code',
    v_grant.amount_nanos,
    v_wallet.balance_nanos - v_grant.amount_nanos,
    v_wallet.balance_nanos,
    'promo_code_redeem',
    v_redemption_id::text,
    now(),
    'paid'
  ) on conflict (ref_type, ref_id) do nothing;

  update public.credit_grants
  set redemptions_count = redemptions_count + 1
  where id = v_grant.id;

  return query
  select
    'succeeded'::text,
    'Promo credit applied successfully.'::text,
    v_grant.id,
    v_grant.amount_nanos,
    v_wallet.balance_nanos - v_grant.amount_nanos,
    v_wallet.balance_nanos,
    p_workspace_id;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."redeem_credit_code"(text, uuid) FROM PUBLIC, "anon";

CREATE OR REPLACE FUNCTION public.refresh_effective_entitlements_after_directory_change()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare target_workspace_id uuid;
begin
  if current_setting('phaseo.scim_group_replace',true)='on' then return coalesce(new,old); end if;
  target_workspace_id := coalesce(new.workspace_id,old.workspace_id);
  perform set_config('phaseo.entitlement_reconcile','on',true);
  update public.workspace_members wm set role=o.access_role::public.workspace_role
  from public.workspace_member_overrides o
  where wm.workspace_id=target_workspace_id and wm.workspace_id=o.workspace_id and wm.user_id=o.user_id and o.access_role is not null
    and lower(wm.role::text) is distinct from o.access_role;
  perform public.refresh_workspace_effective_entitlements(target_workspace_id,null,'directory_sync');
  return coalesce(new,old);
end;
$function$;

REVOKE ALL ON FUNCTION "public"."refresh_effective_entitlements_after_directory_change"() FROM PUBLIC, "anon", "authenticated";

