CREATE OR REPLACE FUNCTION public.update_workspace_auto_top_up (
  p_workspace_id            uuid,
  p_enabled                 boolean,
  p_balance_threshold_nanos bigint,
  p_amount_nanos            bigint,
  p_payment_method_id       text,
  p_mfa_enabled             boolean,
  p_mfa_bypass_acknowledged boolean,
  p_mfa_bypass_phrase       text,
  p_actor_user_id           uuid    DEFAULT NULL::uuid,
  p_request_id              text    DEFAULT NULL::text
)
  RETURNS SETOF public.wallets
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  v_wallet public.wallets%rowtype;
  v_requires_mfa boolean;
begin
  if p_workspace_id is null then
    raise exception 'missing_workspace_id';
  end if;

  select *
  into v_wallet
  from public.wallets
  where workspace_id = p_workspace_id
  for update;

  if not found then
    raise exception 'wallet_not_found';
  end if;

  v_requires_mfa := p_enabled
    and not coalesce(p_mfa_enabled, false)
    and not coalesce(v_wallet.auto_top_up_enabled, false);

  if v_requires_mfa
    and not (
      coalesce(p_mfa_bypass_acknowledged, false)
      and coalesce(p_mfa_bypass_phrase, '') = 'I ACCEPT THE RISK'
    ) then
    raise exception 'mfa_required';
  end if;

  update public.wallets
  set auto_top_up_enabled = p_enabled,
      low_balance_threshold = case when p_enabled then coalesce(p_balance_threshold_nanos, 0) else 0 end,
      auto_top_up_amount = case when p_enabled then coalesce(p_amount_nanos, 0) else 0 end,
      auto_top_up_account_id = case when p_enabled then p_payment_method_id else null end,
      updated_at = now()
  where workspace_id = p_workspace_id;

  if v_requires_mfa then
    insert into public.workspace_audit_events (
      workspace_id,
      actor_user_id,
      action,
      target_type,
      target_id,
      metadata,
      request_id
    ) values (
      p_workspace_id,
      p_actor_user_id,
      'auto_top_up.enabled_without_mfa',
      'wallet',
      p_workspace_id::text,
      jsonb_build_object('consentVersion', 'mfa-bypass-v1', 'mfaEnabled', false),
      nullif(left(trim(coalesce(p_request_id, '')), 200), '')
    );
  end if;

  return query
  select updated_wallet.*
  from public.wallets as updated_wallet
  where updated_wallet.workspace_id = p_workspace_id;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."update_workspace_auto_top_up"(uuid, boolean, bigint, bigint, text, boolean, boolean, text, uuid, text) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.update_workspace_department (
  p_workspace_id  uuid,
  p_department_id uuid,
  p_name          text,
  p_icon          text,
  p_color         text,
  p_actor_user_id uuid,
  p_request_id    text DEFAULT NULL::text
)
  RETURNS public.workspace_departments
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare before_row public.workspace_departments; updated public.workspace_departments;
begin
  select * into before_row from public.workspace_departments where id=p_department_id and workspace_id=p_workspace_id for update;
  if before_row is null then raise exception 'Department not found'; end if;
  update public.workspace_departments set name=btrim(p_name),icon=p_icon,color=p_color,
    name_overridden=case when source_type='scim_group' and btrim(p_name) is distinct from directory_name then true else name_overridden end,
    updated_at=now()
  where id=p_department_id and workspace_id=p_workspace_id returning * into updated;
  perform public.refresh_workspace_effective_entitlements(p_workspace_id,p_actor_user_id,'department_updated');
  insert into public.workspace_directory_audit_events(workspace_id,actor_user_id,action,target_type,target_id,before_state,after_state,request_id)
  values(p_workspace_id,p_actor_user_id,'workspace.department.update','workspace_department',p_department_id::text,to_jsonb(before_row),to_jsonb(updated),p_request_id);
  return updated;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."update_workspace_department"(uuid, uuid, text, text, text, uuid, text) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.update_workspace_tier (
  p_team_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public', 'pg_temp'
  AS $function$
DECLARE
    v_current_tier text;
    v_new_tier text;
    v_prev_month_spend numeric(12, 2);
    v_consecutive_low integer;
    v_threshold numeric(12, 2) := 10000.00; -- $10k threshold
    v_changed boolean := false;
    v_reason text;
BEGIN
    -- Get current tier and consecutive low-spend months
    SELECT tier, consecutive_low_spend_months
    INTO v_current_tier, v_consecutive_low
    FROM public.teams
    WHERE id = p_team_id;

    IF v_current_tier IS NULL THEN
        RAISE EXCEPTION 'Team not found: %', p_team_id;
    END IF;

    -- Calculate previous month's spend
    v_prev_month_spend := calculate_team_previous_month_spend(p_team_id);

    -- Determine new tier based on logic:
    -- - If spent >$10k in previous month → Enterprise
    -- - If spent <$10k for 3 consecutive months → Basic
    IF v_prev_month_spend >= v_threshold THEN
        -- High spend → Enterprise tier
        v_new_tier := 'enterprise';
        v_consecutive_low := 0;
        IF v_current_tier != 'enterprise' THEN
            v_reason := format('Previous month spend $%s exceeded $10k threshold', v_prev_month_spend);
            v_changed := true;
        END IF;
    ELSE
        -- Low spend → increment counter
        v_consecutive_low := v_consecutive_low + 1;

        IF v_consecutive_low >= 3 AND v_current_tier != 'basic' THEN
            -- 3 months of low spend → downgrade to Basic
            v_new_tier := 'basic';
            v_reason := format('3 consecutive months below $10k threshold (current: $%s)', v_prev_month_spend);
            v_changed := true;
        ELSE
            -- Keep current tier
            v_new_tier := v_current_tier;
        END IF;
    END IF;

    -- Update team record
    UPDATE public.teams
    SET
        tier = v_new_tier,
        tier_updated_at = CASE WHEN v_changed THEN now() ELSE tier_updated_at END,
        consecutive_low_spend_months = v_consecutive_low
    WHERE id = p_team_id;

    -- Record tier change in history if changed
    IF v_changed THEN
        INSERT INTO public.team_tier_history (
            team_id,
            old_tier,
            new_tier,
            reason,
            previous_month_spend_usd,
            threshold_usd,
            consecutive_low_months
        ) VALUES (
            p_team_id,
            v_current_tier,
            v_new_tier,
            v_reason,
            v_prev_month_spend,
            v_threshold,
            v_consecutive_low
        );
    END IF;

    RETURN jsonb_build_object(
        'team_id', p_team_id,
        'old_tier', v_current_tier,
        'new_tier', v_new_tier,
        'changed', v_changed,
        'reason', v_reason,
        'previous_month_spend_usd', v_prev_month_spend,
        'consecutive_low_months', v_consecutive_low
    );
END;
$function$;

REVOKE ALL ON FUNCTION "public"."update_workspace_tier"(uuid) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.upsert_api_app (
  p_team_id uuid,
  p_title   text,
  p_url     text
)
  RETURNS uuid
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
DECLARE
    v_app_key text;
    v_id uuid;
BEGIN
    -- Derive app_key from title (assuming title is X-Title)
    v_app_key := p_title;

    -- Try to find existing app
    SELECT id INTO v_id FROM public.api_apps WHERE team_id = p_team_id AND app_key = v_app_key;

    IF v_id IS NOT NULL THEN
        -- Update last_seen and meta
        UPDATE public.api_apps SET
            last_seen = now(),
            updated_at = now(),
            meta = jsonb_build_object('referer', p_url, 'appTitle', p_title)
        WHERE id = v_id;
        RETURN v_id;
    ELSE
        -- Insert new app
        INSERT INTO public.api_apps (team_id, app_key, title, url, meta) VALUES (
            p_team_id,
            v_app_key,
            p_title,
            p_url,
            jsonb_build_object('referer', p_url, 'appTitle', p_title)
        ) RETURNING id INTO v_id;
        RETURN v_id;
    END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.upsert_gateway_request_into_workspace_usage_rollup (
  p_request_row_id     uuid,
  p_request_created_at timestamp with time zone,
  p_workspace_id       uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_fact record;
  v_seconds numeric;
begin
  select fact.request_event_id, fact.occurred_at, request.endpoint, request.usage
  into v_fact
  from public.gateway_requests request
  join public.v2_request_facts fact
    on fact.gateway_request_id = request.id
    and fact.gateway_request_created_at = request.created_at
    and fact.workspace_id = request.workspace_id
  where request.id = p_request_row_id
    and request.created_at = p_request_created_at
    and request.workspace_id = p_workspace_id
  for update of fact;

  if not found then return false; end if;

  if v_fact.endpoint = 'video.generation'
    and v_fact.usage->>'output_video_seconds' ~ '^[0-9]+(\.[0-9]+)?$' then
    v_seconds := (v_fact.usage->>'output_video_seconds')::numeric;
    if v_seconds > 0 then
      -- Replace the measurement, never increment it: polling and webhooks can
      -- deliver the same completed job repeatedly, with different old sequences.
      delete from public.v2_request_usage
      where request_event_id = v_fact.request_event_id
        and meter_key in ('output_video_seconds', 'video_seconds');
      insert into public.v2_request_usage (
        request_event_id, meter_key, modality, unit, quantity, source, billable, sequence
      ) values (
        v_fact.request_event_id, 'output_video_seconds', 'video', 'seconds',
        v_seconds, 'gateway', true, 0
      );
    end if;
  end if;

  insert into public.v2_analytics_outbox (
    request_event_id, workspace_id, occurred_at, status, attempt_count,
    available_at, last_error, updated_at
  ) values (
    v_fact.request_event_id, p_workspace_id, v_fact.occurred_at, 'pending', 0,
    now(), null, now()
  ) on conflict (request_event_id) do update set
    status = 'pending', attempt_count = 0, available_at = now(),
    last_error = null, updated_at = now();
  return true;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."upsert_gateway_request_into_workspace_usage_rollup"(uuid, timestamp WITH time zone, uuid) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.upsert_model_discovery_review_items (
  p_rows jsonb
)
  RETURNS void
  LANGUAGE plpgsql
  SET search_path TO 'public'
  AS $function$
begin
  if jsonb_typeof(p_rows) <> 'array' then
    raise exception 'model discovery review rows must be a JSON array';
  end if;

  insert into public.model_discovery_review_items (
    dedupe_key,
    run_id,
    source,
    provider_id,
    provider_name,
    model_id,
    change_type,
    details,
    last_detected_at
  )
  select
    nullif(trim(entry->>'dedupe_key'), ''),
    nullif(trim(entry->>'run_id'), '')::uuid,
    entry->>'source',
    entry->>'provider_id',
    entry->>'provider_name',
    entry->>'model_id',
    entry->>'change_type',
    case when jsonb_typeof(entry->'details') = 'object' then entry->'details' else '{}'::jsonb end,
    coalesce(nullif(trim(entry->>'last_detected_at'), '')::timestamptz, now())
  from jsonb_array_elements(p_rows) as entries(entry)
  where nullif(trim(entry->>'dedupe_key'), '') is not null
  on conflict (dedupe_key) do update set
    run_id = excluded.run_id,
    source = excluded.source,
    provider_id = excluded.provider_id,
    provider_name = excluded.provider_name,
    model_id = excluded.model_id,
    change_type = excluded.change_type,
    details = excluded.details,
    last_detected_at = excluded.last_detected_at;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."upsert_model_discovery_review_items"(jsonb) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.valid_key_ip_allowlist (
  entries jsonb
)
  RETURNS boolean
  LANGUAGE plpgsql
  IMMUTABLE
  SET search_path TO 'pg_catalog'
  AS $function$
declare
  entry jsonb;
  address text;
begin
  if entries is null or jsonb_typeof(entries) <> 'array' then return false; end if;
  if jsonb_array_length(entries) > 100 then return false; end if;
  for entry in select value from jsonb_array_elements(entries) loop
    if jsonb_typeof(entry) <> 'object'
      or jsonb_typeof(entry->'label') is distinct from 'string'
      or jsonb_typeof(entry->'address') is distinct from 'string'
      or length(btrim(entry->>'label')) not between 1 and 100
    then return false; end if;
    address := entry->>'address';
    -- Require full dotted IPv4 or IPv6, with an optional prefix length.
    if address !~ '^([0-9]{1,3}\.){3}[0-9]{1,3}(/[0-9]{1,3})?$'
      and address !~ '^[0-9A-Fa-f:.]+:[0-9A-Fa-f:.]*(/[0-9]{1,3})?$'
    then return false; end if;
    perform address::inet;
  end loop;
  return true;
exception when invalid_text_representation then return false;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."valid_key_ip_allowlist"(jsonb) FROM PUBLIC, "anon";

CREATE OR REPLACE FUNCTION public.wallet_apply_delta (
  p_workspace_id uuid,
  p_delta_nanos  bigint
)
  RETURNS TABLE (
    before_balance_nanos bigint,
    after_balance_nanos  bigint
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
    v_before bigint;
    v_after bigint;
begin
    if p_workspace_id is null then
        raise exception 'missing_workspace_id';
    end if;

    update public.wallets
    set balance_nanos = balance_nanos + p_delta_nanos,
        updated_at = now()
    where workspace_id = p_workspace_id
    returning balance_nanos - p_delta_nanos, balance_nanos
    into v_before, v_after;

    if not found then
        raise exception 'wallet_not_found';
    end if;

    return query select v_before, v_after;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."wallet_apply_delta"(uuid, bigint) FROM PUBLIC, "anon", "authenticated";

