CREATE VIEW "private"."v2_rpc_benchmark_results_compat" WITH (security_invoker=true) AS  SELECT result_id,
    model_slug,
    benchmark_id,
    score,
    score_numeric,
    is_self_reported,
    other_info,
    source_link,
    rank,
    occur_idx,
    variant,
    result_key,
    created_at,
    updated_at,
    result_id AS id,
    model_slug AS model_id
   FROM public.v2_benchmark_results result;

CREATE VIEW "private"."v2_rpc_benchmarks_compat" WITH (security_invoker=true) AS  SELECT benchmark_id,
    name,
    category,
    link,
    total_models,
    ascending_order,
    benchmark_type,
    created_at,
    updated_at,
    benchmark_id AS id,
    benchmark_type AS type
   FROM public.v2_benchmarks benchmark;

CREATE VIEW "private"."v2_rpc_capabilities_compat" WITH (security_invoker=true) AS  SELECT provider_model_id,
    capability_id,
    status,
    max_input_tokens,
    max_output_tokens,
    params,
    effective_from,
    effective_to,
    metadata,
    created_at,
    updated_at,
    provider_model_id AS provider_api_model_id
   FROM public.v2_route_capabilities capability;

CREATE VIEW "private"."v2_rpc_gateway_requests_compat" WITH (security_invoker=true) AS  SELECT fact.request_event_id AS id,
    fact.occurred_at AS created_at,
    fact.workspace_id AS team_id,
    fact.workspace_id,
    fact.request_id,
    fact.app_id,
    fact.endpoint,
    COALESCE(fact.routed_model_slug, fact.requested_model_slug, fact.requested_model_input) AS model_id,
    fact.requested_model_input AS requested_model_id,
    fact.routed_model_slug AS routed_model_id,
    COALESCE(fact.routed_model_slug, fact.requested_model_slug) AS canonical_model_id,
    route.provider_slug AS provider,
    fact.native_response_id,
    fact.stream,
    fact.byok,
    fact.status_code,
    fact.success,
    fact.error_code,
    (fact.safe_metadata ->> 'error_message'::text) AS error_message,
    fact.latency_ms,
    fact.generation_ms,
    fact.gateway_total_ms AS e2e_latency_ms,
    COALESCE(usage.payload, '{}'::jsonb) AS usage,
    (COALESCE(usage.total_tokens, (0)::numeric))::bigint AS usage_total_tokens,
    (COALESCE(((usage.payload ->> 'input_tokens'::text))::numeric, (0)::numeric))::bigint AS usage_input_tokens,
    (COALESCE(((usage.payload ->> 'output_tokens'::text))::numeric, (0)::numeric))::bigint AS usage_output_tokens,
    (COALESCE(((usage.payload ->> 'reasoning_tokens'::text))::numeric, (0)::numeric))::bigint AS usage_reasoning_tokens,
    (COALESCE(((usage.payload ->> 'input_text_tokens'::text))::numeric, (0)::numeric))::bigint AS usage_input_text_tokens,
    (COALESCE(((usage.payload ->> 'output_text_tokens'::text))::numeric, (0)::numeric))::bigint AS usage_output_text_tokens,
    (COALESCE(((usage.payload ->> 'input_image_tokens'::text))::numeric, (0)::numeric))::bigint AS usage_input_image_tokens,
    (COALESCE(((usage.payload ->> 'output_image_tokens'::text))::numeric, (0)::numeric))::bigint AS usage_output_image_tokens,
    (COALESCE(((usage.payload ->> 'input_audio_tokens'::text))::numeric, (0)::numeric))::bigint AS usage_input_audio_tokens,
    (COALESCE(((usage.payload ->> 'output_audio_tokens'::text))::numeric, (0)::numeric))::bigint AS usage_output_audio_tokens,
    (COALESCE(((usage.payload ->> 'input_video_tokens'::text))::numeric, (0)::numeric))::bigint AS usage_input_video_tokens,
    (COALESCE(((usage.payload ->> 'output_video_tokens'::text))::numeric, (0)::numeric))::bigint AS usage_output_video_tokens,
    (COALESCE(((usage.payload ->> 'image_inputs'::text))::numeric, (0)::numeric))::bigint AS usage_image_inputs,
    (COALESCE(((usage.payload ->> 'image_outputs'::text))::numeric, (0)::numeric))::bigint AS usage_image_outputs,
    (COALESCE(((usage.payload ->> 'audio_inputs'::text))::numeric, (0)::numeric))::bigint AS usage_audio_inputs,
    (COALESCE(((usage.payload ->> 'audio_outputs'::text))::numeric, (0)::numeric))::bigint AS usage_audio_outputs,
    (COALESCE(((usage.payload ->> 'video_inputs'::text))::numeric, (0)::numeric))::bigint AS usage_video_inputs,
    (COALESCE(((usage.payload ->> 'video_outputs'::text))::numeric, (0)::numeric))::bigint AS usage_video_outputs,
    (COALESCE(((usage.payload ->> 'cached_read_tokens'::text))::numeric, ((usage.payload ->> 'cached_input_tokens'::text))::numeric, (0)::numeric))::bigint AS usage_cached_read_tokens,
    (COALESCE(((usage.payload ->> 'cached_write_tokens'::text))::numeric, (0)::numeric))::bigint AS usage_cached_write_tokens,
    (COALESCE(((usage.payload ->> 'cached_read_text_tokens'::text))::numeric, (0)::numeric))::bigint AS usage_cached_read_text_tokens,
    (COALESCE(((usage.payload ->> 'cached_write_text_tokens'::text))::numeric, (0)::numeric))::bigint AS usage_cached_write_text_tokens,
    (COALESCE(((usage.payload ->> 'cached_write_text_tokens_5m'::text))::numeric, (0)::numeric))::bigint AS usage_cached_write_text_tokens_5m,
    (COALESCE(((usage.payload ->> 'cached_write_text_tokens_1h'::text))::numeric, (0)::numeric))::bigint AS usage_cached_write_text_tokens_1h,
    (COALESCE(((usage.payload ->> 'cached_read_image_tokens'::text))::numeric, (0)::numeric))::bigint AS usage_cached_read_image_tokens,
    (COALESCE(((usage.payload ->> 'cached_write_image_tokens'::text))::numeric, (0)::numeric))::bigint AS usage_cached_write_image_tokens,
    (COALESCE(((usage.payload ->> 'cached_read_audio_tokens'::text))::numeric, (0)::numeric))::bigint AS usage_cached_read_audio_tokens,
    (COALESCE(((usage.payload ->> 'cached_write_audio_tokens'::text))::numeric, (0)::numeric))::bigint AS usage_cached_write_audio_tokens,
    (COALESCE(((usage.payload ->> 'cached_read_video_tokens'::text))::numeric, (0)::numeric))::bigint AS usage_cached_read_video_tokens,
    (COALESCE(((usage.payload ->> 'cached_write_video_tokens'::text))::numeric, (0)::numeric))::bigint AS usage_cached_write_video_tokens,
    (COALESCE(((usage.payload ->> 'input_quad_tokens'::text))::numeric, (0)::numeric))::bigint AS usage_input_quad_tokens,
    (COALESCE(((usage.payload ->> 'output_quad_tokens'::text))::numeric, (0)::numeric))::bigint AS usage_output_quad_tokens,
    (COALESCE(((usage.payload ->> 'total_quad_tokens'::text))::numeric, (0)::numeric))::bigint AS usage_total_quad_tokens,
    (COALESCE(((usage.payload ->> 'text_quad_tokens'::text))::numeric, (0)::numeric))::bigint AS usage_text_quad_tokens,
    (COALESCE(((usage.payload ->> 'rerank_quad_tokens'::text))::numeric, (0)::numeric))::bigint AS usage_rerank_quad_tokens,
    (COALESCE(((usage.payload ->> 'embedding_quad_tokens'::text))::numeric, (0)::numeric))::bigint AS usage_embedding_quad_tokens,
    (COALESCE(((usage.payload ->> 'moderation_quad_tokens'::text))::numeric, (0)::numeric))::bigint AS usage_moderation_quad_tokens,
    (COALESCE(((usage.payload ->> 'ocr_quad_tokens'::text))::numeric, (0)::numeric))::bigint AS usage_ocr_quad_tokens,
    COALESCE(((usage.payload ->> 'image_megapixels'::text))::numeric, (0)::numeric) AS usage_image_megapixels,
    COALESCE(((usage.payload ->> 'audio_seconds'::text))::numeric, (0)::numeric) AS usage_audio_seconds,
    COALESCE(((usage.payload ->> 'video_pixel_seconds'::text))::numeric, (0)::numeric) AS usage_video_pixel_seconds,
    (COALESCE(((usage.payload ->> 'input_characters'::text))::numeric, (0)::numeric))::bigint AS usage_input_characters,
    (COALESCE(((usage.payload ->> 'output_characters'::text))::numeric, (0)::numeric))::bigint AS usage_output_characters,
    (COALESCE(((usage.payload ->> 'total_characters'::text))::numeric, (0)::numeric))::bigint AS usage_total_characters,
    fact.occurred_at AS usage_normalized_at,
    fact.cost_nanos,
    fact.currency,
    COALESCE(pricing.payload, '[]'::jsonb) AS pricing_lines,
    fact.key_id,
    fact.throughput,
    COALESCE(fact.cloudflare_colo, fact.region) AS location,
    fact.auth_method,
    (fact.safe_metadata ->> 'oauth_client_id'::text) AS oauth_client_id,
    (NULLIF((fact.safe_metadata ->> 'oauth_user_id'::text), ''::text))::uuid AS oauth_user_id,
    fact.end_user_id,
    fact.session_id,
    (fact.safe_metadata -> 'trace_data'::text) AS trace_data,
    COALESCE(attempts.payload, '[]'::jsonb) AS provider_attempts,
    fact.stop_reason,
    fact.stop_reason AS finish_reason,
    fact.tool_call_count,
    fact.structured_output_attempted,
    fact.structured_output_succeeded,
    fact.cloudflare_colo
   FROM ((((public.v2_request_facts fact
     LEFT JOIN public.v2_model_provider_routes route ON ((route.provider_model_id = fact.provider_model_id)))
     LEFT JOIN LATERAL ( SELECT jsonb_object_agg(grouped_usage.meter_key, grouped_usage.quantity) AS payload,
            sum(grouped_usage.quantity) FILTER (WHERE (grouped_usage.meter_key = ANY (ARRAY['input_tokens'::text, 'output_tokens'::text]))) AS total_tokens
           FROM ( SELECT request_usage.meter_key,
                    sum(request_usage.quantity) AS quantity
                   FROM public.v2_request_usage request_usage
                  WHERE (request_usage.request_event_id = fact.request_event_id)
                  GROUP BY request_usage.meter_key) grouped_usage) usage ON (true))
     LEFT JOIN LATERAL ( SELECT jsonb_agg(jsonb_build_object('sku_id', line.sku_id, 'sku_meter_id', line.sku_meter_id, 'meter', line.meter_key, 'quantity', line.quantity, 'unit', line.unit, 'unit_price_nanos', line.unit_price_nanos, 'cost_nanos', line.charged_nanos) ORDER BY line.created_at, line.pricing_line_id) AS payload
           FROM public.v2_request_pricing_lines line
          WHERE (line.request_event_id = fact.request_event_id)) pricing ON (true))
     LEFT JOIN LATERAL ( SELECT jsonb_agg(jsonb_build_object('attempt', attempt.attempt_number, 'provider_model_id', attempt.provider_model_id, 'provider', attempt_route.provider_slug, 'started_at', attempt.started_at, 'completed_at', attempt.completed_at, 'status_code', attempt.status_code, 'success', attempt.success, 'error_code', attempt.error_code, 'failure_class', attempt.failure_class, 'latency_ms', attempt.latency_ms) ORDER BY attempt.attempt_number) AS payload
           FROM (public.v2_request_attempts attempt
             LEFT JOIN public.v2_model_provider_routes attempt_route ON ((attempt_route.provider_model_id = attempt.provider_model_id)))
          WHERE (attempt.request_event_id = fact.request_event_id)) attempts ON (true));

CREATE VIEW "private"."v2_rpc_labs_compat" WITH (security_invoker=true) AS  SELECT lab_slug,
    name,
    country_code,
    description,
    status,
    routable,
    metadata,
    created_at,
    updated_at,
    lab_slug AS organisation_id,
    (metadata ->> 'colour'::text) AS colour,
    (metadata ->> 'link'::text) AS link
   FROM public.v2_labs lab;

CREATE VIEW "private"."v2_rpc_models_compat" WITH (security_invoker=true) AS  SELECT model_slug,
    lab_slug,
    name,
    description,
    status,
    hidden,
    input_modalities,
    output_modalities,
    family_slug,
    announced_at,
    released_at,
    deprecated_at,
    retired_at,
    metadata,
    created_at,
    updated_at,
    license,
    license_url,
    previous_model_slug,
    removal_date,
    replacement_model_slug,
    variant_kind,
    base_model_slug,
    model_slug AS model_id,
    model_slug AS api_model_id,
    lab_slug AS organisation_id,
    previous_model_slug AS previous_model_id,
    announced_at AS announcement_date,
    released_at AS release_date,
    deprecated_at AS deprecation_date,
    retired_at AS retirement_date,
    array_to_string(input_modalities, ','::text) AS input_types,
    array_to_string(output_modalities, ','::text) AS output_types,
    family_slug AS family_id,
    (metadata -> 'timeline'::text) AS timeline
   FROM public.v2_models model;

CREATE VIEW "private"."v2_rpc_pricing_compat" WITH (security_invoker=true) AS  SELECT (meter.sku_meter_id)::text AS rule_id,
    route.provider_slug AS provider_id,
    route.model_slug AS api_model_id,
    ((((route.provider_slug || ':'::text) || route.model_slug) || ':'::text) || sku.operation) AS model_key,
    sku.operation AS capability_id,
    COALESCE(sku.service_tier_slug, 'standard'::text) AS pricing_plan,
    meter.meter_key AS meter,
    meter.unit,
    meter.unit_quantity AS unit_size,
    (meter.price_nanos / 1000000000.0) AS price_per_unit,
    sku.currency,
    meter.meter_order AS priority,
    sku.effective_from,
    sku.effective_to,
    COALESCE((sku.metadata -> 'match'::text), (meter.metadata -> 'match'::text), '[]'::jsonb) AS match,
    COALESCE((sku.metadata ->> 'billing_timestamp_basis'::text), 'request_start'::text) AS billing_timestamp_basis,
    COALESCE((sku.metadata -> 'time_windows'::text), '[]'::jsonb) AS time_windows,
    COALESCE((meter.metadata ->> 'note'::text), sku.description) AS note,
    GREATEST(sku.created_at, meter.created_at) AS created_at,
    GREATEST(sku.updated_at, meter.updated_at) AS updated_at
   FROM ((public.v2_pricing_skus sku
     JOIN public.v2_model_provider_routes route ON ((route.provider_model_id = sku.provider_model_id)))
     JOIN public.v2_pricing_sku_meters meter ON ((meter.sku_id = sku.sku_id)))
  WHERE meter.billable;

CREATE VIEW "private"."v2_rpc_providers_compat" AS  SELECT provider_slug,
    lab_slug,
    name,
    status,
    routing_enabled,
    routable,
    country_code,
    base_url,
    metadata,
    created_at,
    updated_at,
    provider_family_slug,
    offer_scope,
    offer_label,
    residency_mode,
    default_execution_regions,
    default_data_regions,
    zero_data_retention,
    prompt_training_policy,
    data_policy_tier,
    data_policy_confidence,
    data_policy_contract_mode,
    data_policy_variant,
    stream_cancellation_support,
    stream_cancellation_stops_provider_billing,
    stream_cancellation_usage_recovery,
    stream_cancellation_evidence_kind,
    stream_cancellation_source_url,
    stream_cancellation_verified_at,
    provider_slug AS api_provider_id,
    name AS api_provider_name,
    lab_slug AS organisation_id,
        CASE
            WHEN routing_enabled THEN 'active'::text
            ELSE 'disabled'::text
        END AS routing_status,
    (metadata ->> 'description'::text) AS description,
    COALESCE((metadata ->> 'link'::text), base_url) AS link,
    (metadata ->> 'colour'::text) AS colour,
    (metadata ->> 'pricing_source_url'::text) AS pricing_source_url,
    (metadata ->> 'privacy_policy_url'::text) AS privacy_policy_url,
    (metadata ->> 'terms_of_service_url'::text) AS terms_of_service_url
   FROM public.v2_providers provider;

CREATE VIEW "private"."v2_rpc_routes_compat" WITH (security_invoker=true) AS  SELECT provider_model_id,
    model_slug,
    provider_slug,
    provider_model_slug,
    status,
    routing_enabled,
    input_modalities,
    output_modalities,
    regions,
    context_length,
    max_output_tokens,
    effective_from,
    effective_to,
    metadata,
    created_at,
    updated_at,
    provider_model_id AS provider_api_model_id,
    provider_slug AS provider_id,
    model_slug AS api_model_id,
    model_slug AS model_id,
    model_slug AS internal_model_id,
    routing_enabled AS is_active_gateway,
    status AS routing_status,
    (metadata ->> 'quantization_scheme'::text) AS quantization_scheme,
    (metadata ->> 'prompt_training_policy_override'::text) AS prompt_training_policy_override,
    (metadata ->> 'prompt_training_override_notes'::text) AS prompt_training_override_notes,
    (metadata ->> 'prompt_training_override_source_url'::text) AS prompt_training_override_source_url
   FROM public.v2_model_provider_routes route;

CREATE VIEW "private"."v2_rpc_subscription_features_compat" WITH (security_invoker=true) AS  SELECT plan_uuid,
    feature_name,
    feature_value,
    feature_description,
    other_info
   FROM public.v2_subscription_plan_features feature;

CREATE VIEW "private"."v2_rpc_subscription_models_compat" WITH (security_invoker=true) AS  SELECT plan_uuid,
    model_slug,
    model_info,
    rate_limit,
    other_info,
    model_slug AS model_id
   FROM public.v2_subscription_plan_models relation;

CREATE VIEW "private"."v2_rpc_subscription_plans_compat" WITH (security_invoker=true) AS  SELECT plan_uuid,
    plan_id,
    name,
    lab_slug,
    description,
    frequency,
    price,
    currency,
    link,
    other_info,
    created_at,
    updated_at,
    lab_slug AS organisation_id
   FROM public.v2_subscription_plans plan;

CREATE VIEW "public"."oauth_apps_with_stats" WITH (security_invoker=true) AS  SELECT oam.id,
    oam.client_id,
    oam.workspace_id,
    oam.name,
    oam.description,
    oam.homepage_url,
    oam.logo_url,
    oam.privacy_policy_url,
    oam.terms_of_service_url,
    oam.created_by,
    oam.created_at,
    oam.updated_at,
    oam.status,
    oam.redirect_uris,
    count(DISTINCT oa.id) FILTER (WHERE (oa.revoked_at IS NULL)) AS active_authorizations,
    count(DISTINCT oa.id) AS total_authorizations,
    max(oa.last_used_at) AS last_used_at,
    count(DISTINCT gr.id) AS requests_last_30d
   FROM ((public.oauth_app_metadata oam
     LEFT JOIN public.oauth_authorizations oa ON ((oa.client_id = oam.client_id)))
     LEFT JOIN public.gateway_requests gr ON (((gr.oauth_client_id = oam.client_id) AND (gr.created_at > (now() - '30 days'::interval)))))
  WHERE (oam.status = 'active'::text)
  GROUP BY oam.id;

CREATE VIEW "public"."v2_rpc_gateway_activity_rollup_daily" WITH (security_invoker=true) AS  SELECT usage.usage_date AS day_bucket,
    usage.workspace_id AS team_id,
    usage.model_slug AS model_id,
    'unknown'::text AS endpoint,
    route.provider_slug AS provider,
    (0)::bigint AS usage_nanos,
    (0)::bigint AS byok_usage_nanos,
    usage.requests,
    (0)::bigint AS prompt_tokens,
    (0)::bigint AS completion_tokens,
    (0)::bigint AS reasoning_tokens,
    usage.updated_at
   FROM (public.v2_private_usage_daily usage
     LEFT JOIN public.v2_model_provider_routes route ON ((route.provider_model_id = usage.provider_model_id)));

CREATE VIEW "public"."v2_rpc_gateway_model_usage_daily" WITH (security_invoker=true) AS  SELECT usage.usage_date AS day_bucket,
    usage.model_slug AS model_id,
    route.provider_slug AS provider_id,
    'unknown'::text AS endpoint,
    usage.requests,
    usage.successful_requests AS success_requests,
    usage.failed_requests,
    (0)::bigint AS neutral_requests,
    usage.rate_limited_requests,
    (COALESCE(((meters."values" ->> 'total_tokens'::text))::numeric, (((meters."values" ->> 'input_tokens'::text))::numeric + ((meters."values" ->> 'output_tokens'::text))::numeric), (((meters."values" ->> 'input_text_tokens'::text))::numeric + ((meters."values" ->> 'output_text_tokens'::text))::numeric), (0)::numeric))::bigint AS total_tokens,
    (COALESCE(((meters."values" ->> 'input_tokens'::text))::numeric, ((meters."values" ->> 'input_text_tokens'::text))::numeric, (0)::numeric))::bigint AS input_tokens,
    (COALESCE(((meters."values" ->> 'output_tokens'::text))::numeric, ((meters."values" ->> 'output_text_tokens'::text))::numeric, (0)::numeric))::bigint AS output_tokens,
    (COALESCE(((meters."values" ->> 'reasoning_tokens'::text))::numeric, (0)::numeric))::bigint AS reasoning_tokens,
    (COALESCE(((meters."values" ->> 'input_text_tokens'::text))::numeric, (0)::numeric))::bigint AS input_text_tokens,
    (COALESCE(((meters."values" ->> 'output_text_tokens'::text))::numeric, (0)::numeric))::bigint AS output_text_tokens,
    (COALESCE(((meters."values" ->> 'input_image_tokens'::text))::numeric, (0)::numeric))::bigint AS input_image_tokens,
    (COALESCE(((meters."values" ->> 'output_image_tokens'::text))::numeric, (0)::numeric))::bigint AS output_image_tokens,
    (COALESCE(((meters."values" ->> 'input_audio_tokens'::text))::numeric, (0)::numeric))::bigint AS input_audio_tokens,
    (COALESCE(((meters."values" ->> 'output_audio_tokens'::text))::numeric, (0)::numeric))::bigint AS output_audio_tokens,
    (COALESCE(((meters."values" ->> 'input_video_tokens'::text))::numeric, (0)::numeric))::bigint AS input_video_tokens,
    (COALESCE(((meters."values" ->> 'output_video_tokens'::text))::numeric, (0)::numeric))::bigint AS output_video_tokens,
    (COALESCE(((meters."values" ->> 'image_inputs'::text))::numeric, ((meters."values" ->> 'input_images'::text))::numeric, (0)::numeric))::bigint AS image_inputs,
    (COALESCE(((meters."values" ->> 'image_outputs'::text))::numeric, ((meters."values" ->> 'output_images'::text))::numeric, (0)::numeric))::bigint AS image_outputs,
    (COALESCE(((meters."values" ->> 'audio_inputs'::text))::numeric, ((meters."values" ->> 'input_audio'::text))::numeric, (0)::numeric))::bigint AS audio_inputs,
    (COALESCE(((meters."values" ->> 'audio_outputs'::text))::numeric, ((meters."values" ->> 'output_audio'::text))::numeric, (0)::numeric))::bigint AS audio_outputs,
    (COALESCE(((meters."values" ->> 'video_inputs'::text))::numeric, ((meters."values" ->> 'input_video'::text))::numeric, (0)::numeric))::bigint AS video_inputs,
    (COALESCE(((meters."values" ->> 'video_outputs'::text))::numeric, ((meters."values" ->> 'output_video'::text))::numeric, (0)::numeric))::bigint AS video_outputs,
    (COALESCE(((meters."values" ->> 'cached_read_tokens'::text))::numeric, ((meters."values" ->> 'cached_input_tokens'::text))::numeric, (0)::numeric))::bigint AS cached_read_tokens,
    (COALESCE(((meters."values" ->> 'cached_write_tokens'::text))::numeric, ((meters."values" ->> 'cache_write_tokens'::text))::numeric, (0)::numeric))::bigint AS cached_write_tokens,
    (COALESCE(((meters."values" ->> 'cached_read_text_tokens'::text))::numeric, (0)::numeric))::bigint AS cached_read_text_tokens,
    (COALESCE(((meters."values" ->> 'cached_write_text_tokens'::text))::numeric, (0)::numeric))::bigint AS cached_write_text_tokens,
    (COALESCE(((meters."values" ->> 'cached_read_image_tokens'::text))::numeric, (0)::numeric))::bigint AS cached_read_image_tokens,
    (COALESCE(((meters."values" ->> 'cached_write_image_tokens'::text))::numeric, (0)::numeric))::bigint AS cached_write_image_tokens,
    (COALESCE(((meters."values" ->> 'cached_read_audio_tokens'::text))::numeric, (0)::numeric))::bigint AS cached_read_audio_tokens,
    (COALESCE(((meters."values" ->> 'cached_write_audio_tokens'::text))::numeric, (0)::numeric))::bigint AS cached_write_audio_tokens,
    (COALESCE(((meters."values" ->> 'cached_read_video_tokens'::text))::numeric, (0)::numeric))::bigint AS cached_read_video_tokens,
    (COALESCE(((meters."values" ->> 'cached_write_video_tokens'::text))::numeric, (0)::numeric))::bigint AS cached_write_video_tokens,
    (0)::bigint AS total_cost_nanos,
    usage.latency_sum_ms,
    usage.latency_count AS latency_samples,
    usage.generation_sum_ms,
    usage.generation_count AS generation_samples,
    usage.throughput_sum,
    usage.throughput_count AS throughput_samples,
    usage.updated_at AS last_request_at,
    usage.updated_at AS refreshed_at,
    (COALESCE(((meters."values" ->> 'input_quad_tokens'::text))::numeric, (0)::numeric))::bigint AS input_quad_tokens,
    (COALESCE(((meters."values" ->> 'output_quad_tokens'::text))::numeric, (0)::numeric))::bigint AS output_quad_tokens,
    (COALESCE(((meters."values" ->> 'total_quad_tokens'::text))::numeric, (0)::numeric))::bigint AS total_quad_tokens,
    (COALESCE(((meters."values" ->> 'cached_write_text_tokens_5m'::text))::numeric, (0)::numeric))::bigint AS cached_write_text_tokens_5m,
    (COALESCE(((meters."values" ->> 'cached_write_text_tokens_1h'::text))::numeric, (0)::numeric))::bigint AS cached_write_text_tokens_1h,
    (COALESCE(((meters."values" ->> 'text_quad_tokens'::text))::numeric, (0)::numeric))::bigint AS text_quad_tokens,
    (COALESCE(((meters."values" ->> 'rerank_quad_tokens'::text))::numeric, (0)::numeric))::bigint AS rerank_quad_tokens,
    (COALESCE(((meters."values" ->> 'embedding_quad_tokens'::text))::numeric, (0)::numeric))::bigint AS embedding_quad_tokens,
    (COALESCE(((meters."values" ->> 'moderation_quad_tokens'::text))::numeric, (0)::numeric))::bigint AS moderation_quad_tokens,
    (COALESCE(((meters."values" ->> 'ocr_quad_tokens'::text))::numeric, (0)::numeric))::bigint AS ocr_quad_tokens,
    COALESCE(((meters."values" ->> 'image_megapixels'::text))::numeric, (0)::numeric) AS image_megapixels,
    COALESCE(((meters."values" ->> 'audio_seconds'::text))::numeric, (0)::numeric) AS audio_seconds,
    COALESCE(((meters."values" ->> 'video_pixel_seconds'::text))::numeric, (0)::numeric) AS video_pixel_seconds,
    (COALESCE(((meters."values" ->> 'input_characters'::text))::numeric, (0)::numeric))::bigint AS input_characters,
    (COALESCE(((meters."values" ->> 'output_characters'::text))::numeric, (0)::numeric))::bigint AS output_characters,
    (COALESCE(((meters."values" ->> 'total_characters'::text))::numeric, (0)::numeric))::bigint AS total_characters,
    (COALESCE(((meters."values" ->> 'embedding_tokens'::text))::numeric, (0)::numeric))::bigint AS embedding_tokens,
    COALESCE(((meters."values" ->> 'video_seconds'::text))::numeric, ((meters."values" ->> 'output_video_seconds'::text))::numeric, (0)::numeric) AS video_seconds,
    COALESCE(((meters."values" ->> 'speech_seconds'::text))::numeric, (0)::numeric) AS speech_seconds,
    COALESCE(((meters."values" ->> 'transcription_seconds'::text))::numeric, (0)::numeric) AS transcription_seconds
   FROM (((public.v2_public_usage_daily usage
     JOIN public.v2_model_provider_routes route ON (((route.provider_model_id = usage.provider_model_id) AND (COALESCE(route.is_stealth, false) = false) AND (route.routing_enabled = true) AND (route.status = ANY (ARRAY['active'::text, 'degraded'::text])) AND ((route.effective_from IS NULL) OR (route.effective_from <= now())) AND ((route.effective_to IS NULL) OR (route.effective_to > now())))))
     JOIN public.v2_models model ON (((model.model_slug = usage.model_slug) AND (model.hidden = false) AND (model.status <> 'disabled'::text))))
     LEFT JOIN LATERAL ( SELECT jsonb_object_agg(meter.meter_key, meter.quantity) AS "values"
           FROM ( SELECT v2_public_usage_daily_meters.meter_key,
                    sum(v2_public_usage_daily_meters.quantity) AS quantity
                   FROM public.v2_public_usage_daily_meters
                  WHERE (v2_public_usage_daily_meters.rollup_id = usage.rollup_id)
                  GROUP BY v2_public_usage_daily_meters.meter_key) meter) meters ON (true));

CREATE VIEW "public"."v2_web_gateway_requests" WITH (security_invoker=true) AS  SELECT request_row.id,
    request_row.created_at,
    request_row.team_id,
    request_row.workspace_id,
    request_row.request_id,
    request_row.app_id,
    request_row.endpoint,
    request_row.model_id,
    request_row.requested_model_id,
    request_row.routed_model_id,
    request_row.canonical_model_id,
    request_row.provider,
    request_row.native_response_id,
    request_row.stream,
    request_row.byok,
    request_row.status_code,
    request_row.success,
    request_row.error_code,
    request_row.error_message,
    request_row.latency_ms,
    request_row.generation_ms,
    request_row.e2e_latency_ms,
    request_row.usage,
    request_row.usage_total_tokens,
    request_row.usage_input_tokens,
    request_row.usage_output_tokens,
    request_row.usage_reasoning_tokens,
    request_row.usage_input_text_tokens,
    request_row.usage_output_text_tokens,
    request_row.usage_input_image_tokens,
    request_row.usage_output_image_tokens,
    request_row.usage_input_audio_tokens,
    request_row.usage_output_audio_tokens,
    request_row.usage_input_video_tokens,
    request_row.usage_output_video_tokens,
    request_row.usage_image_inputs,
    request_row.usage_image_outputs,
    request_row.usage_audio_inputs,
    request_row.usage_audio_outputs,
    request_row.usage_video_inputs,
    request_row.usage_video_outputs,
    request_row.usage_cached_read_tokens,
    request_row.usage_cached_write_tokens,
    request_row.usage_cached_read_text_tokens,
    request_row.usage_cached_write_text_tokens,
    request_row.usage_cached_write_text_tokens_5m,
    request_row.usage_cached_write_text_tokens_1h,
    request_row.usage_cached_read_image_tokens,
    request_row.usage_cached_write_image_tokens,
    request_row.usage_cached_read_audio_tokens,
    request_row.usage_cached_write_audio_tokens,
    request_row.usage_cached_read_video_tokens,
    request_row.usage_cached_write_video_tokens,
    request_row.usage_input_quad_tokens,
    request_row.usage_output_quad_tokens,
    request_row.usage_total_quad_tokens,
    request_row.usage_text_quad_tokens,
    request_row.usage_rerank_quad_tokens,
    request_row.usage_embedding_quad_tokens,
    request_row.usage_moderation_quad_tokens,
    request_row.usage_ocr_quad_tokens,
    request_row.usage_image_megapixels,
    request_row.usage_audio_seconds,
    request_row.usage_video_pixel_seconds,
    request_row.usage_input_characters,
    request_row.usage_output_characters,
    request_row.usage_total_characters,
    request_row.usage_normalized_at,
    request_row.cost_nanos,
    request_row.currency,
    request_row.pricing_lines,
    request_row.key_id,
    request_row.throughput,
    request_row.location,
    request_row.auth_method,
    request_row.oauth_client_id,
    request_row.oauth_user_id,
    request_row.end_user_id,
    request_row.session_id,
    request_row.trace_data,
    request_row.provider_attempts,
    request_row.stop_reason,
    request_row.finish_reason,
    request_row.tool_call_count,
    request_row.structured_output_attempted,
    request_row.structured_output_succeeded,
    request_row.cloudflare_colo,
    (fact.safe_metadata -> 'error_payload'::text) AS error_payload,
    fact.safe_metadata AS detail_metadata,
    fact.client_source_id,
    fact.client_source_name,
    fact.client_source_kind,
    fact.client_source_version,
    fact.client_source_detection
   FROM (private.v2_rpc_gateway_requests_compat request_row
     JOIN public.v2_request_facts fact ON ((fact.request_event_id = request_row.id)));

CREATE VIEW "public"."v2_web_private_usage_daily" WITH (security_invoker=true) AS  SELECT (usage.usage_date)::timestamp with time zone AS bucket_15m,
    usage.workspace_id,
    usage.model_slug AS canonical_model_id,
    route.provider_slug AS provider,
    usage.app_id,
    usage.requests,
    usage.successful_requests AS success_requests,
    (usage.cost_nanos)::bigint AS total_cost_nanos,
    usage.latency_sum_ms,
    usage.latency_count AS latency_samples,
    usage.throughput_sum,
    usage.throughput_count AS throughput_samples,
    COALESCE(meters.total_tokens, (0)::numeric) AS total_tokens
   FROM ((public.v2_private_usage_daily usage
     LEFT JOIN public.v2_model_provider_routes route ON ((route.provider_model_id = usage.provider_model_id)))
     LEFT JOIN LATERAL ( SELECT COALESCE(max(meter.quantity) FILTER (WHERE (meter.meter_key = 'total_tokens'::text)), sum(meter.quantity) FILTER (WHERE (meter.meter_key = ANY (ARRAY['input_tokens'::text, 'output_tokens'::text, 'input_text_tokens'::text, 'output_text_tokens'::text]))), (0)::numeric) AS total_tokens
           FROM public.v2_private_usage_daily_meters meter
          WHERE (meter.rollup_id = usage.rollup_id)) meters ON (true));

CREATE VIEW "public"."v2_web_public_usage_daily" WITH (security_invoker=true) AS  WITH meters AS (
         SELECT meter.rollup_id,
            COALESCE(max(meter.quantity) FILTER (WHERE (meter.meter_key = 'total_tokens'::text)), sum(meter.quantity) FILTER (WHERE (meter.meter_key = ANY (ARRAY['input_tokens'::text, 'output_tokens'::text]))), sum(meter.quantity) FILTER (WHERE (meter.meter_key = ANY (ARRAY['input_text_tokens'::text, 'output_text_tokens'::text]))), (0)::numeric) AS total_tokens
           FROM public.v2_public_usage_daily_meters meter
          GROUP BY meter.rollup_id
        )
 SELECT usage.usage_date AS day_bucket,
    usage.model_slug AS canonical_model_id,
    route.provider_slug AS provider,
    usage.app_id,
    usage.requests,
    usage.successful_requests AS success_requests,
    COALESCE(meters.total_tokens, (0)::numeric) AS total_tokens,
    (usage.cost_nanos)::bigint AS total_cost_nanos,
    usage.latency_sum_ms,
    usage.latency_count AS latency_samples,
    usage.throughput_sum,
    usage.throughput_count AS throughput_samples,
    usage.generation_sum_ms,
    usage.generation_count AS generation_samples
   FROM (((public.v2_public_usage_daily usage
     JOIN public.v2_model_provider_routes route ON (((route.provider_model_id = usage.provider_model_id) AND (COALESCE(route.is_stealth, false) = false) AND (route.routing_enabled = true) AND (route.status = ANY (ARRAY['active'::text, 'degraded'::text])) AND ((route.effective_from IS NULL) OR (route.effective_from <= now())) AND ((route.effective_to IS NULL) OR (route.effective_to > now())))))
     JOIN public.v2_models model ON (((model.model_slug = usage.model_slug) AND (model.hidden = false) AND (model.status <> 'disabled'::text))))
     LEFT JOIN meters ON ((meters.rollup_id = usage.rollup_id)));

CREATE VIEW "public"."v2_rpc_gateway_usage_rollup_daily_app" WITH (security_invoker=true) AS  SELECT (day_bucket)::timestamp with time zone AS day_bucket,
    app_id,
    (sum(requests))::bigint AS requests,
    (sum(success_requests))::bigint AS success_requests,
    (sum(total_tokens))::bigint AS total_tokens,
    (sum(total_cost_nanos))::bigint AS total_cost_nanos,
    (count(DISTINCT canonical_model_id))::integer AS unique_models
   FROM public.v2_web_public_usage_daily usage
  WHERE (app_id IS NOT NULL)
  GROUP BY day_bucket, app_id;

CREATE VIEW "public"."v2_rpc_public_app_model_usage_daily" WITH (security_invoker=true) AS  SELECT usage.day_bucket,
    (usage.app_id)::text AS app_id,
    usage.canonical_model_id AS model_id,
    usage.requests,
    (usage.total_tokens)::bigint AS tokens,
    now() AS refreshed_at
   FROM (public.v2_web_public_usage_daily usage
     JOIN public.api_apps app ON (((app.id = usage.app_id) AND (app.is_public = true))));

CREATE VIEW "public"."v2_web_public_usage_hourly" WITH (security_invoker=true) AS  WITH meters AS (
         SELECT meter.rollup_id,
            COALESCE(max(meter.quantity) FILTER (WHERE (meter.meter_key = 'total_tokens'::text)), sum(meter.quantity) FILTER (WHERE (meter.meter_key = ANY (ARRAY['input_tokens'::text, 'output_tokens'::text]))), sum(meter.quantity) FILTER (WHERE (meter.meter_key = ANY (ARRAY['input_text_tokens'::text, 'output_text_tokens'::text]))), (0)::numeric) AS total_tokens
           FROM public.v2_public_usage_hourly_meters meter
          GROUP BY meter.rollup_id
        )
 SELECT usage.bucket_start AS bucket_15m,
    usage.model_slug AS canonical_model_id,
    route.provider_slug AS provider,
    usage.app_id,
    usage.requests,
    usage.successful_requests AS success_requests,
    COALESCE(meters.total_tokens, (0)::numeric) AS total_tokens,
    (usage.cost_nanos)::bigint AS total_cost_nanos,
    usage.latency_sum_ms,
    usage.latency_count AS latency_samples,
    usage.throughput_sum,
    usage.throughput_count AS throughput_samples,
    usage.generation_sum_ms,
    usage.generation_count AS generation_samples
   FROM (((public.v2_public_usage_hourly usage
     JOIN public.v2_model_provider_routes route ON (((route.provider_model_id = usage.provider_model_id) AND (COALESCE(route.is_stealth, false) = false) AND (route.routing_enabled = true) AND (route.status = ANY (ARRAY['active'::text, 'degraded'::text])) AND ((route.effective_from IS NULL) OR (route.effective_from <= now())) AND ((route.effective_to IS NULL) OR (route.effective_to > now())))))
     JOIN public.v2_models model ON (((model.model_slug = usage.model_slug) AND (model.hidden = false) AND (model.status <> 'disabled'::text))))
     LEFT JOIN meters ON ((meters.rollup_id = usage.rollup_id)));

