CREATE EVENT TRIGGER "ensure_rls"
  ON ddl_command_end
  WHEN TAG IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
  EXECUTE FUNCTION "public"."rls_auto_enable"();

COMMENT ON COLUMN "public"."byok_keys"."allowed_api_key_ids" IS 'Null or empty allows every workspace API key; otherwise only requests authenticated by a listed API key may use this credential.';

COMMENT ON COLUMN "public"."byok_keys"."allowed_model_slugs" IS 'Null or empty allows every model routed through this provider; otherwise only listed canonical model slugs may use this credential.';

COMMENT ON COLUMN "public"."byok_keys"."enc_aad_version" IS 'AES-GCM associated-data format. Version 1 binds ciphertext to workspace, provider, and key version; 0 identifies legacy rows.';

COMMENT ON COLUMN "public"."email_outbox"."dedupe_key" IS 'Stable event identity used to suppress duplicate transactional email delivery.';

COMMENT ON COLUMN "public"."gateway_async_operations"."internal_id" IS 'Gateway-facing identifier used on retrieval routes (e.g. /videos/{id}, /batches/{id}).';

COMMENT ON COLUMN "public"."gateway_async_operations"."last_reconcile_error" IS 'Last reconciliation error summary, cleared after a successful attempt.';

COMMENT ON COLUMN "public"."gateway_async_operations"."native_id" IS 'Provider-native operation identifier for upstream polling APIs.';

COMMENT ON COLUMN "public"."gateway_async_operations"."next_reconcile_at" IS 'Next time a scheduled reconciler should claim this async operation for provider status refresh/finalization.';

COMMENT ON COLUMN "public"."gateway_async_operations"."reconcile_attempts" IS 'Number of reconciliation claim attempts. Used for bounded retry backoff.';

COMMENT ON COLUMN "public"."gateway_async_operations"."reconcile_locked_at" IS 'Lease timestamp set by claim_gateway_async_operations_for_reconciliation to avoid duplicate workers.';

COMMENT ON COLUMN "public"."gateway_async_operations"."reconcile_locked_by" IS 'Worker identifier holding the current reconciliation lease.';

COMMENT ON COLUMN "public"."gateway_async_operations"."request_id" IS 'Gateway request_id that initiated this async operation.';

COMMENT ON COLUMN "public"."gateway_async_operations"."session_id" IS 'Session identifier copied from the originating request for grouping.';

COMMENT ON COLUMN "public"."gateway_feedback"."metadata" IS 'Arbitrary developer-supplied feedback metadata. Use metadata_dimensions for bounded indexed cohort filters.';

COMMENT ON COLUMN "public"."gateway_feedback"."metadata_dimensions" IS 'Bounded flat string map for indexed preset feedback comparison filters such as user_tier, region, plan, cohort, or app_version.';

COMMENT ON COLUMN "public"."gateway_observability_events"."metadata_dimensions" IS 'Bounded flat string map for indexed cohort and segment filters. Full arbitrary metadata remains in metadata.';

COMMENT ON COLUMN "public"."gateway_requests"."api_model_id" IS 'Concrete provider API model id executed for this request, preserving variants such as :free, -fast, or -flex.';

COMMENT ON COLUMN "public"."gateway_requests"."auth_method" IS 'Authentication method used for the request: api_key (legacy HMAC keys) or oauth (JWT tokens)';

COMMENT ON COLUMN "public"."gateway_requests"."detail_metadata" IS 'Request-level routing, provider, guardrail, and plugin diagnostics for observability detail views.';

COMMENT ON COLUMN "public"."gateway_requests"."end_user_id" IS 'Caller-supplied user identifier for trace/session analytics (for example request.user).';

COMMENT ON COLUMN "public"."gateway_requests"."error_payload" IS 'Sanitized structured gateway error payload captured for failed requests, used by request/session/job investigation surfaces.';

COMMENT ON COLUMN "public"."gateway_requests"."finish_reason" IS 'Normalized finish reason across all providers (e.g., stop, length, tool_calls, content_filter, error)';

COMMENT ON COLUMN "public"."gateway_requests"."is_free_variant" IS 'True when the executed request used a free model or free pricing plan.';

COMMENT ON COLUMN "public"."gateway_requests"."itl_ms" IS 'Mean observed interval in milliseconds between successive content-bearing provider stream frames.';

COMMENT ON COLUMN "public"."gateway_requests"."oauth_client_id" IS 'OAuth client ID if auth_method is oauth';

COMMENT ON COLUMN "public"."gateway_requests"."oauth_user_id" IS 'User ID who authorized the OAuth app (from JWT claims)';

COMMENT ON COLUMN "public"."gateway_requests"."pricing_plan" IS 'Pricing plan selected by the gateway pricing engine for this request, such as standard, free, priority, flex, or batch.';

COMMENT ON COLUMN "public"."gateway_requests"."provider_attempts" IS 'Gateway-captured provider routing attempts for this request, including failures, statuses, durations, and upstream error summaries.';

COMMENT ON COLUMN "public"."gateway_requests"."requested_model_id" IS 'Original model id requested by the client before any routing or router expansion.';

COMMENT ON COLUMN "public"."gateway_requests"."routed_model_id" IS 'Concrete routed model id chosen for execution. For non-router requests this typically matches the requested model.';

COMMENT ON COLUMN "public"."gateway_requests"."session_id" IS 'Caller-supplied session identifier for grouping related requests.';

COMMENT ON COLUMN "public"."gateway_requests"."trace_data" IS 'Arbitrary caller-supplied trace key-value metadata for observability.';

COMMENT ON COLUMN "public"."gateway_requests"."usage_audio_seconds" IS 'Provider-independent audio workload in seconds.';

COMMENT ON COLUMN "public"."gateway_requests"."usage_embedding_tokens" IS 'Native embedding endpoint token count from provider usage metadata.';

COMMENT ON COLUMN "public"."gateway_requests"."usage_image_inputs" IS 'Normalized per-request count of image inputs when providers expose a count.';

COMMENT ON COLUMN "public"."gateway_requests"."usage_image_megapixels" IS 'Provider-independent image workload in megapixels when dimensions are known.';

COMMENT ON COLUMN "public"."gateway_requests"."usage_image_outputs" IS 'Normalized per-request count of image outputs when providers expose a count.';

COMMENT ON COLUMN "public"."gateway_requests"."usage_input_image_tokens" IS 'Normalized per-request image input tokens.';

COMMENT ON COLUMN "public"."gateway_requests"."usage_input_quad_tokens" IS 'Provider-independent input quadtokens, calculated as ceil(input text characters / 4).';

COMMENT ON COLUMN "public"."gateway_requests"."usage_input_tokens" IS 'Normalized per-request input tokens across modalities.';

COMMENT ON COLUMN "public"."gateway_requests"."usage_output_image_tokens" IS 'Normalized per-request image output tokens.';

COMMENT ON COLUMN "public"."gateway_requests"."usage_output_quad_tokens" IS 'Provider-independent output quadtokens, calculated as ceil(output text characters / 4).';

COMMENT ON COLUMN "public"."gateway_requests"."usage_output_tokens" IS 'Normalized per-request output tokens across modalities.';

COMMENT ON COLUMN "public"."gateway_requests"."usage_reasoning_tokens" IS 'Normalized per-request reasoning/thinking tokens.';

COMMENT ON COLUMN "public"."gateway_requests"."usage_text_quad_tokens" IS 'Provider-independent text-like workload quadtokens across text, rerank, embeddings, moderation, and OCR text.';

COMMENT ON COLUMN "public"."gateway_requests"."usage_total_tokens" IS 'Normalized per-request total tokens derived from usage JSON at write time.';

COMMENT ON COLUMN "public"."gateway_requests"."usage_video_pixel_seconds" IS 'Provider-independent video workload in pixel-seconds when dimensions and duration are known.';

COMMENT ON COLUMN "public"."gateway_requests"."usage_video_seconds" IS 'Normalized generated/processed video seconds derived from gateway usage metadata or request duration.';

COMMENT ON COLUMN "public"."gateway_upstream_requests"."request_payload" IS 'Sanitized upstream request snapshot. Full raw payloads remain in opt-in R2 I/O logs.';

COMMENT ON COLUMN "public"."gateway_upstream_requests"."response_payload" IS 'Sanitized upstream response snapshot. Full raw payloads remain in opt-in R2 I/O logs.';

COMMENT ON COLUMN "public"."gateway_webhook_endpoints"."secret_ciphertext" IS 'Encrypted signing secret. Public API responses must never expose this value.';

COMMENT ON COLUMN "public"."gateway_webhook_endpoints"."secret_key_version" IS 'Version identifier for the dedicated async webhook secret encryption key.';

COMMENT ON COLUMN "public"."keys"."ip_allowlist" IS 'Labeled IPv4/IPv6 addresses or CIDRs allowed to use this key. Empty permits any IP.';

COMMENT ON COLUMN "public"."model_discovery_public_announcements"."catalogue_status_snapshot" IS 'Lifecycle status captured to detect a public catalog transition to available.';

COMMENT ON COLUMN "public"."model_discovery_public_announcements"."public_visibility_snapshot" IS 'Whether the model was public when the announcement state was last observed.';

COMMENT ON COLUMN "public"."oauth_app_metadata"."redirect_uris" IS 'Registered OAuth callback URLs for this app (mirrors Supabase OAuth client redirect_uris).';

COMMENT ON COLUMN "public"."provider_catalog_sources"."managed_catalog" IS 'Provider-managed catalog document in the validated {data: [...]} contract shape.';

COMMENT ON COLUMN "public"."provider_catalog_sources"."management_mode" IS 'Catalog authority: remote provider URL or a provider-managed Phaseo document.';

COMMENT ON COLUMN "public"."provider_catalog_sync_models"."route_projection_status" IS 'Approved claims are staged as disabled routes; only a successful endpoint probe may enable routing.';

COMMENT ON COLUMN "public"."provider_rate_limits"."headroom_bps" IS 'Capacity held back to absorb token usage from requests that are still in flight.';

COMMENT ON COLUMN "public"."users"."country_declared_at" IS 'Time at which the user most recently confirmed their declared country.';

COMMENT ON COLUMN "public"."users"."declared_country_code" IS 'ISO 3166-1 alpha-2 country explicitly selected by the user; separate from request-origin geography.';

COMMENT ON COLUMN "public"."users"."display_code_language" IS 'Preferred language for code samples.';

COMMENT ON COLUMN "public"."users"."display_dark_accent" IS 'Preferred hexadecimal accent colour for dark mode.';

COMMENT ON COLUMN "public"."users"."display_dark_palette" IS 'Preferred neutral surface palette for dark mode.';

COMMENT ON COLUMN "public"."users"."display_date_style" IS 'Preferred date presentation style.';

COMMENT ON COLUMN "public"."users"."display_density" IS 'Preferred interface spacing density.';

COMMENT ON COLUMN "public"."users"."display_hour_cycle" IS 'Preferred 12-hour, 24-hour, or system clock.';

COMMENT ON COLUMN "public"."users"."display_landing_page" IS 'Preferred destination after an ordinary sign-in.';

COMMENT ON COLUMN "public"."users"."display_light_accent" IS 'Preferred hexadecimal accent colour for light mode.';

COMMENT ON COLUMN "public"."users"."display_light_palette" IS 'Preferred neutral surface palette for light mode.';

COMMENT ON COLUMN "public"."users"."display_locale" IS 'Preferred locale for display formatting; system follows the browser.';

COMMENT ON COLUMN "public"."users"."display_number_notation" IS 'Preferred standard or compact number notation.';

COMMENT ON COLUMN "public"."users"."display_relative_time" IS 'Preferred relative versus absolute timestamp presentation.';

COMMENT ON COLUMN "public"."users"."display_time_zone" IS 'Preferred IANA time zone; system follows the browser.';

COMMENT ON COLUMN "public"."v2_labs"."subdivision_code" IS 'Primary organisation location as an ISO 3166-2 subdivision code, for example US-CA.';

COMMENT ON COLUMN "public"."v2_model_provider_routes"."access_scope" IS 'Route audience. Internal routes require authenticated gateway testing mode and are never publicly routing-enabled.';

COMMENT ON COLUMN "public"."v2_model_provider_routes"."credential_mode" IS 'Optional route-level override requiring a workspace BYOK credential for this model offer.';

COMMENT ON COLUMN "public"."v2_model_provider_routes"."is_stealth" IS 'Keeps the real provider target available to internal service-role routing while every public projection exposes provider identity as exactly stealth; provider_model_id remains a synthetic stealth-prefixed identity.';

COMMENT ON COLUMN "public"."v2_model_provider_routes"."phaseo_status" IS 'Phaseo integration readiness. Only enabled routes may set routing_enabled=true.';

COMMENT ON COLUMN "public"."v2_model_provider_routes"."provider_availability_status" IS 'Upstream provider offer availability; does not imply Phaseo support.';

COMMENT ON COLUMN "public"."v2_model_provider_routes"."routing_enabled" IS 'Per provider/model routing switch, evaluated together with provider and model status.';

COMMENT ON COLUMN "public"."v2_models"."base_model_slug" IS 'Optional related standard model. It is not required for standalone free API models.';

